  str_skill_href_desc_desc_30058 = "起源之牌分為太陽、月亮和星星3種。任選3張牌，根據牌的種類發動對應效果。\n全相同——「類聚同明」：<color=#00F6FF>目前隊長</color>獲得傑諾基礎攻擊力<color=#00F6FF>8%</color>的額外攻擊力。\n各不相同——「星月凌日」：<color=#00F6FF>目前隊尾</color>獲得傑諾基礎攻擊力<color=#00F6FF>7%</color>的額外攻擊力。\n其他情況——「異色雙輝」：本場戰鬥可更換隊長次數+1，回復<color=#00F6FF>18%</color>已損失理智值。\n攻擊力提高效果持續整場戰鬥，同一效果不疊加。",
  str_skill_href_desc_name_30059 = "起源之牌",
  str_skill_href_desc_desc_30059 = "起源之牌分為太陽、月亮和星星3種。任選3張牌，根據牌的種類發動對應效果。\n全相同——「類聚同明」：<color=#00F6FF>目前隊長</color>獲得傑諾基礎攻擊力<color=#00F6FF>8%</color>的額外攻擊力。\n各不相同——「星月凌日」：<color=#00F6FF>目前隊尾</color>獲得傑諾基礎攻擊力<color=#00F6FF>7%</color>的額外攻擊力。\n其他情況——「異色雙輝」：本場戰鬥可更換隊長次數+1，回復<color=#00F6FF>18%</color>已損失理智值。\n攻擊力提高效果持續整場戰鬥，同一效果不疊加。",
  str_skill_href_desc_name_30060 = "起源之牌",
  str_skill_href_desc_desc_30060 = "起源之牌分為太陽、月亮和星星3種。任選3張牌，根據牌的種類發動對應效果。\n全相同——「類聚同明」：<color=#00F6FF>目前隊長</color>獲得傑諾基礎攻擊力<color=#00F6FF>8%</color>的額外攻擊力。\n各不相同——「星月凌日」：<color=#00F6FF>目前隊尾</color>獲得傑諾基礎攻擊力<color=#00F6FF>7%</color>的額外攻擊力。\n其他情況——「異色雙輝」：本場戰鬥可更換隊長次數+1，回復<color=#00F6FF>25%</color>已損失理智值。\n攻擊力提高效果持續整場戰鬥，同一效果不疊加。",
  str_skill_href_desc_name_30061 = "花灑印記",
  str_skill_href_desc_desc_30061 = "花灑印記在場上存在<color=#00F6FF>3</color>回合後消失。",
  str_skill_href_desc_name_30062 = "律法之像",
  str_skill_href_desc_desc_30062 = "律法之像最高等級為5級，無法替換其他光靈的機關，敵人經過後消失。",
  str_skill_href_desc_name_30063 = "銃禦值",
  str_skill_href_desc_desc_30063 = "每回合開始時獲得<color=#00F6FF>1</color>點。",
  str_skill_href_desc_name_30064 = "銃禦值",
  str_skill_href_desc_desc_30064 = "進入戰鬥時自帶<color=#00F6FF>2</color>點，每回合開始時獲得<color=#00F6FF>1</color>點。",
  str_skill_href_desc_name_30065 = "吸收",
  str_skill_href_desc_desc_30065 = "效果等同於連線經過觸發，提供傷害加成。可觸發相關光靈的對應效果。",
  str_skill_href_desc_name_30066 = "快閃陣",
  str_skill_href_desc_desc_30066 = "施放連鎖技能後，如果位於<color=#00F6FF>快閃陣</color>之外，以本次連鎖技能的範圍生成一個新的快閃陣；場上同時至多保留<color=#00F6FF>2</color>個快閃陣，超出數量後最早生成的會消失。",
  str_skill_href_desc_name_30067 = "快閃陣",
  str_skill_href_desc_desc_30067 = "施放連鎖技能後，如果位於<color=#00F6FF>快閃陣</color>之外，以本次連鎖技能的範圍生成一個新的快閃陣；場上同時至多保留<color=#00F6FF>3</color>個快閃陣，超出數量後最早生成的會消失。",
  str_skill_href_desc_name_30068 = "快閃陣",
  str_skill_href_desc_desc_30068 = "施放連鎖技能後，如果位於<color=#00F6FF>快閃陣</color>之外，以本次連鎖技能的範圍生成一個新的快閃陣；場上同時至多保留<color=#00F6FF>3</color>個快閃陣，超出數量後最早生成的會消失；進入戰鬥後會在初始位置生成一個<color=#00F6FF>菱形12格</color>範圍的快閃陣。",
  str_skill_href_desc_name_30069 = "立方能",
  str_skill_href_desc_desc_30069 = "每回合獲得<color=#00F6FF>1</color>點，最大<color=#00F6FF>9</color>點。",
  str_skill_href_desc_name_30070 = "立方能",
  str_skill_href_desc_desc_30070 = "進入戰鬥自帶<color=#00F6FF>2</color>點，每回合獲得<color=#00F6FF>1</color>點，最大<color=#00F6FF>9</color>點。",
  str_skill_href_desc_name_30071 = "偵控模組",
  str_skill_href_desc_desc_30071 = "可在偵控模組內切換主動技能效果，偵控模組內會記錄本場戰鬥內出現過的<color=#00F6FF>部分雷屬性光靈召喚物</color>。\n可選擇的<color=#00F6FF>特殊格子</color>：深色格子、稜鏡格子、十字稜鏡格子。\n可選擇以下<color=#00F6FF>我方光靈</color>的召喚物：雨森、萊因哈特、叭噗、羅伊、琪爾、娜汀、艾米。",
  str_skill_href_desc_name_30072 = "適癒球",
  str_skill_href_desc_desc_30072 = "存在<color=#00F6FF>0/1/2</color>回合時，光靈經過或透過主動技能吸收時，回復相當於阿克希亞<color=#00F6FF>40%/100%/200%</color>攻擊力的生命值。",
  str_skill_href_desc_name_30073 = "適癒球",
  str_skill_href_desc_desc_30073 = "存在<color=#00F6FF>0/1/2</color>回合時，光靈經過時回復相當於阿克希亞<color=#00F6FF>40%/100%/250%</color>攻擊力的生命值，透過主動技吸收時效果提升至<color=#00F6FF>80%/180%/400%</color>。",
  str_skill_href_desc_name_30074 = "淨龍輝",
  str_skill_href_desc_desc_30074 = "發動<color=#00F6FF>2|3|4</color>階連鎖技能後，各自對應的「淨龍輝」會亮起，<color=#00F6FF>3</color>盞「淨龍輝」亮起後主動技能就緒，主動技能施放後所有「淨龍輝」熄滅。",
  str_skill_href_desc_name_30075 = "洞悉點",
  str_skill_href_desc_desc_30075 = "每經過1個火屬性格子獲得<color=#00F6FF>1</color>點。",
  str_skill_href_desc_name_30076 = "洞悉點",
  str_skill_href_desc_desc_30076 = "每經過1個火屬性格子獲得<color=#00F6FF>1</color>點，進入戰鬥時獲得<color=#00F6FF>5</color>點，每波次開始時獲得<color=#00F6FF>5</color>點。",
  str_skill_href_desc_name_30077 = "洞悉點",
  str_skill_href_desc_desc_30077 = "每經過1個格子獲得<color=#00F6FF>1</color>點，進入戰鬥時獲得<color=#00F6FF>5</color>點，每波次開始時獲得<color=#00F6FF>5</color>點。",
  str_skill_href_desc_name_30078 = "熱值",
  str_skill_href_desc_desc_30078 = "每次普通攻擊獲得<color=#00F6FF>5</color>點，最多<color=#00F6FF>100</color>點。",
  str_skill_href_desc_name_30079 = "儲備彈藥",
  str_skill_href_desc_desc_30079 = "每回合開始時可儲備1顆；自身施放主動技能時可儲備5顆；任意光靈施放主動技能可儲備1顆。",
  str_skill_href_desc_name_30080 = "十字稜鏡格子",
  str_skill_href_desc_desc_30080 = "連線時，將十字稜鏡格子周圍十字4格的屬性轉為與十字稜鏡格子相同",
  str_skill_href_desc_name_30081 = "靠攏",
  str_skill_href_desc_desc_30081 = "只對可牽引的目標生效，先點選的目標較靠近中央區域。",
  str_skill_href_desc_name_30082 = "聚集",
  str_skill_href_desc_desc_30082 = "攻擊目標周圍1圈範圍內有其他目標。",
  str_skill_href_desc_name_30083 = "聖決",
  str_skill_href_desc_desc_30083 = "無法對沒有生命上限的目標附加聖決值。\n",
  str_skill_href_desc_name_30084 = "聚攏",
  str_skill_href_desc_desc_30084 = "只重新排列格子的屬性，讓該列/行的水格子集中出現在點選格周圍，不會改變格子上方敵人、召喚物、特殊格子的位置。\n",
  str_skill_href_desc_name_30085 = "漣漪波",
  str_skill_href_desc_desc_30085 = "最多99層，每次至少消耗7層的倍數，生命值全滿時不再消耗層數。\n",
  str_skill_href_desc_name_30086 = "漣漪波",
  str_skill_href_desc_desc_30086 = "最多99層，每次至少消耗5層的倍數，生命值全滿時不再消耗層數。\n",
  str_skill_href_desc_name_30087 = "四腳鐵蜥",
  str_skill_href_desc_desc_30087 = "四腳鐵蜥最多存在2回合，場上最多同時存在1隻。",
  str_skill_href_desc_name_30088 = "四腳鐵蜥",
  str_skill_href_desc_desc_30088 = "每回合可點選四腳鐵蜥施放技能。四腳鐵蜥最多存在2回合，場上最多同時存在1隻。",
  str_skill_href_desc_name_30089 = "「牽鳴」",
  str_skill_href_desc_desc_30089 = "施放後將周圍2圈內的敵人牽引1格，隨後消失。",
  str_skill_href_desc_name_30090 = "「洪引」",
  str_skill_href_desc_desc_30090 = "施放後將叭噗本回合的連鎖技能範圍改為朝向四腳鐵蜥自身，範圍延伸至場地邊緣。",
  str_skill_href_desc_name_30091 = "觸碰",
  str_skill_href_desc_desc_30091 = "晶礦在敵人腳下生成或敵人移動至晶礦上時，會對敵人造成傷害，在敵人腳下多次生成晶礦可重複造成傷害。",
  str_skill_href_desc_name_30092 = "位移",
  str_skill_href_desc_desc_30092 = "包括我方光靈主動技能瞬移、敵人技能擊退/牽引、使用傳送漩渦等。",
  str_skill_href_desc_name_30093 = "深色格子",
  str_skill_href_desc_desc_30093 = "所在位置更新的下個格子必定與目前屬性相同。",
  str_skill_href_desc_name_30094 = "浸體",
  str_skill_href_desc_desc_30094 = "最高40層，每層持續3回合。",
  str_skill_href_desc_name_30095 = "工備",
  str_skill_href_desc_desc_30095 = "戰鬥開始時獲得3枚，此後每回合開始時獲得1枚。",
  str_skill_href_desc_name_30096 = "影賦",
  str_skill_href_desc_desc_30096 = "每回合開始時獲得1點，每次經過深色格子獲得1點。",
  str_skill_href_desc_name_30097 = "影賦",
  str_skill_href_desc_desc_30097 = "進入戰鬥時獲得5點，每回合開始時獲得1點，每次經過深色格子獲得1點。",
  str_skill_href_desc_name_30098 = "影賦",
  str_skill_href_desc_desc_30098 = "進入戰鬥時獲得5點，每回合開始時獲得1點，每波次開始時獲得2點，每次經過深色格子獲得1點。",
  str_skill_href_desc_name_30099 = "影賦",
  str_skill_href_desc_desc_30099 = "每回合開始時獲得1點，每波次開始時獲得2點，每次經過深色格子獲得1點。",
  str_skill_href_desc_name_510218 = "投資戰略",
  str_skill_href_desc_desc_510218 = "每經過5個水屬性格子/1個深色格子獲得1點資本。\n資本累積達2/5/8點時，投資戰略會依序解鎖對應的主動技能、連鎖技能、普通攻擊3組新戰鬥能力，每次在組內二選一獲得。可獲得的戰鬥能力如下：\n影蛇纏繞：主動技能範圍擴大至菱形13格。\n霧氣驅使：主動技能傷害提升50%。\n平「億」近人：連鎖技能可追加攻擊，對最遠的目標造成1次傷害，不計算衰減次數。\n一擲億金：本次連線每經過1個深色格子，增加1次連鎖技能傷害。\n資本擴張：可斜方向攻擊。\n資本打擊：本次連線每經過1個深色格子，普通攻擊傷害提升20%，最高可提升100%。",
  str_skill_href_desc_name_513218 = "投資戰略",
  str_skill_href_desc_desc_513218 = "每經過5個水屬性格子/1個深色格子獲得1點資本。第二輪投資結束後，接下來每獲得1點資本，涉的攻擊力便提升1%，最多折算40點。（覺醒3解鎖）。\n資本累積達2/5/8點時，投資戰略會依序解鎖對應的主動技能、連鎖技能、普通攻擊3組新戰鬥能力，每次在組內二選一獲得。可獲得的戰鬥能力如下：\n影蛇纏繞：主動技能範圍擴大至菱形13格。\n霧氣驅使：主動技能傷害提升50%。\n平「億」近人：連鎖技能可追加攻擊，對最遠的目標造成1次傷害，不計算衰減次數。\n一擲億金：本次連線每經過1個深色格子，增加1次連鎖技能傷害。\n資本擴張：可斜方向攻擊。\n資本打擊：本次連線每經過1個深色格子，普通攻擊傷害提升20%，最高可提升100%。\n",
  str_skill_href_desc_name_516218 = "投資戰略",
  str_skill_href_desc_desc_516218 = "戰鬥一開始便擁有5點資本，每經過5個水屬性格子/1個深色格子獲得1點資本。第二輪投資結束後，接下來每獲得1點資本，涉的攻擊力便提升1%，最多折算40點。（覺醒3解鎖）。\n資本累積達2/5/8點時，投資戰略會依序解鎖對應的主動技能、連鎖技能、普通攻擊3組新戰鬥能力，每次在組內二選一獲得。可獲得的戰鬥能力如下：\n影蛇纏繞：主動技能範圍擴大至菱形13格。\n霧氣驅使：主動技能傷害提升50%。\n平「億」近人：連鎖技能可追加攻擊，對最遠的目標造成1次傷害，不計算衰減次數。\n一擲億金：本次連線每經過1個深色格子，增加1次連鎖技能傷害。\n資本擴張：可斜方向攻擊。\n資本打擊：本次連線每經過1個深色格子，普通攻擊傷害提升20%，最高可提升100%。",
  str_skill_href_desc_name_530218 = "投資戰略",
  str_skill_href_desc_desc_530218 = "每經過5個水屬性格子/1個深色格子獲得1點資本。\n資本累積達2/5/8點時，投資戰略會依序解鎖對應的主動技能、連鎖技能、普通攻擊3組新戰鬥能力，每次在組內二選一獲得。第一輪投資完成後，可繼續第二輪投資，獲得第一輪未獲得的戰鬥能力。可獲得的戰鬥能力如下：\n影蛇纏繞：主動技能範圍擴大至菱形13格。\n霧氣驅使：主動技能傷害提升50%。\n平「億」近人：連鎖技能可追加攻擊，對最遠的目標造成1次傷害，不計算衰減次數。\n一擲億金：本次連線每經過1個深色格子，增加1次連鎖技能傷害。\n資本擴張：可斜方向攻擊。\n資本打擊：本次連線每經過1個深色格子，普通攻擊傷害提升20%，最高可提升100%。",
  str_skill_href_desc_name_533218 = "投資戰略",
  str_skill_href_desc_desc_533218 = "每經過5個水屬性格子/1個深色格子獲得1點資本。第二輪投資結束後，接下來每獲得1點資本，涉的攻擊力便提升1%，最多折算40點。\n資本累積達2/5/8點時，投資戰略會依序解鎖對應的主動技能、連鎖技能、普通攻擊3組新戰鬥能力，每次在組內二選一獲得。第一輪投資完成後，可繼續第二輪投資，獲得第一輪未獲得的戰鬥能力。可獲得的戰鬥能力如下：\n影蛇纏繞：主動技能範圍擴大至菱形13格。\n霧氣驅使：主動技能傷害提升50%。\n平「億」近人：連鎖技能可追加攻擊，對最遠的目標造成1次傷害，不計算衰減次數。\n一擲億金：本次連線每經過1個深色格子，增加1次連鎖技能傷害。\n資本擴張：可斜方向攻擊。\n資本打擊：本次連線每經過1個深色格子，普通攻擊傷害提升20%，最高可提升100%。",
  str_skill_href_desc_name_536218 = "投資戰略",
  str_skill_href_desc_desc_536218 = "戰鬥一開始便擁有5點資本，每經過5個水屬性格子/1個深色格子獲得1點資本。第二輪投資結束後，接下來每獲得1點資本，涉的攻擊力便提升1%，最多折算40點。\n資本累積達2/5/8點時，投資戰略會依序解鎖對應的主動技能、連鎖技能、普通攻擊3組新戰鬥能力，每次在組內二選一獲得。第一輪投資完成後，可繼續第二輪投資，獲得第一輪未獲得的戰鬥能力。可獲得的戰鬥能力如下：\n影蛇纏繞：主動技能範圍擴大至菱形13格。\n霧氣驅使：主動技能傷害提升50%。\n平「億」近人：連鎖技能可追加攻擊，對最遠的目標造成1次傷害，不計算衰減次數。\n一擲億金：本次連線每經過1個深色格子，增加1次連鎖技能傷害。\n資本擴張：可斜方向攻擊。\n資本打擊：本次連線每經過1個深色格子，普通攻擊傷害提升20%，最高可提升100%。",
  str_skill_href_desc_name_30100 = "集彩板",
  str_skill_href_desc_desc_30100 = "澤塔可以透過以下方式填滿集彩板，填滿顏色後能施放主動技能【斑斕祕技】\n1.主動技能【什錦轟炸】會在重設點選格子前記錄格子的顏色，並填入集彩板。\n2.主動技能【斑斕祕技】召喚出的「科南」在攻擊過程中會對經過的格子進行取色，並填入集彩板。",
  str_skill_href_desc_name_30110 = "待降方塊",
  str_skill_href_desc_desc_30110 = "【待降方塊】的形狀為巴緹牙主動技能的轉色範圍，共7種。\n巴緹牙每次施放主動技能後，方塊形狀隨機改變1次。",
  str_skill_href_desc_name_30111 = "待降方塊",
  str_skill_href_desc_desc_30111 = "【待降方塊】的形狀為巴緹牙主動技能的轉色範圍，共7種。\n巴緹牙每次施放主動技能後，方塊形狀隨機改變1次。\n【待降方塊】可以重骰方塊形狀。每次重骰消耗5點能量。經過火屬性格子可獲得1點能量。下次主動技能施放前，每次重骰消耗的能量遞增5點。",
  str_skill_href_desc_name_30112 = "待降方塊",
  str_skill_href_desc_desc_30112 = "【待降方塊】的形狀為巴緹牙主動技能的轉色範圍，共7種。\n巴緹牙每次施放主動技能後，方塊形狀隨機改變1次。\n【待降方塊】可以重骰方塊形狀。每次重骰消耗5點能量，初始能量10點。經過火屬性格子可獲得1點能量。下次主動技能施放前，每次重骰消耗的能量遞增5點。",
  str_skill_href_desc_name_30113 = "待降方塊",
  str_skill_href_desc_desc_30113 = "【待降方塊】的形狀為巴緹牙主動技能的轉色範圍，共7種。\n巴緹牙每次施放主動技能後，方塊形狀隨機改變1次。\n【待降方塊】可以重骰方塊形狀。每次重骰消耗5點能量，初始能量10點。經過火屬性格子可獲得1點能量。",
  str_skill_href_desc_name_30114 = "待降方塊",
  str_skill_href_desc_desc_30114 = "【待降方塊】的形狀為巴緹牙主動技能的轉色範圍，共7種。\n巴緹牙每次施放主動技能後，方塊形狀隨機改變1次。\n【待降方塊】可以重骰方塊形狀。每次重骰消耗5點能量。經過火屬性格子可獲得1點能量。下次主動技能施放前，每次重骰消耗的能量遞增5點。\n鎖定【待降方塊】可以使形狀不會隨機改變。鎖定狀態下，使用重骰功能會強化該方塊。每強化1次，施放主動技能時額外在其中隨機1處生成深色格子。",
  str_skill_href_desc_name_30115 = "待降方塊",
  str_skill_href_desc_desc_30115 = "【待降方塊】的形狀為巴緹牙主動技能的轉色範圍，共7種。\n巴緹牙每次施放主動技能後，方塊形狀隨機改變1次。\n【待降方塊】可以重骰方塊形狀。每次重骰消耗5點能量，初始能量10點。經過火屬性格子可獲得1點能量。下次主動技能施放前，每次重骰消耗的能量遞增5點。\n鎖定【待降方塊】可以使形狀不會隨機改變。鎖定狀態下，使用重骰功能會強化該方塊。每強化1次，施放主動技能時額外在其中隨機1處生成深色格子。",
  str_skill_href_desc_name_30116 = "待降方塊",
  str_skill_href_desc_desc_30116 = "【待降方塊】的形狀為巴緹牙主動技能的轉色範圍，共7種。\n巴緹牙每次施放主動技能後，方塊形狀隨機改變1次。\n【待降方塊】可以重骰方塊形狀。每次重骰消耗5點能量，初始能量10點。經過火屬性格子可獲得1點能量。\n鎖定【待降方塊】可以使形狀不會隨機改變。鎖定狀態下，使用重骰功能會強化該方塊。每強化1次，施放主動技能時額外在其中隨機1處生成深色格子。",
  str_skill_href_desc_name_30117 = "鎮魂印記",
  str_skill_href_desc_desc_30117 = "每當連鎖技能或普通攻擊觸發雷擊攻擊敵人時，獲得1層。",
  str_skill_href_desc_name_30118 = "真主契約",
  str_skill_href_desc_desc_30118 = "場上最多同時有1名目標擁有真主契約。",
  str_skill_href_desc_name_30119 = "AP",
  str_skill_href_desc_desc_30119 = "萊莎、科洛蒂婭、派翠夏AP點數量彼此共通，每個角色每回合至多施放1次主動技能。若角色在回合內沒有施放主動技能，回合結束時獲得10點AP。",
  str_skill_href_desc_name_30120 = "AP",
  str_skill_href_desc_desc_30120 = "萊莎、科洛蒂婭、派翠夏AP點數量彼此共通，每個角色每回合至多施放1次主動技能。進入戰鬥時獲得20點AP。若角色在回合內沒有施放主動技能，回合結束時獲得10點AP。",
  str_skill_href_desc_name_30121 = "AP",
  str_skill_href_desc_desc_30121 = "萊莎、科洛蒂婭、派翠夏AP點數量彼此共通，每個角色每回合至多施放1次主動技能。進入戰鬥時獲得20點AP。每回合結束時獲得10點AP。",
  str_skill_href_desc_name_30122 = "戰術系統",
  str_skill_href_desc_desc_30122 = "戰鬥中許多行為可獲得「戰術值」，累積到不同程度可獲得對應效果。\n10點戰術值－等級1：萊莎、科洛蒂婭、派翠夏連鎖技能最終傷害提高15%。\n40點戰術值－等級2：每回合開始時，在隨機位置生成1個深色格子。\n70點戰術值－等級3：萊莎、派翠夏連鎖技能命中可附加1層灼燒效果；科洛蒂婭連鎖技能命中可附加1層中毒效果。\n100點戰術值－等級4：萊莎、科洛蒂婭、派翠夏主動技能最終傷害提高50%。\n130點戰術值－等級5：每回合開始時，在隨機位置生成1個深色格子。",
  str_skill_href_desc_name_30123 = "戰術系統",
  str_skill_href_desc_desc_30123 = "戰鬥中許多行為可獲得「戰術值」，累積到不同程度可獲得對應效果。預設等級上限為5等，進入戰鬥後，戰術系統等級上限+1。\n10點戰術值－等級1：萊莎、科洛蒂婭、派翠夏連鎖技能最終傷害提高15%。\n40點戰術值－等級2：每回合開始時，在隨機位置生成1個深色格子。\n70點戰術值－等級3：萊莎、派翠夏連鎖技能命中可附加1層灼燒效果；科洛蒂婭連鎖技能命中可附加1層中毒效果。\n100點戰術值－等級4：萊莎、科洛蒂婭、派翠夏主動技能最終傷害提高50%。\n130點戰術值－等級5：每回合開始時，在隨機位置生成1個深色格子。\n160點戰術值－等級6：萊莎、科洛蒂婭、派翠夏基礎攻擊力提高10%。\n200點戰術值－等級7：每回合開始時，在隨機位置生成1個深色格子。",
  str_skill_href_desc_name_30124 = "吸收",
  str_skill_href_desc_desc_30124 = "效果等同於連線經過觸發，可觸發相關光靈的對應效果。",
  str_skill_href_desc_name_30125 = "威能",
  str_skill_href_desc_desc_30125 = "隊伍每連線經過2格，獲得1點威能。",
  str_skill_href_desc_name_30126 = "威能",
  str_skill_href_desc_desc_30126 = "隊伍每連線經過2格，獲得1點威能。每回合開始時獲得5點威能。",
  str_skill_href_desc_name_30127 = "連線操作",
  str_skill_href_desc_desc_30127 = "連線可無視格子顏色，每連線1格消耗1點威能。",
  str_skill_href_desc_name_30128 = "離隊狀態",
  str_skill_href_desc_desc_30128 = "離隊期間，祭劍座無法成為隊長，不會隨隊伍連線出戰。",
  str_skill_href_desc_name_30129 = "殘影",
  str_skill_href_desc_desc_30129 = "在隊伍或敵人經過後殘影即消失，且祭劍座歸隊。",
