  str_skill_name_590028105 = "召喚信標",
  str_skill_desc_590028105 = "暗潮喚塔者在身邊召喚3個信標，隨後為所有隨潮恢復生命。",
  str_skill_name_590028106 = "蓄能I",
  str_skill_desc_590028106 = "暗潮喚塔者原地積蓄能量，準備施放大範圍攻擊，信標數量愈多，攻擊範圍愈大。",
  str_skill_name_590028107 = "蓄能II",
  str_skill_desc_590028107 = "暗潮喚塔者瞬移到目標附近蓄能，準備施放大範圍攻擊，信標數量愈多，攻擊範圍愈大。",
  str_skill_name_590028108 = "靜默",
  str_skill_desc_590028108 = "暗潮喚塔者將積蓄的能量圈引爆，造成小範圍傷害。",
  str_skill_name_590028109 = "沉寂",
  str_skill_desc_590028109 = "暗潮喚塔者將積蓄的能量圈引爆，造成大範圍傷害。",
  str_skill_name_590028110 = "虛無",
  str_skill_desc_590028110 = "暗潮喚塔者將積蓄的能量圈引爆，對全場範圍造成傷害。",
  str_skill_desc_510001 = "揮動利爪對位於攻擊範圍內的目標進行攻擊。",
  str_skill_desc_510002 = "使用堅硬的頭部對位於攻擊範圍內的目標進行撞擊。",
  str_skill_desc_510003 = "舞動雙拳捶擊位於攻擊範圍內的目標。",
  str_skill_desc_511003 = "舞動雙拳捶擊位於攻擊範圍內的目標，下回合會對周圍的敵人造成傷害並使其眩暈。",
