  str_skill_desc_29203121 = "傲戈揚使用手中的利刃對位於攻擊範圍內的目標進行2次攻擊，並附加流血狀態。",
  str_skill_desc_29203123 = "傲戈揚使用手中的利刃對位於攻擊範圍內的目標進行2次攻擊，並附加流血和疲憊狀態。",
  str_skill_desc_510011 = "黑箱使用特製兵刃對位於攻擊範圍內的目標進行攻擊。",
  str_skill_desc_510012 = "張開屏障，可抵禦3次攻擊。",
  str_skill_desc_510013 = "使用雷射對距離自己1格的目標進行攻擊。",
  str_skill_desc_510014 = "對攻擊範圍內的目標進行攻擊，攻擊後瞬移到場景內的任意位置。",
  str_skill_desc_510015 = "使用長槍對位於攻擊範圍內的目標進行攻擊。",
