  str_skill_desc_510021 = "對面前3列範圍造成傷害，對擊中的目標帶有擊退效果。",
  str_skill_desc_510022 = "召喚暗能保護自身，每層暗能可免疫1次傷害。",
  str_skill_desc_510023 = "對範圍內的目標造成火焰傷害。",
  str_skill_desc_510024 = "發射砲彈擊退同一直線的目標。",
  str_skill_desc_510025 = "觸碰控制器會朝弩箭臺方向射出1支弩箭，對命中目標造成傷害。",
  str_skill_desc_510026 = "樊尼驅動能量對位於攻擊範圍內的目標進行遠程攻擊。",
  str_skill_desc_510027 = "樊尼驅動能量為菲萊克斯恢復生命值。",
  str_skill_desc_510028 = "菲萊克斯揮動武器守禦，對攻擊範圍內的目標進行攻擊。",
  str_skill_desc_510029 = "菲萊克斯為武器守禦注入能量後砸向地面，對範圍內的目標造成傷害和眩暈。",
  str_skill_desc_510030 = "戰狂揮動雙拳猛擊地面，對範圍內的目標造成傷害和眩暈。",
  str_skill_desc_510031 = "每2回合對自身周圍1圈目標造成1次傷害。",
  str_skill_desc_510032 = "對經過的格子布置地刺，地刺會對經過的目標造成傷害。",
  str_skill_desc_510033 = "對範圍內的目標造成傷害，被擊中的目標會被擊退。",
  str_skill_desc_510034 = "對範圍內的目標進行1次攻擊。",
  str_skill_desc_510035 = "無聊凝聚力量，準備施放十字大範圍火屬性攻擊，對命中的目標造成傷害和附帶灼燒，凝聚力量時無法被打斷。",
  str_skill_desc_510036 = "無聊吸收周圍1圈和自身屬性相同的格子能量，對範圍內的目標進行攻擊（吸收的格子愈多，傷害愈高），擊中後附加灼燒狀態。",
  str_skill_desc_510037 = "無聊凝聚力量，準備施放十字大範圍雷屬性攻擊，對命中的目標造成傷害和麻痺效果，凝聚力量時無法被打斷。",
  str_skill_desc_510038 = "無聊吸收周圍1圈和自身屬性相同的格子能量，對範圍內的目標進行攻擊（吸收的格子愈多，傷害愈高），擊中後附加麻痺狀態。",
  str_skill_desc_500039 = "嘶魘兒使用粗壯的尾部攻擊自身攻擊範圍內的目標，造成2次傷害。",
  str_skill_desc_500040 = "夏爾使用尾部凝聚能量尖刺，遠程攻擊位於攻擊範圍內的目標，造成2次傷害。",
  str_skill_desc_510039 = "嘶魘兒使用粗壯的尾部對自身攻擊範圍內的目標進行攻擊。",
  str_skill_desc_510040 = "夏爾使用尾部凝聚能量尖刺，對位於攻擊範圍內的目標進行遠程攻擊。",
  str_skill_desc_510041 = "觸碰控制器會朝箭臺所處方向射出1支附毒弩箭，對命中目標造成傷害，並附加中毒狀態。",
  str_skill_desc_510042 = "觸碰控制器會朝箭臺所處方向射出1支麻痺弩箭，命中光靈會使光靈停止移動，同時下回合只能移動1格。",
  str_skill_desc_510043 = "存有殲星爆彈的裝置，始終會負載1顆殲星爆彈庫。",
  str_skill_desc_510044 = "塔巴德揮動利爪，對攻擊範圍內的目標造成傷害。",
  str_skill_desc_510045 = "對所有目標造成1次傷害。",
  str_skill_desc_510046 = "尤尼梅特製作的神奇道具，經過其所在格子時可觸發。為全體光靈增加尤尼梅特10%的攻擊力。",
  str_skill_desc_510047 = "尤尼梅特製作的神奇道具，經過其所在格子時可觸發。為隊伍增加尤尼梅特10%的防禦力。",
  str_skill_desc_80001 = "尤尼梅特模仿落雷結晶製作的仿真品，經過其所在格子時可觸發。觸發後召喚雷電，對所有敵方目標造成尤尼梅特50%的傷害。",
  str_skill_desc_80002 = "尤尼梅特模仿隕石結晶製作的仿真品，經過其所在格子時可觸發。觸發後召喚隕石，對敵方生命值最高的目標造成尤尼梅特100%的傷害。",
  str_skill_desc_80003 = "尤尼梅特製作的神奇道具，經過其所在格子時可觸發。為全體光靈恢復尤尼梅特100%攻擊力的生命值。",
  str_skill_desc_510048 = "恢復20%最大生命值。",
  str_skill_desc_5100482 = "恢復10%最大生命值。",
  str_skill_desc_510049 = "所有出戰光靈技能回合數-1。",
  str_skill_desc_510050 = "可被擊退，擊退過程中碰撞到目標或受阻擋會發生劇烈爆炸，對爆炸位置及其周圍1圈造成範圍傷害。",
  str_skill_desc_510051 = "擺放在戰鬥區域的堅硬石塊，無法被擊碎。可阻擋遠程彈道攻擊。",
  str_skill_desc_510052 = "普通的碎石，可被範圍傷害技能擊碎。",
  str_skill_desc_510053 = "開啟寶箱的開關，踩下3個機關後即可開啟中間的寶箱。",
  str_skill_desc_510054 = "舊首都存放大量物資的寶箱，踩下寶箱周圍3個控制開關後即可開啟寶箱，獲取大量物資。",
  str_skill_desc_500216 = "鮑林格下回合進入蓄能狀態。蓄能狀態下若被殲星爆彈擊中中間暗鬼位置，鮑林格會陷入癱瘓狀態，持續1回合。",
  str_skill_desc_510216 = "鮑林格施放殲星爆彈，然後進入蓄能狀態。蓄能狀態下若被殲星爆彈擊中中間暗鬼位置，鮑林格會進入癱瘓狀態，持續1回合。",
  str_skill_desc_500217 = "鮑林格對棋盤的六個2*2區域施放爆裂炸彈，攻擊位於區域內的目標（若被殲星爆彈擊中中部，鮑林格會陷入癱瘓）。",
  str_skill_desc_500218 = "鮑林格釋放蓄積的能量，對全體敵人造成傷害並將其擊退。",
  str_skill_name_510219 = "錯亂",
  str_skill_desc_510219 = "對範圍內的目標進行1次攻擊，並使所有光靈的主動技能冷卻回合數+1。",
  str_skill_name_510220 = "躍擊",
  str_skill_desc_510220 = "躍起對範圍內的目標進行1次攻擊。",
  str_skill_name_510221 = "光能禁錮",
