  str_skill_name_510222 = "狙擊",
  str_skill_desc_510222 = "對範圍內的目標進行1次遠程攻擊，蔓靶距離目標愈遠，造成的傷害愈高。",
  str_skill_name_510223 = "利爪",
  str_skill_desc_510223 = "對範圍內的目標進行1次攻擊。",
  str_skill_name_510224 = "力拔",
  str_skill_desc_510224 = "對範圍內的目標造成傷害，同時擊碎範圍內的所有格子。",
  str_skill_name_510225 = "怨恨",
  str_skill_desc_510225 = "對範圍內的目標造成傷害，命中目標後，向屬性與自身相同的非隊長光靈施放「怨恨」。受到怨恨的光靈無法出戰，也無法使用主動技能。詛魍死亡時，為屬性與其相同的光靈清除怨恨效果。",
  str_skill_name_510226 = "魂火",
  str_skill_desc_510226 = "對範圍內的目標進行1次遠程攻擊。",
  str_skill_name_510227 = "囚籠之觸",
  str_skill_desc_510227 = "對目標發起衝鋒，將其撞擊到自身周圍，同時改變自身所處位置以及周圍2圈格子的屬性。",
  str_skill_name_510228 = "震盪之光",
  str_skill_desc_510228 = "對範圍內的目標造成大量傷害。",
  str_skill_name_510229 = "靜謐之暉",
  str_skill_desc_510229 = "對範圍內的目標造成較高傷害，若命中目標，則改變其所處位置周圍1圈格子的屬性。",
  str_skill_name_1001811 = "月輪",
  str_skill_desc_1001811 = "月瀆化為月輪，對範圍內的目標造成傷害，並鎖定攻擊範圍中間區域的格子。",
  str_skill_name_1001821 = "月凌",
