  str_skill_name_1001831 = "月勢",
  str_skill_desc_1001831 = "月瀆化為月輪，對範圍內的目標造成傷害，同時位移至場地另一側。位移後，鎖定自身周圍2圈的格子，鎖定的格子無法轉色。",
  str_skill_name_1002111 = "擊碎",
