  str_skill_name_1002121 = "風勢",
  str_skill_desc_1002121 = "對自身周圍2圈內的目標造成大量傷害並擊退之，同時擊碎攻擊範圍內所有格子。",
  str_skill_name_1002131 = "力湧",
  str_skill_desc_1002131 = "對橫縱4列範圍造成傷害，若命中目標，則將其擊退至場邊。",
  str_skill_name_1002211 = "強化落雷神符",
  str_skill_desc_1002211 = "召喚大量落雷，對範圍內的目標造成傷害。",
  str_skill_name_1002221 = "鋒銳",
  str_skill_desc_1002221 = "移動後，對自身十字最大範圍內的目標造成傷害。",
  str_skill_name_1002231 = "巨像·音波狂嘯",
  str_skill_desc_1002231 = "舒默控制巨像施放音波攻擊，攻擊全場目標。",
  str_skill_name_1002251 = "喚醒魔物",
  str_skill_desc_1002251 = "舒默移動後將目標擊退至場邊，同時喚醒附近魔物；甦醒的魔物會對自身周圍2圈內的目標造成傷害。",
  str_skill_name_1002261 = "能量狂暴",
  str_skill_desc_1002261 = "舒默放出狂暴的能量，攻擊全場的目標。目標離舒默越遠，受到的傷害越高。",
  str_skill_name_1002271 = "疾風",
  str_skill_desc_1002271 = "舒默遠離目標，向攻擊區域施放「疾風」，對範圍內的目標造成傷害。",
  str_skill_name_29002421 = "燃燒",
  str_skill_desc_29002421 = "對自身前5列範圍內的目標造成傷害。",
  str_skill_name_29002422 = "烈焰大地",
  str_skill_desc_29002422 = "施放烈焰對全場範圍造成傷害，額外對位於場邊4行範圍內的目標造成1次大量傷害。",
  str_skill_name_29002423 = "召喚蔓靶",
  str_skill_desc_29002423 = "召喚2個蔓靶進入戰場。",
  str_skill_name_1002603 = "能量衝擊",
  str_skill_desc_1002603 = "凝聚能量攻擊眼前的目標，並擊退命中的目標。",
  str_skill_name_1002604 = "反射屏障",
  str_skill_desc_1002604 = "張開屏障以降低自身受到的傷害。若在屏障存在時受到攻擊，受到的部分傷害會反射到目標身上。",
  str_skill_name_1002605 = "靜態修復",
  str_skill_desc_1002605 = "T1024留在原地修復受損部位，恢復自身一定生命值。",
  str_skill_name_1004501 = "禁錮",
  str_skill_desc_1004501 = "傷害範圍內的目標，若命中目標，則鎖定其周圍1圈的格子；被鎖定的格子無法轉色。",
  str_skill_name_1002702 = "動態修復",
  str_skill_desc_1002702 = "對處於攻擊範圍同一行或同一列的目標進行遠程攻擊。",
  str_skill_name_1000901 = "見機",
  str_skill_desc_1000901 = "行動方式取決於與目標距離的遠近。距離較近時能夠造成巨大傷害，距離較遠時將目標牽引到自身附近。",
  str_skill_name_1000911 = "見機",
  str_skill_desc_1000911 = "行動方式取決於與目標距離的遠近。距離較近時能夠造成巨大傷害，距離較遠時將目標牽引到自身附近，隨後在自身周圍1圈召喚地刺。",
  str_skill_name_1000921 = "應變",
  str_skill_desc_1000921 = "行動方式取決於與目標距離的遠近，隨後在身旁布置地刺。與目標距離較近時造成巨大傷害，距離較遠時將其牽引到附近。",
  str_skill_name_1000931 = "應變",
  str_skill_desc_1000931 = "行動方式取決於與目標距離的遠近，隨後在身旁布置地刺。與目標距離較近時造成巨大傷害，距離較遠時將其牽引到附近。",
  str_skill_name_1001001 = "能量奪取",
  str_skill_desc_1001001 = "掠奪主動技能冷卻回合數最少的光靈的能量，使其主動技能冷卻回合數+3。",
  str_skill_name_1001611 = "亂·孤島",
  str_skill_desc_1001611 = "將範圍內的目標撞擊至自身周圍，同時改變自身所在位置以及周圍2圈格子的屬性。",
  str_skill_name_1001621 = "亂·爆炸",
  str_skill_desc_1001621 = "對範圍內的目標造成較高傷害。若命中目標則改變其所在位置周圍1圈格子的屬性。",
  str_skill_name_1001631 = "亂·灰燼",
  str_skill_desc_1001631 = "隨機對場上7個2*2範圍造成傷害。若命中目標則改變其所在位置周圍1圈格子的屬性。",
  str_skill_name_1001711 = "不滅·爆破",
  str_skill_desc_1001711 = "對周圍2圈範圍內的目標造成傷害。若被其命中，隊伍中所有光靈的主動技能冷卻回合數+2。",
  str_skill_name_1001721 = "不滅·餘波",
  str_skill_desc_1001721 = "對十字形最大範圍造成傷害。若被其命中，隊伍中所有光靈的主動技能冷卻回合數+2。",
  str_skill_name_1001741 = "滅·尾擊",
  str_skill_desc_1001741 = "對範圍內的目標造成傷害。若被其命中，隊伍中所有光靈的主動技能冷卻回合數+1。",
  str_skill_name_1001751 = "滅·餘韻",
  str_skill_desc_1001751 = "對十字形最大範圍造成傷害。若被其命中，隊伍中所有光靈的主動技能冷卻回合數+1。",
  str_skill_name_1001771 = "尾擊",
  str_skill_desc_1001771 = "對十字形最大範圍造成傷害。若被其命中，則使主動技能冷卻回合數最少的光靈其冷卻回合數+3。",
  str_skill_name_1001781 = "能量奪取",
  str_skill_desc_1001781 = "對範圍內的目標造成傷害。若被其命中，主動技能冷卻回合數最少的光靈其冷卻回合數+3。",
  str_skill_name_500411 = "供能",
  str_skill_desc_500411 = "信標停留在原地，透過能量連結為暗潮喚塔者提供傷害減免效果。",
  str_skill_name_500244 = "落雷結晶",
  str_skill_desc_500244 = "神祕的光之結晶，經過其所在格子時可觸發。觸發後會召喚雷電攻擊所有敵方目標。",
  str_skill_name_500245 = "隕石結晶",
  str_skill_desc_500245 = "神祕的光之結晶，經過其所在格子時可觸發。觸發後會召喚隕石攻擊敵方生命值最高的目標。",
  str_skill_name_500170 = "鐮刀",
  str_skill_desc_500170 = "幽靈造成1次屬性攻擊。",
  str_skill_name_500171 = "鐮刀+",
  str_skill_desc_500171 = "狂暴的幽靈進行2次屬性攻擊，傷害大幅提高。",
  str_skill_name_500172 = "禍不單行",
  str_skill_desc_500172 = "幽靈造成十字範圍屬性傷害。",
  str_skill_name_500173 = "禍不單行+",
  str_skill_desc_500173 = "狂暴的幽靈造成全部格子範圍內的屬性傷害",
  str_skill_name_500174 = "幻象助戰",
  str_skill_desc_500174 = "召喚1個幻象幫助幽靈本體作戰，如果場上已有幻象，則會先召回現有的幻象，再召喚新的幻象。",
  str_skill_name_500227 = "尋覓",
  str_skill_desc_500227 = "攝輪移動到與自身屬性相同的格子附近，準備吸收格子的屬性能量。",
  str_skill_name_500228 = "聚能",
  str_skill_desc_500228 = "攝輪吸取自身及周圍1圈內同屬性格子的能量，隨後釋放能量球攻擊全體敵人，傷害隨吸收的格子數量而提高。",
  str_skill_desc_520228 = "攝輪吸收自身及周圍1圈內同屬性格子的能量，並擊碎其中的火屬性格子，隨後釋出能量球攻擊全體敵人，傷害隨吸收格子數量增加而提高。",
  str_skill_name_501001 = "幻雷",
  str_skill_desc_501001 = "鳴灼在棋盤內隨機區域召喚雷電，造成屬性傷害並使目標陷入麻痺狀態。",
  str_skill_name_501003 = "火雨",
  str_skill_desc_501003 = "鳴灼在棋盤內隨機位置召喚火雨，造成屬性傷害並使目標進入灼燒狀態。",
  str_skill_name_501011 = "遠程攻擊",
  str_skill_desc_501011 = "影遊者對自身周圍2格十字形最大範圍施放衝擊波，對範圍內的目標造成傷害。",
  str_skill_name_501015 = "鼓舞",
  str_skill_desc_501015 = "影遊者移動到友方單位最多的區域，為自身周圍12格的友軍施加強勢印記，擁有印記的友軍目標可提高攻擊。",
  str_skill_name_501021 = "頭槌",
  str_skill_desc_501021 = "崩蟻使用堅硬的頭部傷害範圍內的目標。生命值較低時會進入不穩定狀態，向玩家移動後自爆。",
  str_skill_name_501025 = "燃盡",
  str_skill_desc_501025 = "崩蟻燃燒最後的生命，移動後自爆，對周圍1圈內的目標造成傷害。",
  str_skill_name_501031 = "污染",
  str_skill_desc_501031 = "彌染攻擊範圍內的目標。彌染擁有極強的屬性抗性，剋制屬性能更容易地對彌染造成傷害。",
  str_skill_name_501032 = "污染",
  str_skill_desc_501032 = "彌染攻擊範圍內的目標，並將移動路徑上的格子屬性轉變為與自身相同的屬性。",
  str_skill_name_501042 = "嘶吼",
  str_skill_desc_501042 = "格茲德僕從向自身周圍2圈內的目標施加破裂印記。每層印記能降低目標一定的防禦力，印記層數愈高，防禦力愈低。",
  str_skill_name_501052 = "巨像·鋒銳",
  str_skill_desc_501052 = "舒默對自身十字範圍的目標造成傷害。",
  str_skill_name_501053 = "雷電之力",
  str_skill_desc_501053 = "舒默召喚雷電之力，對場上多個隨機區域造成傷害。",
  str_skill_name_501054 = "巨像·音波狂嘯",
  str_skill_desc_501054 = "舒默控制巨像施放音波攻擊，攻擊全場目標。",
  str_skill_name_501056 = "巨像·觸手",
  str_skill_desc_501056 = "舒默控制巨像，對前方大面積範圍造成傷害。",
  str_skill_name_501057 = "巨像·音波狂嘯",
  str_skill_desc_501057 = "舒默控制巨像攻擊全場，同時在場內隨機位置召喚落雷結晶，光靈經過落雷結晶時，結晶會消失。",
  str_skill_name_501058 = "召喚落雷結晶",
  str_skill_desc_501058 = "舒默在場內隨機位置召喚落雷結晶，若不踩掉落雷結晶，下回合舒默將在此位置召喚落雷，造成傷害。",
  str_skill_name_501059 = "雷鳴之音",
  str_skill_desc_501059 = "舒默在落雷結晶處召喚落雷，造成大量傷害，同時對命中的目標附加麻痺狀態。光靈經過落雷結晶時，結晶會消失。",
  str_skill_name_501061 = "領域",
  str_skill_desc_501061 = "舒默對位於自身攻擊範圍的目標施放遠程攻擊。",
  str_skill_name_501062 = "震爆",
  str_skill_desc_501062 = "舒默對位於自身範圍的目標施放震盪攻擊，造成較高傷害。",
  str_skill_name_501063 = "同步之境",
  str_skill_desc_501063 = "舒默進行生命值同步。以剩餘生命值最高的舒默為準，將其生命值與所有舒默的生命值同步。最多回復自身30%生命值。",
  str_skill_desc_511063 = "舒默進行生命值同步。以剩餘生命值最高的舒默為準，將其生命值與所有舒默的生命值同步。若場上無其他舒默，則直接回復自身最大生命值的20%。",
  str_skill_name_501082 = "僕從喚醒",
  str_skill_desc_501082 = "格茲德在場景中的隨機位置召喚2個不會移動的格茲德僕從。",
  str_skill_name_501083 = "裂地",
  str_skill_desc_501083 = "格茲德攻擊範圍內的目標，並為目標施加1層破裂印記。印記層數愈高，目標防禦愈低。",
  str_skill_name_501084 = "嘶吼",
  str_skill_desc_501084 = "格茲德怒吼，對範圍內的敵方目標施加2層破裂印記，印記層數越高，目標防禦越低。",
  str_skill_name_501085 = "引爆",
  str_skill_desc_501085 = "格茲德引爆目標身上的破裂印記，對其造成大量傷害。印記層數愈多，傷害愈高。",
  str_skill_name_501087 = "強化僕從喚醒",
  str_skill_desc_501087 = "格茲德在場景中隨機區域召喚3個僕從，僕從不會移動。",
  str_skill_name_501088 = "強化裂地",
  str_skill_desc_501088 = "格茲德瘋狂攻擊範圍內的目標2次，並對目標施加2層破裂印記。印記層數愈高，目標防禦愈低。",
  str_skill_name_501089 = "強化嘶吼",
  str_skill_desc_501089 = "格茲德最後的怒吼，對範圍內的目標施加3層破裂印記。印記層數越高，目標防禦越低。",
  str_skill_name_501092 = "晦暗撕裂",
  str_skill_desc_501092 = "麥格芬將扭曲並撕裂眼前的空間，傷害位於攻擊範圍內的目標。",
  str_skill_name_501093 = "輪迴使者",
  str_skill_desc_501093 = "麥格芬為即將到來的白夜升潮積蓄力量。",
  str_skill_name_501095 = "白夜升潮",
  str_skill_desc_501095 = "麥格芬對場景中的固定區域進行輪迴轟炸。",
  str_skill_name_501192 = "晦暗撕裂",
  str_skill_desc_501192 = "麥格芬·斯摩將扭曲並撕裂眼前的空間，傷害位於攻擊範圍內的目標。",
  str_skill_name_501193 = "輪迴使者",
  str_skill_desc_501193 = "麥格芬·斯摩為即將到來的白夜升潮積蓄力量。",
  str_skill_name_501195 = "白夜升潮",
  str_skill_desc_501195 = "麥格芬·斯摩輪迴轟炸場景中的固定區域。",
  str_skill_name_501102 = "鑽地",
  str_skill_desc_501102 = "瑪拉索爾",
  str_skill_name_501103 = "砂炎",
  str_skill_desc_501103 = "噴射火焰對範圍內的目標造成傷害。",
  str_skill_name_501104 = "召喚",
  str_skill_desc_501104 = "瑪拉·索爾召喚3隻崩蟻進入戰場。",
  str_skill_desc_580043104 = "瑪拉·索爾召喚3隻爆裂進入戰場。",
  str_skill_name_501113 = "裂石",
  str_skill_desc_501113 = "黯角攻擊並擊退範圍內的目標。",
  str_skill_name_501114 = "召喚水晶",
  str_skill_desc_501114 = "黯角在場景中隨機位置召喚2個增生水晶。",
  str_skill_name_501115 = "地裂斬",
  str_skill_desc_501115 = "黯角攻擊並擊退範圍內的目標。若目標被擊退，則在其身前額外生成1個元素碎石。",
  str_skill_name_501116 = "巨石墜落",
  str_skill_desc_501116 = "黯角凝聚所有元素碎石並對目標造成傷害。元素碎石數量愈多，黯角造成的傷害愈高。",
  str_skill_name_501141 = "召喚碎石",
  str_skill_desc_501141 = "增生水晶",
  str_skill_name_515002 = "蔓延",
  str_skill_desc_515002 = "化變對目標所在方向釋放1道寬度兩行的衝擊波，對命中目標造成傷害。",
  str_skill_name_515003 = "化變陷阱",
  str_skill_desc_515003 = "化變對範圍內的目標造成傷害並將其牽引至自己身邊。不論是否攻擊到目標，均會重設自身周圍2圈的格子。",
  str_skill_name_534001 = "逃逸之道",
  str_skill_name_510244 = "審判衝鋒",
  str_skill_desc_510244 = "塔巴德瞬移到場邊，準備向目標所在位置發動衝鋒。",
  str_skill_desc_534001 = "掌握逃跑訣竅的盜掘者們，總會試圖遠離追蹤者！",
  str_skill_name_500638 = "地火",
  str_skill_desc_500638 = "麥格芬撕裂地面，施放地火對範圍內目標造成傷害，並召喚兩隻疾犬。",
  str_skill_desc_5006381 = "麥格芬撕裂地面，施放地火對範圍內目標造成傷害。",
  str_skill_name_500639 = "湮滅",
  str_skill_desc_500639 = "麥格芬凝聚力量噴射而出，對面前3列範圍的目標造成傷害。",
  str_skill_name_500640 = "炎之氣息",
  str_skill_desc_500640 = "麥格芬振翅施放藍炎，對全體敵人造成傷害。",
  str_skill_desc_5006401 = "麥格芬振翅施放藍炎，對全體敵人造成傷害，並為自己展開無敵屏障。",
  str_skill_desc_49005111 = "麥格芬振翅施放藍炎，對全體敵人造成傷害並擊退3格距離，隨後在固定位置召喚影妖。",
  str_skill_name_505106 = "背襲",
  str_skill_desc_505106 = "映鏡從光壁中衝出，對目標造成傷害，並重設目標所在行或列的格子屬性。",
  str_skill_name_505109 = "黑流",
  str_skill_desc_505109 = "映鏡移動後遠程攻擊範圍內的目標，且每回合從場邊召喚1個幻象進入戰場。",
  str_skill_name_504901 = "影擊",
  str_skill_desc_504901 = "幻象對攻擊範圍內的目標造成傷害。",
  str_skill_name_505121 = "光壁",
  str_skill_desc_505121 = "映鏡幻化之物。映鏡會藏匿在距離敵人最遠的光壁之中（可攻擊該光壁）。光壁被擊破後，會召喚幻象攻擊敵人，擊破2個光壁後，所有光壁會消失，映鏡本體現形。",
  str_skill_name_500251 = "颶風靈動",
  str_skill_desc_500251 = "使用溫蒂之羽，將我方角色傳送回羽毛所在位置。",
  str_skill_name_500252 = "槍刺",
  str_skill_desc_500252 = "對範圍內的目標進行1次攻擊。",
  str_skill_name_1002811 = "裝甲暗鬼",
  str_skill_desc_1002811 = "負責運輸任務的暗鬼，擊敗後可獲得其運輸的白夜幣。",
  str_skill_name_515121 = "光壁",
  str_skill_desc_515121 = "映鏡幻化之物。映鏡會隱匿於距離敵人最遠的光壁之中（該光壁可被攻擊）。光壁被擊破後會召喚幻象攻擊敵人，擊破3個光壁後，所有光壁會消失，映鏡本體現形。",
  str_skill_name_1003401 = "戰力提升",
  str_skill_desc_1003401 = "擁抱者附身到周圍1圈內的暗鬼上，為其提供護盾，同時強化其攻擊力。",
  str_skill_name_1003421 = "失智",
  str_skill_desc_1003421 = "失智擁抱者附身到周圍1圈內的光靈身上，持續降低光靈的理智值。",
  str_skill_name_1003501 = "恢復",
  str_skill_desc_1003501 = "靠近多恩周圍1圈時，可融入其體內，為其恢復生命。",
  str_skill_name_1003502 = "強化回復",
  str_skill_desc_1003502 = "靠近多恩周圍1圈時，可融入其體內，為其回復生命值，並為其新增護盾。",
  str_skill_name_1003601 = "破曉綻放",
  str_skill_desc_1003601 = "對自身周圍2圈內的目標造成大量傷害。",
  str_skill_name_1003611 = "林間颶風",
  str_skill_desc_1003611 = "發動颶風，傷害全體敵人。場上黎精數量越多，造成傷害越高。",
  str_skill_name_1003621 = "召喚黎精",
  str_skill_desc_1003621 = "多恩召喚出具有恢復能力的黎精。黎精移動到多恩周圍1圈時，可為其恢復生命值。",
  str_skill_name_1003622 = "強化召喚黎精",
  str_skill_desc_1003622 = "多恩召喚出具有回復能力的黎精。黎精移動到多恩周圍1圈時，可為其回復生命值及新增護盾。",
  str_skill_name_1003800 = "孤兵",
  str_skill_desc_1003800 = "移動後對自身周圍十字形4格造成傷害。",
  str_skill_name_1003901 = "直擊",
  str_skill_desc_1003901 = "可朝所在位置的十字方向移動，移動後傷害自身周圍1圈的目標。若移動過程中撞擊目標，對其造成較高傷害，同時將其擊退到場地邊緣。",
  str_skill_name_1003902 = "縱橫",
  str_skill_desc_1003902 = "可朝所在位置的十字方向移動，移動後傷害自身周圍2圈的目標。若移動過程中撞擊目標，對其造成較高傷害，同時將其擊退到場地邊緣。",
  str_skill_name_1003912 = "凝結",
  str_skill_desc_1003912 = "彷彿和空間凝結在一起，無法移動、攻擊，也不會受到傷害，會在接下來的攻勢中觸發並開始行動。",
  str_skill_name_1004001 = "躍擊",
  str_skill_desc_1004001 = "落地後傷害所在位置十字形4格。若落點處有目標，對其造成大量傷害，同時眩暈並擊退該目標。",
  str_skill_name_1004002 = "躍踏",
  str_skill_desc_1004002 = "落地後傷害對所在位置周圍1圈。若落點處有目標，對其造成大量傷害，同時眩暈並擊退該目標。",
  str_skill_desc_1104002 = "落地後對所在位置周圍1圈造成傷害，並在範圍內佈置地刺。若落點處有目標，則對目標造成大量傷害，同時眩暈並擊退該目標。",
  str_skill_name_1004101 = "斜行擊",
  str_skill_desc_1004101 = "可朝斜方向移動，移動後，對自身十字最大範圍內的目標造成傷害。",
  str_skill_name_1004102 = "斜行擊破",
  str_skill_desc_1004102 = "可朝斜方向移動，移動後，對自身十字最大範圍內的目標造成傷害，並降低目標防禦。",
  str_skill_desc_1104102 = "可朝斜方向移動，移動後對自身十字最大範圍內的目標造成傷害並大幅降低目標防禦值。",
  str_skill_name_1004201 = "後翼",
  str_skill_desc_1004201 = "對位於自身米字形最大方向的目標造成傷害，傷害值依目標最大生命值比例計算。",
  str_skill_name_1004202 = "據守",
  str_skill_desc_1004202 = "對位於自身米字形最大方向的目標造成傷害，傷害值依目標最大生命值比例計算；若自身周圍8方向沒有目標，則為自身加上防禦屏障，同時為友軍單位回復生命值。",
  str_skill_desc_1104202 = "對位於自身米字形最大方向上的目標造成基於目標最大生命值的百分比傷害。若自身周圍8個方向上沒有目標，則為自身加上防禦屏障，並降低玩家理智值，同時為友軍單位回復生命值。",
  str_skill_name_1004301 = "號令",
  str_skill_desc_1004301 = "指揮兵傷害其自身周圍1圈的目標。",
  str_skill_name_1004302 = "拒敵",
  str_skill_desc_1004302 = "將範圍內的目標擊退出技能的攻擊範圍。",
  str_skill_name_1004303 = "君主領域",
  str_skill_desc_1004303 = "傷害場上全體敵人。",
  str_skill_name_1006511 = "撞擊",
  str_skill_desc_1006511 = "對範圍內的目標造成傷害。",
  str_skill_name_1006521 = "爆裂",
  str_skill_desc_1006521 = "引爆體內的能量，對範圍內的目標造成傷害，並摧毀所處位置的格子。",
  str_skill_name_1007001 = "遁地",
  str_skill_desc_1007001 = "當目標範圍有碎裂格子時，遁地至目標身邊的碎裂格子鑽出，造成傷害，同時擊碎身邊格子。光靈在碎裂格子上移動不會增加連鎖數。",
  str_skill_name_1007011 = "碎地",
  str_skill_desc_1007011 = "當目標周圍沒有碎裂格子時，位移至距離自身2格的位置，並粉碎周圍1圈8個格子。光靈在碎裂格子上移動不會增加連鎖數。",
  str_skill_name_29010011 = "驚叫",
  str_skill_desc_29010011 = "當目標周圍有碎裂格子時，位移至目標身邊的碎裂格子，對目標造成傷害並擊退目標。",
  str_skill_name_29010012 = "恐嚇",
  str_skill_desc_29010012 = "當目標處於自身米字形範圍內時，位移至目標身邊，對目標造成傷害並擊退之；同時擊碎目標與自身所處的一條直線範圍內的格子。",
  str_skill_name_1007102 = "撻",
  str_skill_desc_1007102 = "對範圍內的目標造成傷害。",
  str_skill_desc_10071021 = "秒殺範圍內的目標。",
  str_skill_desc_220091202 = "擊碎範圍內的格子，並對範圍內的目標造成傷害。",
  str_skill_name_1007103 = "死亡衝擊",
  str_skill_desc_1007103 = "對目標上回合所在位置及其周圍1圈施放衝擊，若目標處於衝擊範圍，將造成大量傷害。",
  str_skill_desc_1107103 = "對目標上回合所在位置及其周圍1圈釋放衝擊，秒殺範圍內的目標。",
  str_skill_desc_220091201 = "對目標上回合所在位置及其周圍1圈釋放衝擊，擊碎範圍內的格子，秒殺範圍內的目標。",
  str_skill_name_1007104 = "音波覆蓋",
  str_skill_desc_1007104 = "對範圍內的目標造成傷害並擊退目標。",
  str_skill_desc_10071041 = "對範圍內的目標造成傷害並擊退目標。同時召喚多個降低光靈理智值的碩腕。",
  str_skill_name_1007112 = "光束衝擊",
  str_skill_desc_1007112 = "朝目標上回合所在位置施放光束衝擊，對路徑上及目標位置的目標造成傷害。（怪物死亡2回合後會原地復活）",
  str_skill_desc_10071121 = "朝目標上回合所在位置施放光束衝擊，對路徑上及目標位置的目標造成傷害。",
  str_skill_name_1007113 = "風襲",
