  str_skill_name_20005011 = "應變",
  str_skill_desc_20005011 = "行動方式取決於與目標距離的遠近，隨後在身旁布置地刺。與目標距離較近時造成巨大傷害，距離較遠時將其牽引到附近。",
  str_skill_name_20002441 = "暗鬼召喚",
