  str_skill_desc_28002411 = "吞羅每回合都會將你擊退。",
  str_skill_name_390041101 = "厄孽·裂地",
  str_skill_desc_390041101 = "格茲德瘋狂攻擊範圍內的目標2次，並為目標附加2層弱勢印記。印記層數越高，目標攻擊越低。隨後格茲德在指定位置召喚4名格茲德僕從。",
  str_skill_name_390041102 = "厄孽·裂地",
  str_skill_desc_390041102 = "格茲德瘋狂攻擊範圍內的目標2次，並為目標附加2層弱勢印記。印記層數越高，目標攻擊越低。隨後格茲德在指定位置召喚4名格茲德僕從。",
  str_skill_name_390041103 = "厄孽·強化嘶吼",
  str_skill_desc_390041103 = "格茲德最後的怒吼，對範圍內的目標附加3層破裂印記。印記層數越高，目標防禦越低。",
  str_skill_name_390041104 = "厄孽·引爆",
  str_skill_desc_390041104 = "格茲德引爆目標身上的破裂印記，對其造成大量傷害。印記層數越多，傷害越高，破裂印記引爆後不會被清除。",
  str_skill_name_300045101 = "厄孽·嘶吼",
