  str_skill_name_300040101 = "超量供能",
  str_skill_desc_300040101 = "信標藉由能量連結為暗潮喚塔者提供能量，每個信標增加暗潮喚塔者5%攻擊力。",
  str_skill_name_390026401 = "厄孽·破曉綻放",
  str_skill_desc_390026401 = "移動後對自身周圍2圈內的目標造成大量傷害，並在指定位置召喚2個黎精。",
  str_skill_name_390026402 = "厄孽·破曉綻放",
  str_skill_desc_390026402 = "移動後對自身周圍2圈內的目標造成大量傷害，並在指定位置召喚2個黎精。",
