  str_skill_desc_290130113 = "心魔對2圈範圍內的目標造成傷害，並將技能範圍內的格子轉色，同時鎖定技能範圍內部分格子。隨後，心魔在場上召喚2名僕從。",
  str_skill_desc_290130123 = "心魔對2圈範圍內的目標造成傷害，並將技能範圍內的格子轉色，同時鎖定技能範圍內部分格子。隨後，心魔在場上召喚4名僕從。",
