  str_skill_desc_300050 = "對<color=#00F6FF>米字形16格</color>造成<color=#00F6FF>{1}%</color>的傷害並擊退敵人。",
  str_skill_desc_320050 = "對<color=#00F6FF>米字形16格</color>造成<color=#00F6FF>{1}%</color>的傷害並擊退敵人，被擊退敵人的防禦降低10%。",
  str_skill_desc_300022 = "對<color=#00F6FF>周圍1圈</color>及<color=#00F6FF>十字形最大</color>範圍造成<color=#00F6FF>{1}%</color>的傷害並擊退敵人。",
  str_skill_desc_303022 = "對<color=#00F6FF>周圍1圈</color>及<color=#00F6FF>十字形最大</color>範圍造成<color=#00F6FF>{1}%</color>的傷害並擊退敵人。",
  str_skill_desc_310022 = "對<color=#00F6FF>周圍1圈</color>及<color=#00F6FF>十字形最大</color>範圍造成<color=#00F6FF>{1}%</color>的傷害並擊退敵人。",
  str_skill_desc_313022 = "對<color=#00F6FF>周圍1圈</color>及<color=#00F6FF>十字形最大</color>範圍造成<color=#00F6FF>{1}%</color>的傷害並擊退敵人。",
  str_skill_desc_300047 = "為隊伍恢復等同於卓婭<color=#00F6FF>150%</color>攻擊力的生命值，場上每有1個水屬性格子，恢復增加<color=#00F6FF>5%</color>。",
  str_skill_desc_303047 = "為隊伍恢復等同於卓婭<color=#00F6FF>150%</color>攻擊力的生命值，場上每有1個水屬性格子，恢復增加<color=#00F6FF>5%</color>。",
  str_skill_desc_320047 = "為隊伍恢復等同於卓婭<color=#00F6FF>150%</color>攻擊力的生命值，場上每有1個水屬性格子，恢復增加<color=#00F6FF>8%</color>。",
  str_skill_desc_323047 = "為隊伍恢復等同於卓婭<color=#00F6FF>150%</color>攻擊力的生命值，場上每有1個水屬性格子，恢復增加<color=#00F6FF>8%</color>。",
  str_skill_desc_300049 = "對<color=#00F6FF>周圍1圈</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_303049 = "對<color=#00F6FF>周圍1圈</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_320049 = "對<color=#00F6FF>周圍1圈</color>造成<color=#00F6FF>{1}%</color>的傷害。同時將攻擊範圍內的火屬性格子重設為其他屬性。",
  str_skill_desc_323049 = "對<color=#00F6FF>周圍1圈</color>造成<color=#00F6FF>{1}%</color>的傷害。同時將攻擊範圍內的火屬性格子重設為其他屬性。",
  str_skill_desc_300051 = "選擇1個方向攻擊，對命中的首名敵人及其<color=#00F6FF>周圍1圈</color>內敵人，造成<color=#00F6FF>240%</color>的傷害。",
  str_skill_desc_310051 = "選擇1個方向攻擊，對命中的首名敵人及其<color=#00F6FF>周圍1圈</color>內敵人，造成<color=#00F6FF>240%</color>的傷害。",
  str_skill_desc_320051 = "選擇1個方向攻擊，對命中的首名敵人及其<color=#00F6FF>周圍1圈</color>內的敵人造成<color=#00F6FF>240%</color>傷害並附加2回合<link=\"10002\"><#FFAE07><u>灼燒</u></color></link>狀態（首名敵人附加2層，其餘附加1層）。",
  str_skill_desc_300052 = "瞬移到任意方向3格範圍內的指定位置，對該位置<color=#00F6FF>十字形4格</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_310052 = "瞬移到任意方向3格範圍內的指定位置，對該位置<color=#00F6FF>十字形4格</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_320052 = "瞬移至任意方向3格範圍內的指定位置，對該位置<color=#00F6FF>周圍1圈</color>造成<color=#00F6FF>{1}%</color>傷害。",
  str_skill_desc_300007 = "對<color=#00F6FF>十字形最大</color>範圍造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_320007 = "對<color=#00F6FF>十字形最大</color>範圍造成<color=#00F6FF>{1}%</color>的傷害。若攻擊目標處於中毒狀態，可使中毒狀態層數加倍，若中毒層數達到上限5層，主動技能傷害會增加<color=#00F6FF>50%</color>。",
  str_skill_desc_300008 = "選擇1個可行走的格子，將其轉變為火屬性的<link=\"30001\"><#FFAE07><u>稜鏡格子</u></color></link>。",
  str_skill_desc_310008 = "選擇1個可行走的格子，將其轉變為火屬性的<link=\"30001\"><#FFAE07><u>稜鏡格子</u></color></link>。",
  str_skill_desc_300032 = "隨機對場上的敵人造成<color=#00F6FF>6-10</color>次<color=#00F6FF>100%</color>的傷害，對同一目標造成多次傷害時，從第2次起每次傷害減半。",
  str_skill_desc_310032 = "隨機對場上的敵人造成<color=#00F6FF>6-10</color>次<color=#00F6FF>100%</color>的傷害，對同一目標造成多次傷害時，從第2次起每次傷害減半。",
  str_skill_desc_300035 = "瞬移到自身<color=#00F6FF>周圍2圈</color>內的任意位置。",
  str_skill_desc_310035 = "瞬移到自身<color=#00F6FF>周圍2圈</color>內的任意位置。",
  str_skill_desc_320035 = "瞬移到自身<color=#00F6FF>周圍2圈</color>內的任意位置。",
  str_skill_desc_300058 = "任選1格放置旗幟。艾米與旗幟的距離愈近，防禦愈高，最高增加<color=#00F6FF>100%</color>的防禦。旗幟被敵人觸碰後會消失。",
  str_skill_desc_303058 = "任選1格放置旗幟。艾米與旗幟的距離愈近，防禦愈高，最高增加<color=#00F6FF>100%</color>的防禦。旗幟被敵人觸碰後會消失。",
  str_skill_desc_310058 = "任選1格放置旗幟。艾米與旗幟的距離愈近，防禦愈高，最高增加<color=#00F6FF>100%</color>的防禦。旗幟被敵人觸碰後會消失。",
  str_skill_desc_313058 = "任選1格放置旗幟。艾米與旗幟的距離愈近，防禦愈高，最高增加<color=#00F6FF>100%</color>的防禦。旗幟被敵人觸碰後會消失。",
  str_skill_desc_300053 = "對<color=#00F6FF>周圍1圈</color>造成<color=#00F6FF>150%</color>傷害。只有1名敵人時，傷害提升為<color=#00F6FF>1.5</color>倍。",
  str_skill_desc_303053 = "對<color=#00F6FF>周圍1圈</color>造成<color=#00F6FF>150%</color>傷害。只有1名敵人時，傷害變為<color=#00F6FF>1.5</color>倍。主動技能擊殺目標後可再次使用。",
  str_skill_desc_310053 = "對<color=#00F6FF>周圍1圈</color>造成<color=#00F6FF>150%</color>傷害。只有1名敵人時，傷害提升為<color=#00F6FF>1.5</color>倍。",
  str_skill_desc_313053 = "對<color=#00F6FF>周圍1圈</color>造成<color=#00F6FF>150%</color>傷害。只有1名敵人時，傷害變為<color=#00F6FF>1.5</color>倍。主動技能擊殺目標後可再次使用。",
  str_skill_desc_320053 = "對<color=#00F6FF>周圍1圈</color>造成<color=#00F6FF>150%</color>傷害。只有1名敵人時，傷害變為<color=#00F6FF>2</color>倍。",
  str_skill_desc_323053 = "對<color=#00F6FF>周圍1圈</color>造成<color=#00F6FF>150%</color>傷害。只有1名敵人時，傷害變為<color=#00F6FF>2</color>倍。主動技能擊殺目標後可再次使用。",
  str_skill_desc_300074 = "對<color=#00F6FF>十字形最大</color>範圍造成<color=#00F6FF>{1}%</color>的傷害，並把敵人牽引到自身周圍。",
  str_skill_desc_310074 = "對<color=#00F6FF>十字形最大</color>範圍造成<color=#00F6FF>{1}%</color>的傷害，並把敵人牽引到自身周圍。",
  str_skill_desc_320074 = "對<color=#00F6FF>十字形最大</color>範圍造成<color=#00F6FF>{1}%</color>的傷害，並把敵人牽引到自身周圍，敵人每被牽引<color=#00F6FF>1</color>格，最終傷害增加<color=#00F6FF>10%</color>。",
  str_skill_desc_300017 = "瞬移到指定位置，並對該位置<color=#00F6FF>十字形4格</color>的敵人造成<color=#00F6FF>{1}%</color>的傷害，並擊退敵人。",
  str_skill_desc_320017 = "瞬移到指定位置，並對該位置<color=#00F6FF>周圍1圈</color>內的敵人造成<color=#00F6FF>{1}%</color>的傷害，並擊退敵人。",
  str_skill_desc_300040 = "對<color=#00F6FF>周圍2圈</color>造成<color=#00F6FF>{1}%</color>的傷害，並重設範圍內的所有格子。",
  str_skill_desc_330040 = "對<color=#00F6FF>周圍2圈</color>造成<color=#00F6FF>{1}%</color>傷害，並重設範圍內所有<color=#00F6FF>非火屬性</color>的格子，<color=#00F6FF>小機率</color>生成火屬性格子。",
  str_skill_desc_300041 = "將<color=#00F6FF>十字形4格</color>轉變為水屬性。",
  str_skill_desc_304041 = "將<color=#00F6FF>十字形4格</color>轉變為水屬性，生成的格子有機率出現最多2個<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>。",
  str_skill_desc_300021 = "重設場上所有格子，重設時保留<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>的數量並重新分配。",
  str_skill_desc_310021 = "重設場上所有格子，重設時保留<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>的數量並重新分配。",
  str_skill_desc_330021 = "重設場上所有格子，重設時保留<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>的數量並重新分配。<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>出現在森屬性格子上的機率增加。",
