  str_skill_desc_330001 = "將最靠近的<color=#00F6FF>4</color>個火或雷屬性格子轉變為森屬性（有機率生成<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>，最多2個）。",
  str_skill_desc_333001 = "將最靠近的<color=#00F6FF>4</color>個火或雷屬性格子轉變為森屬性，有機率出現最多2個<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>。若技能上回合就緒，本回合轉色數量<color=#00F6FF>+1</color>。",
  str_skill_desc_336001 = "將最靠近的<color=#00F6FF>5</color>個火或雷屬性格子轉變為森屬性（有機率生成<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>，最多不超過2個）上回合技能就緒，本回合轉色數量<color=#00F6FF>+1</color>。",
  str_skill_desc_300011 = "瞬移到指定位置，對<color=#00F6FF>周圍2圈</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_320011 = "瞬移到指定位置，對<color=#00F6FF>周圍2圈</color>造成<color=#00F6FF>{1}%</color>的傷害，並附加<color=#00F6FF>2</color>層龍牙印記（若擊殺敵人，範圍內其他敵人的印記層數將增加至上限）。",
  str_skill_desc_330011 = "瞬移到指定位置，對<color=#00F6FF>周圍2圈</color>造成<color=#00F6FF>{1}%</color>的傷害，並附加<color=#00F6FF>2</color>層龍牙印記（若擊殺敵人，範圍內其他敵人的印記層數將增加至上限）。",
  str_skill_desc_300019 = "對<color=#00F6FF>周圍3圈</color>至多3名敵人造成<color=#00F6FF>250%</color>傷害，僅有1名敵人時，造成重設<color=#00F6FF>250%</color>無視防禦的傷害。回復本次傷害25%的生命值。",
  str_skill_desc_303019 = "對<color=#00F6FF>周圍3圈</color>最多3名敵人造成<color=#00F6FF>250%</color>傷害，僅有1名敵人時，造成<color=#00F6FF>250%</color>無視防禦的傷害。回復本次傷害35%的生命值。",
  str_skill_desc_306019 = "對最靠近的3名敵人造成<color=#00F6FF>250%</color>傷害，僅有1名敵人時造成<color=#00F6FF>250%</color>無視防禦的傷害。回復本次傷害35%的生命值。",
  str_skill_desc_320019 = "對<color=#00F6FF>周圍3圈</color>最多3名敵人造成<color=#00F6FF>250%</color>傷害，僅有1名敵人時造成<color=#00F6FF>250%</color>無視防禦的傷害。回復本次傷害25%的生命值。目標每有1層流血狀態，最終傷害增加10%。",
  str_skill_desc_323019 = "對<color=#00F6FF>周圍3圈</color>最多3名敵人造成<color=#00F6FF>250%</color>傷害，僅有1名敵人時造成<color=#00F6FF>250%</color>無視防禦的傷害。回復本次傷害35%的生命值。目標每有1層流血狀態，最終傷害增加10%。",
  str_skill_desc_326019 = "對最靠近的3名敵人造成<color=#00F6FF>250%</color>傷害，僅有1名敵人時造成<color=#00F6FF>250%</color>無視防禦的傷害。回復本次傷害35%的生命值。目標每有1層流血狀態，最終傷害增加10%。",
  str_skill_desc_300023 = "對<color=#00F6FF>全體</color>敵人造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_303023 = "對<color=#00F6FF>全體</color>敵人造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_306023 = "對<color=#00F6FF>全體</color>敵人造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_300002 = "任選<color=#00F6FF>2</color>個格子轉變為森屬性<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>，並對每格<color=#00F6FF>十字形最大</color>範圍造成<color=#00F6FF>200%</color>的傷害。",
  str_skill_desc_303002 = "任選<color=#00F6FF>2</color>個格子轉變為森屬性<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>，並對每個格子<color=#00F6FF>十字形最大</color>範圍造成<color=#00F6FF>240%</color>傷害。",
  str_skill_desc_306002 = "任選<color=#00F6FF>2</color>個格子轉變為森屬性<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>，並對每個格子<color=#00F6FF>十字形最大</color>範圍造成<color=#00F6FF>240%</color>傷害。",
  str_skill_desc_320002 = "任選<color=#00F6FF>2</color>個格子轉變為森屬性<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>，並對每格<color=#00F6FF>十字形最大</color>範圍造成<color=#00F6FF>200%</color>的傷害。",
  str_skill_desc_323002 = "任選<color=#00F6FF>2</color>個格子轉變為森屬性<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>，並對每個格子<color=#00F6FF>十字形最大</color>範圍造成<color=#00F6FF>240%</color>傷害。",
  str_skill_desc_326002 = "任選<color=#00F6FF>2</color>個格子轉變為森屬性<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>，並對每個格子<color=#00F6FF>十字形最大</color>範圍造成<color=#00F6FF>240%</color>傷害。",
  str_skill_desc_16000213 = "任選2個格子轉變為森屬性的強化格子，並對每格十字形最大範圍造成傷害。",
  str_skill_desc_300005 = "對<color=#00F6FF>全體</color>敵人造成<color=#00F6FF>{1}%</color>的傷害，敵人生命值百分比愈低，傷害愈高（最高增加100%）。",
  str_skill_desc_306005 = "對<color=#00F6FF>全體</color>敵人造成<color=#00F6FF>{1}%</color>的傷害，敵人生命值百分比愈低，傷害愈高（最高增加100%）。",
  str_skill_desc_310005 = "對<color=#00F6FF>全體</color>敵人造成<color=#00F6FF>{1}%</color>的傷害，敵人生命值百分比愈低，傷害愈高（最高增加100%）。",
  str_skill_desc_316005 = "對<color=#00F6FF>全體</color>敵人造成<color=#00F6FF>{1}%</color>的傷害，敵人生命值百分比愈低，傷害愈高（最高增加100%）。",
  str_skill_desc_330005 = "對<color=#00F6FF>全體</color>敵人造成<color=#00F6FF>{1}%</color>的傷害，敵人生命值百分比愈低，傷害愈高（最高增加100%）。",
  str_skill_desc_336005 = "對<color=#00F6FF>全體</color>敵人造成<color=#00F6FF>{1}%</color>的傷害，敵人生命值百分比愈低，傷害愈高（最高增加100%）。",
  str_skill_desc_300006 = "瞬移到指定位置，對<color=#00F6FF>縱向1列</color>造成<color=#00F6FF>{1}%</color>的傷害並擊退敵人。同時將攻擊範圍的格子轉變為水屬性。",
  str_skill_desc_303006 = "瞬移到指定位置，對<color=#00F6FF>縱向1列</color>造成<color=#00F6FF>{1}%</color>的傷害並擊退敵人。同時將攻擊範圍的格子轉變為水屬性。",
  str_skill_desc_300025 = "選擇<color=#00F6FF>3列</color>或<color=#00F6FF>3行</color>造成<color=#00F6FF>{1}%</color>傷害，並擊退敵人。重設範圍內<color=#00F6FF>非火屬性</color>格子。",
  str_skill_desc_306025 = "選擇<color=#00F6FF>3列</color>或<color=#00F6FF>3行</color>造成<color=#00F6FF>{1}%</color>傷害並擊退敵人。重設範圍內<color=#00F6FF>非火屬性</color>格子，<color=#00F6FF>小機率</color>生成火屬性格子。",
  str_skill_desc_320025 = "選擇<color=#00F6FF>3列</color>或<color=#00F6FF>3行</color>造成<color=#00F6FF>{1}%</color>傷害並擊退敵人，中間行或列傷害為兩側的1.5倍。重設範圍內<color=#00F6FF>非火屬性</color>格子。",
  str_skill_desc_326025 = "選擇<color=#00F6FF>3列</color>或<color=#00F6FF>3行</color>造成<color=#00F6FF>{1}%</color>傷害並擊退敵人，中間行或列傷害為兩側的1.5倍。重設範圍內<color=#00F6FF>非火屬性</color>格子，<color=#00F6FF>小機率</color>生成火屬性格子。",
  str_skill_desc_300026 = "重設<color=#00F6FF>所有非火屬性</color>格子，<color=#00F6FF>小機率</color>生成火屬性格子。敵人所處位置至少1格轉變為火屬性。",
  str_skill_desc_306026 = "重設<color=#00F6FF>所有非火屬性</color>格子，<color=#00F6FF>小機率</color>生成火屬性格子。敵人所處位置至少1格轉變為火屬性。",
  str_skill_desc_300028 = "為隊伍回復相當於拉斐爾攻擊力<color=#00F6FF>200%</color>的生命值，同時重設<color=#00F6FF>周圍3圈非水屬性</color>的格子。",
  str_skill_desc_306028 = "為隊伍回復相當於拉斐爾攻擊力<color=#00F6FF>200%</color>的生命值，同時重設<color=#00F6FF>周圍3圈非水屬性</color>的格子，<color=#00F6FF>小機率</color>生成水屬性格子。",
  str_skill_desc_330028 = "為隊伍回復相當於拉斐爾攻擊力<color=#00F6FF>200%</color>的生命值，同時重設<color=#00F6FF>所有非水屬性</color>的格子。",
  str_skill_desc_336028 = "為隊伍回復相當於拉斐爾攻擊力<color=#00F6FF>200%</color>的生命值，同時重設<color=#00F6FF>所有非水屬性</color>的格子，<color=#00F6FF>小機率</color>生成水屬性格子。",
  str_skill_desc_300029 = "從水、火、雷屬性格子中選擇<color=#00F6FF>1</color>種重設為其他屬性，保留格子的強化屬性。",
  str_skill_desc_306029 = "從水、火、雷屬性格子中選擇<color=#00F6FF>1</color>種重設為其他屬性，保留格子的強化屬性。",
  str_skill_desc_320029 = "從水、火、雷屬性格子中選擇<color=#00F6FF>1</color>種來重設成其他屬性，保留格子的強化屬性。每重設<color=#00F6FF>10</color>個格子，必然出現1個<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>。",
  str_skill_desc_326029 = "從水、火、雷屬性格子中選擇<color=#00F6FF>1</color>種來重設成其他屬性，保留格子的強化屬性。每重設<color=#00F6FF>10</color>個格子，必然出現1個<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>。",
  str_skill_desc_300038 = "將最靠近的<color=#00F6FF>4</color>個水和火屬性格子轉變為雷屬性。",
  str_skill_desc_303038 = "將最靠近的<color=#00F6FF>4</color>個水和火屬性格子轉變為雷屬性，若主動技能上回合就緒，本回合轉色數量<color=#00F6FF>+1</color>。",
  str_skill_desc_306038 = "將最靠近的<color=#00F6FF>5</color>個水和火屬性格子轉變為雷屬性，若主動技能上回合就緒，本回合轉色數量<color=#00F6FF>+1</color>。",
