  str_skill_desc_335092 = "將最靠近的<color=#00F6FF>5</color>個火屬性格子轉變為森屬性，有機率出現最多2個<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>。若主動技能上回合就緒，本回合轉色數量<color=#00F6FF>+1</color>。",
  str_skill_desc_300075 = "對<color=#00F6FF>周圍3圈</color>內的敵人造成{1}%的傷害，並對其附加<link=\"10006\"><#FFAE07><u>緩速</u></color></link>狀態，持續2回合。",
  str_skill_desc_302075 = "對<color=#00F6FF>周圍3圈</color>內的敵人造成{1}%的傷害，並對其附加<link=\"10006\"><#FFAE07><u>緩速</u></color></link>狀態，持續2回合。",
