  str_skill_desc_320075 = "對<color=#00F6FF>周圍3圈</color>內的敵人造成{1}%的傷害，並對其附加<link=\"10006\"><#FFAE07><u>緩速</u></color></link>狀態，持續2回合，再附加2層<link=\"10001\"><#FFAE07><u>中毒</u></color></link>狀態，持續2回合。",
  str_skill_desc_322075 = "對<color=#00F6FF>周圍3圈</color>內的敵人造成{1}%的傷害，並對其附加<link=\"10006\"><#FFAE07><u>緩速</u></color></link>狀態，持續2回合，再附加2層<link=\"10001\"><#FFAE07><u>中毒</u></color></link>狀態，持續2回合。",
  str_skill_desc_325075 = "對<color=#00F6FF>全體</color>敵人造成{1}%的傷害，並對其附加<link=\"10006\"><#FFAE07><u>緩速</u></color></link>狀態，持續2回合，再附加2層<link=\"10001\"><#FFAE07><u>中毒</u></color></link>狀態，持續2回合。",
  str_skill_desc_300086 = "為隊伍恢復等同於尤萊雅生命上限<color=#00F6FF>60%</color>的生命值。若恢復的生命值溢出，則將最近的森屬性格子轉變成<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>。",
  str_skill_desc_304086 = "為隊伍恢復等同於尤萊雅生命上限<color=#00F6FF>70%</color>的生命值。若恢復的生命值溢出，則將最靠近的森屬性格子轉變成<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>。",
  str_skill_desc_330086 = "為隊伍恢復等同於尤萊雅生命上限<color=#00F6FF>60%</color>的生命值。若恢復的生命值溢出，則將最靠近的森屬性格子轉變成<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>。觸發<link=\"30010\"><#FFAE07><u>極光時刻</u></color></link>時，可再次施放主動技能。",
  str_skill_desc_334086 = "為隊伍恢復等同於尤萊雅生命上限<color=#00F6FF>70%</color>的生命值。若恢復的生命值溢出，則將最靠近的森屬性格子轉變成<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>。觸發<link=\"30010\"><#FFAE07><u>極光時刻</u></color></link>時，可再次施放主動技能。",
  str_skill_desc_300068 = "瞬移到任意位置，並在原地生成1個溫蒂之羽，點選溫蒂之羽可返回原地。場上最多可存在1個溫蒂之羽。",
  str_skill_desc_320068 = "戰鬥開始時在場上生成1個溫蒂之羽；施放主動技能瞬移後，在原地生成1個溫蒂之羽，點選溫蒂之羽即可返回原地。場上最多可存在1個溫蒂之羽。",
  str_skill_desc_300082 = "任選<color=#00F6FF>2</color>個格子，交換其格子屬性。",
  str_skill_desc_320082 = "任選<color=#00F6FF>2</color>個格子，交換其格子屬性。交換的格子中若有森屬性，則將該格子轉變成<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>。",
  str_skill_desc_300057 = "瞬移至任意位置，並為隊伍回復相當於菲莉詩<color=#00F6FF>250%</color>攻擊力的生命值；瞬移位置<color=#00F6FF>周圍2圈</color>每有1名敵人，回復效果提升<color=#00F6FF>10%</color>。",
  str_skill_desc_305057 = "瞬移至任意位置，並為隊伍回復相當於菲莉詩<color=#00F6FF>250%</color>攻擊力的生命值，瞬移位置<color=#00F6FF>周圍3圈</color>每有1名敵人，回復效果提升<color=#00F6FF>15%</color>。",
  str_skill_desc_320057 = "瞬移至任意位置，並為隊伍回復相當於菲莉詩<color=#00F6FF>250%</color>攻擊力的生命值。瞬移後位置<color=#00F6FF>周圍2圈</color>內每有1名敵人，為菲莉詩提供<color=#00F6FF>30%</color>生命上限的護盾，並提升<color=#00F6FF>10%</color>回復效果。",
  str_skill_desc_325057 = "瞬移至任意位置，並為隊伍回復相當於菲莉詩<color=#00F6FF>250%</color>攻擊力的生命值。瞬移後位置<color=#00F6FF>周圍3圈</color>內每有1名敵人，為菲莉詩提供<color=#00F6FF>30%</color>生命上限的護盾，並提升<color=#00F6FF>15%</color>回復效果。",
  str_skill_desc_300091 = "施放時，場上每個水屬性格子會為出戰成員增加等同於克蘿伊<color=#00F6FF>0.5%</color>攻擊力的攻擊加成，持續2回合。",
  str_skill_desc_320091 = "可獲得<link=\"30006\"><#FFAE07><u>協奏印記</u></color></link>。施放時，場上每個水屬性格子和每層印記會為出戰成員增加等同於克蘿伊<color=#00F6FF>0.5%</color>攻擊力的攻擊加成，持續2回合。",
  str_skill_desc_300079 = "對<color=#00F6FF>周圍2圈</color>內的敵人造成<color=#00F6FF>{1}%</color>的傷害，並重設範圍內所有格子。",
  str_skill_desc_330079 = "對<color=#00F6FF>周圍2圈</color>內的敵人造成<color=#00F6FF>{1}%</color>傷害，並重設範圍內所有<color=#00F6FF>非水屬性</color>格子，<color=#00F6FF>小機率</color>生成水屬性格子。",
  str_skill_desc_300085 = "對<color=#00F6FF>生命值百分比最低</color>的敵人造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_320085 = "對<color=#00F6FF>生命值百分比最低</color>的敵人造成<color=#00F6FF>{1}%</color>的傷害。使用主動技能擊殺目標後可再次使用。",
  str_skill_desc_330085 = "對<color=#00F6FF>生命值百分比最低</color>的敵人造成<color=#00F6FF>{1}%</color>的傷害。可獲得<link=\"30005\"><#FFAE07><u>見證印記</u></color></link>，每層印記會增加水屬性光靈<color=#00F6FF>1%</color>的攻擊。使用主動技能擊殺目標後可再次使用。",
  str_skill_desc_300089 = "任選<color=#00F6FF>2</color>個格子轉變成雷屬性的<link=\"30001\"><#FFAE07><u>稜鏡格子</u></color></link>。",
  str_skill_desc_16008901 = "任選2個格子轉變為雷屬性的稜鏡格子。",
  str_skill_desc_303089 = "任選<color=#00F6FF>2</color>個格子轉變成雷屬性的稜鏡<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>。",
  str_skill_desc_300027 = "衝刺到所選位置，對沿途及相鄰格子上的敵人造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_303027 = "衝刺至選定位置，對沿途及相鄰格子上的敵人造成<color=#00F6FF>{1}%</color>傷害，並根據位移距離，在選定位置立即施放1次連鎖技能。",
  str_skill_desc_330027 = "衝刺到所選位置，對沿途及相鄰格子的敵人造成<color=#00F6FF>{1}%</color>的傷害，額外造成敵人<color=#00F6FF>5%</color>現有生命值的傷害。",
  str_skill_desc_333027 = "衝刺到所選位置，對沿途及鄰格敵人造成<color=#00F6FF>{1}%</color>傷害，額外傷害敵人<color=#00F6FF>5%</color>生命值，並根據位移距離，在所選位置立刻施放1次連鎖技能。",
  str_skill_desc_300060 = "進入午時狀態，增加約娜<color=#00F6FF>10%</color>的攻擊和<color=#00F6FF>30%</color>的連鎖技能傷害，持續2回合。",
  str_skill_desc_303060 = "進入午時狀態，增加約娜<color=#00F6FF>10%</color>的攻擊和<color=#00F6FF>30%</color>的連鎖技能傷害，持續2回合。",
  str_skill_desc_306060 = "進入午時狀態，增加約娜<color=#00F6FF>15%</color>的攻擊和<color=#00F6FF>30%</color>的連鎖技能傷害，持續2回合。",
  str_skill_desc_330060 = "進入午時狀態，增加約娜<color=#00F6FF>10%</color>的攻擊和<color=#00F6FF>30%</color>的連鎖技能傷害，同時使火屬性光靈連鎖技能觸發所需的格子數量<color=#00F6FF>-2</color>，持續2回合。",
  str_skill_desc_333060 = "進入午時狀態，增加約娜<color=#00F6FF>10%</color>的攻擊和<color=#00F6FF>30%</color>的連鎖技能傷害，同時使火屬性光靈連鎖技能觸發所需的格子數量<color=#00F6FF>-2</color>，持續2回合。",
  str_skill_desc_336060 = "進入午時狀態，增加約娜的<color=#00F6FF>15%</color>攻擊和<color=#00F6FF>30%</color>的連鎖技能傷害，同時使火屬性光靈連鎖技能觸發所需的格子數量<color=#00F6FF>-2</color>，持續2回合。",
  str_skill_desc_300064 = "進入超載狀態，雷霆的連鎖技能能傷害增加<color=#00F6FF>50%</color>，且對最靠近的1個敵人造成2次傷害，持續2回合。",
  str_skill_desc_303064 = "進入超載狀態，雷霆的連鎖技能能傷害增加<color=#00F6FF>50%</color>，且對最靠近的1個敵人造成2次傷害，持續2回合。",
  str_skill_desc_306064 = "進入超載狀態，雷霆的連鎖技能能傷害增加<color=#00F6FF>50%</color>，且對最靠近的1個敵人造成2次傷害，持續2回合。",
  str_skill_desc_320064 = "進入超載狀態，雷霆的連鎖技能能傷害增加<color=#00F6FF>50%</color>，且對最靠近的1個敵人造成2次傷害，持續2回合。",
  str_skill_desc_323064 = "進入超載狀態，雷霆的連鎖技能能傷害增加<color=#00F6FF>50%</color>，且對最靠近的1個敵人造成2次傷害，持續2回合。",
  str_skill_desc_326064 = "進入超載狀態，雷霆的連鎖技能能傷害增加<color=#00F6FF>50%</color>，且對最靠近的1個敵人造成2次傷害，持續2回合。",
  str_skill_desc_300070 = "隨機對場上的敵人造成<color=#00F6FF>5</color>次<color=#00F6FF>90%</color>的傷害，所處位置<color=#00F6FF>周圍1圈</color>內每有1個火屬性格子，再額外攻擊1次。",
  str_skill_desc_302070 = "隨機對場上的敵人造成<color=#00F6FF>5</color>次<color=#00F6FF>90%</color>的傷害，所處位置<color=#00F6FF>周圍1圈</color>內每有1個火屬性格子，再額外攻擊1次。",
  str_skill_desc_305070 = "隨機對場上的敵人造成<color=#00F6FF>6</color>次<color=#00F6FF>90%</color>的傷害，所處位置<color=#00F6FF>周圍12格</color>每有1個火屬性格子，再額外攻擊1次。",
  str_skill_desc_300088 = "對<color=#00F6FF>十字形最大</color>範圍造成<color=#00F6FF>{1}%</color>的傷害並擊退敵人，同時將攻擊範圍內的格子轉變成火屬性。",
  str_skill_desc_302088 = "對<color=#00F6FF>十字形最大</color>範圍造成<color=#00F6FF>{1}%</color>的傷害並擊退敵人，同時將攻擊範圍內的格子轉變成火屬性。",
  str_skill_desc_305088 = "對<color=#00F6FF>十字形最大</color>範圍造成<color=#00F6FF>{1}%</color>的傷害並擊退敵人，同時將攻擊範圍內的格子轉變成火屬性。",
  str_skill_desc_300084 = "使用後本回合火系光靈的連鎖技能會施放<color=#00F6FF>2</color>次，第<color=#00F6FF>2</color>次施放時，所有火系光靈攻擊力為伊斯塔萬攻擊力的<color=#00F6FF>70%</color>。",
  str_skill_desc_302084 = "使用後本回合火系光靈的連鎖技能會施放<color=#00F6FF>2</color>次，第<color=#00F6FF>2</color>次施放時，所有火系光靈攻擊力為伊斯塔萬攻擊力的<color=#00F6FF>70%</color>。",
  str_skill_desc_305084 = "使用後本回合火系光靈的連鎖技能會施放<color=#00F6FF>2</color>次，第<color=#00F6FF>2</color>次施放時，所有火系光靈攻擊力為伊斯塔萬攻擊力的<color=#00F6FF>70%</color>。",
  str_skill_desc_330084 = "使用後本回合火系光靈的連鎖技能會施放<color=#00F6FF>2</color>次，第<color=#00F6FF>2</color>次施放時所有火系光靈攻擊力為伊斯塔萬攻擊力的<color=#00F6FF>85%</color>。",
  str_skill_desc_332084 = "使用後本回合火系光靈的連鎖技能會施放<color=#00F6FF>2</color>次，第<color=#00F6FF>2</color>次施放時所有火系光靈攻擊力為伊斯塔萬攻擊力的<color=#00F6FF>85%</color>。",
  str_skill_desc_335084 = "使用後本回合火系光靈的連鎖技能會施放<color=#00F6FF>2</color>次，第<color=#00F6FF>2</color>次施放時所有火系光靈攻擊力為伊斯塔萬攻擊力的<color=#00F6FF>85%</color>。",
  str_skill_desc_300090 = "對<color=#00F6FF>全體</color>敵人造成<color=#00F6FF>{1}%</color>的傷害，位於火屬性格子上的敵人必定眩暈。",
  str_skill_desc_302090 = "對<color=#00F6FF>全體</color>敵人造成<color=#00F6FF>{1}%</color>的傷害，位於火屬性格子上的敵人必定眩暈。",
  str_skill_desc_320090 = "對<color=#00F6FF>全體</color>敵人造成<color=#00F6FF>{1}%</color>的傷害。位於火屬性格子上的敵人必定眩暈，有<color=#00F6FF>35%</color>的機率眩暈位於其他屬性格子上的敵人。",
  str_skill_desc_322090 = "對<color=#00F6FF>全體</color>敵人造成<color=#00F6FF>{1}%</color>的傷害。位於火屬性格子上的敵人必定眩暈，有<color=#00F6FF>35%</color>的機率眩暈位於其他屬性格子上的敵人。",
  str_skill_desc_300045 = "任選1格，消耗自身目前生命值的<color=#00F6FF>15%</color>，對<color=#00F6FF>方形9格</color>範圍內的敵人，造成1次等同於損失生命值的傷害，可無視防禦；並附加1層<link=\"10000\"><#FFAE07><u>流血</u></color></link>狀態，持續2回合。",
  str_skill_desc_320045 = "任選1格，消耗自身目前生命值的<color=#00F6FF>15%</color>，對<color=#00F6FF>方形9格</color>範圍內的敵人，造成1次等同於損失生命值的傷害，可無視防禦；並附加<link=\"30004\"><#FFAE07><u>1層</u></color></link>流血狀態，持續2回合。",
  str_skill_desc_330045 = "任選1格，消耗自身目前生命值的<color=#00F6FF>15%</color>，對<color=#00F6FF>方形9格</color>範圍內的敵人，造成1次等同於損失生命值的傷害，可無視防禦；並附加<link=\"30004\"><#FFAE07><u>1層</u></color></link>流血狀態，持續2回合。聖釘生命上限增加<color=#00F6FF>50%</color>。",
  str_skill_desc_300081 = "對<color=#00F6FF>全體</color>敵人造成<color=#00F6FF>{1}%</color>的傷害，並將全體敵人牽引到自身周圍。",
  str_skill_desc_320081 = "對<color=#00F6FF>全體</color>敵人造成<color=#00F6FF>{1}%</color>的傷害，並將全體敵人牽引至自身周圍，敵人每移動1格最終傷害增加<color=#00F6FF>10%</color>。",
  str_skill_desc_300083 = "任選1格，對該位置<color=#00F6FF>十字形4格</color>造成<color=#00F6FF>{1}%</color>的傷害並擊退敵人。",
  str_skill_desc_320083 = "任選1格，對該位置<color=#00F6FF>周圍1圈</color>造成<color=#00F6FF>{1}%</color>的傷害並擊退敵人。",
  str_skill_desc_330083 = "任選1格，對該位置<color=#00F6FF>周圍1圈</color>造成<color=#00F6FF>{1}%</color>的傷害並擊退敵人，同時降低其防禦，降低比例等同本次傷害的百分比，持續2回合。",
  str_skill_desc_300059 = "移動到自身<color=#00F6FF>周圍1圈</color>內的任意位置。",
  str_skill_desc_3000591 = "移動到自身<color=#00F6FF>周圍1圈</color>內的任意位置。",
  str_skill_desc_3000592 = "移動到自身<color=#00F6FF>周圍2圈</color>內的任意位置。",
  str_skill_desc_3000593 = "移動到自身<color=#00F6FF>周圍3圈</color>內的任意位置。",
  str_skill_desc_3000594 = "移動到自身<color=#00F6FF>周圍4圈</color>內的任意位置。",
  str_skill_desc_3000595 = "移動到自身<color=#00F6FF>周圍5圈</color>內的任意位置。",
  str_skill_desc_300080 = "任選1個格子投擲罐頭，將該格子轉變成雷屬性。同時從落雷結晶、隕石結晶、繃帶、攻擊和防禦中，隨機生成1種在該格子上。",
  str_skill_desc_320080 = "任選1個格子投擲罐頭，將該格子轉變成雷屬性的<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>。同時從落雷結晶、隕石結晶、繃帶、攻擊和防禦中，隨機生成1種在該格子上。",
  str_skill_desc_300093 = "瞬移至<color=#00F6FF>周圍3圈</color>內的任意位置，對<color=#00F6FF>周圍1圈</color>內的敵人造成<color=#00F6FF>{1}%</color>傷害，範圍內只有1名敵人時傷害變為2倍。",
  str_skill_desc_306093 = "瞬移至<color=#00F6FF>周圍3圈</color>內的任意位置，對<color=#00F6FF>周圍1圈</color>內的敵人造成<color=#00F6FF>{1}%</color>傷害，範圍內只有1名敵人時傷害變為2倍。主動技能擊殺敵人後可再次使用，每回合限1次。",
  str_skill_desc_310093 = "瞬移至<color=#00F6FF>周圍3圈</color>內的任意位置，對<color=#00F6FF>周圍1圈</color>內的敵人造成<color=#00F6FF>{1}%</color>傷害，範圍內只有1名敵人時傷害變為2倍。",
  str_skill_desc_316093 = "瞬移至<color=#00F6FF>周圍3圈</color>內的任意位置，對<color=#00F6FF>周圍1圈</color>內的敵人造成<color=#00F6FF>{1}%</color>傷害，範圍內只有1名敵人時傷害變為2倍。主動技能擊殺敵人後可再次使用，每回合限1次。",
  str_skill_desc_320093 = "瞬移至<color=#00F6FF>周圍3圈</color>內的任意位置，對<color=#00F6FF>周圍1圈</color>內的敵人造成<color=#00F6FF>{1}%</color>傷害，範圍內只有1名敵人時，傷害變為2倍。每擊殺1名敵人，最終傷害增加<color=#00F6FF>15%</color>，可累積10次。",
  str_skill_desc_326093 = "瞬移至<color=#00F6FF>周圍3圈</color>內的任意位置，對<color=#00F6FF>周圍1圈</color>內的敵人造成<color=#00F6FF>{1}%</color>傷害，範圍內只有1名敵人時，傷害變為2倍。每擊殺1名敵人，最終傷害增加<color=#00F6FF>15%</color>，可累積10次。主動技能擊殺敵人後可再次使用，每回合限1次。",
  str_skill_desc_330093 = "瞬移至<color=#00F6FF>周圍3圈</color>內的任意位置，對<color=#00F6FF>周圍1圈</color>內的敵人造成<color=#00F6FF>{1}%</color>傷害，範圍內只有1名敵人時，傷害變為2倍。每擊殺1名敵人，最終傷害增加<color=#00F6FF>15%</color>，可累積10次。",
  str_skill_desc_336093 = "瞬移至<color=#00F6FF>周圍3圈</color>內的任意位置，對<color=#00F6FF>周圍1圈</color>內的敵人造成<color=#00F6FF>{1}%</color>傷害，範圍內只有1名敵人時，傷害變為2倍。每擊殺1名敵人，最終傷害增加<color=#00F6FF>15%</color>，可累積10次。主動技能擊殺敵人後可再次使用，每回合限1次。",
  str_skill_desc_300097 = "瞬移至任意位置，對起點和終點之間矩形範圍內的敵人造成傷害。矩形空間越小，造成的傷害越高，最高可造成<color=#00F6FF>480%</color>傷害。",
  str_skill_desc_302097 = "瞬移至任意位置，對起點和終點之間矩形範圍內的敵人造成傷害。矩形空間越小，造成的傷害越高，最高可造成<color=#00F6FF>600%</color>傷害。",
  str_skill_desc_300095 = "任選1格，在該位置<color=#00F6FF>及X形4格</color>內各布置1枚地雷。對觸碰地雷的敵人造成<color=#00F6FF>190%</color>的傷害並附加1層<link=\"10001\"><#FFAE07><u>中毒</u></color></link>狀態，持續2回合。",
  str_skill_desc_320095 = "任選1格，在該位置<color=#00F6FF>及X形4格</color>內各布置1枚地雷。對觸碰地雷的敵人造成<color=#00F6FF>190%</color>的傷害（所選格子的傷害加倍），並附加1層<link=\"10001\"><#FFAE07><u>中毒</u></color></link>狀態，持續2回合。",
  str_skill_desc_330095 = "任選1格，在該位置<color=#00F6FF>及X形4格</color>內各布置1枚地雷。對觸碰地雷的敵人造成<color=#00F6FF>190%</color>的傷害（所選格子的傷害加倍），並附加1層<link=\"10001\"><#FFAE07><u>中毒</u></color></link>狀態，持續2回合。",
  str_skill_desc_300062 = "從自身周圍<color=#00F6FF>8</color>個方向中任選1個最遠的格子，衝刺到該位置，並對沿途及相鄰格上的敵人造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_320062 = "任選1個場上邊緣的格子，衝刺到該位置，並對沿途及相鄰格子上的敵人造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_300024 = "標記1個格子。本次連線格子數量達到觸發連鎖技能所需格子數量的<color=#00F6FF>2</color>倍時，則在標記位置施放1次連鎖技能。",
  str_skill_desc_305024 = "標記1個格子。本次連線格子數量達到觸發連鎖技能所需格子數量的<color=#00F6FF>2</color>倍時，則在標記位置施放1次連鎖技能。",
  str_skill_desc_320024 = "標記1個格子。本次連線格子數量達到觸發連鎖技能所需格子數量的<color=#00F6FF>2</color>倍時，則在標記位置施放1次連鎖技能（兩處連鎖技能的最終傷害均會增加<color=#00F6FF>30%</color>）。",
  str_skill_desc_325024 = "標記1個格子。本次連線格子數量達到觸發連鎖技能所需格子數量的<color=#00F6FF>2</color>倍時，則在標記位置施放1次連鎖技能（兩處連鎖技能的最終傷害均會增加<color=#00F6FF>30%</color>）。",
  str_skill_desc_330024 = "標記1個格子。本次連線格子數量達到觸發連鎖技能所需格子數量的<color=#00F6FF>1.5</color>倍時，則在標記位置施放1次連鎖技能（兩處連鎖技能的最終傷害均增加<color=#00F6FF>30%</color>）。",
  str_skill_desc_335024 = "標記1個格子。本次連線格子數量達到觸發連鎖技能所需格子數量的<color=#00F6FF>1.5</color>倍時，則在標記位置施放1次連鎖技能（兩處連鎖技能的最終傷害均增加<color=#00F6FF>30%</color>）。",
  str_skill_desc_300087 = "將最靠近的<color=#00F6FF>4</color>個火屬性格子轉變為雷屬性。",
  str_skill_desc_302087 = "將最靠近的<color=#00F6FF>4</color>個火屬性格子轉變為雷屬性。若主動技能上回合就緒，本回合轉色數量<color=#00F6FF>+1</color>。",
  str_skill_desc_305087 = "將最靠近的<color=#00F6FF>5</color>個火屬性格子轉變為雷屬性。若主動技能上回合就緒，本回合轉色數量<color=#00F6FF>+1</color>。",
  str_skill_desc_330087 = "將最靠近的<color=#00F6FF>4</color>個火屬性格子轉變為雷屬性，有機率出現最多2個<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>。",
  str_skill_desc_332087 = "將最靠近的<color=#00F6FF>4</color>個火屬性格子轉變為雷屬性，有機率出現最多2個<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>。若主動技能上回合就緒，本回合轉色數量<color=#00F6FF>+1</color>。",
  str_skill_desc_335087 = "將最靠近的<color=#00F6FF>5</color>個火屬性格子轉變為雷屬性，有機率出現最多2個<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>。若主動技能上回合就緒，本回合轉色數量<color=#00F6FF>+1</color>。",
  str_skill_desc_3020871 = "將最靠近的<color=#00F6FF>4</color>個火屬性格子轉變為雷屬性。若主動技能上回合就緒，本回合轉色數量<color=#00F6FF>+1</color>。",
  str_skill_desc_3050871 = "將最靠近的<color=#00F6FF>5</color>個火屬性格子轉變為雷屬性。若主動技能上回合就緒，本回合轉色數量<color=#00F6FF>+1</color>。",
  str_skill_desc_3320871 = "將最靠近的<color=#00F6FF>4</color>個火屬性格子轉變為雷屬性，有機率出現最多2個<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>。若主動技能上回合就緒，本回合轉色數量<color=#00F6FF>+1</color>。",
  str_skill_desc_3350871 = "將最靠近的<color=#00F6FF>5</color>個火屬性格子轉變為雷屬性，有機率出現最多2個<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>。若主動技能上回合就緒，本回合轉色數量<color=#00F6FF>+1</color>。",
  str_skill_desc_300101 = "對<color=#00F6FF>周圍2圈</color>造成<color=#00F6FF>{1}%</color>的傷害，並重設範圍內的所有格子。",
  str_skill_desc_330101 = "對<color=#00F6FF>周圍2圈</color>造成<color=#00F6FF>{1}%</color>傷害，並重設範圍內所有<color=#00F6FF>非雷屬性</color>的格子，<color=#00F6FF>小機率</color>生成雷屬性格子。",
  str_skill_desc_300102 = "從自身周圍的<color=#00F6FF>4</color>個方向選擇1個，將所選方向及其相鄰行或列上的所有敵人牽引到身邊，並對牽引的敵人造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_300099 = "驅動魔劍，使自身本回合的攻擊增加<color=#00F6FF>20%</color>。結束後攻擊和防禦降低<color=#00F6FF>50%</color>，持續1回合。",
  str_skill_desc_305099 = "驅動魔劍，使自身本回合的攻擊增加<color=#00F6FF>25%</color>。結束後攻擊和防禦降低<color=#00F6FF>50%</color>，持續1回合。",
  str_skill_desc_330099 = "驅動魔劍，使自身本回合的攻擊增加<color=#00F6FF>20%</color>。結束後攻擊和防禦降低<color=#00F6FF>50%</color>，持續1回合。若在驅動魔劍期間擊殺敵人，會免疫攻防降低狀態。",
  str_skill_desc_335099 = "驅動魔劍，使自身本回合的攻擊增加<color=#00F6FF>25%</color>。結束後攻擊和防禦降低<color=#00F6FF>50%</color>，持續1回合。若在驅動魔劍期間擊殺敵人，會免疫攻防降低狀態。",
  str_skill_desc_300100 = "對十字形最大範圍造成<color=#00F6FF>{1}%</color>的傷害，並擊退敵人。同時將攻擊範圍內的格子轉變成森屬性。",
  str_skill_desc_302100 = "對十字形最大範圍造成<color=#00F6FF>{1}%</color>的傷害，並擊退敵人。同時將攻擊範圍內的格子轉變成森屬性。",
  str_skill_desc_300098 = "從自身<color=#00F6FF>周圍3圈</color>內選擇1個敵人，對其造成<color=#00F6FF>{1}%</color>的傷害，若該敵人為單格且可擊退，則將其移到攻擊範圍內的所選位置。",
  str_skill_desc_305098 = "任選1個敵人，對其造成<color=#00F6FF>{1}%</color>的傷害，若該敵人為單格且可擊退，則將其移到攻擊範圍內的所選位置。",
  str_skill_desc_330098 = "從自身<color=#00F6FF>周圍3圈</color>內選擇1名敵人，對其造成<color=#00F6FF>{1}%</color>傷害，若該敵人能以單格擊退，則將其移到攻擊範圍內的所選位置。擊殺帶有印記的目標時，對其<color=#00F6FF>周圍1圈</color>敵人造成庫絲庫塔攻擊力<color=#00F6FF>40%</color>傷害，可無視防禦。",
  str_skill_desc_335098 = "任選1名敵人，對其造成<color=#00F6FF>{1}%</color>傷害，若該敵人能以單格擊退，則將其移到攻擊範圍內的所選位置。擊殺帶有印記的目標時，對其<color=#00F6FF>周圍1圈</color>敵人造成庫絲庫塔攻擊力<color=#00F6FF>40%</color>傷害，可無視防禦。",
  str_skill_desc_300094 = "記錄目前位置，光靈施放連鎖技能結束或移動結束後，返回記錄的位置。",
