  str_skill_desc_300067 = "本回合受到的下一次傷害減少<color=#00F6FF>30%</color>，最多不超過愛麗絲生命值上限的<color=#00F6FF>2</color>倍。",
  str_skill_desc_304067 = "本回合受到的下一次傷害減少<color=#00F6FF>40%</color>，最多不超過愛麗絲生命值上限的<color=#00F6FF>2</color>倍。",
  str_skill_desc_320067 = "本回合受到的下一次傷害減少<color=#00F6FF>30%</color>，受傷後，立即恢復隊伍已損失生命<color=#00F6FF>10%</color>的生命值，降低的傷害值和恢復生命值均不會超過愛麗絲生命值上限的<color=#00F6FF>2</color>倍。",
  str_skill_desc_324067 = "本回合受到的下一次傷害減少<color=#00F6FF>40%</color>，受傷後，立即恢復隊伍已損失生命<color=#00F6FF>10%</color>的生命值，降低的傷害值和恢復生命值均不會超過愛麗絲生命值上限的<color=#00F6FF>2</color>倍。",
  str_skill_desc_300104 = "對全體敵人造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_310104 = "對全體敵人造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_320104 = "對全體敵人造成<color=#00F6FF>{1}%</color>傷害。若命中敵人不超過2名，則本回合可再施放1次。",
  str_skill_desc_300030 = "從自身周圍<color=#00F6FF>十字4格</color>中選擇1格，對該方向扇形區域造成<color=#00F6FF>{1}%</color>的傷害（敵人距離醒山愈近傷害愈高，最高為2.5倍）。",
  str_skill_desc_306030 = "從自身周圍<color=#00F6FF>十字4格</color>中選擇1格，對該方向扇形區域造成<color=#00F6FF>{1}%</color>的傷害（敵人距離醒山愈近傷害愈高，最高為3倍）。",
  str_skill_desc_320030 = "從自身周圍<color=#00F6FF>十字8格</color>中選擇1格，對該方向扇形區域造成<color=#00F6FF>{1}%</color>的傷害（敵人距離醒山愈近傷害愈高，最高為2.5倍）。若選擇外圍地格，則醒山會往前移動1格再施放技能。",
  str_skill_desc_326030 = "從自身周圍<color=#00F6FF>十字8格</color>中選擇1格，對該方向扇形區域造成<color=#00F6FF>{1}%</color>的傷害（敵人距離醒山愈近傷害愈高，最高為3倍）。若選擇外圍地格，則醒山會往前移動1格再施放技能。",
  str_skill_desc_330030 = "從自身周圍<color=#00F6FF>十字8格</color>中選擇1格，對該方向扇形區域造成<color=#00F6FF>{1}%</color>的傷害（敵人距離醒山愈近傷害愈高，最高為2.5倍）。若選擇外圍地格，則醒山會往前移動1格再施放技能。",
  str_skill_desc_336030 = "從自身周圍<color=#00F6FF>十字8格</color>中選擇1格，對該方向扇形區域造成<color=#00F6FF>{1}%</color>的傷害（敵人距離醒山愈近傷害愈高，最高為3倍）。若選擇外圍地格，則醒山會往前移動1格再施放技能。",
  str_skill_desc_300071 = "在<color=#00F6FF>十字</color>方向上任選一格轉為火屬性強化格子，同時放出焚龍，對沿途格子造成<color=#00F6FF>{1}%</color>的傷害。焚龍在抵達所選格子後向<color=#00F6FF>左右兩側</color>擴散至最遠距離，造成80%的傷害。",
  str_skill_desc_305071 = "在<color=#00F6FF>十字</color>方向上任選一格轉為火屬性強化格子，同時放出焚龍對沿途格子造成<color=#00F6FF>{1}%</color>的傷害。焚龍在抵達所選格子後向<color=#00F6FF>左右兩側</color>擴散至最遠距離，造成80%的傷害，同時將最遠的格子轉為火屬性。",
  str_skill_desc_320071 = "在<color=#00F6FF>十字</color>方向上任選一格轉為火屬性強化格子，同時放出焚龍對沿途格子造成<color=#00F6FF>{1}%</color>的傷害。焚龍在抵達所選格子後向<color=#00F6FF>左右兩側</color>擴散至最遠距離，造成80%的傷害。焚龍造成傷害前為目標附加灼印。",
  str_skill_desc_325071 = "在<color=#00F6FF>十字</color>方向上任選一格轉為火屬性強化格子，同時放出焚龍對沿途格子造成<color=#00F6FF>{1}%</color>的傷害。焚龍在抵達所選格子後向<color=#00F6FF>左右兩側</color>擴散至最遠距離，造成80%的傷害，同時將最遠的格子轉為火屬性。焚龍造成傷害前為目標附加灼印。",
  str_skill_desc_300105 = "任選1名敵人腳下的格子，對其造成20次<color=#00F6FF>40%</color>的傷害，擊敗敵人後重新選擇距離該敵人最近的目標。所在位置<color=#00F6FF>周圍1圈</color>內每有1個雷屬性格子，主動技能額外造成1次傷害。",
  str_skill_desc_306105 = "任選1名敵人腳下的格子，對其造成20次<color=#00F6FF>40%</color>的傷害，擊敗敵人後重新選擇距離該敵人最近的目標。所在位置<color=#00F6FF>周圍2圈</color>內每有1個雷屬性格子，主動技能額外造成1次傷害。",
  str_skill_desc_330105 = "任選1名敵人腳下的格子，對其造成20次<color=#00F6FF>40%</color>的傷害，每次傷害係數增加<color=#00F6FF>0.8%</color>，擊敗敵人後重新選擇距離該敵人最近的目標，最後攻擊的目標防禦力減少10%，持續1回合。所在位置<color=#00F6FF>周圍1圈</color>內每有1個雷屬性格子，主動技能額外造成1次傷害。",
  str_skill_desc_336105 = "任選1名敵人腳下的格子，對其造成20次<color=#00F6FF>40%</color>的傷害，每次傷害係數增加<color=#00F6FF>0.8%</color>，擊敗敵人後重新選擇距離該敵人最近的目標，最後攻擊的目標防禦力減少10%，持續1回合。所在位置<color=#00F6FF>周圍2圈</color>內每有1個雷屬性格子，主動技能額外造成1次傷害。",
  str_skill_desc_330109 = "消耗<color=#00F6FF>10</color>點威能並清空剩餘威能，對所選方向沿途及鄰格的敵人造成<color=#00F6FF><color=#00F6FF>150%</color></color>傷害，每清空1點威能最終傷害增加<color=#00F6FF>8%</color>。",
  str_skill_desc_330110 = "消耗<color=#00F6FF>10</color>點威能並清空剩餘威能，對全體敵人造成<color=#00F6FF>150%</color>傷害，每清空1點威能，傷害增加<color=#00F6FF>15%</color>。",
  str_skill_desc_336110 = "消耗<color=#00F6FF>10</color>點威能並清空剩餘威能，對全體敵人造成<color=#00F6FF>150%</color>傷害，每清空1點威能，傷害增加<color=#00F6FF>15%</color>並無視目標<color=#00F6FF>1%</color>的防禦。",
  str_skill_desc_330107 = "消耗<color=#00F6FF>10</color>點威能，本回合進入增幅狀態：普通攻擊可攻擊斜方向且普通攻擊和連鎖傷害增加<color=#00F6FF>20%</color>（重複施放可疊加）。",
  str_skill_desc_333107 = "消耗<color=#00F6FF>10</color>點威能，本回合進入增幅狀態：普通攻擊可攻擊斜方向且普通攻擊和連鎖傷害增加<color=#00F6FF>20%</color>（重複施放可疊加）。增幅狀態下，每擊殺1個敵人可獲得2點威能。",
  str_skill_desc_336107 = "消耗<color=#00F6FF>10</color>點威能，本回合進入增幅狀態：普通攻擊可攻擊斜方向且普通攻擊和連鎖傷害增加<color=#00F6FF>20%</color>（重複施放可疊加）。增幅狀態下，每擊殺1個敵人可獲得2點威能。",
  str_skill_desc_330108 = "消耗<color=#00F6FF>10</color>點威能，任選1格，對所選位置造成<color=#00F6FF>{1}%</color>傷害，並對所選位置周圍<color=#00F6FF>十字4格</color>造成一半的<link=\"30015\"><#FFAE07><u>濺射</u></color></link>傷害。每回合可施放多次。",
  str_skill_desc_333108 = "消耗<color=#00F6FF>10</color>點威能，任選1格，對所選位置造成<color=#00F6FF>{1}%</color>傷害，並對所選位置周圍<color=#00F6FF>十字4格</color>造成一半的<link=\"30015\"><#FFAE07><u>濺射</u></color></link>傷害。每回合可施放多次。",
  str_skill_desc_336108 = "消耗<color=#00F6FF>10</color>點威能，任選1格，對所選位置造成<color=#00F6FF>{1}%</color>傷害，並對所選位置周圍<color=#00F6FF>十字4格</color>造成一半的<link=\"30015\"><#FFAE07><u>濺射</u></color></link>傷害。每施放1次基礎攻擊力增加<color=#00F6FF>3%</color>，每回合可施放多次。",
  str_skill_desc_300112 = "瞬移至自身<color=#00F6FF>周圍3圈</color>內的任意位置，對瞬移位置<color=#00F6FF>周圍2圈</color>造成<color=#00F6FF>{1}%</color>的傷害，並重設範圍內所有<color=#00F6FF>非火屬性</color>的格子。",
  str_skill_desc_301112 = "瞬移到任意位置，對瞬移位置<color=#00F6FF>周圍2圈</color>造成<color=#00F6FF>{1}%</color>的傷害，並重設範圍內所有<color=#00F6FF>非火屬性</color>的格子。",
  str_skill_desc_303112 = "瞬移至任意位置，對瞬移位置<color=#00F6FF>周圍2圈</color>造成<color=#00F6FF>{1}%</color>的傷害，並重設範圍內所有<color=#00F6FF>非火屬性</color>的格子。敵人所在位置至少1個格子轉為火屬性。",
  str_skill_desc_320112 = "瞬移至自身<color=#00F6FF>周圍3圈</color>內的任意位置，對瞬移位置<color=#00F6FF>周圍2圈</color>造成<color=#00F6FF>{1}%</color>的傷害，並重設範圍內所有<color=#00F6FF>非火屬性</color>的格子。",
  str_skill_desc_321112 = "瞬移到任意位置，對瞬移位置<color=#00F6FF>周圍2圈</color>造成<color=#00F6FF>{1}%</color>的傷害，並重設範圍內所有<color=#00F6FF>非火屬性</color>的格子。",
  str_skill_desc_323112 = "瞬移至任意位置，對瞬移位置<color=#00F6FF>周圍2圈</color>造成<color=#00F6FF>{1}%</color>的傷害，並重設範圍內所有<color=#00F6FF>非火屬性</color>的格子。敵人所在位置至少1個格子轉為火屬性。",
  str_skill_desc_330112 = "瞬移至自身<color=#00F6FF>周圍3圈</color>內的任意位置，對瞬移位置<color=#00F6FF>周圍2圈</color>造成<color=#00F6FF>{1}%</color>的傷害，並重設範圍內所有<color=#00F6FF>非火屬性</color>的格子。觸發<color=#00F6FF>火吻</color>效果後，清空目標的火吻印記。",
  str_skill_desc_331112 = "瞬移至任意位置，對瞬移位置<color=#00F6FF>周圍2圈</color>造成<color=#00F6FF>{1}%</color>的傷害，並重設範圍內所有<color=#00F6FF>非火屬性</color>的格子。觸發<color=#00F6FF>火吻</color>效果後，清除目標的火吻印記。",
  str_skill_desc_333112 = "瞬移至任意位置，對瞬移位置<color=#00F6FF>周圍2圈</color>造成<color=#00F6FF>{1}%</color>的傷害，並重設範圍內所有<color=#00F6FF>非火屬性</color>的格子。觸發<color=#00F6FF>火吻</color>效果後，清除目標的火吻印記。敵人所處位置至少1個格子轉為火屬性。",
  str_skill_desc_300113 = "從自身周圍<color=#00F6FF>4</color>個方向中選擇1個，將場上所有單格非頭目敵人朝所選方向強制位移1格，並對場上全體敵人造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_305113 = "從自身周圍<color=#00F6FF>4</color>個方向中選擇1個，將場上所有單格非頭目敵人朝所選方向強制位移1格，並對場上全體敵人造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_330113 = "從自身周圍<color=#00F6FF>4</color>個方向選擇1個，將場上所有單格非頭目敵人朝所選方向強制位移1格，並對場上全體敵人造成<color=#00F6FF>{1}%</color>的傷害。若命中敵人不超過2名，則本回合可再施放1次。",
  str_skill_desc_335113 = "從自身周圍<color=#00F6FF>4</color>個方向選擇1個，將場上所有單格非頭目敵人朝所選方向強制位移1格，並對場上全體敵人造成<color=#00F6FF>{1}%</color>的傷害。若命中敵人不超過2名，則本回合可再施放1次。",
  str_skill_desc_300114 = "瞬移至自身周圍8個日字形對角的任意位置，對瞬移位置<color=#00F6FF>周圍1圈</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_302114 = "瞬移至自身周圍8個日字形對角的任意位置，對瞬移位置<color=#00F6FF>周圍1圈</color>造成<color=#00F6FF>{1}%</color>傷害。施放主動技能後，本回合連鎖技能可攻擊範圍內的全體敵人。",
  str_skill_desc_305114 = "瞬移到自身周圍8個日字形對角的任意位置，對瞬移位置<color=#00F6FF>周圍1圈</color>造成<color=#00F6FF>{1}%</color>的傷害。施放主動技能後，本回合連鎖技能可攻擊範圍內的全體敵人。若只命中單一敵人，則本回合可再施放1次。",
  str_skill_desc_320114 = "瞬移至自身周圍8個日字形對角的任意位置，對瞬移位置<color=#00F6FF>周圍1圈</color>造成<color=#00F6FF>{1}%</color>的傷害。施放主動技能後，本回合連鎖技能範圍增加1圈。",
  str_skill_desc_322114 = "瞬移至自身周圍8個日字形對角的任意位置，對瞬移位置<color=#00F6FF>周圍1圈</color>造成<color=#00F6FF>{1}%</color>傷害。施放主動技能後，本回合連鎖技能範圍增加1圈，並可攻擊範圍內的全體敵人。",
  str_skill_desc_325114 = "瞬移到自身周圍8個日字形對角的任意位置，對瞬移位置<color=#00F6FF>周圍1圈</color>造成<color=#00F6FF>{1}%</color>的傷害。施放主動技能後，本回合連鎖技能範圍增加1圈且可攻擊範圍內的全體敵人。若只命中單一敵人，則本回合可再施放1次。",
  str_skill_desc_300127 = "選擇1個格子（可以選擇深淵格子），放置1隻紙鶴，同時將該格子轉為森屬性。隊伍經過紙鶴時，紙鶴消失。",
  str_skill_desc_304127 = "選擇1個格子（可以選擇深淵格子），放置1隻紙鶴，同時將該格子轉為森屬性<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>。隊伍經過紙鶴時，紙鶴消失。",
  str_skill_desc_320127 = "選擇1個格子（可以選擇深淵格子），放置1隻紙鶴，同時將該格子轉為森屬性。隊伍經過紙鶴時，紙鶴消失，並將下方的非深淵格子轉為森屬性。",
  str_skill_desc_324127 = "選擇1個格子（可以選擇深淵格子），放置1隻紙鶴，同時將該格子轉為森屬性<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>。隊伍經過紙鶴時，紙鶴消失，並將下方的非深淵格子轉為森屬性。",
  str_skill_desc_300117 = "瞬移至自身<color=#00F6FF>周圍菱形12格</color>內的任意位置，對瞬移位置<color=#00F6FF>周圍20格</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_303117 = "瞬移至自身<color=#00F6FF>周圍菱形12格</color>內的任意位置，對瞬移位置<color=#00F6FF>周圍20格</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_306117 = "瞬移至自身<color=#00F6FF>周圍菱形12格</color>內的任意位置，對瞬移位置<color=#00F6FF>周圍20格</color>造成<color=#00F6FF>{1}%</color>的傷害。主動技能上回合就緒，本回合位移範圍變為<color=#00F6FF>周圍2圈</color>。",
  str_skill_desc_3061171 = "瞬移至自身<color=#00F6FF>周圍菱形12格</color>內的任意位置，對瞬移位置<color=#00F6FF>周圍20格</color>造成<color=#00F6FF>{1}%</color>的傷害。主動技能上回合就緒，本回合位移範圍變為<color=#00F6FF>周圍2圈</color>。",
  str_skill_desc_320117 = "瞬移至自身<color=#00F6FF>周圍菱形12格</color>內的任意位置，對瞬移位置<color=#00F6FF>周圍20格</color>造成<color=#00F6FF>{1}%</color>的傷害，對外圈範圍造成內圈的1.5倍傷害。",
  str_skill_desc_323117 = "瞬移至自身<color=#00F6FF>周圍菱形12格</color>內的任意位置，對瞬移位置<color=#00F6FF>周圍20格</color>造成<color=#00F6FF>{1}%</color>的傷害，對外圈範圍造成內圈的1.5倍傷害。",
  str_skill_desc_326117 = "瞬移至自身<color=#00F6FF>周圍菱形12格</color>內的任意位置，對瞬移位置<color=#00F6FF>周圍20格</color>造成<color=#00F6FF>{1}%</color>的傷害，對外圈範圍造成內圈的1.5倍傷害。主動技能上回合就緒，本回合位移範圍變為<color=#00F6FF>周圍2圈</color>。",
  str_skill_desc_3261171 = "瞬移至自身<color=#00F6FF>周圍菱形12格</color>內的任意位置，對瞬移位置<color=#00F6FF>周圍20格</color>造成<color=#00F6FF>{1}%</color>的傷害，對外圈範圍造成內圈的1.5倍傷害。主動技能上回合就緒，本回合位移範圍變為<color=#00F6FF>周圍2圈</color>。",
  str_skill_desc_330117 = "瞬移至自身<color=#00F6FF>周圍菱形12格</color>內的任意位置，對瞬移位置<color=#00F6FF>周圍20格</color>造成<color=#00F6FF>{1}%</color>的傷害，對外圈範圍造成內圈的1.5倍傷害。",
  str_skill_desc_333117 = "瞬移至自身<color=#00F6FF>周圍菱形12格</color>內的任意位置，對瞬移位置<color=#00F6FF>周圍20格</color>造成<color=#00F6FF>{1}%</color>的傷害，對外圈範圍造成內圈的1.5倍傷害。",
  str_skill_desc_336117 = "瞬移至自身<color=#00F6FF>周圍菱形12格</color>內的任意位置，對瞬移位置<color=#00F6FF>周圍20格</color>造成<color=#00F6FF>{1}%</color>的傷害，對外圈範圍造成內圈的1.5倍傷害。主動技能上回合就緒，本回合位移範圍變為<color=#00F6FF>周圍2圈</color>。",
  str_skill_desc_3361171 = "瞬移至自身<color=#00F6FF>周圍菱形12格</color>內的任意位置，對瞬移位置<color=#00F6FF>周圍20格</color>造成<color=#00F6FF>{1}%</color>的傷害，對外圈範圍造成內圈的1.5倍傷害。主動技能上回合就緒，本回合位移範圍變為<color=#00F6FF>周圍2圈</color>。",
  str_skill_desc_300119 = "從自身周圍<color=#00F6FF>4</color>個方向中選擇1個，向前方3列範圍打出3道雷波，造成<color=#00F6FF>250%</color>的傷害，每道雷波命中目標後傷害降低<color=#00F6FF>40%</color>，最多造成<color=#00F6FF>3</color>次傷害。",
  str_skill_desc_306119 = "從自身周圍<color=#00F6FF>4</color>個方向中選擇1個，向前方3列範圍打出3道雷波，造成<color=#00F6FF>250%</color>的傷害，每道雷波命中目標後傷害降低<color=#00F6FF>20%</color>，最多造成<color=#00F6FF>5</color>次傷害。",
  str_skill_desc_300122 = "選擇1個格子，對<color=#00F6FF>米字形17格</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_305122 = "選擇1個格子，對<color=#00F6FF>米字形17格</color>造成<color=#00F6FF>{1}%</color>的傷害。清除範圍內的<color=#00F6FF>損壞格子</color>效果。",
  str_skill_desc_320122 = "選擇1個格子，對<color=#00F6FF>米字形17格</color>造成<color=#00F6FF>{1}%</color>的傷害，對所選格子造成無視防禦的傷害。",
  str_skill_desc_325122 = "選擇1個格子，對<color=#00F6FF>米字形17格</color>造成<color=#00F6FF>{1}%</color>的傷害，對所選格子造成無視防禦的傷害。清除範圍內的<color=#00F6FF>損壞格子</color>效果。",
  str_skill_desc_330122 = "選擇1個格子，對<color=#00F6FF>米字形17格</color>造成<color=#00F6FF>{1}%</color>的傷害，對所選格子造成無視防禦的傷害。祝福達到10層時主動技能範圍變為<color=#00F6FF>米字形最大</color>。",
  str_skill_desc_3301221 = "選擇1個格子，對<color=#00F6FF>米字形17格</color>造成<color=#00F6FF>{1}%</color>的傷害，對所選格子造成無視防禦的傷害。祝福達到10層時主動技能範圍變為<color=#00F6FF>米字形最大</color>。",
  str_skill_desc_335122 = "選擇1個格子，對<color=#00F6FF>米字形17格</color>造成<color=#00F6FF>{1}%</color>的傷害，對所選格子造成無視防禦的傷害。清除範圍內的<color=#00F6FF>損壞格子</color>效果。祝福達到10層時主動技能範圍變為<color=#00F6FF>米字形最大</color>。",
  str_skill_desc_300121 = "選擇1個格子，隨後以該格子為中心，選擇1個方向伸出藤蔓，蔓延至邊緣格子，對該範圍造成<color=#00F6FF>360%</color>的傷害，並將前<color=#00F6FF>2</color>格轉成<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>。藤蔓每蔓延1格，傷害提升<color=#00F6FF>10%</color>。",
  str_skill_desc_306121 = "選擇1個格子，隨後以該格子為中心，選擇1個方向伸出藤蔓，蔓延至邊緣格子，對該範圍造成<color=#00F6FF>360%</color>的傷害，並將前<color=#00F6FF>3</color>格轉成<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>。藤蔓每蔓延1格，傷害提升<color=#00F6FF>15%</color>。",
  str_skill_desc_320121 = "選擇1個格子，隨後以該格子為中心，選擇1個方向伸出藤蔓，蔓延至邊緣格子，對該範圍造成<color=#00F6FF>360%</color>的傷害，並將前<color=#00F6FF>2</color>格轉成<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>。藤蔓在造成傷害後，會向十字方向各蔓延<color=#00F6FF>3</color>格，每名敵人最多觸發1次蔓延效果。藤蔓每蔓延1格，傷害提升<color=#00F6FF>10%</color>。",
  str_skill_desc_326121 = "選擇1個格子，隨後以該格子為中心，選擇1個方向伸出藤蔓，蔓延至邊緣格子，對該範圍造成<color=#00F6FF>360%</color>的傷害，並將前<color=#00F6FF>3</color>格轉成<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>。藤蔓在造成傷害後會向十字方向各蔓延<color=#00F6FF>3</color>格，每名敵人最多觸發1次蔓延效果。藤蔓每蔓延1格，傷害提升<color=#00F6FF>15%</color>。",
  str_skill_desc_300065 = "瞬移到自身<color=#00F6FF>周圍2圈</color>和全場所有水屬性格子中的任意位置。",
  str_skill_desc_330065 = "瞬移到自身<color=#00F6FF>周圍2圈</color>和全場所有水屬性格子中的任意位置。進入極光時刻後可再施放1次。",
  str_skill_desc_300115 = "瞬移到指定位置，對<color=#00F6FF>周圍2圈</color>及其餘部分格子進行<link=\"30020\"><#FFAE07><u>淨化</u></color></link>；淨化範圍內<color=#00F6FF>3</color>個格子變成<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>。",
  str_skill_desc_305115 = "瞬移到指定位置，對<color=#00F6FF>周圍2圈</color>及其餘部分格子進行<link=\"30020\"><#FFAE07><u>淨化</u></color></link>；淨化範圍內<color=#00F6FF>4</color>個格子變成<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>。",
  str_skill_desc_320115 = "瞬移到指定位置，對<color=#00F6FF>周圍3圈</color>及其餘部分格子進行<link=\"30020\"><#FFAE07><u>淨化</u></color></link>；淨化範圍內<color=#00F6FF>4</color>個格子變成<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>。",
  str_skill_desc_325115 = "瞬移到指定位置，對<color=#00F6FF>周圍3圈</color>及其餘部分格子進行<link=\"30020\"><#FFAE07><u>淨化</u></color></link>，淨化範圍內不超過<color=#00F6FF>5</color>個格子變為<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>。",
  str_skill_desc_300126 = "選擇1個可行走的格子，對<color=#00F6FF>十字形5格</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_303126 = "選擇1個可行走的格子，對<color=#00F6FF>十字形5格</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_306126 = "選擇1個可行走的格子，對<color=#00F6FF>十字形5格</color>造成<color=#00F6FF>{1}%</color>的傷害。進入極光時刻後可再施放1次（每波次觸發1次）。",
  str_skill_desc_310126 = "選擇1個可行走的格子，對<color=#00F6FF>十字形5格</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_313126 = "選擇1個可行走的格子，對<color=#00F6FF>十字形5格</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_316126 = "選擇1個可行走的格子，對<color=#00F6FF>十字形5格</color>造成<color=#00F6FF>{1}%</color>的傷害。進入極光時刻後可再施放1次（每波次觸發1次）。",
  str_skill_desc_320126 = "選擇1個可行走的格子，對<color=#00F6FF>十字形5格</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_323126 = "選擇1個可行走的格子，對<color=#00F6FF>十字形5格</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_326126 = "選擇1個可行走的格子，對<color=#00F6FF>十字形5格</color>造成<color=#00F6FF>{1}%</color>的傷害。進入極光時刻後可再施放1次（每波次觸發1次）。",
  str_skill_desc_300129 = "消耗所有<link=\"30021\"><#FFAE07><u>砧卵</u></color></link>對1名敵人造成傷害，每枚<link=\"30021\"><#FFAE07><u>砧卵</u></color></link>造成<color=#00F6FF>40%</color>的傷害。",
  str_skill_desc_303129 = "消耗所有<link=\"30022\"><#FFAE07><u>砧卵</u></color></link>對1名敵人造成傷害，每枚<link=\"30022\"><#FFAE07><u>砧卵</u></color></link>造成<color=#00F6FF>50%</color>的傷害。",
  str_skill_desc_306129 = "消耗所有<link=\"30023\"><#FFAE07><u>砧卵</u></color></link>對1名敵人造成傷害，每枚<link=\"30023\"><#FFAE07><u>砧卵</u></color></link>造成<color=#00F6FF>50%</color>的傷害。",
  str_skill_desc_300055 = "選擇1個方向攻擊，對該方向上的所有敵人造成<color=#00F6FF>160%</color>的傷害並擊退。",
  str_skill_desc_302055 = "選擇1個方向攻擊，對該方向上的所有敵人造成<color=#00F6FF>160%</color>的傷害並擊退。主動技能上回合就緒，本回合最終傷害增加<color=#00F6FF>60%</color>。",
  str_skill_desc_3020551 = "選擇1個方向攻擊，對該方向上的所有敵人造成<color=#00F6FF>160%</color>的傷害並擊退。主動技能上回合就緒，本回合最終傷害增加<color=#00F6FF>60%</color>。",
  str_skill_desc_305055 = "選擇1個方向攻擊，對該方向上的所有敵人造成<color=#00F6FF>160%</color>的傷害並擊退。敵人每被擊退<color=#00F6FF>1</color>格，最終傷害增加<color=#00F6FF>5%</color>。主動技能上回合就緒，本回合最終傷害增加<color=#00F6FF>60%</color>。",
  str_skill_desc_3050551 = "選擇1個方向攻擊，對該方向上的所有敵人造成<color=#00F6FF>160%</color>的傷害並擊退。敵人每被擊退<color=#00F6FF>1</color>格，最終傷害增加<color=#00F6FF>5%</color>。主動技能上回合就緒，本回合最終傷害增加<color=#00F6FF>60%</color>。",
  str_skill_desc_300120 = "瞬移到指定位置，對<color=#00F6FF>縱向1列</color>造成<color=#00F6FF>{1}%</color>的傷害並擊退敵人。同時將攻擊範圍的格子轉變為森屬性。",
  str_skill_desc_16012001 = "對指定位置縱向1列範圍造成少量傷害並擊退敵人。同時將攻擊範圍內的格子轉變為森屬性。",
  str_skill_desc_16012002 = "擊退指定位置縱向1列範圍內的敵人。同時將範圍內的格子轉變為森屬性。",
  str_skill_desc_303120 = "瞬移到指定位置，對<color=#00F6FF>縱向1列</color>造成<color=#00F6FF>{1}%</color>的傷害並擊退敵人。同時將攻擊範圍的格子轉變為森屬性。",
  str_skill_desc_300123 = "對<color=#00F6FF>周圍1圈</color>內的1名敵人造成<color=#00F6FF>{1}%</color>的傷害。首次命中同一目標時，附加1回合<link=\"10004\"><#FFAE07><u>麻痺</u></color></link>效果。第2次命中附加1回合<color=#00F6FF><color=#00F6FF>眩暈</color></color>效果。",
  str_skill_desc_302123 = "對<color=#00F6FF>周圍1圈</color>內的1名敵人造成<color=#00F6FF>{1}%</color>的傷害。首次命中同一目標時，附加1回合<link=\"10004\"><#FFAE07><u>麻痺</u></color></link>效果。第2次命中附加1回合<color=#00F6FF>眩暈</color>效果。",
  str_skill_desc_305123 = "對<color=#00F6FF>周圍1圈</color>內的1名敵人造成<color=#00F6FF>{1}%</color>的傷害。前2次命中同一目標都附加1回合<color=#00F6FF>眩暈</color>效果。",
  str_skill_desc_320123 = "對<color=#00F6FF>周圍1圈</color>內的1名敵人造成<color=#00F6FF>{1}%</color>的傷害。首次命中同一目標時，附加1回合<link=\"10004\"><#FFAE07><u>麻痺</u></color></link>效果。第2次命中附加1回合<color=#00F6FF>眩暈</color>效果。目標所占格數越多，主動技能傷害越高。",
  str_skill_desc_322123 = "對<color=#00F6FF>周圍1圈</color>內的1名敵人造成<color=#00F6FF>{1}%</color>的傷害。首次命中同一目標時，附加1回合<link=\"10004\"><#FFAE07><u>麻痺</u></color></link>效果。第2次命中附加1回合<color=#00F6FF>眩暈</color>效果。目標所占格數越多，主動技能傷害越高。",
  str_skill_desc_325123 = "對<color=#00F6FF>周圍1圈</color>內的1名敵人造成<color=#00F6FF>{1}%</color>的傷害。前2次命中同一目標都附加1回合<color=#00F6FF>眩暈</color>效果。目標所占格數越多，主動技能傷害越高。",
  str_skill_desc_300015 = "選擇1個可行走的格子，召喚銀城並確定他的方向，向其擲出1顆手榴彈，手榴彈會被銀城按所選擇的方向擊至最遠處。手榴彈行進時對沿途敵人造成<color=#00F6FF>200%</color>的傷害。",
  str_skill_desc_330015 = "選擇1個可行走的格子，召喚銀城並確定他的方向，向其擲出1顆手榴彈，手榴彈會被銀城按所選擇的方向擊至最遠處。手榴彈行進時對沿途敵人造成<color=#00F6FF>200%</color>的傷害。銀城的方向可以為斜向。",
  str_skill_desc_300131 = "為隊伍回復相當於諾維亞<color=#00F6FF>220%</color>攻擊力的生命值，同時獲得相當於諾維亞<color=#00F6FF>90%</color>生命值的護盾。若回復的生命值溢出，對<color=#00F6FF>菱形12格</color>內的敵人造成等同於溢出值的無視防禦傷害。",
  str_skill_desc_306131 = "為隊伍回復相當於諾維亞<color=#00F6FF>220%</color>攻擊力的生命值，同時獲得相當於諾維亞<color=#00F6FF>120%</color>生命值的護盾。若回復的生命值溢出，對<color=#00F6FF>菱形12格</color>內的敵人造成等同於溢出值的無視防禦傷害。",
  str_skill_desc_320131 = "為隊伍回復相當於諾維亞<color=#00F6FF>220%</color>攻擊力的生命值，同時獲得相當於諾維亞<color=#00F6FF>90%</color>生命值的護盾。若回復的生命值溢出，對<color=#00F6FF>周圍2圈</color>內的敵人造成等同於溢出值的無視防禦傷害。進入極光時刻時，將不超過生命值上限的護盾值轉化為生命值。",
  str_skill_desc_326131 = "為隊伍回復相當於諾維亞<color=#00F6FF>220%</color>攻擊力的生命值，同時獲得相當於諾維亞<color=#00F6FF>120%</color>生命值的護盾。若回復的生命值溢出，對<color=#00F6FF>周圍2圈</color>內的敵人造成等同於溢出值的無視防禦傷害。進入極光時刻時，將不超過生命值上限的護盾值轉化為生命值。",
  str_skill_desc_300132 = "任選1名敵人，對其造成<color=#00F6FF>{1}%</color>的傷害。若回合結束時該敵人仍然存活，則該敵人回復等同於本次主動技能傷害的生命值。",
  str_skill_desc_302132 = "任選1名敵人，對其造成<color=#00F6FF>{1}%</color>的傷害。若回合結束時該敵人仍然存活，則該敵人回復等同於本次主動技能傷害的生命值。若回合結束時本次主動技能造成的傷害被回復，則主動技能冷卻回合數<color=#00F6FF>-1</color>。",
  str_skill_desc_305132 = "任選1名敵人，對其造成<color=#00F6FF>{1}%</color>的傷害。若回合結束時該敵人仍然存活，則該敵人回復等同於本次主動技能傷害的生命值。若回合結束時本次主動技能造成的傷害被回復，則主動技能冷卻回合數<color=#00F6FF>-1</color>。",
  str_skill_desc_320132 = "任選1名敵人，對其造成<color=#00F6FF>{1}%</color>的傷害。若回合結束時該敵人仍然存活，則該敵人回復等同於本次主動技能傷害的生命值。進入極光時刻後，回合結束時敵人不會回復。",
  str_skill_desc_3201321 = "任選1名敵人，對其造成<color=#00F6FF>{1}%</color>的傷害。若回合結束時該敵人仍然存活，則該敵人回復等同於本次主動技能傷害的生命值。進入極光時刻後，回合結束時敵人不會回復。",
  str_skill_desc_322132 = "任選1名敵人，對其造成<color=#00F6FF>{1}%</color>的傷害。若回合結束時該敵人仍然存活，則該敵人回復等同於本次主動技能傷害的生命值。若回合結束時本次主動技能造成的傷害被回復，則主動技能冷卻回合數<color=#00F6FF>-1</color>。進入極光時刻後，回合結束時敵人不會回復。",
  str_skill_desc_3221321 = "任選1名敵人，對其造成<color=#00F6FF>{1}%</color>的傷害。若回合結束時該敵人仍然存活，則該敵人回復等同於本次主動技能傷害的生命值。若回合結束時本次主動技能造成的傷害被回復，則主動技能冷卻回合數<color=#00F6FF>-1</color>。進入極光時刻後，回合結束時敵人不會回復。",
  str_skill_desc_325132 = "任選1名敵人，對其造成<color=#00F6FF>{1}%</color>的傷害。若回合結束時該敵人仍然存活，則該敵人回復等同於本次主動技能傷害的生命值。若回合結束時本次主動技能造成的傷害被回復，則主動技能冷卻回合數<color=#00F6FF>-1</color>。進入極光時刻後，回合結束時敵人不會回復。",
  str_skill_desc_3251321 = "任選1名敵人，對其造成<color=#00F6FF>{1}%</color>的傷害。若回合結束時該敵人仍然存活，則該敵人回復等同於本次主動技能傷害的生命值。若回合結束時本次主動技能造成的傷害被回復，則主動技能冷卻回合數<color=#00F6FF>-1</color>。進入極光時刻後，回合結束時敵人不會回復。",
  str_skill_desc_300133 = "選擇1個格子，對<color=#00F6FF>菱形13格</color>造成<color=#00F6FF>{1}%</color>的傷害並擊退敵人。",
  str_skill_desc_302133 = "選擇1個格子，對<color=#00F6FF>菱形13格</color>造成<color=#00F6FF>{1}%</color>的傷害並擊退敵人。",
  str_skill_desc_300137 = "任選1名敵人，將其腳下最多<color=#00F6FF>2</color>個非水屬性格子轉化為水屬性。",
  str_skill_desc_310137 = "任選1名敵人，將其腳下最多<color=#00F6FF>2</color>個非水屬性格子轉化為水屬性。",
  str_skill_desc_304137 = "任選1名敵人，將其腳下最多<color=#00F6FF>3</color>個非水屬性格子轉化為水屬性。",
  str_skill_desc_314137 = "任選1名敵人，將其腳下最多<color=#00F6FF>3</color>個非水屬性格子轉化為水屬性。",
  str_skill_desc_300135 = "從身邊<color=#00F6FF>4</color>個方向中任選1個，然後在其兩側中選擇一個方向掃射，對<color=#00F6FF>45度</color>範圍區域造成<color=#00F6FF>340%</color>攻擊力的傷害，掃射過程中傷害會衰減，最低為初始值的30%。",
  str_skill_desc_302135 = "從身邊<color=#00F6FF>4</color>個方向中任選1個，然後在其兩側中選擇一個方向掃射，對<color=#00F6FF>45度</color>範圍區域造成<color=#00F6FF>340%</color>攻擊力的傷害，掃射過程中傷害會衰減，最低為初始值的30%。",
  str_skill_desc_305135 = "從身邊<color=#00F6FF>4</color>個方向中任選1個，然後在其兩側中選擇一個方向掃射，對<color=#00F6FF>45度</color>範圍區域造成<color=#00F6FF>340%</color>攻擊力的傷害，掃射過程中傷害會衰減，最低為初始值的40%。",
  str_skill_desc_320135 = "從身邊<color=#00F6FF>4</color>個方向中任選1個，然後在其兩側中選擇一個方向掃射，對<color=#00F6FF>90度</color>範圍區域造成<color=#00F6FF>340%</color>攻擊力的傷害，掃射過程中傷害會衰減，最低為初始值的30%。",
  str_skill_desc_322135 = "從身邊<color=#00F6FF>4</color>個方向中任選1個，然後在其兩側中選擇一個方向掃射，對<color=#00F6FF>90度</color>範圍區域造成<color=#00F6FF>340%</color>攻擊力的傷害，掃射過程中傷害會衰減，最低為初始值的30%。",
  str_skill_desc_325135 = "從身邊<color=#00F6FF>4</color>個方向中任選1個，然後在其兩側中選擇一個方向掃射，對<color=#00F6FF>90度</color>範圍區域造成<color=#00F6FF>340%</color>攻擊力的傷害，掃射過程中傷害會衰減，最低為初始值的40%。",
  str_skill_desc_300134 = "選擇一個格子，對該方向沿途及相鄰格子上的敵人造成<color=#00F6FF>{1}%</color>攻擊力的傷害並擊退至最遠。",
  str_skill_desc_303134 = "選擇一個格子，對該方向沿途及相鄰格子上的敵人造成<color=#00F6FF>{1}%</color>攻擊力的傷害並擊退至最遠。",
  str_skill_desc_320134 = "選擇一個格子，對該方向<color=#00F6FF>沿途</color>及<color=#00F6FF>相鄰</color>格子上的敵人造成<color=#00F6FF>{1}%</color>攻擊力的傷害並擊退至最遠，其中<color=#00F6FF>沿途</color>的敵人受到<color=#00F6FF>1.3</color>倍傷害。",
  str_skill_desc_323134 = "選擇一個格子，對該方向<color=#00F6FF>沿途</color>及<color=#00F6FF>相鄰</color>格子上的敵人造成<color=#00F6FF>{1}%</color>攻擊力的傷害並擊退至最遠，其中<color=#00F6FF>沿途</color>的敵人受到<color=#00F6FF>1.3</color>倍傷害。",
  str_skill_desc_300136 = "對全體敵人造成<color=#00F6FF>{1}%</color>的傷害，同時對位於森屬性格子上的敵人附加<link=\"10006\"><#FFAE07><u>緩速</u></color></link>狀態，持續2回合。",
  str_skill_desc_302136 = "對全體敵人造成<color=#00F6FF>{1}%</color>的傷害，同時對位於森屬性格子上的敵人附加<link=\"10006\"><#FFAE07><u>緩速</u></color></link>狀態，持續2回合。",
  str_skill_desc_320136 = "對全體敵人造成<color=#00F6FF>{1}%</color>的傷害，同時對位於森屬性格子上的敵人附加<link=\"10006\"><#FFAE07><u>緩速</u></color></link>狀態，持續2回合。主動技能造成傷害前，對敵人附加<color=#00F6FF>2層</color>凡塵印記。",
  str_skill_desc_322136 = "對全體敵人造成<color=#00F6FF>{1}%</color>的傷害，同時對位於森屬性格子上的敵人附加<link=\"10006\"><#FFAE07><u>緩速</u></color></link>狀態，持續2回合。主動技能造成傷害前，對敵人附加<color=#00F6FF>2層</color>凡塵印記。",
  str_skill_desc_325136 = "對全體敵人造成<color=#00F6FF>{1}%</color>的傷害，同時對位於森屬性格子上的敵人附加<link=\"10006\"><#FFAE07><u>緩速</u></color></link>狀態，持續2回合。主動技能造成傷害前，對敵人附加<color=#00F6FF>3層</color>凡塵印記。",
  str_skill_passive_desc_410022 = "主動技能傷害增加<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_410051 = "主動技能傷害增加<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_410047 = "連鎖技能恢復係數增加<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_410049 = "<color=#00F6FF>{1}</color>機率連鎖技能傷害增加<color=#00F6FF>50%</color>。",
  str_skill_passive_desc_410050 = "連鎖技能傷害增加<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_410052 = "主動技能有<color=#00F6FF>{1}</color>機率<link=\"10006\"><#FFAE07><u>緩速</u></color></link>敵人，持續2回合。",
  str_skill_passive_desc_410074 = "主動技能傷害增加<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_410008 = "使用主動技能後，小不點本回合的普通攻擊傷害增加<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_410007 = "施放連鎖技能時，對往返攻擊的首個敵人傷害增加<color=#00F6FF>{1}</color>，並附加1層中毒效果，持續2回合。",
  str_skill_passive_desc_410032 = "主動技能每道閃電有<color=#00F6FF>15%</color>機率額外造成<color=#00F6FF>{1}</color>的傷害。",
  str_skill_passive_desc_410053 = "主動技能就緒時，連鎖技能增加<color=#00F6FF>{1}</color>的傷害。",
  str_skill_passive_desc_410058 = "回合結束時，若旗幟存在，則為隊伍恢復等同於艾米<color=#00F6FF>{1}</color>倍防禦的生命值。",
  str_skill_passive_desc_400035 = "使用位移技能後，阿褐本回合普通攻擊傷害增加<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_410035 = "使用位移技能後，阿褐本回合普通攻擊傷害增加<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_420035 = "使用位移技能後，阿褐本回合普通攻擊和連鎖傷害增加<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_410017 = "我方光靈擊退敵人時，菈比將對其造成<color=#00F6FF>{1}</color>攻擊力的傷害，無視防禦。",
  str_skill_passive_desc_430017 = "我方光靈擊退敵人時，菈比將對其造成<color=#00F6FF>{1}</color>攻擊力的傷害，無視防禦，敵人每被擊退1格增加<color=#00F6FF>10%</color>傷害，無視防禦。",
  str_skill_passive_desc_410040 = "每回合開始時獲得1層黏膠印記。連鎖技能命中敵人時，每層印記有<color=#00F6FF>{1}</color>機率使目標<link=\"10002\"><#FFAE07><u>灼燒</u></color></link>2回合。每波次開始時清空印記。",
  str_skill_passive_desc_420040 = "每回合開始和使用主動技能時會獲得1層黏膠印記。連鎖技能命中敵人時，每層印記有<color=#00F6FF>{1}</color>機率使目標<link=\"10002\"><#FFAE07><u>灼燒</u></color></link>2回合。每波次開始時清空印記。",
  str_skill_passive_desc_410041 = "生命值全滿時，白蘭的攻擊增加<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_420041 = "生命值大於70%時，白蘭的攻擊增加<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_430041 = "生命值大於70%時，白蘭的攻擊增加<color=#00F6FF>{1}</color>，其他出戰的水屬性光靈增加相當於白蘭<color=#00F6FF>{2}</color>攻擊力的攻擊。",
  str_skill_passive_desc_410021 = "主動技能未就緒時，連鎖技能的傷害增加<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_420021 = "主動技能未就緒時，連鎖技能的傷害增加<color=#00F6FF>{1}</color>，普通攻擊傷害增加<color=#00F6FF>{2}</color>。",
  str_skill_passive_desc_410004 = "隊伍生命上限增加<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_410073 = "在連線起點位置額外施放1次連鎖技能，傷害是正常的<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_430073 = "在連線起點位置額外施放1次連鎖技能，傷害是正常的<color=#00F6FF>{1}</color>。起點連鎖與本體連鎖攻擊範圍重疊時，起點連鎖重疊區域傷害增加<color=#00F6FF>100%</color>。",
  str_skill_passive_desc_410061 = "每次施放主動技能時會獲得1層低落印記，最多<color=#00F6FF>3</color>層。每層印記會增加1次主動技能傷害次數，減少<color=#00F6FF>{1}</color>最終傷害。",
  str_skill_passive_desc_420061 = "每次施放主動技能會獲得1層低落印記，最多<color=#00F6FF>5</color>層。每層印記會增加1次主動技能傷害次數，減少<color=#00F6FF>{1}</color>最終傷害。每層印記增加<color=#00F6FF>5%</color>連鎖傷害。",
  str_skill_passive_desc_430061 = "每次施放主動技能會獲得1層低落印記，最多<color=#00F6FF>5</color>層。每層印記會增加1次主動技能傷害次數，減少<color=#00F6FF>{1}</color>最終傷害。每層印記增加<color=#00F6FF>5%</color>連鎖傷害。",
  str_skill_passive_desc_414061 = "每次施放主動技能時會獲得1層低落印記，最多<color=#00F6FF>3</color>層。每層印記會增加1次主動技能傷害次數，減少<color=#00F6FF>{1}</color>最終傷害。",
  str_skill_passive_desc_424061 = "每次施放主動技能會獲得1層低落印記，最多<color=#00F6FF>5</color>層。每層印記會增加1次主動技能傷害次數，減少<color=#00F6FF>{1}</color>最終傷害。每層印記增加<color=#00F6FF>5%</color>連鎖傷害。",
  str_skill_passive_desc_434061 = "每次施放主動技能會獲得1層低落印記，最多<color=#00F6FF>5</color>層。每層印記會增加1次主動技能傷害次數，減少<color=#00F6FF>{1}</color>最終傷害。每層印記增加<color=#00F6FF>5%</color>連鎖傷害。",
  str_skill_passive_desc_410054 = "若燈盞持續至回合結束時才消失，對<color=#00F6FF>周圍1圈</color>施放光芒並造成<color=#00F6FF>{1}</color>的傷害，有<color=#00F6FF>{2}</color>機率<link=\"10005\"><#FFAE07><u>致盲</u></color></link>敵人1回合。",
  str_skill_passive_desc_430054 = "若燈盞存在，會於每回合結束時施放光芒，對<color=#00F6FF>周圍1圈</color>造成<color=#00F6FF>{1}</color>傷害，並有<color=#00F6FF>{2}</color>機率<link=\"10005\"><#FFAE07><u>致盲</u></color></link>敵人1回合。",
  str_skill_passive_desc_410016 = "每經過1個雷屬性格子可獲得1層蓄能，最多疊加99層。每層蓄能會增加<color=#00F6FF>{1}</color>主動技能傷害，施放主動技能後，蓄能會清空。",
  str_skill_passive_desc_410046 = "每層奚笑印記會增加雷屬性光靈<color=#00F6FF>{1}</color>普通攻擊傷害。",
  str_skill_passive_desc_430046 = "擊殺帶有奚笑印記的敵人後，所有剩餘敵人的印記層數<color=#00F6FF>+1</color>。每層印記增加雷屬性光靈<color=#00F6FF>{1}</color>普通攻擊傷害。",
  str_skill_passive_desc_410044 = "連鎖技能對所有敵人造成傷害時，雷屬性光靈本回合會獲得薇薇安<color=#00F6FF>{1}</color>攻擊力的攻擊加成。",
  str_skill_passive_desc_430044 = "連鎖技能對所有敵人造成傷害時，水、雷屬性以及啟光陣營的光靈獲得等同於薇薇安<color=#00F6FF>{1}</color>攻擊力的攻擊加成，持續2回合。",
  str_skill_passive_desc_410048 = "烈雀對位於雷屬性格子上的敵人的傷害增加<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_430048 = "烈雀對位於雷屬性格子上的敵人的傷害增加<color=#00F6FF>{1}</color>，隊伍中其他雷屬性光靈獲得<color=#00F6FF>一半</color>加成。",
  str_skill_passive_desc_410009 = "每回合開始時，有<color=#00F6FF>{1}</color>機率為敵人附加<link=\"10003\"><#FFAE07><u>恐懼</u></color></link>狀態，持續1回合。",
  str_skill_passive_desc_420009 = "每回合開始時，有<color=#00F6FF>{1}</color>的機率<link=\"10003\"><#FFAE07><u>恐懼</u></color></link>敵人1回合。擊殺<link=\"10003\"><#FFAE07><u>恐懼</u></color></link>狀態的敵人時會觸發爆炸，對周圍1圈敵人造成<color=#00F6FF>10%</color>最大生命的傷害。",
  str_skill_passive_desc_410012 = "連鎖技能命中1個敵人可獲得1層裁決印記，每層印記可增加自身<color=#00F6FF>{1}</color>防禦，回合結束後印記消失。",
  str_skill_passive_desc_420012 = "連鎖技能命中1個敵人可獲得1層裁決印記（主動技能獲得2層），每層印記可增加自身<color=#00F6FF>{1}</color>的防禦。回合結束時保留一半的印記層數。",
  str_skill_passive_desc_430012 = "連鎖技能命中1名敵人可獲得1層裁決印記（主動技能獲得2層），每層印記提高自身<color=#00F6FF>3%</color>的攻擊和<color=#00F6FF>{1}</color>的防禦。回合結束時保留一半印記層數。",
  str_skill_passive_desc_410013 = "護盾消失時，將剩餘護盾值的<color=#00F6FF>{1}</color>轉化為生命。",
  str_skill_passive_desc_430013 = "護盾消失時，將剩餘護盾值的<color=#00F6FF>{1}</color>轉化為生命。擁有護盾時，諾爾的防禦增加<color=#00F6FF>50%</color>。",
  str_skill_passive_desc_410018 = "連鎖技能對距離愈近的敵人傷害愈高，傷害最多增加<color=#00F6FF>{1}</color>。與敵人距離超過3格時無加成。",
  str_skill_passive_desc_420018 = "主動技能和連鎖技能對距離愈近的敵人傷害愈高，傷害最多增加<color=#00F6FF>{1}</color>。與敵人距離超過3圈時無加成。",
  str_skill_passive_desc_430018 = "<color=#00F6FF>周圍1圈</color>範圍內每有1個敵人，提高<color=#00F6FF>5%</color>攻擊力。主動技能和連鎖技能對距離越近的敵人傷害越高，傷害最多增加<color=#00F6FF>{1}</color>。與敵人距離超過3圈無加成。",
  str_skill_passive_desc_410033 = "薇絲每次造成傷害都會獲得1層瞄定印記，每層印記增加<color=#00F6FF>{1}</color>的傷害，回合結束後印記會清空。",
  str_skill_passive_desc_430033 = "薇絲每次造成傷害都會獲得1層瞄定印記，每層印記增加<color=#00F6FF>{1}</color>的傷害（連鎖技能增加<color=#00F6FF>{2}</color>），回合結束後印記會清空。",
  str_skill_passive_desc_410036 = "每回合開始時，獲得1個狼魂。首次受到攻擊時，消耗1個狼魂對目標造成相當於修拉德<color=#00F6FF>{1}</color>攻擊力的傷害，無視防禦。回合結束狼魂清空。",
  str_skill_passive_desc_420036 = "每回合開始時，獲得1個狼魂。受到攻擊時，會消耗1個狼魂對目標造成相當於修拉德<color=#00F6FF>{1}</color>攻擊力的傷害，無視防禦。回合結束後狼魂<color=#00F6FF>不清空</color>。",
  str_skill_passive_desc_410010 = "觸發<link=\"30010\"><#FFAE07><u>極光時刻</u></color></link>時，立刻為隊伍恢復等同於露易絲<color=#00F6FF>{1}</color>生命上限的生命值。",
  str_skill_passive_desc_420010 = "觸發<link=\"30010\"><#FFAE07><u>極光時刻</u></color></link>時，立刻為隊伍回復等同露易絲<color=#00F6FF>{1}</color>生命上限的生命值。同時露易絲的防禦增加<color=#00F6FF>50%</color>，持續2回合。",
  str_skill_passive_desc_410014 = "出戰成員每擁有1名雷屬性或白夜城陣營的光靈，舒瓦茲的防禦增加<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_430014 = "出戰成員中，每有1名雷屬性或白夜城陣營的光靈，舒瓦茲的防禦增加{1}（同時增加攻擊，等同於所提升的防禦數值）。",
  str_skill_passive_desc_410078 = "知更對位於森屬性格子上的敵人造成的傷害增加<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_430078 = "知更對位於森屬性格子上的敵人造成的傷害增加<color=#00F6FF>{1}</color>，隊伍中其他森屬性光靈獲得<color=#00F6FF>一半</color>加成。",
  str_skill_passive_desc_410076 = "施放連鎖後，觸碰周圍<color=#00F6FF>十字形4格</color>生命最低的敵人，若生命低於<color=#00F6FF>{1}</color>，則對該敵人附加<link=\"10003\"><#FFAE07><u>恐懼</u></color></link>狀態，持續1回合。",
  str_skill_passive_desc_420076 = "施放連鎖後，對自身<color=#00F6FF>十字形4格</color>生命最低且低於<color=#00F6FF>{1}</color>的敵人附加1回合的<link=\"10003\"><#FFAE07><u>恐懼</u></color></link>狀態。擊殺<link=\"10003\"><#FFAE07><u>恐懼</u></color></link>狀態敵人有<color=#00F6FF>50%</color>的機率<link=\"10003\"><#FFAE07><u>恐懼</u></color></link>其周圍<color=#00F6FF>十字形4格</color>敵人。",
  str_skill_passive_desc_410042 = "普通攻擊可射擊斜方向，造成<color=#00F6FF>{1}</color>的傷害。",
  str_skill_passive_desc_420042 = "普通攻擊對斜方向敵人造成<color=#00F6FF>{1}</color>的傷害，並對其附加火力印記，持續2回合。巴頓對帶有印記的敵人的普通攻擊傷害增加<color=#00F6FF>10%</color>。",
  str_skill_passive_desc_430042 = "普通攻擊對斜方向敵人造成<color=#00F6FF>{1}</color>的傷害，並對其附加火力印記，持續2回合。巴頓對帶有印記的敵人的<color=#00F6FF>所有傷害</color>增加<color=#00F6FF>10%</color>。",
  str_skill_passive_desc_410001 = "戰鬥開始時可獲得鏡界印記，印記存在時娜席里絲的防禦增加<color=#00F6FF>{1}</color>，損失生命時印記消失。<color=#00F6FF>使用主動技能</color>時可以重設印記。",
  str_skill_passive_desc_420001 = "戰鬥開始時可獲得鏡界印記，印記存在時娜席里絲的防禦增加<color=#00F6FF>{1}</color>，損失生命時印記消失。<color=#00F6FF>使用主動技能或進入極光時刻</color>時可以重設印記。",
  str_skill_passive_desc_410011 = "普通攻擊對敵人附加1層龍牙印記，最多疊加<color=#00F6FF>4</color>層。每層提高希羅娜連鎖技能<color=#00F6FF>{1}</color>最終傷害。",
  str_skill_passive_desc_430011 = "普通攻擊對敵人附加1層龍牙印記，最多疊加<color=#00F6FF>6</color>層。每層提高希羅娜<color=#00F6FF>主動技能</color>和連鎖技能<color=#00F6FF>{1}</color>最終傷害。",
  str_skill_passive_desc_440011 = "普通攻擊對敵人附加1層龍牙印記，最多疊加<color=#00F6FF>7</color>層。每層增加希羅娜<color=#00F6FF>主動技能</color>和連鎖技能<color=#00F6FF>5%</color>的最終傷害。",
  str_skill_passive_desc_410019 = "若連鎖技能命中帶有<link=\"10000\"><#FFAE07><u>流血</u></color></link>狀態的敵人，每層<link=\"10000\"><#FFAE07><u>流血</u></color></link>可恢復維多利亞最大生命值<color=#00F6FF>{1}</color>的生命值。",
  str_skill_passive_desc_420019 = "若連鎖技能命中帶有<link=\"10000\"><#FFAE07><u>流血</u></color></link>狀態的敵人，每層<link=\"10000\"><#FFAE07><u>流血</u></color></link>可恢復維多利亞最大生命值<color=#00F6FF>{1}</color>的生命值。",
  str_skill_passive_desc_430019 = "連鎖技能命中帶有<link=\"10000\"><#FFAE07><u>流血</u></color></link>狀態的敵人時，每層<link=\"10000\"><#FFAE07><u>流血</u></color></link>回復維多利亞<color=#00F6FF>{1}</color>生命值，若敵人生命值百分比高於隊伍，則回復效果增加<color=#00F6FF>50%</color>。",
  str_skill_passive_desc_410023 = "施放連鎖技能可獲得1層顫慄印記，最多<color=#00F6FF>5</color>層。每層印記增加<color=#00F6FF>{1}</color>主動技能傷害。使用主動技能可<link=\"10003\"><#FFAE07><u>恐懼</u></color></link>等同於印記層數的敵人<color=#00F6FF>1</color>回合，<color=#00F6FF>印記不會清空</color>。",
  str_skill_passive_desc_430023 = "施放連鎖技能可獲得1層顫慄印記，最多<color=#00F6FF>5</color>層。每層印記增加<color=#00F6FF>{1}</color>主動技能傷害。使用主動技能可<link=\"10003\"><#FFAE07><u>恐懼</u></color></link>等同於印記層數的敵人<color=#00F6FF>1</color>回合，<color=#00F6FF>印記不會清空</color>。若施放連鎖技能前已有5層印記，本次連鎖技能額外對最靠近的1名敵人造成傷害。",
  str_skill_passive_desc_410002 = "每回合開始時，緋進入居合狀態。下次普通攻擊時對敵人造成<color=#00F6FF>{1}</color>傷害，並對其周圍<color=#00F6FF>十字形4格</color>的敵人造成<color=#00F6FF>{2}</color>傷害。",
  str_skill_passive_desc_420002 = "回合開始或經過<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>時，緋進入居合狀態。下次普通攻擊對敵人造成<color=#00F6FF>{1}</color>傷害，並對其周圍<color=#00F6FF>十字形4格</color>的敵人造成<color=#00F6FF>{2}</color>傷害。",
  str_skill_passive_desc_430002 = "回合開始或經過<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>時，緋進入居合狀態。下次普通攻擊對敵人造成<color=#00F6FF>{1}</color>傷害，並對其周圍<color=#00F6FF>十字形4格</color>的敵人造成<color=#00F6FF>{2}</color>傷害。本回合每施放1次居合勢，攻擊增加<color=#00F6FF>4%</color>，最高增加<color=#00F6FF>20%</color>。",
  str_skill_passive_desc_410005 = "蜜雅主動技能擊殺敵人後獲得1層靈魂，最多5層。每層靈魂對單一敵人施放1次<color=#00F6FF>{1}</color>攻擊力的衝擊。",
  str_skill_passive_desc_420005 = "蜜雅使用主動技能擊殺敵人後會獲得1層靈魂，最多5層。每層靈魂對單一敵人施放1次<color=#00F6FF>{1}</color>攻擊力的衝擊，並增加蜜雅<color=#00F6FF>5%</color>的連鎖傷害和<color=#00F6FF>3%</color>的普通攻擊傷害。",
  str_skill_passive_desc_430005 = "<color=#00F6FF>光靈</color>主動技能擊殺敵人後獲得1層靈魂，最大<color=#00F6FF>7</color>層。每層靈魂對單個敵人施放1次<color=#00F6FF>{1}</color>攻擊力的衝擊，並增加蜜雅<color=#00F6FF>5%</color>的連鎖傷害和<color=#00F6FF>3%</color>的普通攻擊傷害。",
  str_skill_passive_desc_410006 = "在水屬性格子上每移動1格，卡蓮本回合基礎攻擊力提高<color=#00F6FF>{1}</color>（最高不超過<color=#00F6FF>{2}</color>）。",
  str_skill_passive_desc_420006 = "在水屬性格子上每移動1格，卡蓮本回合基礎攻擊力提高<color=#00F6FF>{1}</color>（最高不超過<color=#00F6FF>{2}</color>）。施放主動技能後，加成效果變為2倍。",
  str_skill_passive_desc_430006 = "在水屬性格子上每移動1格，卡蓮本回合的攻擊提高<color=#00F6FF>{1}</color>（最高不超過<color=#00F6FF>{2}</color>），施放主動技能後，加成效果加倍。卡蓮在水屬性格子上的普通攻擊會貫穿敵人，對敵人身後1格上的目標造成<color=#00F6FF>40%</color>的傷害。",
  str_skill_passive_desc_410025 = "普通攻擊附加攻擊力<color=#00F6FF>{1}</color>的傷害，可無視防禦。",
  str_skill_passive_desc_430025 = "普通攻擊<color=#00F6FF>可攻擊斜方向</color>，普通攻擊附加攻擊力<color=#00F6FF>{1}</color>的傷害，可無視防禦。",
  str_skill_passive_desc_410026 = "每層<link=\"10002\"><#FFAE07><u>灼燒</u></color></link>狀態增加火屬性光靈<color=#00F6FF>{1}</color>傷害。",
  str_skill_passive_desc_430026 = "每回合開始時，對位於火屬性格子的敵人附加1層<link=\"10002\"><#FFAE07><u>灼燒</u></color></link>狀態，持續2回合。每層<link=\"10002\"><#FFAE07><u>灼燒</u></color></link>狀態增加火屬性光靈<color=#00F6FF>{1}</color>傷害。",
  str_skill_passive_desc_410028 = "每當地圖生成水格子時，每個格子為隊伍恢復等同於拉斐爾生命最大值<color=#00F6FF>{1}</color>的生命值。",
  str_skill_passive_desc_420028 = "每當地圖生成水格子時，每個格子為隊伍恢復等同於拉斐爾最大生命值<color=#00F6FF>{1}</color>的生命值。隊伍生命值越低，恢復效果越高，最多提供<color=#00F6FF>100%加成</color>。",
  str_skill_passive_desc_410029 = "本回合每次經過<color=#00F6FF>{1}</color>個森屬性格子，生成的格子必會出現1個<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>。",
  str_skill_passive_desc_430029 = "本回合每次經過<color=#00F6FF>{1}</color>個森屬性格子，生成的格子必會出現1個<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>，並且優先強化森屬性格子。",
  str_skill_passive_desc_410038 = "每3回合獲得1次磁暴，下次連鎖技能對範圍內的1個敵人額外造成<color=#00F6FF>{1}</color>的傷害，並附加<link=\"10004\"><#FFAE07><u>麻痺</u></color></link>狀態，持續1回合。",
  str_skill_passive_desc_420038 = "每3回合獲得1次磁暴，下次連鎖技能對範圍內的1個敵人額外造成<color=#00F6FF>{1}</color>的傷害，並附加1回合的<link=\"10004\"><#FFAE07><u>麻痺</u></color></link>狀態。有<color=#00F6FF>50%</color>機率再攻擊1個敵人。",
  str_skill_passive_desc_430038 = "戰鬥開始時獲得磁暴（每3回合1次），下次連鎖技能對範圍內1個敵人額外造成<color=#00F6FF>{1}</color>的傷害，並附加<link=\"10004\"><#FFAE07><u>麻痺</u></color></link>狀態。有<color=#00F6FF>50%</color>機率再攻擊1個敵人。",
  str_skill_passive_desc_410077 = "施放過主動技能的光靈，本回合獲得伯利恆基礎攻擊力<color=#00F6FF>{1}</color>的加成。",
  str_skill_passive_desc_420077 = "本回合施放過主動技能的光靈獲得伯利恆基礎攻擊力<color=#00F6FF>{1}</color>的加成。進入極光時刻後，本回合內全隊額外獲得伯利恆基礎攻擊力<color=#00F6FF>{2}</color>的加成。",
  str_skill_passive_desc_430077 = "本回合施放過主動技能的光靈獲得伯利恆基礎攻擊力<color=#00F6FF>{1}</color>的加成，同時伯利恆獲得<color=#00F6FF>{2}</color>基礎攻擊力的加成。伯利恆單回合內獲得的攻擊加成可疊加。進入極光時刻後，本回合內全隊額外獲得伯利恆基礎攻擊力<color=#00F6FF>{2}</color>的加成。",
  str_skill_passive_desc_400092 = "被標記的敵人死亡時，獲得其生命上限<color=#00F6FF>{1}</color>的生命上限提高和<link=\"30007\"><#FFAE07><u>恢復效果</u></color></link>。",
  str_skill_passive_desc_410092 = "被標記的敵人死亡時，獲得其生命上限<color=#00F6FF>{1}</color>的生命上限提高和<link=\"30007\"><#FFAE07><u>恢復效果</u></color></link>。",
  str_skill_passive_desc_420092 = "被標記的敵人死亡時，獲得其生命上限<color=#00F6FF>{1}</color>的生命上限提高和<link=\"30007\"><#FFAE07><u>恢復效果</u></color></link>，同時將敵人所處位置最多1個格子轉變為<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>。",
  str_skill_passive_desc_400075 = "普通攻擊有<color=#00F6FF>{1}</color>機率附加1層<link=\"10001\"><#FFAE07><u>中毒</u></color></link>狀態，持續2回合。",
  str_skill_passive_desc_410075 = "普通攻擊有<color=#00F6FF>{1}</color>機率附加1層<link=\"10001\"><#FFAE07><u>中毒</u></color></link>狀態，持續2回合。",
  str_skill_passive_desc_430075 = "普通攻擊<color=#00F6FF>可攻擊斜方向</color>的敵人，且有<color=#00F6FF>{1}</color>機率附加1層<link=\"10001\"><#FFAE07><u>中毒</u></color></link>狀態，持續2回合。",
  str_skill_passive_desc_400086 = "每次經過森屬性<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>時，立即恢復尤萊雅<color=#00F6FF>{1}</color>防禦的生命值。",
  str_skill_passive_desc_410086 = "每次經過森屬性<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>時，立即恢復尤萊雅<color=#00F6FF>{1}</color>防禦的生命值。",
  str_skill_passive_desc_400068 = "光靈瞬移時，落點位置與起點位置每間隔1圈，可使溫蒂獲得1層印記。每層印記能使溫蒂下次普通攻擊傷害提高<color=#00F6FF>{1}</color>，普通攻擊後印記清空。",
  str_skill_passive_desc_410068 = "光靈瞬移時，落點位置與起點位置每間隔1圈，可使溫蒂獲得1層印記。每層印記能使溫蒂下次普通攻擊傷害提高<color=#00F6FF>{1}</color>，普通攻擊後印記清空。",
  str_skill_passive_desc_430068 = "光靈瞬移時，落點位置與起點位置每間隔1圈，可使溫蒂獲得1層印記。每層印記使溫蒂的下次普通攻擊傷害增加<color=#00F6FF>{1}</color>，普通攻擊後保留<color=#00F6FF>30%</color>的印記層數。",
  str_skill_passive_desc_400082 = "連鎖技能有<color=#00F6FF>{1}</color>的機率為敵人附加1層<link=\"10001\"><#FFAE07><u>中毒</u></color></link>狀態，持續2回合。",
  str_skill_passive_desc_410082 = "連鎖技能有<color=#00F6FF>{1}</color>的機率為敵人附加1層<link=\"10001\"><#FFAE07><u>中毒</u></color></link>狀態，持續2回合。",
  str_skill_passive_desc_400057 = "每回合開始時，為隊伍恢復等同於菲莉詩<color=#00F6FF>{1}</color>的攻擊力和隊伍已損失生命<color=#00F6FF>{2}</color>的生命值。",
  str_skill_passive_desc_410057 = "每回合開始時，為隊伍恢復等同於菲莉詩<color=#00F6FF>{1}</color>的攻擊力和隊伍已損失生命<color=#00F6FF>{2}</color>的生命值。",
  str_skill_passive_desc_430057 = "每回合開始時，為隊伍恢復等同於菲莉詩<color=#00F6FF>{1}</color>攻擊力和隊伍已損失生命<color=#00F6FF>{2}</color>的生命值。隊伍每損失<color=#00F6FF>5%</color>的生命值，菲莉詩的攻擊會增加<color=#00F6FF>1%</color>。",
  str_skill_passive_desc_400091 = "施放主動技能和連鎖技能時，降低自身<color=#00F6FF>周圍1圈</color>內的敵人<color=#00F6FF>{1}</color>的攻擊，持續1回合。",
  str_skill_passive_desc_410091 = "施放主動技能和連鎖技能時，降低自身<color=#00F6FF>周圍1圈</color>內的敵人<color=#00F6FF>{1}</color>的攻擊，持續1回合。",
  str_skill_passive_desc_420091 = "施放主動技能和連鎖技能時，降低自身<color=#00F6FF>周圍1圈</color>內的敵人<color=#00F6FF>{1}</color>的攻擊，持續1回合。",
  str_skill_passive_desc_430091 = "施放主動技能和連鎖技能時，降低自身<color=#00F6FF>周圍2圈</color>內的敵人<color=#00F6FF>{1}</color>的攻擊和防禦，持續1回合。",
  str_skill_passive_desc_400079 = "若目標生命值百分比高於我方，被攻擊時會將米潔妮<color=#00F6FF>{1}</color>的攻擊轉為防禦。",
  str_skill_passive_desc_410079 = "若目標生命值百分比高於我方，被攻擊時會將米潔妮<color=#00F6FF>{1}</color>的攻擊轉為防禦。",
  str_skill_passive_desc_420079 = "若目標生命值百分比高於我方，被攻擊時會將米潔妮<color=#00F6FF>{1}</color>的攻擊轉為防禦；若米潔妮造成傷害，米潔妮會將同等百分比的防禦轉為攻擊。",
  str_skill_passive_desc_400085 = "主動技能對敵人造成傷害時，敵人每損失<color=#00F6FF>{1}</color>的生命值，最終傷害增加<color=#00F6FF>10%</color>。",
  str_skill_passive_desc_410085 = "主動技能對敵人造成傷害時，敵人每損失<color=#00F6FF>{1}</color>的生命值，最終傷害增加<color=#00F6FF>10%</color>。",
  str_skill_passive_desc_400089 = "每次經過<link=\"30001\"><#FFAE07><u>稜鏡格子</u></color></link>，便能獲得1層金澤印記。每層印記增加<color=#00F6FF>{1}</color>連鎖傷害。",
  str_skill_passive_desc_410089 = "每次經過<link=\"30001\"><#FFAE07><u>稜鏡格子</u></color></link>，便能獲得1層金澤印記。每層印記增加<color=#00F6FF>{1}</color>連鎖傷害。",
  str_skill_passive_desc_420089 = "每次經過<link=\"30001\"><#FFAE07><u>稜鏡格子</u></color></link>，便能獲得1層金澤印記。每層印記增加<color=#00F6FF>{1}</color>的連鎖傷害和<color=#00F6FF>3%</color>的普通攻擊傷害。",
  str_skill_passive_desc_430089 = "每次經過<link=\"30001\"><#FFAE07><u>稜鏡格子</u></color></link>，便能獲得1層金澤印記。每層印記增加<color=#00F6FF>{1}</color>連鎖傷害和<color=#00F6FF>3%</color>普通攻擊傷害。若觸發<link=\"30010\"><#FFAE07><u>極光時刻</u></color></link>，起點格子會轉變成<link=\"30001\"><#FFAE07><u>稜鏡格子</u></color></link>。",
  str_skill_passive_desc_400027 = "每回合開始時獲得1層靜雷印記。普通攻擊時消耗1層印記，額外傷害敵人<color=#00F6FF>{1}</color>目前生命值。",
  str_skill_passive_desc_410027 = "每回合開始時獲得1層靜雷印記。普通攻擊時消耗1層印記，額外傷害敵人<color=#00F6FF>{1}</color>目前生命值。",
  str_skill_passive_desc_420027 = "回合開始、施放主動技能和連鎖技能時獲得1層靜雷印記。普通攻擊時消耗1層印記，額外傷害敵人<color=#00F6FF>{1}</color>目前生命值。",
  str_skill_passive_desc_400060 = "午時狀態下，普通攻擊對敵人周圍<color=#00F6FF>十字形4格</color>範圍內的目標造成<color=#00F6FF>{1}</color>的<link=\"30015\"><#FFAE07><u>濺射</u></color></link>傷害。",
  str_skill_passive_desc_410060 = "午時狀態下，普通攻擊對敵人周圍<color=#00F6FF>十字形4格</color>範圍內的目標造成<color=#00F6FF>{1}</color>的<link=\"30015\"><#FFAE07><u>濺射</u></color></link>傷害。",
  str_skill_passive_desc_420060 = "午時狀態下，普通攻擊傷害增加<color=#00F6FF>20%</color>，同時普通攻擊對敵人周圍<color=#00F6FF>十字形4格</color>範圍內的目標造成<color=#00F6FF>{1}</color>的<link=\"30015\"><#FFAE07><u>濺射</u></color></link>傷害。",
  str_skill_passive_desc_430060 = "午時狀態下，普通攻擊傷害增加<color=#00F6FF>20%</color>，同時普通攻擊對敵人周圍<color=#00F6FF>十字形4格</color>範圍內的目標造成<color=#00F6FF>{1}</color>的<link=\"30015\"><#FFAE07><u>濺射</u></color></link>傷害。",
  str_skill_passive_desc_400064 = "可<link=\"30008\"><#FFAE07><u>儲備彈藥</u></color></link>。連鎖技能每造成1次傷害，消耗1顆彈藥（超載狀態下每次最多消耗<color=#00F6FF>3</color>顆）。每消耗1顆彈藥，增加<color=#00F6FF>{1}</color>最終傷害。",
  str_skill_passive_desc_410064 = "可<link=\"30008\"><#FFAE07><u>儲備彈藥</u></color></link>。連鎖技能每造成1次傷害，消耗1顆彈藥（超載狀態下每次最多消耗<color=#00F6FF>3</color>顆）。每消耗1顆彈藥，增加<color=#00F6FF>{1}</color>最終傷害。",
  str_skill_passive_desc_430064 = "可<link=\"30009\"><#FFAE07><u>儲備彈藥</u></color></link>。連鎖技能每造成1次傷害，消耗1顆彈藥（超載狀態下每次最多消耗<color=#00F6FF>3</color>顆）。每消耗1顆彈藥，增加<color=#00F6FF>{1}</color>最終傷害。",
  str_skill_passive_desc_400070 = "普通攻擊有<color=#00F6FF>{1}</color>機率觸發1次紅龍攻擊，傷害為莉奧娜普通攻擊傷害的<color=#00F6FF>50%</color>。",
  str_skill_passive_desc_410070 = "普通攻擊有<color=#00F6FF>{1}</color>機率觸發1次紅龍攻擊，傷害為莉奧娜普通攻擊傷害的<color=#00F6FF>50%</color>。",
  str_skill_passive_desc_420070 = "普通攻擊有<color=#00F6FF>{1}</color>機率觸發1次紅龍攻擊，傷害為莉奧娜普通攻擊傷害的<color=#00F6FF>50%</color>，並附加1層<link=\"10002\"><#FFAE07><u>灼燒</u></color></link>，持續2回合。",
  str_skill_passive_desc_400088 = "每<color=#00F6FF>10</color>次COMBO會使瑪姬的連鎖技能傷害增加<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_410088 = "每<color=#00F6FF>10</color>次COMBO會使瑪姬的連鎖技能傷害增加<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_420088 = "每<color=#00F6FF>10</color>次COMBO使瑪姬的連鎖技能傷害增加<color=#00F6FF>{1}</color>，同時使觸發連鎖技能所需格子數量<color=#00F6FF>-1</color>。",
  str_skill_passive_desc_430088 = "每<color=#00F6FF>8</color>次COMBO使瑪姬的連鎖技能傷害增加<color=#00F6FF>{1}</color>，同時使觸發連鎖技能所需格子數量<color=#00F6FF>-1</color>。",
  str_skill_passive_desc_400084 = "連鎖技能施放結束後，降低自身<color=#00F6FF>周圍1圈</color>內的敵人<color=#00F6FF>{1}</color>的攻擊。",
  str_skill_passive_desc_410084 = "連鎖技能施放結束後，降低自身<color=#00F6FF>周圍1圈</color>內的敵人<color=#00F6FF>{1}</color>的攻擊。",
  str_skill_passive_desc_420084 = "連鎖技能施放結束後，降低自身<color=#00F6FF>周圍2圈</color>內的敵人<color=#00F6FF>{1}</color>的攻擊。",
  str_skill_passive_desc_400090 = "芭芭拉對位於火屬性格子上的敵人造成的傷害增加<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_410090 = "芭芭拉對位於火屬性格子上的敵人造成的傷害增加<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_430090 = "芭芭拉對位於火屬性格子上的敵人造成的傷害增加<color=#00F6FF>{1}</color>，隊伍中其他火屬性光靈獲得<color=#00F6FF>一半</color>加成。",
  str_skill_passive_desc_400045 = "生命值百分比愈低，聖釘的攻擊和防禦愈高，最多提高<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_410045 = "生命值百分比愈低，聖釘的攻擊和防禦愈高，最多提高<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_400081 = "施放主動技能後，<color=#00F6FF>周圍1圈</color>內每有1名敵人，為火屬性光靈提高攻擊，相當於黑潮<color=#00F6FF>{1}</color>攻擊力。",
  str_skill_passive_desc_410081 = "施放主動技能後，<color=#00F6FF>周圍1圈</color>內每有1名敵人，為火屬性光靈提高攻擊，相當於黑潮<color=#00F6FF>{1}</color>攻擊力。",
  str_skill_passive_desc_430081 = "施放主動技能後，<color=#00F6FF>周圍2圈</color>內每有1名敵人，為火屬性光靈提高攻擊，相當於黑潮<color=#00F6FF>{1}</color>攻擊力。",
  str_skill_passive_desc_400083 = "主動技能有<color=#00F6FF>{1}</color>的機率使敵人的移動範圍降低<color=#00F6FF>50%</color>。",
  str_skill_passive_desc_410083 = "主動技能有<color=#00F6FF>{1}</color>的機率使敵人的移動範圍降低<color=#00F6FF>50%</color>。",
  str_skill_passive_desc_430083 = "主動技能有<color=#00F6FF>{1}</color>的機率使敵人的移動範圍降低<color=#00F6FF>50%</color>。",
  str_skill_passive_desc_400059 = "可獲得<link=\"30002\"><#FFAE07><u>匹皮印記</u></color></link>，最多<color=#00F6FF>{1}</color>層。主動技能移動範圍變為自身周圍與印記層數相同的圈數。使用主動技能後印記會清空。",
  str_skill_passive_desc_410059 = "可獲得<link=\"30002\"><#FFAE07><u>匹皮印記</u></color></link>，最多<color=#00F6FF>{1}</color>層。主動技能移動範圍變為自身周圍與印記層數相同的圈數。使用主動技能後印記會清空。",
  str_skill_passive_desc_420059 = "可獲得<link=\"30003\"><#FFAE07><u>匹皮印記</u></color></link>，最多<color=#00F6FF>{1}</color>層。主動技能移動範圍變為自身周圍與印記層數相同的圈數。使用主動技能後印記會清空。",
  str_skill_passive_desc_400080 = "若連鎖技能範圍內沒有敵人，則為隊伍恢復等同於尤尼梅特<color=#00F6FF>{1}</color>攻擊力的生命值。",
  str_skill_passive_desc_410080 = "若連鎖技能範圍內沒有敵人，則為隊伍恢復等同於尤尼梅特<color=#00F6FF>{1}</color>攻擊力的生命值。",
  str_skill_passive_desc_400093 = "施放連鎖技能或主動技能後，若目標生命值低於<color=#00F6FF>{1}</color>，則對其追加1次<color=#00F6FF>{2}</color>攻擊力的無視防禦的傷害。",
  str_skill_passive_desc_410093 = "施放連鎖技能或主動技能後，若目標生命值低於<color=#00F6FF>{1}</color>，則對其追加1次<color=#00F6FF>{2}</color>攻擊力的無視防禦的傷害。",
  str_skill_passive_desc_430093 = "施放連鎖技能或主動技能後，若目標生命值低於<color=#00F6FF>{1}</color>,則對其追加1次<color=#00F6FF>{2}</color>攻擊的無視防禦的傷害。追擊後若目標生命值低於彌加德的攻擊，則將其斬殺。",
  str_skill_passive_desc_400097 = "普通攻擊變為2連擊，每次傷害為基礎傷害的<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_410097 = "普通攻擊變為2連擊，每次傷害為基礎傷害的<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_420097 = "普通攻擊變為2連擊，每次傷害為基礎傷害的<color=#00F6FF>{1}</color>。每次攻擊有<color=#00F6FF>20%</color>的機率使傷害增加<color=#00F6FF>50%</color>。",
  str_skill_passive_desc_430097 = "普通攻擊變為2連擊，每次傷害為基礎傷害的<color=#00F6FF>{1}</color>。每次攻擊有<color=#00F6FF>20%</color>的機率使傷害增加<color=#00F6FF>50%</color>，每1次COMBO額外增加0.5%的觸發機率，最高不超過50%。",
  str_skill_passive_desc_400095 = "對帶有<link=\"10001\"><#FFAE07><u>中毒</u></color></link>狀態的敵人造成傷害時，每層中毒狀態會使最終傷害增加<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_410095 = "對帶有<link=\"10001\"><#FFAE07><u>中毒</u></color></link>狀態的敵人造成傷害時，每層中毒狀態會使最終傷害增加<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_420095 = "對帶有<link=\"10001\"><#FFAE07><u>中毒</u></color></link>狀態的敵人造成傷害時，每層中毒狀態會使最終傷害增加<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_430095 = "對帶有<link=\"10001\"><#FFAE07><u>中毒</u></color></link>狀態的敵人造成傷害時，每層中毒狀態會讓最終傷害增加<color=#00F6FF>{1}</color>。主動技能和連鎖技能命中帶有中毒狀態的目標時，額外為其附加1層中毒狀態。",
  str_skill_passive_desc_400062 = "若普通攻擊、連鎖技能和主動技能只對1個敵人造成傷害，該次傷害無視目標<color=#00F6FF>{1}</color>的防禦。",
  str_skill_passive_desc_410062 = "若普通攻擊、連鎖技能和主動技能只對1個敵人造成傷害，該次傷害無視目標<color=#00F6FF>{1}</color>的防禦。",
  str_skill_passive_desc_430062 = "普通攻擊、連鎖技能和主動技能只對1個敵人造成傷害時，該次傷害無視目標<color=#00F6FF>{1}</color>的防禦。當場上只有1個敵人時，隊伍中其他森屬性光靈的主動技造成傷害時獲得一半加成。",
  str_skill_passive_desc_400024 = "普通攻擊對位於火屬性格子上的敵人額外造成<color=#00F6FF>{1}</color>的傷害。",
  str_skill_passive_desc_410024 = "普通攻擊對位於火屬性格子上的敵人額外造成<color=#00F6FF>{1}</color>的傷害。",
  str_skill_passive_desc_400087 = "連鎖技能命中目標時，對其<color=#00F6FF>周圍1圈</color>的隨機<color=#00F6FF>{1}</color>個目標造成傷害（同1個目標只會承受1次傷害），每次傷害會減少<color=#00F6FF>{2}</color>。",
  str_skill_passive_desc_410087 = "連鎖技能命中目標時，對其<color=#00F6FF>周圍1圈</color>的隨機<color=#00F6FF>{1}</color>個目標造成傷害（同1個目標只會承受1次傷害），每次傷害會減少<color=#00F6FF>{2}</color>。",
  str_skill_passive_desc_420087 = "連鎖技能命中目標時，對其<color=#00F6FF>周圍2圈</color>的隨機<color=#00F6FF>{1}</color>個目標造成傷害（同1個目標只會承受1次傷害），每次傷害會減少<color=#00F6FF>{2}</color>。",
  str_skill_passive_desc_400101 = "安希雅對場上邊緣的敵人造成的所有傷害均增加（敵人在角落時加成最大），最大增加<color=#00F6FF>{1}</color>最終傷害。",
  str_skill_passive_desc_410101 = "安希雅對場上邊緣的敵人造成的所有傷害均增加（敵人在角落時加成最大），最大增加<color=#00F6FF>{1}</color>最終傷害。",
  str_skill_passive_desc_400102 = "隊伍中雷屬性光靈施放主動技能時，可獲得1層泰莎印記。施放主動技能時，每層印記對<color=#00F6FF>周圍1圈</color>的敵人造成<color=#00F6FF>{1}</color>傷害。施放主動技能後，印記會清空。",
  str_skill_passive_desc_410102 = "隊伍中雷屬性光靈施放主動技能時，可獲得1層泰莎印記。施放主動技能時，每層印記對<color=#00F6FF>周圍1圈</color>的敵人造成<color=#00F6FF>{1}</color>傷害。施放主動技能後，印記會清空。",
  str_skill_passive_desc_420102 = "隊伍中雷屬性光靈施放主動技能，或泰莎施放連鎖技能時，可獲得1層泰莎印記。施放主動技能時，每層印記對<color=#00F6FF>周圍1圈</color>的敵人造成<color=#00F6FF>{1}</color>傷害。施放主動技能後，印記會清空。",
  str_skill_passive_desc_430102 = "隊伍中雷屬性光靈施放主動技能，或泰莎施放連鎖技能時，可獲得1層泰莎印記。施放主動技能時，每層印記對<color=#00F6FF>周圍2圈</color>的敵人造成<color=#00F6FF>{1}</color>無視防禦的傷害。施放主動技能後，印記會清空。",
  str_skill_passive_desc_400099 = "驅動魔劍期間，普通攻擊會貫穿敵人，對敵人身後1格的目標造成<color=#00F6FF>{1}</color>傷害。",
  str_skill_passive_desc_410099 = "驅動魔劍期間，普通攻擊會貫穿敵人，對敵人身後1格的目標造成<color=#00F6FF>{1}</color>傷害。",
  str_skill_passive_desc_400100 = "希卡蕾首次攻擊敵人時，會收割目標的靈魂，對其立即造成<color=#00F6FF>{1}</color>攻擊力的傷害，無視防禦。",
  str_skill_passive_desc_410100 = "希卡蕾首次攻擊敵人時，會收割目標的靈魂，對其立即造成<color=#00F6FF>{1}</color>攻擊力的傷害，無視防禦。",
  str_skill_passive_desc_430100 = "希卡蕾首次攻擊敵人時，會收割目標的靈魂，對其立即造成<color=#00F6FF>{1}</color>攻擊力以及<color=#00F6FF>5%</color>目前生命值的傷害，無視防禦。",
  str_skill_passive_desc_400098 = "連鎖技能命中敵人時，為其附加1層割裂印記，最多5層。每層印記使庫絲庫塔傷害提高<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_410098 = "連鎖技能命中敵人時，為其附加1層割裂印記，最多5層。每層印記使庫絲庫塔傷害提高<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_420098 = "連鎖技能命中敵人時，為其附加1層割裂印記，最多5層。每層印記使庫絲庫塔傷害提高<color=#00F6FF>{1}</color>。普通攻擊有<color=#00F6FF>30%</color>機率附加1層印記。",
  str_skill_passive_desc_4200981 = "連鎖技能命中敵人時為其附加1層割裂印記，最多10層。每層印記使庫絲庫塔的傷害提高<color=#00F6FF>6%</color>。普通攻擊有<color=#00F6FF>30%</color>的機率附加1層印記。",
  str_skill_passive_desc_400094 = "連鎖技能命中目標後，降低其<color=#00F6FF>{1}</color>的攻擊力，持續1回合。",
  str_skill_passive_desc_410094 = "連鎖技能命中目標後，降低其<color=#00F6FF>{1}</color>的攻擊力，持續1回合。",
  str_skill_passive_desc_400096 = "可獲得<link=\"30013\"><#FFAE07><u>沙利葉印記</u></color></link>，最多8層。每層能提高沙利葉<color=#00F6FF>{1}</color>的防禦，回合結束時保留一半的印記層數。",
  str_skill_passive_desc_410096 = "可獲得<link=\"30013\"><#FFAE07><u>沙利葉印記</u></color></link>，最多8層。每層能提高沙利葉<color=#00F6FF>{1}</color>的防禦，回合結束時保留一半的印記層數。",
  str_skill_passive_desc_420096 = "可獲得<link=\"30013\"><#FFAE07><u>沙利葉印記</u></color></link>，最多8層。每層能提高沙利葉<color=#00F6FF>{1}</color>的防禦，根據損失生命值提升防禦效果，最多增加<color=#00F6FF>50%</color>，回合結束時保留一半的印記層數。",
  str_skill_passive_desc_400056 = "普通攻擊或主動技能造成傷害時（取最高值），將傷害數值的<color=#00F6FF>{1}</color>轉為攻擊，僅在目前回合生效。",
  str_skill_passive_desc_410056 = "普通攻擊或主動技能造成傷害時（取最高值），將傷害數值的<color=#00F6FF>{1}</color>轉為攻擊，僅在目前回合生效。",
  str_skill_passive_desc_430056 = "普通攻擊或主動技能造成傷害時（取最高值），將傷害數值的<color=#00F6FF>{1}</color>轉為攻擊，僅在目前回合生效。場上只有1個敵人時，水屬性光靈攻擊增加<color=#00F6FF>5%</color>。",
  str_skill_passive_desc_400103 = "每3回合獲得1次空虛狀態（未使用則保留該狀態）。空虛狀態下，連鎖技能對目標造成艾希<color=#00F6FF>{1}</color>攻擊力的無視防禦傷害，並回復等量的生命值。",
  str_skill_passive_desc_410103 = "每3回合獲得1次空虛狀態（未使用則保留該狀態）。空虛狀態下，連鎖技能對目標造成艾希<color=#00F6FF>{1}</color>攻擊力的無視防禦傷害，並回復等量的生命值。",
  str_skill_passive_desc_430103 = "每3回合獲得1次空虛狀態（未使用則保留該狀態）。空虛狀態下，連鎖技能對目標造成艾希<color=#00F6FF>{1}</color>攻擊力的傷害，無視防禦，並回復等量的生命值。隊伍生命值越低，回復效果越高，最高增加<color=#00F6FF>50%</color>。",
  str_skill_passive_desc_410067 = "若本回合恢復生命值，則愛麗絲本回合的基礎防禦增加<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_430067 = "若本回合恢復生命值，則愛麗絲本回合的基礎防禦增加<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_400030 = "<color=#00F6FF>可斜方向發動普通攻擊</color>，且斜向普通攻擊可對目標附加1層崩裂狀態，最多5層。每層降低目標等同於醒山基礎防禦<color=#00F6FF>{1}</color>的防禦，持續1回合。",
  str_skill_passive_desc_410030 = "<color=#00F6FF>可斜方向發動普通攻擊</color>，且斜向普通攻擊可對目標附加1層崩裂狀態，最多5層。每層降低目標等同於醒山基礎防禦<color=#00F6FF>{1}</color>的防禦，持續1回合。",
  str_skill_passive_desc_430030 = "<color=#00F6FF>可斜方向發動普通攻擊</color>，且斜向普通攻擊、主動技能和連鎖技能均可對目標附加1層崩裂狀態，最多5層。每層降低目標等同於醒山基礎防禦<color=#00F6FF>{1}</color>的防禦，持續1回合。",
  str_skill_passive_desc_410104 = "主動技能可標記被攻擊的敵人。多恩以主動技能和連鎖技能攻擊標記敵人時，會消耗標記並回復相當於本次傷害<color=#00F6FF>{1}</color>的生命值。",
  str_skill_passive_desc_430104 = "主動技能可標記被攻擊的敵人。多恩以主動技能和連鎖技能攻擊標記敵人時，會消耗標記並回復相當於本次傷害<color=#00F6FF>{1}</color>的生命值。若隊伍生命為滿，則本次攻擊的最終傷害增加<color=#00F6FF>25%</color>。",
  str_skill_passive_desc_410071 = "每回合開始時，為生命百分比最高的敵人附加灼印，瀧對其造成的所有傷害增加<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_430071 = "每回合開始時，對生命百分比最高的敵人附加灼印，瀧對其造成的所有傷害增加<color=#00F6FF>{1}</color>。每擊殺一個帶有灼印的敵人，瀧的攻擊增加<color=#00F6FF>3%</color>，最高不超過<color=#00F6FF>30%</color>。",
  str_skill_passive_desc_400105 = "主動技能、連鎖技能和普通攻擊造成傷害時，每<color=#00F6FF>10</color>次傷害，對<color=#00F6FF>全體</color>敵人造成1次<color=#00F6FF>{1}</color>傷害。",
  str_skill_passive_desc_410105 = "主動技能、連鎖技能和普通攻擊造成傷害時，每<color=#00F6FF>10</color>次傷害，對<color=#00F6FF>全體</color>敵人造成1次<color=#00F6FF>{1}</color>傷害。",
  str_skill_passive_desc_420105 = "主動技能、連鎖技能和普通攻擊造成傷害時，每<color=#00F6FF>8</color>次傷害，對<color=#00F6FF>全體</color>敵人造成1次<color=#00F6FF>{1}</color>傷害。",
  str_skill_passive_desc_430105 = "主動技能、連鎖技能和普通攻擊造成傷害時，每<color=#00F6FF>8</color>次傷害，對<color=#00F6FF>全體</color>敵人造成1次<color=#00F6FF>{1}</color>傷害。",
  str_skill_passive_desc_430109 = "每回合開始時獲得<color=#00F6FF>5</color>點威能。",
  str_skill_passive_desc_433109 = "每回合開始時獲得<color=#00F6FF>5</color>點威能。每回合首次普通攻擊可獲得<color=#00F6FF>1</color>點威能且該次普通攻擊的傷害增加<color=#00F6FF>100%</color>。",
  str_skill_passive_desc_430110 = "每回合開始時獲得<color=#00F6FF>5</color>點威能。普通攻擊有<color=#00F6FF>30%</color>機率對距離自己最遠的敵人施放1次雷擊。",
  str_skill_passive_desc_433110 = "每回合開始時獲得<color=#00F6FF>5</color>點威能，每次以主動技能擊殺1名敵人時獲得<color=#00F6FF>2</color>點威能。普通攻擊有<color=#00F6FF>30%</color>機率對距離最遠的敵人施放1次雷擊。",
  str_skill_passive_desc_430107 = "戰鬥開始時獲得10點威能；回合結束時若處於非增幅狀態，可獲得<color=#00F6FF>5</color>點威能（此時每損失20%生命值，額外獲得1點威能）。",
  str_skill_passive_desc_436107 = "戰鬥開始時獲得10點威能；每回合開始時，周圍<color=#00F6FF>十字4格</color>每有1名敵人則獲得<color=#00F6FF>1</color>點威能；回合結束時若處於非增幅狀態，可獲得<color=#00F6FF>5</color>點威能（此時每損失20%生命值，額外獲得1點）。",
  str_skill_passive_desc_430108 = "每回合開始時獲得<color=#00F6FF>5</color>點威能，使用主動技能擊殺目標可獲得<color=#00F6FF>5</color>點威能。",
  str_skill_passive_desc_400116 = "弗勞爾對生命值低於40%的敵人造成的所有傷害提高<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_410112 = "斯莫奇對<color=#00F6FF>每一名</color>敵人的<color=#00F6FF>主動技能、連鎖技能、每回合首次普通攻擊</color>均會觸發<color=#00F6FF>火吻</color>，額外造成斯莫奇<color=#00F6FF>{1}</color>攻擊的傷害，無視防禦。重複觸發時效果會遞減，最低降為原始效果的<color=#00F6FF>20%</color>。",
  str_skill_passive_desc_420112 = "斯莫奇對<color=#00F6FF>每一名</color>敵人的<color=#00F6FF>主動技能、連鎖技能、每回合首次普通攻擊</color>均會觸發<color=#00F6FF>火吻</color>，額外造成斯莫奇<color=#00F6FF>{1}</color>攻擊的傷害，無視防禦。重複觸發時效果會遞減，最低降為原始效果的<color=#00F6FF>20%</color>。<color=#00F6FF>火吻</color>對處於火屬性格子上的敵人造成<color=#00F6FF>雙倍</color>傷害。",
  str_skill_passive_desc_430112 = "斯莫奇對<color=#00F6FF>每一名</color>敵人的<color=#00F6FF>主動技能、連鎖技能、每回合首次普通攻擊</color>均會觸發<color=#00F6FF>火吻</color>，額外造成斯莫奇<color=#00F6FF>{1}</color>攻擊的傷害，無視防禦。重複觸發時效果會遞減，最低降為原始效果的<color=#00F6FF>20%</color>。<color=#00F6FF>火吻</color>對處於火屬性格子上的敵人造成<color=#00F6FF>雙倍</color>傷害。",
  str_skill_passive_desc_400113 = "戰鬥開始或使用主動技能時，獲得神鳴印記，印記存在時波娜瑟的防禦增加<color=#00F6FF>{1}</color>，損失生命時印記消失。",
  str_skill_passive_desc_410113 = "戰鬥開始或使用主動技能時，獲得神鳴印記，印記存在時波娜瑟的防禦增加<color=#00F6FF>{1}</color>，損失生命時印記消失。",
  str_skill_passive_desc_420113 = "戰鬥開始或使用主動技能時，獲得神鳴印記，印記存在時波娜瑟的防禦增加<color=#00F6FF>{1}</color>，損失生命時印記消失。印記存在時，出戰的雷屬性光靈連鎖技能傷害增加<color=#00F6FF>10%</color>。",
  str_skill_passive_desc_400114 = "主動技能造成傷害時，為隊伍回復相當於本次傷害<color=#00F6FF>{1}</color>的生命值。",
  str_skill_passive_desc_410114 = "主動技能造成傷害時，為隊伍回復相當於本次傷害<color=#00F6FF>{1}</color>的生命值。",
  str_skill_passive_desc_430114 = "主動技能造成傷害時，為隊伍回復相當於本次傷害<color=#00F6FF>{1}</color>的生命值，同時使火屬性光靈本回合的連鎖技能傷害增加<color=#00F6FF>10%</color>。",
  str_skill_passive_desc_410127 = "每回合開始時，若自身<color=#00F6FF>周圍2圈</color>有敵人，則向其中任意1名敵人投擲匕首，對其造成<color=#00F6FF>{1}</color>的傷害，並附加1層<link=\"10000\"><#FFAE07><u>流血</u></color></link>狀態，持續2回合。",
  str_skill_passive_desc_430127 = "每回合開始時，若自身<color=#00F6FF>周圍2圈</color>內存在敵人，則向其中任意1名敵人投擲匕首，對其造成<color=#00F6FF>{1}</color>的傷害，並附加1層<link=\"10000\"><#FFAE07><u>流血</u></color></link>狀態，持續2回合。經過紙鶴也會觸發投擲匕首的效果。",
  str_skill_desc_3351221 = "選擇1個格子，對<color=#00F6FF>米字形16格</color>造成<color=#00F6FF>{1}%</color>的傷害，對所選格子造成無視防禦的傷害。清除範圍內的<color=#00F6FF>損壞格子</color>效果。祝福達到10層時主動技能範圍變為<color=#00F6FF>米字形最大</color>。",
  str_skill_passive_desc_410117 = "可獲得<link=\"30016\"><#FFAE07><u>勇虎值</u></color></link>，每層勇虎值增加克<color=#00F6FF>{1}</color>的基礎攻擊力。",
  str_skill_passive_desc_430117 = "可獲得<link=\"30017\"><#FFAE07><u>勇虎值</u></color></link>，每層勇虎值增加克<color=#00F6FF>{1}</color>的基礎攻擊力。主動技能獲得的勇虎值沒有上限，波次結束會清空，每清空1層回復等同於克<color=#00F6FF>5%</color>生命值上限的生命值。",
  str_skill_passive_desc_410119 = "可獲得<link=\"30018\"><#FFAE07><u>無畏值</u></color></link>，每層無畏值增加雷文頓<color=#00F6FF>{1}</color>的基礎攻擊力。",
  str_skill_passive_desc_420119 = "可獲得<link=\"30018\"><#FFAE07><u>無畏值</u></color></link>，每層無畏值增加雷文頓<color=#00F6FF>{1}</color>的基礎攻擊力和<color=#00F6FF>5%</color>主動技能傷害。",
  str_skill_passive_desc_430119 = "可獲得<link=\"30018\"><#FFAE07><u>無畏值</u></color></link>，每層無畏值增加雷文頓<color=#00F6FF>{1}</color>的基礎攻擊力和<color=#00F6FF>5%</color>主動技能傷害。普通攻擊<color=#00F6FF>可攻擊斜方向</color>的敵人。",
  str_skill_passive_desc_410122 = "可獲得<link=\"30019\"><#FFAE07><u>祝福</u></color></link>，每層祝福增加艾爾戈絲<color=#00F6FF>{1}</color>主動技能傷害。",
  str_skill_passive_desc_410121 = "每次經過<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>，便獲得1層芒刺印記。每層印記增加<color=#00F6FF>{1}</color>連鎖傷害，回合結束時保留一半印記層數。",
  str_skill_passive_desc_430121 = "每次經過<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>，便獲得1層芒刺印記。每層印記增加<color=#00F6FF>{1}</color>連鎖技能和普通攻擊的傷害，回合結束時保留一半印記層數。",
  str_skill_passive_desc_410065 = "連鎖技能命中1個敵人可獲得1層球雀印記，每層印記可增加自身<color=#00F6FF>{1}</color>防禦，回合結束後印記消失。",
  str_skill_passive_desc_410115 = "每次經過<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>，便獲得1層碧翠印記；每層印記增加納努塞爾<color=#00F6FF>{1}</color>基礎攻擊力；回合結束時保留一半印記層數。",
  str_skill_passive_desc_430115 = "每次經過<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>，獲得1層碧翠印記；每層印記為全隊增加納努塞爾<color=#00F6FF>{1}</color>的基礎攻擊力；回合結束時保留一半印記層數。",
  str_skill_passive_desc_410126 = "在主動技能選擇的格子上召喚<link=\"30024\"><#FFAE07><u>弗蘭克</u></color></link>。每當有光靈施放主動技能時，弗蘭克發動<color=#00F6FF>吼叫</color>，對<color=#00F6FF>周圍1圈</color>的敵人造成<color=#00F6FF>{1}</color>的傷害。弗蘭克消失時也會觸發<color=#00F6FF>吼叫</color>。",
  str_skill_passive_desc_420126 = "在主動技能選擇的格子上召喚<link=\"30024\"><#FFAE07><u>弗蘭克</u></color></link>。每當有光靈施放主動技能時，弗蘭克發動<color=#00F6FF>吼叫</color>，對<color=#00F6FF>周圍1圈</color>的敵人造成<color=#00F6FF>{1}</color>的傷害；範圍內只有1名敵人時改為<color=#00F6FF>爪擊</color>，傷害提升<color=#00F6FF>50%</color>。弗蘭克消失時也會觸發<color=#00F6FF>吼叫</color>。",
  str_skill_passive_desc_410129 = "主動技能與連鎖技能每造成1次傷害，在敵人身上疊加1層寄生標記，上限<color=#00F6FF>9</color>層。敵人每移動一格，每層寄生標記造成<color=#00F6FF>{1}</color>的傷害。",
  str_skill_passive_desc_420129 = "主動技能與連鎖技能每造成1次傷害，在敵人身上疊加1層寄生標記，上限<color=#00F6FF>9</color>層。敵人每移動一格，每層寄生標記造成<color=#00F6FF>{1}</color>的傷害。路克對層數最高的敵人所造成的普通攻擊與連鎖傷害提升<color=#00F6FF>30%</color>。",
  str_skill_passive_desc_430129 = "主動技能與連鎖技能每造成1次傷害，在敵人身上疊加1層寄生標記，上限<color=#00F6FF>9</color>層。敵人每移動一格，每層寄生標記造成<color=#00F6FF>{1}</color>的傷害；若該敵人標記層數為場上最高，該傷害提升至<color=#00F6FF>{2}</color>。路克對層數最高的敵人所造成的普通攻擊與連鎖傷害提升<color=#00F6FF>30%</color>。",
  str_skill_passive_desc_410055 = "受到攻擊時獲得1層戰痕，上限<color=#00F6FF>15</color>層。每層戰痕提升<color=#00F6FF>{1}</color>的攻擊力，每回合減少50%戰痕層數。",
  str_skill_passive_desc_420055 = "受到攻擊時獲得1層戰痕，上限<color=#00F6FF>15</color>層。每層戰痕提升<color=#00F6FF>{1}</color>的攻擊力與防禦力，每回合減少50%戰痕層數。",
  str_skill_passive_desc_430055 = "受到攻擊時獲得1層戰痕，上限<color=#00F6FF>15</color>層。每層戰痕提升<color=#00F6FF>{1}</color>的攻擊力與防禦力，每回合減少50%戰痕層數。每減少1層戰痕，獲得相當於彼亞塔曼<color=#00F6FF>12%</color>最大生命值的護盾。",
  str_skill_passive_desc_410120 = "在施放連鎖技能與主動技能時，龐佩會出現替代海蒂攻擊，龐佩的攻擊力為海蒂攻擊力的<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_430120 = "在施放連鎖技能與主動技能時，龐佩會出現替代海蒂攻擊，龐佩的攻擊力為海蒂攻擊力的<color=#00F6FF>{1}</color>。極光時刻下，連線每經過一格，龐佩的攻擊力提升<color=#00F6FF>2%</color>，最多提升<color=#00F6FF>30%</color>。",
  str_skill_passive_desc_410123 = "<color=#00F6FF>周圍菱形12格</color>範圍內每有1名敵人，提升<color=#00F6FF>{1}</color>攻擊力。",
  str_skill_passive_desc_430123 = "<color=#00F6FF>周圍2圈</color>範圍內每有1名敵人，提升<color=#00F6FF>{1}</color>攻擊力與防禦力。",
  str_skill_passive_desc_410015 = "主動技能造成傷害前，手榴彈每行進1圈，最終傷害提升<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_420015 = "主動技能造成傷害前，手榴彈每行進1圈，最終傷害提升<color=#00F6FF>{1}</color>；連鎖技能造成傷害前，手榴彈每行進1圈，最終傷害提升<color=#00F6FF>{2}</color>。",
  str_skill_passive_desc_410131 = "普通攻擊前若隊伍生命值未滿，則本次普通攻擊改為回復諾維亞攻擊力<color=#00F6FF>{1}</color>的生命值。",
  str_skill_passive_desc_430131 = "普通攻擊前若隊伍生命值未滿，則本次普通攻擊改為回復諾維亞攻擊力<color=#00F6FF>{1}</color>的生命值。若隊伍生命值為滿，則普通攻擊與連鎖技能傷害提升<color=#00F6FF>10%</color>，同時擁有護盾時該傷害加成提升至<color=#00F6FF>25%</color>。",
  str_skill_passive_desc_410132 = "極光時刻期間，攻擊力提升<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_430132 = "極光時刻期間，攻擊力提升<color=#00F6FF>{1}</color>，且經過任意屬性的格子都能施放連鎖技能，連鎖技能傷害始終視為森屬性。",
  str_skill_passive_desc_410133 = "每次COMBO連鎖技能傷害提升<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_430133 = "每次COMBO提升<color=#00F6FF>{1}</color>連鎖技能傷害與<color=#00F6FF>{2}</color>濺射傷害。",
  str_skill_passive_desc_410137 = "主動技能對所選敵人造成傷害，敵人腳下每有<color=#00F6FF>1</color>個水屬性格子，造成<color=#00F6FF>{1}</color>法夫納攻擊力的傷害。",
  str_skill_passive_desc_430137 = "主動技能對所選敵人造成傷害，敵人腳下每有<color=#00F6FF>1</color>個水屬性格子，造成<color=#00F6FF>{1}</color>法夫納攻擊力的傷害。其他小林家聯動角色的主動技能命中敵人時，也會觸發此傷害效果。",
  str_skill_passive_desc_410134 = "康娜施放主動技能時獲得3層蓄能，其他雷屬性光靈或小林家聯動角色施放主動技能時獲得1層蓄能，最高10層。每層提升<color=#00F6FF>{1}</color>基礎攻擊力，回合結束後清空蓄能。",
  str_skill_passive_desc_430134 = "康娜施放主動技能時獲得3層蓄能，其他雷屬性光靈或小林家聯動角色施放主動技能時獲得1層蓄能，最高10層。每層提升<color=#00F6FF>{1}</color>基礎攻擊力，回合結束時保留一半蓄能層數。",
  str_skill_passive_desc_416134 = "康娜施放主動技能時獲得3層蓄能，其他雷屬性光靈或小林家聯動角色施放主動技能時獲得1層蓄能，最高10層。每層提升<color=#00F6FF>{1}</color>基礎攻擊力，回合結束後清空蓄能。每波次開始時，康娜額外獲得2層蓄能。",
  str_skill_passive_desc_436134 = "康娜施放主動技能時獲得3層蓄能，其他雷屬性光靈或小林家聯動角色施放主動技能時獲得1層蓄能，最高10層。每層提升<color=#00F6FF>{1}</color>基礎攻擊力，回合結束時保留一半蓄能層數。每波次開始時，康娜額外獲得2層蓄能。",
  str_skill_passive_desc_410135 = "目前生命值為滿時，普通攻擊傷害提升<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_430135 = "目前生命值為滿時，普通攻擊、連鎖技能、主動技能傷害均提升<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_410136 = "連鎖技能命中敵人時附加凡塵印記，每層印記增加<color=#00F6FF>{1}</color>該敵人受到所有光靈主動技能的傷害。印記最高<color=#00F6FF>10</color>層，持續本場戰鬥。",
  str_skill_desc_200501 = "對<color=#00F6FF>X形8格</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_210501 = "對<color=#00F6FF>X形8格</color>造成<color=#00F6FF>{1}%</color>的傷害。",
