  str_skill_desc_302139 = "在自身周圍<color=#00F6FF>8</color>個方向中選擇其一，對沿途及相鄰格子上的敵人造成<color=#00F6FF>{1}%</color>的傷害。並重設範圍內<color=#00F6FF>非雷屬性</color>的格子。",
  str_skill_desc_320139 = "在自身周圍<color=#00F6FF>4</color>個方向中選擇其一，對沿途及相鄰格子上的敵人造成<color=#00F6FF>{1}%</color>的傷害，且隨機對沿途範圍內的1名敵人附加1回合<link=\"10004\"><#FFAE07><u>麻痺</u></color></link>效果。並重設範圍內<color=#00F6FF>非雷屬性</color>的格子。",
  str_skill_desc_322139 = "在自身周圍<color=#00F6FF>8</color>個方向中選擇其一，對沿途及相鄰格子上的敵人造成<color=#00F6FF>{1}%</color>的傷害，且隨機對沿途範圍內的1名敵人附加1回合<link=\"10004\"><#FFAE07><u>麻痺</u></color></link>效果。並重設範圍內<color=#00F6FF>非雷屬性</color>的格子。",
