  str_skill_upgrade_desc_16013813 = "主動技能強化：主動技能變為<color=#FFFF00>先制攻擊</color>，進入戰鬥即可使用。",
  str_skill_upgrade_desc_16013816 = "裝備技能強化：透過<link=\"30025\"><#FFAE07><u>蛛絲印記</u></color></link>獲得護盾時，若印記不少於10層，額外獲得希諾普<color=#00F6FF>15%</color>生命值的護盾。",
  str_skill_desc_300138 = "任選1個格子，然後再次點選確定2*2或1*4的範圍，將範圍內格子轉化為森屬性。",
  str_skill_desc_320138 = "任選1個格子，然後再次點選確定2*2或1*4的範圍，將範圍內格子轉化為森屬性。兩次點選的格子均變為<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>。",
  str_skill_desc_330138 = "任選1個格子，然後再次點選確定2*2或1*4的範圍，將範圍內格子轉化為森屬性。兩次點選的格子均變為<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>。極光時刻下達成15格連鎖，主動技能冷卻回合數<color=#00F6FF>-1</color>。",
  str_skill_desc_2001381 = "對<color=#00F6FF>周圍4圈</color>內最靠近的2個敵人造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2001382 = "對<color=#00F6FF>周圍4圈</color>內最靠近的3個敵人造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2001383 = "對<color=#00F6FF>周圍4圈</color>內的全體敵人造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_passive_desc_410138 = "可獲得<link=\"30025\"><#FFAE07><u>蛛絲印記</u></color></link>。受到攻擊前，立即清空層數，每層提供希諾普防禦力<color=#00F6FF>{1}</color>的護盾。",
  str_skill_passive_desc_416138 = "可獲得<link=\"30025\"><#FFAE07><u>蛛絲印記</u></color></link>。受到攻擊前，立即清空層數，每層提供希諾普防禦力<color=#00F6FF>{1}</color>的護盾。透過<link=\"30025\"><#FFAE07><u>蛛絲印記</u></color></link>獲得護盾時，若印記不少於10層，額外獲得希諾普<color=#00F6FF>15%</color>生命值的護盾。",
  str_skill_upgrade_desc_16014113 = "主動技能強化：主動技能變為<color=#FFFF00>先制攻擊</color>，進入戰鬥即可使用。",
  str_skill_upgrade_desc_16014116 = "主動技能強化：點選腳下的格子可以切換擊退和轉色的方向。",
  str_skill_desc_2001411 = "對最近2名敵人造成<color=#00F6FF>115%</color>的傷害。如果只有1名敵人則造成2次傷害。",
  str_skill_desc_2001412 = "對最近2名敵人造成<color=#00F6FF>130%</color>的傷害。如果只有1名敵人則造成2次傷害。",
  str_skill_desc_2001413 = "對最近2名敵人造成<color=#00F6FF>150%</color>的傷害。如果只有1名敵人則造成2次傷害。",
  str_skill_desc_300141 = "選擇<color=#00F6FF>十字形最大</color>或<color=#00F6FF>X形最大</color>範圍，造成<color=#00F6FF>{1}%</color>的傷害並擊退敵人，同時將攻擊範圍的格子轉變成水屬性。",
  str_skill_desc_306141 = "選擇<color=#00F6FF>十字形最大</color>或<color=#00F6FF>X形最大</color>範圍，造成<color=#00F6FF>{1}%</color>的傷害並擊退敵人，同時將攻擊範圍的格子轉變成水屬性。點選腳下的格子可以切換擊退和轉色的方向。",
  str_skill_desc_320141 = "選擇<color=#00F6FF>十字形最大</color>或<color=#00F6FF>X形最大</color>範圍，造成<color=#00F6FF>{1}%</color>的傷害並擊退敵人，同時將攻擊範圍的格子轉變成水屬性。對命中的敵人造成一次基於當前裝備技能等級的傷害。",
  str_skill_desc_326141 = "選擇<color=#00F6FF>十字形最大</color>或<color=#00F6FF>X形最大</color>範圍，造成<color=#00F6FF>{1}%</color>的傷害並擊退敵人，同時將攻擊範圍的格子轉變成水屬性。點選腳下的格子可以切換擊退和轉色的方向。對命中的敵人造成一次基於當前裝備技能等級的傷害。",
  str_skill_passive_desc_410141 = "連鎖技能對同一目標每造成<color=#00F6FF>3</color>次傷害，就會觸發一次目標當前生命值<color=#00F6FF>{1}</color>的額外傷害。",
  str_skill_passive_desc_420141 = "連鎖技能對同一目標每造成<color=#00F6FF>3</color>次傷害，就會觸發一次目標當前生命值<color=#00F6FF>{1}</color>的額外傷害。",
  str_skill_passive_desc_430141 = "連鎖技能對同一目標每造成<color=#00F6FF>3</color>次傷害，就會觸發一次目標當前生命值<color=#00F6FF>{1}</color>的額外傷害，該傷害至少為露比基礎防禦力的<color=#00F6FF>{2}</color>。",
