  str_skill_desc_302142 = "從周圍<color=#00F6FF>菱形13格</color>中選擇1個格子，對選中格子以及該格<color=#00F6FF>周圍2圈</color>造成<color=#00F6FF>{1}%</color>的傷害並使范圍內<color=#00F6FF>非首領</color>敵人朝該格強制位移<color=#00F6FF>2</color>格，傷害係數每圈減少53%。",
  str_skill_desc_320142 = "從周圍<color=#00F6FF>菱形13格</color>中選擇1個格子，對選中格子以及該格<color=#00F6FF>周圍3圈</color>造成<color=#00F6FF>{1}%</color>的傷害並使范圍內<color=#00F6FF>非首領</color>敵人朝該格強制位移<color=#00F6FF>2</color>格，傷害係數每圈減少53%。",
  str_skill_desc_322142 = "從周圍<color=#00F6FF>菱形13格</color>中選擇1個格子，對選中格子以及該格<color=#00F6FF>周圍3圈</color>造成<color=#00F6FF>{1}%</color>的傷害並使范圍內<color=#00F6FF>非首領</color>敵人朝該格強制位移<color=#00F6FF>2</color>格，傷害係數每圈減少53%。",
  str_skill_passive_desc_410142 = "每第<color=#00F6FF>3</color>次普通攻擊時，根據目標當前生命值百分比提高本次普通攻擊傷害，目標生命值全滿時達到最大加成<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_420142 = "每第<color=#00F6FF>3</color>次與第<color=#00F6FF>5</color>次普通攻擊時，根據目標當前生命值百分比提高本次普通攻擊傷害，目標生命值全滿時達到最大加成<color=#00F6FF>{1}</color>。",
