  str_skill_desc_300140 = "使用後，本回合雷系光靈的連鎖技能會施放<color=#00F6FF>2</color>次，第<color=#00F6FF>2</color>次施放時，所有雷系光靈攻擊力為芙洛琳攻擊力的<color=#00F6FF>80%</color>。",
  str_skill_desc_306140 = "使用後，本回合雷系光靈的連鎖技能會施放<color=#00F6FF>2</color>次，第<color=#00F6FF>2</color>次施放時，所有雷系光靈攻擊力為芙洛琳攻擊力的<color=#00F6FF>80%</color>。",
  str_skill_desc_320140 = "使用後本回合雷系光靈的連鎖技能會施放<color=#00F6FF>2</color>次，第<color=#00F6FF>2</color>次施放時，所有雷系光靈攻擊力為芙洛琳攻擊力的<color=#00F6FF>80%</color>，同時使觸發雷系光靈連鎖技能所需的格子數量<color=#00F6FF>-1</color>。",
  str_skill_desc_326140 = "使用後本回合雷系光靈的連鎖技能會施放<color=#00F6FF>2</color>次，第<color=#00F6FF>2</color>次施放時，所有雷系光靈攻擊力為芙洛琳攻擊力的<color=#00F6FF>80%</color>，同時使觸發雷系光靈連鎖技能所需的格子數量<color=#00F6FF>-1</color>。",
  str_skill_desc_330140 = "使用後本回合雷系光靈的連鎖技能會施放<color=#00F6FF>2</color>次，第<color=#00F6FF>2</color>次施放時，所有雷系光靈攻擊力為芙洛琳攻擊力的<color=#00F6FF>95%</color>，同時使觸發雷系光靈連鎖技能所需的格子數量<color=#00F6FF>-1</color>。",
  str_skill_desc_336140 = "使用後本回合雷系光靈的連鎖技能會施放<color=#00F6FF>2</color>次，第<color=#00F6FF>2</color>次施放時，所有雷系光靈攻擊力為芙洛琳攻擊力的<color=#00F6FF>95%</color>，同時使觸發雷系光靈連鎖技能所需的格子數量<color=#00F6FF>-1</color>。",
  str_skill_passive_desc_410140 = "所有雷系光靈各階段連鎖技能傷害係數分別增加<color=#00F6FF>{1}</color>/<color=#00F6FF>{2}</color>/<color=#00F6FF>{3}</color>。",
