  str_skill_name_290200101 = "影子信虎",
  str_skill_desc_290200101 = "當敵人位於自身周圍2圈內時，瞬移至距離敵人6格的位置並在原地留下一個影子信虎。",
  str_skill_name_290200102 = "卻退之擊",
  str_skill_desc_290200102 = "當敵人不在自身周圍2圈內時，對範圍內的敵人進行遠距攻擊，並打亂光靈隊伍順序。",
  str_skill_name_290200112 = "卻退之擊",
  str_skill_desc_290200112 = "當敵人不在自身周圍2圈內時，對範圍內的敵人進行遠距攻擊。並打亂光靈隊伍順序。藤雲信虎距離敵人越遠，他的傷害力越高。",
  str_skill_name_290200201 = "影襲",
  str_skill_desc_290200201 = "影子信虎對攻擊範圍內的目標造成傷害。",
  str_skill_upgrade_desc_16014313 = "主動技能強化：主動技能變為<color=#FFFF00>先制攻擊</color>，進入戰鬥即可使用。",
  str_skill_upgrade_desc_16014316 = "裝備技能強化：本場戰鬥可更換隊長次數<color=#FFFF00>+1</color>。",
  str_skill_desc_2001431 = "對<color=#00F6FF>周圍2圈</color>內的全體敵人造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2001432 = "對<color=#00F6FF>周圍3圈</color>內的全體敵人造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2001433 = "對<color=#00F6FF>周圍4圈</color>內的全體敵人造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_300143 = "以自身為中心，召喚一個覆蓋<color=#00F6FF>周圍2圈</color>且持續2回合的結界，召喚時以及回合結束時將結界範圍內隨機<color=#00F6FF>3</color>個非火屬性格子轉化為火屬性，並將範圍內所有火屬性格子<link=\"30020\"><#FFAE07><u>淨化</u></color></link>。",
  str_skill_desc_306143 = "以自身為中心，召喚一個覆蓋<color=#00F6FF>周圍2圈</color>且持續2回合的結界，召喚時以及回合結束時將結界範圍內隨機<color=#00F6FF>3</color>個非火屬性格子轉化為火屬性，並將範圍內所有火屬性格子<link=\"30020\"><#FFAE07><u>淨化</u></color></link>。",
  str_skill_desc_330143 = "以自身為中心，召喚一個覆蓋<color=#00F6FF>周圍2圈</color>且持續2回合的結界，召喚時以及回合結束時將結界範圍內隨機<color=#00F6FF>3</color>個非火屬性格子轉化為火屬性並將範圍內所有火屬性格子<link=\"30020\"><#FFAE07><u>淨化</u></color></link>。當位於結界內時，凜音防禦力提高<color=#00F6FF>50%</color>，隊伍中其他火屬性光靈防禦力提高<color=#00F6FF>10%</color>。",
  str_skill_desc_336143 = "以自身為中心，召喚一個覆蓋<color=#00F6FF>周圍2圈</color>且持續2回合的結界，召喚時以及回合結束時將結界範圍內隨機<color=#00F6FF>3</color>個非火屬性格子轉化為火屬性並將範圍內所有火屬性格子<link=\"30020\"><#FFAE07><u>淨化</u></color></link>。當位於結界內時，凜音防禦力提高<color=#00F6FF>50%</color>，隊伍中其他火屬性光靈防禦力提高<color=#00F6FF>10%</color>。",
  str_skill_passive_desc_410143 = "當凜音以任何方式從隊員位變動至隊長位時，回復凜音目前防禦力<color=#00F6FF>{1}</color>的生命值。每回合最多觸發<color=#00F6FF>1</color>次。",
  str_skill_passive_desc_416143 = "當凜音以任何方式從隊員位變動至隊長位時，回復凜音目前防禦力<color=#00F6FF>{1}</color>的生命值。每回合最多觸發<color=#00F6FF>1</color>次。本場戰鬥可更換隊長次數<color=#00F6FF>+1</color>。",
  str_skill_passive_desc_420143 = "當凜音以任何方式從隊員位變動至隊長位時，回復凜音目前防禦力<color=#00F6FF>{1}</color>的生命值，若觸發後生命值已滿，則將最近的水屬性格子轉化為火屬性。每回合最多觸發<color=#00F6FF>1</color>次。",
  str_skill_passive_desc_426143 = "當凜音以任何方式從隊員位變動至隊長位時，回復凜音目前防禦力<color=#00F6FF>{1}</color>的生命值，若觸發後生命值已滿，則將最近的水屬性格子轉化為火屬性。每回合最多觸發<color=#00F6FF>1</color>次。本場戰鬥可更換隊長次數<color=#00F6FF>+1</color>。",
