  str_skill_desc_2001442 = "對<color=#00F6FF>周圍3圈</color>內的2個敵人造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2001443 = "對<color=#00F6FF>周圍3圈</color>內的3個敵人造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_300144 = "與目前隊長交換位置。",
  str_skill_desc_302144 = "與所選其他隊員交換位置。",
  str_skill_desc_305144 = "與選擇的其他隊員交換位置。本場戰鬥可更換隊長次數+<color=#00F6FF>1</color>。",
  str_skill_desc_310144 = "與目前隊長交換位置。",
  str_skill_desc_312144 = "與所選其他隊員交換位置。",
  str_skill_desc_315144 = "與選擇的其他隊員交換位置。本場戰鬥可更換隊長次數+<color=#00F6FF>1</color>。",
  str_skill_passive_desc_410144 = "當柏乃發現自己不在隊尾時，會強制後退至隊尾，其他隊員前進1個位置。本回合隊伍中<color=#00F6FF>位置後退過</color>的光靈獲得等同於柏乃基礎攻擊力<color=#00F6FF>{1}</color>的攻擊加成（多次觸發時取最高加成）。",
  str_skill_passive_desc_420144 = "當柏乃發現自己不在隊尾時，會強制後退至隊尾，其他隊員前進1個位置。本回合隊伍中<color=#00F6FF>位置後退過</color>的光靈獲得等同於柏乃基礎攻擊力<color=#00F6FF>{1}</color>的攻擊加成（多次觸發時取最高加成）。位置後退得越多，加成越高，最高為基礎值的2.5倍。",
  str_skill_passive_desc_430144 = "當柏乃發現自己不在隊尾時，會強制後退至隊尾，其他隊員前進1個位置。本回合隊伍中<color=#00F6FF>位置後退過</color>的光靈獲得等同於柏乃基礎攻擊力<color=#00F6FF>{1}</color>的攻擊加成（多次觸發時取最高加成）。位置後退得越多，加成越高，最高為基礎值的2.5倍。目前的隊長獲得與柏乃相同的攻擊加成。",
  str_skill_passive_desc_415144 = "當柏乃發現自己不在隊尾時，會強制後退至隊尾，其他隊員前進1個位置。本回合隊伍中<color=#00F6FF>位置後退過</color>的光靈獲得等同於柏乃基礎攻擊力<color=#00F6FF>{1}</color>的攻擊加成（多次觸發時取最高加成）。本場戰鬥可更換隊長次數<color=#00F6FF>+1</color>。",
  str_skill_passive_desc_425144 = "當柏乃發現自己不在隊尾時，會強制後退至隊尾，其他隊員前進1個位置。本回合隊伍中<color=#00F6FF>位置後退過</color>的光靈獲得等同於柏乃基礎攻擊力<color=#00F6FF>{1}</color>的攻擊加成（多次觸發時取最高加成）。位置後退得越多，加成越高，最高為基礎值的2.5倍。本場戰鬥可更換隊長次數<color=#00F6FF>+1</color>。",
  str_skill_passive_desc_435144 = "當柏乃發現自己不在隊尾時，會強制後退至隊尾，其他隊員前進1個位置。本回合隊伍中<color=#00F6FF>位置後退過</color>的光靈獲得等同於柏乃基礎攻擊力<color=#00F6FF>{1}</color>的攻擊加成（多次觸發時取最高加成）。位置後退得越多，加成越高，最高為基礎值的2.5倍。目前的隊長獲得與柏乃相同的攻擊加成。本場戰鬥可更換隊長次數<color=#00F6FF>+1</color>。",
