  str_skill_name_290190110 = "冥土幽刀·襲",
  str_skill_desc_290190110 = "突進至玩家前方，造成大量傷害，並將隊長擊落至隊尾位置。若玩家處於非十字範圍且距離較遠，則對玩家進行遠程射擊。",
  str_skill_name_290190120 = "冥土幽刀·擊",
  str_skill_desc_290190120 = "對處於身旁的玩家橫向斬切，造成大量傷害。若玩家處於非十字範圍且距離較遠，則對玩家進行遠程射擊。",
  str_skill_desc_490190120 = "突進結束後，對處於身邊的玩家橫向斬切，造成大量傷害。",
  str_skill_name_290190130 = "冥土幽刀·落",
  str_skill_desc_290190130 = "向棋盤中心移動後，抽出銃槍，對非十字範圍且距離較遠的玩家造成遠程射擊傷害。",
  str_skill_desc_490190130 = "抽出銃槍，對斬切範圍外的玩家造成遠程射擊傷害。",
  str_skill_name_290191110 = "薙·狂刀二連",
  str_skill_desc_290191110 = "為了應對身旁的威脅，接連使出橫砍和前刺兩段招式。",
  str_skill_name_290191120 = "薙·狂刀突進",
  str_skill_desc_290191120 = "當與玩家距離較遠時，則追擊至玩家至身旁造成傷害。",
  str_skill_name_290191130 = "薙·狂刀瞬爆",
  str_skill_desc_290191130 = "閃現至戰場中央位置，並對自身周圍造成大面積範圍傷害。如命中，則將隊長擊落至隊尾位置。",
  str_skill_name_290210101 = "噬魔吞卷",
  str_skill_desc_290210101 = "當目標處於範圍內時，吞噬前方兩圈內光靈與「鬼」，對光靈造成傷害，隨後將光靈吐至場地邊緣，詛咒當前光靈隊長並將其擊落至隊尾。",
  str_skill_desc_291210101 = "當目標處於範圍內時，吞噬前方兩圈內光靈與「鬼」，對光靈造成傷害，隨後將光靈吐至場地邊緣，並將隊長擊落至隊尾。",
  str_skill_name_290210102 = "噬魔鬼滅",
  str_skill_desc_290210102 = "當目標處於範圍內時，對目標造成大量傷害，打亂光靈隊伍順序，並秒殺目標周圍的「鬼」。",
  str_skill_name_290210201 = "噬魔鬼呼軍陣",
  str_skill_desc_290210201 = "當目標處於範圍內時，召喚大量的「鬼」，並強化場上所有的「鬼」。",
  str_skill_desc_291210201 = "當目標處於範圍內時，召喚大量的「鬼」，強化並治療場上所有的「鬼」。",
  str_skill_name_290210301 = "噬魔吞卷",
  str_skill_desc_290210301 = "當目標處於範圍內時，吞噬前方兩圈內光靈與「鬼」，對光靈造成真實傷害，吞噬的「鬼」數量越多傷害越高，隨後將光靈吐至場地邊緣，詛咒當前光靈隊長並將其擊落至隊尾。",
  str_skill_name_290042201 = "邪龍撕裂",
  str_skill_desc_290042201 = "哈庫多瑪撕裂眼前的空間，對處於攻擊範圍內的目標造成傷害。",
  str_skill_name_290042211 = "邪龍撕裂",
  str_skill_desc_290042211 = "哈庫多瑪撕裂眼前的空間，對處於攻擊範圍內的目標造成傷害，並擊碎場上部分格子。",
  str_skill_name_290042202 = "哈庫多瑪輪迴",
  str_skill_desc_290042202 = "哈庫多瑪為升潮積蓄自己的力量，鼓起翅膀將目標擊退至場地邊緣，並在場上召喚地刺。",
  str_skill_name_290042204 = "升潮使者",
  str_skill_desc_290042204 = "哈庫多瑪向前飛行，將所有格子向上方推移4格 ，隨後轟炸固定區域。",
  str_skill_name_290042214 = "升潮使者",
  str_skill_desc_290042214 = "哈庫多瑪向前飛行，隨後轟炸固定區域，無論是否擊中目標，都會將目標擊退至場地邊緣。哈庫多瑪落地時在自己身前召喚地刺。",
  str_skill_upgrade_desc_16014513 = "主動技能強化：每一波開始獲得<color=#FFFF00>1</color>點忍力。",
  str_skill_upgrade_desc_16014516 = "裝備技能強化：本場戰鬥可更換隊長次數<color=#FFFF00>+1</color>。",
  str_skill_name_2001451 = "無情無息",
  str_skill_name_2001452 = "無情無息",
  str_skill_name_2001453 = "無情無息",
  str_skill_desc_2001451 = "對<color=#00F6FF>十字形8格</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2001452 = "對<color=#00F6FF>菱形12格</color>造成<color=#00F6FF>{1}%</color>的傷害。並在範圍內隨機<color=#00F6FF>1</color>個可行走的格子召喚1把忍刀。",
  str_skill_desc_2001453 = "對<color=#00F6FF>周圍1圈</color>和<color=#00F6FF>十字形最大</color>範圍造成<color=#00F6FF>{1}%</color>的傷害。並在範圍內隨機<color=#00F6FF>2</color>個可行走的格子召喚1把忍刀。",
