  str_skill_passive_desc_410145 = "主動技能瞬移後收回所有忍刀，每收回1把，對最近的<color=#00F6FF>1</color>個敵人造成1次<color=#00F6FF>{1}</color>無視防禦的傷害，距離越遠傷害越低，最低為原傷害的20%。",
  str_skill_passive_desc_413145 = "主動技能瞬移後收回所有忍刀，每收回1把，對最近的<color=#00F6FF>1</color>個敵人造成1次<color=#00F6FF>{1}</color>無視防禦的傷害，距離越遠傷害越低，最低為原傷害的20%。",
  str_skill_passive_desc_416145 = "主動技能瞬移後收回所有忍刀，每收回1把，對最近的<color=#00F6FF>1</color>個敵人造成1次<color=#00F6FF>{1}</color>無視防禦的傷害，距離越遠傷害越低，最低為原傷害的20%。 本場戰鬥可更換隊長次數<color=#00F6FF>+1</color>。",
  str_skill_passive_desc_420145 = "主動技能瞬移後收回所有忍刀，每收回1把，對最近的<color=#00F6FF>1</color>個敵人造成1次<color=#00F6FF>{1}</color>無視防禦的傷害，距離越遠傷害越低，最低為原傷害的20%。若共收回至少<color=#00F6FF>4</color>把忍刀，則重新召喚<color=#00F6FF>1</color>把。",
  str_skill_passive_desc_423145 = "主動技能瞬移後收回所有忍刀，每收回1把，對最近的<color=#00F6FF>1</color>個敵人造成1次<color=#00F6FF>{1}</color>無視防禦的傷害，距離越遠傷害越低，最低為原傷害的20%。若共收回至少<color=#00F6FF>4</color>把忍刀，則重新召喚<color=#00F6FF>1</color>把。",
  str_skill_passive_desc_426145 = "主動技能瞬移後收回所有忍刀，每收回1把，對最近的<color=#00F6FF>1</color>個敵人造成1次<color=#00F6FF>{1}</color>無視防禦的傷害，距離越遠傷害越低，最低為原傷害的20%。若共收回至少<color=#00F6FF>4</color>把忍刀，則重新召喚<color=#00F6FF>1</color>把。本場戰鬥可更換隊長次數<color=#00F6FF>+1</color>。",
  str_skill_passive_desc_430145 = "主動技能瞬移後收回所有忍刀，每收回1把，對最近的<color=#00F6FF>1</color>個敵人造成1次<color=#00F6FF>{1}</color>無視防禦的傷害，距離越遠傷害越低，最低為原傷害的20%。若共收回至少<color=#00F6FF>4</color>把忍刀，則重新召喚<color=#00F6FF>1</color>把。當雨森以任何方式從隊員位變動至隊長位時，獲得<color=#00F6FF>1</color>點<link=\"30028\"><#FFAE07><u>忍力</u></color></link>，每回合最多觸發<color=#00F6FF>3</color>次。",
  str_skill_passive_desc_433145 = "主動技能瞬移後收回所有忍刀，每收回1把，對最近的<color=#00F6FF>1</color>個敵人造成1次<color=#00F6FF>{1}</color>無視防禦的傷害，距離越遠傷害越低，最低為原傷害的20%。若共收回至少<color=#00F6FF>4</color>把忍刀，則重新召喚<color=#00F6FF>1</color>把。當雨森以任何方式從隊員位變動至隊長位時，獲得<color=#00F6FF>1</color>點<link=\"30029\"><#FFAE07><u>忍力</u></color></link>，每回合最多觸發<color=#00F6FF>3</color>次。",
  str_skill_passive_desc_436145 = "主動技能瞬移後收回所有忍刀，每收回1把，對最近的<color=#00F6FF>1</color>個敵人造成1次<color=#00F6FF>{1}</color>無視防禦的傷害，距離越遠傷害越低，最低為原傷害的20%。若共收回至少<color=#00F6FF>4</color>把忍刀，則重新召喚<color=#00F6FF>1</color>把。當雨森以任何方式從隊員位變動至隊長位時，獲得<color=#00F6FF>1</color>點<link=\"30029\"><#FFAE07><u>忍力</u></color></link>，每回合最多觸發<color=#00F6FF>3</color>次。本場戰鬥可更換隊長次數<color=#00F6FF>+1</color>。",
