  str_skill_desc_300146 = "與當前的隊長交換位置，本回合連鎖技能對<color=#00F6FF>相鄰4格</color>傷害翻倍，回合結束時與隊尾的光靈交換位置。",
  str_skill_desc_303146 = "與當前的隊長交換位置，本回合連鎖技能對<color=#00F6FF>相鄰4格</color>傷害翻倍，回合結束時與隊尾的光靈交換位置。",
  str_skill_desc_320146 = "與當前的隊長交換位置並獲得1層<link=\"30026\"><#FFAE07><u>俠心印記</u></color></link>，本回合連鎖技能對<color=#00F6FF>相鄰4格</color>傷害翻倍，回合結束時與隊尾的光靈交換位置。",
  str_skill_desc_323146 = "與當前的隊長交換位置並獲得1層<link=\"30026\"><#FFAE07><u>俠心印記</u></color></link>，本回合連鎖技能對<color=#00F6FF>相鄰4格</color>傷害翻倍，回合結束時與隊尾的光靈交換位置。",
  str_skill_desc_330146 = "與當前的隊長交換位置並獲得1層<link=\"30026\"><#FFAE07><u>俠心印記</u></color></link>，本回合連鎖技能對<color=#00F6FF>相鄰4格</color>傷害翻倍，回合結束時與隊尾的光靈交換位置。",
  str_skill_desc_333146 = "與當前的隊長交換位置並獲得1層<link=\"30026\"><#FFAE07><u>俠心印記</u></color></link>，本回合連鎖技能對<color=#00F6FF>相鄰4格</color>傷害翻倍，回合結束時與隊尾的光靈交換位置。",
  str_skill_passive_name_410146 = "經絡之合",
  str_skill_passive_name_416146 = "經絡之合",
  str_skill_passive_name_430146 = "經絡之合",
  str_skill_passive_name_436146 = "經絡之合",
  str_skill_passive_desc_410146 = "可獲得<link=\"30026\"><#FFAE07><u>俠心印記</u></color></link>。如果瑤在己方回合擔任過隊長，本回合每層印記增加瑤<color=#00F6FF>{1}</color>的基礎攻擊力，回合結束清空。",
  str_skill_passive_desc_416146 = "可獲得<link=\"30026\"><#FFAE07><u>俠心印記</u></color></link>。如果瑤在己方回合擔任過隊長，本回合每層印記增加瑤<color=#00F6FF>{1}</color>的基礎攻擊力，回合結束清空。本場戰鬥可更換隊長次數<color=#00F6FF>+1</color>。",
  str_skill_passive_desc_430146 = "可獲得<link=\"30027\"><#FFAE07><u>俠心印記</u></color></link>。如果瑤在己方回合擔任過隊長，本回合每層印記增加瑤<color=#00F6FF>{1}</color>的基礎攻擊力，回合結束清空。每當瑤以任何方式從隊員位變動至隊長位時獲得<color=#00F6FF>1</color>層<link=\"30027\"><#FFAE07><u>俠心印記</u></color></link>。",
  str_skill_passive_desc_436146 = "可獲得<link=\"30027\"><#FFAE07><u>俠心印記</u></color></link>。如果瑤在己方回合擔任過隊長，本回合每層印記增加瑤<color=#00F6FF>{1}</color>的基礎攻擊力，回合結束清空。每當瑤以任何方式從隊員位變動至隊長位時獲得<color=#00F6FF>1</color>層<link=\"30027\"><#FFAE07><u>俠心印記</u></color></link>。本場戰鬥可更換隊長次數<color=#00F6FF>+1</color>。",
  str_skill_upgrade_desc_15014712 = "主動技能強化：每次擔任隊長時，主動技能冷卻回合<color=#FFFF00>-1</color>，每回合最多觸發<color=#00F6FF>3</color>次。",
  str_skill_upgrade_desc_15014715 = "裝備技能強化：本場戰鬥可更換隊長次數<color=#FFFF00>+1</color>。",
  str_skill_desc_2001471 = "造成2次<color=#00F6FF>150%</color>的傷害，隨機分配至自身<color=#00F6FF>周圍3圈</color>內的敵人身上。對同一目標造成多次傷害時，从第2次起，每次傷害減半。",
  str_skill_desc_2001472 = "造成3次<color=#00F6FF>160%</color>的傷害。隨機分配到自身<color=#00F6FF>周圍3圈</color>內的敵人身上。對同一目標造成多次傷害時，從第2次起每次傷害減半。",
  str_skill_desc_2001473 = "造成4次<color=#00F6FF>160%</color>的傷害，隨機分配到<color=#00F6FF>周圍3圈</color>內的敵人身上。對同一目標造成多次傷害時，第2次起每次傷害減半。",
  str_skill_desc_300147 = "任選<color=#00F6FF>周圍3圈</color>內的1个格子，造成<color=#00F6FF>8</color>次<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_302147 = "任選<color=#00F6FF>周圍3圈</color>內的1個格子，造成<color=#00F6FF>8</color>次<color=#00F6FF>{1}%</color>的傷害。每次擔任隊長時，主動技能冷卻回合<color=#FFFF00>-1</color>，每回合最多觸發<color=#00F6FF>3</color>次。",
  str_skill_desc_320147 = "任選<color=#00F6FF>周圍3圈</color>內的1個格子，造成<color=#00F6FF>8</color>次<color=#00F6FF>{1}%</color>的傷害，隨後對該格子及其<color=#00F6FF>周圍1圈</color>再造成1次<color=#00F6FF>188%</color>的傷害。",
  str_skill_desc_322147 = "任選<color=#00F6FF>周圍3圈</color>內的1個格子，造成<color=#00F6FF>8</color>次<color=#00F6FF>{1}%</color>的傷害，隨後對該格子及其<color=#00F6FF>周圍1圈</color>再造成1次<color=#00F6FF>188%</color>的傷害。每次擔任隊長時，主動技能冷卻回合<color=#FFFF00>-1</color>，每回合最多觸發<color=#00F6FF>3</color>次。",
  str_skill_passive_desc_410147 = "每回合開始時，阿桃&阿杏會強行擔任隊長，其餘隊員後退1個位置。阿桃&阿杏每次成為隊長時，均會獲得一份<link=\"30030\"><#FFAE07><u>「特別蟹家料理」</u></color></link>，有<color=#00F6FF>{1}</color>機率<color=#00F6FF>額外獲得一份</color>。",
  str_skill_passive_desc_415147 = "每回合開始時，阿桃&阿杏會強行擔任隊長，其餘隊員後退1個位置。阿桃&阿杏每次成為隊長時，均會獲得一份<link=\"30030\"><#FFAE07><u>「特別蟹家料理」</u></color></link>，有<color=#00F6FF>{1}</color>機率<color=#00F6FF>額外獲得一份</color>。本場戰鬥可更換隊長次數<color=#00F6FF>+1</color>。",
  str_skill_passive_desc_430147 = "每回合開始時，阿桃&阿杏會強行擔任隊長，其餘隊員後退1個位置。阿桃&阿杏每次成為隊長時，均會獲得一份<link=\"30030\"><#FFAE07><u>「特別蟹家料理」</u></color></link>，<color=#00F6FF>每次都有{1}</color>機率<color=#00F6FF>再來一碗</color>！",
  str_skill_passive_desc_435147 = "每回合開始時，阿桃&阿杏會強行擔任隊長，其餘隊員後退1個位置。阿桃&阿杏每次成為隊長時，均會獲得一份<link=\"30030\"><#FFAE07><u>「特別蟹家料理」</u></color></link>，<color=#00F6FF>每次都有{1}</color>機率<color=#00F6FF>再來一碗</color>！本場戰鬥可更換隊長次數<color=#00F6FF>+1</color>。",
