  str_skill_desc_2301514 = "對生命值百分比最低的敵人造成2次<color=#00F6FF>{1}%</color>攻擊力的傷害。理智值不高於<color=#00F6FF>60|25</color>時，額外造成1|2次傷害；每次的最終傷害降低<color=#00F6FF>15%</color>。",
  str_skill_desc_2301515 = "對生命值百分比最低的敵人造成2次<color=#00F6FF>{1}%</color>攻擊力的傷害。理智值不高於<color=#00F6FF>60|25</color>時，額外造成1|2次傷害；每次的最終傷害降低<color=#00F6FF>10%</color>。",
  str_skill_desc_2301516 = "對生命值百分比最低的敵人造成2次<color=#00F6FF>{1}%</color>攻擊力的傷害。理智值不高於<color=#00F6FF>60|25</color>時，額外造成1|2次傷害；每次的最終傷害降低<color=#00F6FF>5%</color>。",
  str_skill_desc_2301517 = "對生命值百分比最低的敵人造成2次<color=#00F6FF>{1}%</color>攻擊力的傷害。理智值不高於<color=#00F6FF>60|25|0</color>時，額外造成1|2|3次傷害；每次的最終傷害降低<color=#00F6FF>15%</color>。",
  str_skill_desc_2301518 = "對生命值百分比最低的敵人造成2次<color=#00F6FF>{1}%</color>攻擊力的傷害。理智值不高於<color=#00F6FF>60|25|0</color>時，額外造成1|2|3次傷害；每次的最終傷害降低<color=#00F6FF>10%</color>。",
  str_skill_desc_2301519 = "對生命值百分比最低的敵人造成2次<color=#00F6FF>{1}%</color>攻擊力的傷害。理智值不高於<color=#00F6FF>60|25|0</color>時，額外造成1|2|3次傷害；每次的最終傷害降低<color=#00F6FF>5%</color>。",
  str_skill_desc_300151 = "賈爾斯在進入戰鬥後自帶<link=\"30039\"><#FFAE07><u>【理智系統】</u></color></link>。消耗<color=#00F6FF>15</color>點理智值，任選1格，對目標格子<color=#00F6FF>十字相鄰4格</color>造成<color=#00F6FF>{1}%</color>的傷害。如果選擇自身所在格，造成2倍傷害。",
  str_skill_desc_3001510 = "賈爾斯在進入戰鬥後自帶<link=\"30039\"><#FFAE07><u>【理智系統】</u></color></link>。消耗<color=#00F6FF>15</color>點理智值，任選1格，對目標格子<color=#00F6FF>十字相鄰4格</color>造成<color=#00F6FF>{1}%</color>的傷害。如果選擇自身所在格，造成2倍傷害。主動技能擊殺目標後可再次使用，所需的理智值和最終傷害均翻倍。",
  str_skill_desc_3001511 = "賈爾斯在進入戰鬥後自帶<link=\"30039\"><#FFAE07><u>【理智系統】</u></color></link>。消耗<color=#00F6FF>30</color>點理智值，任選1格，對目標格子<color=#00F6FF>十字相鄰4格</color>造成<color=#00F6FF>{1}%</color>的傷害。如果選擇自身所在格，造成2倍傷害。主動技能擊殺目標後可再次使用，所需的理智值和最終傷害均翻倍。",
  str_skill_desc_3001512 = "賈爾斯在進入戰鬥後自帶<link=\"30039\"><#FFAE07><u>【理智系統】</u></color></link>。消耗<color=#00F6FF>60</color>點理智值，任選1格，對目標格子<color=#00F6FF>十字相鄰4格</color>造成<color=#00F6FF>{1}%</color>的傷害。如果選擇自身所在格，造成2倍傷害。主動技能擊殺目標後可再次使用，所需的理智值和最終傷害均翻倍。",
  str_skill_desc_3001513 = "賈爾斯在進入戰鬥後自帶<link=\"30039\"><#FFAE07><u>【理智系統】</u></color></link>。消耗<color=#00F6FF>120</color>點理智值，任選1格，對目標格子<color=#00F6FF>十字相鄰4格</color>造成<color=#00F6FF>{1}%</color>的傷害。如果選擇自身所在格，造成2倍傷害。主動技能擊殺目標後可再次使用，所需的理智值和最終傷害均翻倍。",
  str_skill_desc_3001514 = "賈爾斯在進入戰鬥後自帶<link=\"30039\"><#FFAE07><u>【理智系統】</u></color></link>。消耗<color=#00F6FF>240</color>點理智值，任選1格，對目標格子<color=#00F6FF>十字相鄰4格</color>造成<color=#00F6FF>{1}%</color>的傷害。如果選擇自身所在格，造成2倍傷害。主動技能擊殺目標後可再次使用，所需的理智值和最終傷害均翻倍。",
  str_skill_passive_desc_410151 = "目前回合<color=#00F6FF>擊殺敵人後發動</color>：賈爾斯造成傷害時，根據目前理智值提高傷害，理智值愈低加成愈高，最大提高<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_413151 = "目前回合<color=#00F6FF>擊殺敵人後發動</color>：賈爾斯造成傷害時，根據目前理智值提高傷害，理智值愈低加成愈高，最大提高<color=#00F6FF>{1}</color>。擊殺<color=#00F6FF>蜃妖</color>會額外提高<color=#00F6FF>10%</color>加成。",
  str_skill_passive_desc_416151 = "目前回合<color=#00F6FF>擊殺敵人後發動</color>：賈爾斯造成傷害時，根據目前理智值提高傷害，理智值愈低加成愈高，最大提高<color=#00F6FF>{1}</color>。擊殺<color=#00F6FF>蜃妖</color>會額外提高<color=#00F6FF>10%</color>加成。",
  str_skill_passive_desc_430151 = "目前回合<color=#00F6FF>擊殺敵人後發動</color>：賈爾斯造成傷害時，根據目前理智值提高傷害，理智值愈低加成愈高，最大提高<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_433151 = "目前回合<color=#00F6FF>擊殺敵人後發動</color>：賈爾斯造成傷害時，根據目前理智值提高傷害，理智值愈低加成愈高，最大提高<color=#00F6FF>{1}</color>。擊殺<color=#00F6FF>蜃妖</color>會額外提高<color=#00F6FF>10%</color>加成。",
  str_skill_passive_desc_436151 = "目前回合<color=#00F6FF>擊殺敵人後發動</color>：賈爾斯造成傷害時，根據目前理智值提高傷害，理智值愈低加成愈高，最大提高<color=#00F6FF>{1}</color>。擊殺<color=#00F6FF>蜃妖</color>會額外提高<color=#00F6FF>10%</color>加成。",
  str_skill_upgrade_desc_16015113 = "裝備技能強化：擊殺<color=#00F6FF>蜃妖</color>會額外提高<color=#00F6FF>10%</color>加成。",
  str_skill_upgrade_desc_16015116 = "連鎖技能強化：理智值為0時，額外觸發<color=#00F6FF>3</color>次傷害（覺醒3階生效）。",
