  str_skill_desc_302152 = "梅在進入戰鬥後自帶<link=\"30039\"><#FFAE07><u>【理智系統】</u></color></link>。流失<color=#00F6FF>15%</color>目前生命值，回復<color=#00F6FF>25%</color>已損失理智值。",
  str_skill_desc_305152 = "梅能夠改變本局的<link=\"30040\"><#FFAE07><u>【理智系統】</u></color></link>，更不易受理智系統負面效果影響，且負面效果降低。流失<color=#00F6FF>15%</color>目前生命值，回復<color=#00F6FF>25%</color>已損失理智值。",
