  str_skill_passive_desc_415152 = "每降低1點理智值，回復相當於梅<color=#00F6FF>{1}</color>攻擊力的生命值。",
  str_skill_passive_desc_420152 = "每降低1點理智值，回復相當於梅<color=#00F6FF>{1}</color>攻擊力的生命值。梅的防禦力隨理智值的降低而提高，最大提高<color=#00F6FF>100%</color>。",
  str_skill_passive_desc_425152 = "每降低1點理智值，回復相當於梅<color=#00F6FF>{1}</color>攻擊力的生命值。梅的防禦力隨理智值的降低而提高，最大提高<color=#00F6FF>100%</color>。",
  str_skill_passive_desc_430152 = "每降低1點理智值，回復相當於梅<color=#00F6FF>{1}</color>攻擊力的生命值，理智值愈低回復量愈高，最大提高<color=#00F6FF>100%</color>。梅的防禦力隨理智值的降低而提高，最大提高<color=#00F6FF>100%</color>。",
  str_skill_passive_desc_435152 = "每降低1點理智值，回復相當於梅<color=#00F6FF>{1}</color>攻擊力的生命值，理智值愈低回復量愈高，最大提高<color=#00F6FF>100%</color>。梅的防禦力隨理智值的降低而提高，最大提高<color=#00F6FF>100%</color>。",
  str_skill_upgrade_desc_15015212 = "主動技能強化：流失<color=#00F6FF>15%</color>目前生命值，回復<color=#00F6FF>25%</color>已損失理智值。",
  str_skill_upgrade_desc_15015215 = "改變本局的理智系統：更不易受理智系統負面效果影響，且負面效果降低。",
