  str_skill_desc_22015011 = "對<color=#00F6FF>橫向1排</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_22015012 = "對<color=#00F6FF>橫向3排</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_22015013 = "對<color=#00F6FF>橫向5排</color>造成<color=#00F6FF>{1}%</color>的傷害。理智值不高於<color=#00F6FF>75</color>時，觸發條件減少至<color=#00F6FF>15</color>；處於<color=#00F6FF>瘋狂狀態</color>時，減少至<color=#00F6FF>5</color>。",
  str_skill_desc_23015011 = "對<color=#00F6FF>橫向1排</color>造成<color=#00F6FF>{1}%</color>的傷害。理智值愈低造成傷害愈高，最大提高<color=#00F6FF>80%</color>。",
  str_skill_desc_23015012 = "對<color=#00F6FF>橫向3排</color>造成<color=#00F6FF>{1}%</color>的傷害。理智值愈低造成傷害愈高，最大提高<color=#00F6FF>80%</color>。",
  str_skill_desc_23015013 = "對<color=#00F6FF>橫向5排</color>造成<color=#00F6FF>{1}%</color>的傷害。理智值不高於<color=#00F6FF>75</color>時，觸發條件減少至<color=#00F6FF>15</color>；處於<color=#00F6FF>瘋狂狀態</color>時，減少至<color=#00F6FF>5</color>。理智值越低造成傷害越高，最大提高<color=#00F6FF>80%</color>。",
  str_skill_desc_23615011 = "對<color=#00F6FF>橫向1排</color>造成<color=#00F6FF>{1}%</color>的傷害。理智值愈低造成傷害愈高，最大提高<color=#00F6FF>100%</color>。",
  str_skill_desc_23615012 = "對<color=#00F6FF>橫向3排</color>造成<color=#00F6FF>{1}%</color>的傷害。理智值愈低造成傷害愈高，最大提高<color=#00F6FF>100%</color>。",
  str_skill_desc_23615013 = "對<color=#00F6FF>橫向5排</color>造成<color=#00F6FF>{1}%</color>的傷害。理智值不高於<color=#00F6FF>75</color>時，觸發條件減少至<color=#00F6FF>15</color>；處於<color=#00F6FF>瘋狂狀態</color>時，減少至<color=#00F6FF>5</color>。理智值愈低造成傷害愈高，最大提高<color=#00F6FF>100%</color>。",
  str_skill_desc_3001501 = "蓮在進入戰鬥後自帶<link=\"30039\"><#FFAE07><u>【理智系統】</u></color></link>。任選1個格子，並在<color=#00F6FF>周圍兩圈</color>內再次選擇1個格子確定一個矩形區域，對該區域內格子造成<color=#00F6FF>333%</color>的傷害，矩形內每個格子扣除<color=#00F6FF>3</color>點理智值。對同一敵人造成多次傷害時，後續只有<color=#00F6FF>33%</color>的效果。",
  str_skill_desc_3031501 = "蓮在進入戰鬥後自帶<link=\"30039\"><#FFAE07><u>【理智系統】</u></color></link>。任選1個格子，並在<color=#00F6FF>周圍兩圈</color>內再次選擇1個格子確定一個矩形區域，對該區域內格子造成<color=#00F6FF>333%</color>的傷害，矩形內每個格子扣除<color=#00F6FF>3</color>點理智值。對同一敵人造成多次傷害時，後續只有<color=#00F6FF>33%</color>的效果。主動技能每造成1次傷害，蓮的最大生命值提高<color=#00F6FF>3%</color>。",
  str_skill_passive_desc_410150 = "每回合開始時若未處於<color=#00F6FF>冷靜狀態</color>，對所有敵人造成一次等同於隊伍最大生命值<color=#00F6FF>{1}</color>的傷害，理智值愈低傷害愈高，最大提高到隊伍最大生命值的<color=#00F6FF>{2}</color>。",
  str_skill_name_290220101 = "夜之克破",
  str_skill_desc_290220101 = "對技能範圍內的敵人發動強力攻擊。",
  str_skill_name_290220102 = "夜之憎鳴",
  str_skill_desc_290220102 = "對周圍2圈對目標造成大量傷害，並將50%的瘀傷值轉化為生命值。",
  str_skill_name_290220103 = "夜之反擊",
  str_skill_desc_290220103 = "每當光靈施放主動技能時，對周圍2圈對目標造成大量傷害，並將50%瘀傷值轉化為生命值。",
  str_skill_name_290220201 = "黯徨爪擊",
  str_skill_desc_290220201 = "使用利爪對頭部周圍五格範圍內的敵人造成傷害。",
  str_skill_name_290220202 = "黯徨撲進",
  str_skill_desc_290220202 = "向前撲向敵人，落地時摧毀腳下的機關，並對周圍1圈內的敵人造成傷害。",
  str_skill_name_290220203 = "黯徨剪尾",
  str_skill_desc_290220203 = "當敵人不在自己前方時，立刻甩尾改變自己的朝向，使自己始終朝向敵人。若轉身後的位置受到阻擋，則會直接施放一次黯徨猛撲。",
  str_skill_name_290220204 = "黯徨猛撲",
  str_skill_desc_290220204 = "高高躍起後撲到敵人周圍，從空中落地時對周圍1圈內的敵人造成巨量傷害，隨後結束全部行動。",
  str_skill_name_29026011 = "游冥·掃滅",
  str_skill_desc_29026011 = "向玩家移動，揮動鐮刀橫掃對自身周圍範圍內敵人造成傷害。",
  str_skill_name_29026012 = "游冥·旋鐮",
  str_skill_desc_29026012 = "原地在場邊召喚鐮刀並回收，對米字型範圍內的敵人造成傷害。",
  str_skill_name_29026021 = "游冥·刃雨",
  str_skill_desc_29026021 = "向玩家移動後，如果玩家在攻擊範圍內，則揮動前臂對前方兩格內敵人造成傷害。\n如果不在，則遁入隱匿狀態，閃避普通攻擊傷害。（受到控制效果則解除隱匿狀態）",
  str_skill_name_29026023 = "游冥·血號",
  str_skill_desc_29026023 = "原地施放技能，對全畫面範圍內敵人造成傷害。",
  str_skill_name_290270101 = "吞羅·呼喚",
  str_skill_desc_290270101 = "吞羅在場上隨機位置召喚2隻暗鬼來協助自己戰鬥。",
  str_skill_name_290270102 = "吞羅·卻擊",
  str_skill_desc_290270102 = "吞羅擊退場上的光靈和其他所有暗鬼，並對光靈造成傷害。",
  str_skill_name_290270103 = "吞羅·凋噬",
  str_skill_desc_290270103 = "對光靈上回合所在位置及其周圍1圈施放衝擊。若光靈處於衝擊範圍內，將受到大量傷害。",
  str_skill_name_290270111 = "吞羅·黯進",
  str_skill_desc_290270111 = "吞羅在場上召喚黯域，限制光靈的行動範圍。",
  str_skill_upgrade_desc_16015413 = "連鎖技能強化：連鎖技能最終傷害次數<color=#FFFF00>+1</color>。",
  str_skill_upgrade_desc_16015416 = "連鎖技能強化：連鎖技能傷害係數增加<color=#FFFF00>20%</color>。",
  str_skill_name_200154 = "今空矢雨",
  str_skill_name_203154 = "今空矢雨",
  str_skill_name_206154 = "今空矢雨",
  str_skill_name_300154 = "昔日拘羈",
  str_skill_name_3001541 = "昔日拘羈",
  str_skill_name_320154 = "昔日拘羈",
  str_skill_name_330154 = "昔日拘羈",
  str_skill_desc_300154 = "任選1個敵人，對其進行<color=#00F6FF>鎖定</color>，場上最多只能有<color=#00F6FF>1</color>個目標被鎖定。被鎖定的目標存活期間，薇絲·空瞳的連鎖技能只會<color=#00F6FF>攻擊該目標</color>。若選擇的敵人已經被鎖定，則對其造成1次<color=#00F6FF>100%</color>的傷害。",
  str_skill_desc_330154 = "任選1個敵人，對其進行<color=#00F6FF>鎖定</color>，場上最多只能有<color=#00F6FF>1</color>個目標處於被鎖定的狀態。被鎖定的目標存活期間，薇絲·空瞳的連鎖技能始終<color=#00F6FF>攻擊該目標</color>。若選擇的敵人已經被鎖定，則對其造成1次<color=#00F6FF>100%</color>的傷害，目標每層<link=\"30042\"><#FFAE07><u>無時印記</u></color></link>額外提高<color=#00F6FF>5%</color>傷害。",
  str_skill_desc_200154 = "每連線行走<color=#00F6FF>3</color>個格子，對最靠近的目標造成1次<color=#00F6FF>80%</color>的傷害，該傷害不受連鎖格子數量加成。",
  str_skill_desc_203154 = "每連線行走<color=#00F6FF>3</color>個格子，對最靠近的目標造成1次<color=#00F6FF>80%</color>的傷害，該傷害不受連鎖格子數量加成。連鎖技能最終傷害次數<color=#00F6FF>+1</color>。",
  str_skill_desc_206154 = "每連線行走<color=#00F6FF>3</color>個格子，對最靠近的目標造成1次<color=#00F6FF>100%</color>的傷害，該傷害不受連鎖格子數量加成。連鎖技能最終傷害次數<color=#00F6FF>+1</color>。",
  str_skill_passive_name_410154 = "無時之印",
  str_skill_passive_name_420154 = "無時之印",
  str_skill_passive_desc_410154 = "可對被鎖定的目標附加<link=\"30041\"><#FFAE07><u>無時印記</u></color></link>，每層<link=\"30041\"><#FFAE07><u>無時印記</u></color></link>增加目標受到薇絲·空瞳<color=#00F6FF>{1}</color>的傷害。",
  str_skill_passive_desc_420154 = "可對被鎖定的目標附加<link=\"30042\"><#FFAE07><u>無時印記</u></color></link>，每層<link=\"30042\"><#FFAE07><u>無時印記</u></color></link>增加目標受到薇絲·空瞳<color=#00F6FF>{1}</color>的傷害。被鎖定的目標對我方每造成<color=#00F6FF>3%</color>傷害，薇絲·空瞳對其附加1層無時印記。",
