  str_skill_desc_300155 = "消耗20點<link=\"30045\"><#FFAE07><u>孤勇值</u></color></link>，本回合進入<color=#00F6FF>孤勇狀態</color>：連鎖技能範圍和傷害提升。回合結束時，若目前孤勇值不少於<color=#00F6FF>10</color>點，孤勇值<color=#00F6FF>減半</color>（至少扣除10點），下回合<color=#00F6FF>繼續保持孤勇狀態</color>。",
