  str_skill_desc_316155 = "消耗20點<link=\"30047\"><#FFAE07><u>孤勇值</u></color></link>，本回合進入<color=#00F6FF>孤勇狀態</color>：連鎖技能範圍和傷害提升。回合結束時，若目前孤勇值不少於<color=#00F6FF>10</color>點，孤勇值<color=#00F6FF>減半</color>（至少扣除10點），下回合<color=#00F6FF>繼續保持孤勇狀態</color>。",
  str_skill_desc_320155 = "消耗20點<link=\"30045\"><#FFAE07><u>孤勇值</u></color></link>，本回合進入<color=#00F6FF>孤勇狀態</color>：連鎖技能範圍和傷害提升。回合結束時，若目前孤勇值不少於<color=#00F6FF>10</color>點，孤勇值<color=#00F6FF>減半</color>（至少扣除10點），下回合<color=#00F6FF>繼續保持孤勇狀態</color>。",
  str_skill_desc_323155 = "消耗20點<link=\"30046\"><#FFAE07><u>孤勇值</u></color></link>，本回合進入<color=#00F6FF>孤勇狀態</color>：連鎖技能範圍和傷害提升。回合結束時，若目前孤勇值不少於<color=#00F6FF>10</color>點，孤勇值<color=#00F6FF>減半</color>（至少扣除10點），下回合<color=#00F6FF>繼續保持孤勇狀態</color>。",
  str_skill_desc_326155 = "消耗20點<link=\"30047\"><#FFAE07><u>孤勇值</u></color></link>，本回合進入<color=#00F6FF>孤勇狀態</color>：連鎖技能範圍和傷害提升。回合結束時，若目前孤勇值不少於<color=#00F6FF>10</color>點，孤勇值<color=#00F6FF>減半</color>（至少扣除10點），下回合<color=#00F6FF>繼續保持孤勇狀態</color>。",
  str_skill_desc_2001551 = "<color=#00F6FF>正常狀態</color>：獲得<color=#00F6FF>3</color>點孤勇值，對<color=#00F6FF>周圍1圈</color>造成<color=#00F6FF>{1}%</color>的傷害。\n<color=#00F6FF>孤勇狀態</color>：對<color=#00F6FF>菱形12格</color>造成<color=#00F6FF>170%</color>的傷害。",
  str_skill_desc_2001552 = "<color=#00F6FF>正常狀態</color>：獲得<color=#00F6FF>4</color>點孤勇值，對<color=#00F6FF>菱形12格</color>造成<color=#00F6FF>{1}%</color>的傷害。\n<color=#00F6FF>孤勇狀態</color>：對<color=#00F6FF>米字形16格</color>造成<color=#00F6FF>190%</color>的傷害。",
  str_skill_desc_2001553 = "<color=#00F6FF>正常狀態</color>：獲得<color=#00F6FF>5</color>點孤勇值，對<color=#00F6FF>米字形16格</color>造成<color=#00F6FF>{1}%</color>的傷害。\n<color=#00F6FF>孤勇狀態</color>：對<color=#00F6FF>周圍2圈</color>造成<color=#00F6FF>210%</color>的傷害。",
  str_skill_desc_20015510 = "對<color=#00F6FF>菱形12格</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_20015520 = "對<color=#00F6FF>米字形16格</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_20015530 = "對<color=#00F6FF>周圍2圈</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_passive_desc_410155 = "<color=#00F6FF>孤勇狀態</color>下普通攻擊對自身<color=#00F6FF>周圍1圈</color>造成傷害，對非目標格的傷害是正常傷害的<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_416155 = "<color=#00F6FF>孤勇狀態</color>下普通攻擊對自身<color=#00F6FF>周圍1圈</color>造成傷害，對非目標格的傷害是正常傷害的<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_420155 = "<color=#00F6FF>孤勇狀態</color>下，普通攻擊會對<color=#00F6FF>周圍1圈</color>造成傷害，對非目標格的傷害為正常傷害的<color=#00F6FF>{1}</color>。<color=#00F6FF>孤勇狀態</color>下，每回合對每名敵人首次普通攻擊後，會追加一次普通攻擊，對<color=#00F6FF>周圍1圈</color>造成<color=#00F6FF>{1}</color>的傷害。",
  str_skill_passive_desc_426155 = "<color=#00F6FF>孤勇狀態</color>下，普通攻擊會對<color=#00F6FF>周圍1圈</color>造成傷害，對非目標格的傷害為正常傷害的<color=#00F6FF>{1}</color>。<color=#00F6FF>孤勇狀態</color>下，每回合對每名敵人首次普通攻擊後，會追加一次普通攻擊，對<color=#00F6FF>周圍1圈</color>造成<color=#00F6FF>{1}</color>的傷害。",
  str_skill_passive_desc_430155 = "普通攻擊可攻擊<color=#00F6FF>斜方向</color>的敵人。<color=#00F6FF>孤勇狀態</color>下，普通攻擊會對<color=#00F6FF>周圍1圈</color>造成傷害，對非目標格的傷害為正常傷害的<color=#00F6FF>{1}</color>。<color=#00F6FF>孤勇狀態</color>下，每回合對每名敵人首次普通攻擊後，會追加一次普通攻擊，對<color=#00F6FF>周圍1圈</color>造成<color=#00F6FF>{1}</color>的傷害。",
  str_skill_passive_desc_436155 = "普通攻擊可攻擊<color=#00F6FF>斜方向</color>的敵人。<color=#00F6FF>孤勇狀態</color>下，普通攻擊會對<color=#00F6FF>周圍1圈</color>造成傷害，對非目標格的傷害為正常傷害的<color=#00F6FF>{1}</color>。<color=#00F6FF>孤勇狀態</color>下，每回合對每名敵人首次普通攻擊後，會追加一次普通攻擊，對<color=#00F6FF>周圍1圈</color>造成<color=#00F6FF>{1}</color>的傷害。",
  str_skill_upgrade_desc_16015513 = "主動技能強化：戰鬥開始時獲得<color=#00F6FF>20</color>點孤勇值。",
  str_skill_upgrade_desc_16015516 = "主動技能強化：施放主動技能後立即獲得<color=#00F6FF>5</color>點孤勇值。",
  str_skill_passive_desc_440153 = "普通攻擊可攻擊<color=#00F6FF>斜方向</color>的敵人。<color=#00F6FF>孤勇狀態</color>下，普通攻擊會對<color=#00F6FF>周圍1圈</color>造成傷害，對非目標格的傷害為正常傷害的<color=#00F6FF>65%</color>。<color=#00F6FF>孤勇狀態</color>下，每回合對每名敵人首次普通攻擊後，會追加一次普通攻擊，對<color=#00F6FF>周圍1圈</color>造成<color=#00F6FF>65%</color>的傷害。",
  str_skill_desc_350155 = "消耗20點<link=\"30045\"><#FFAE07><u>孤勇值</u></color></link>，本回合進入<color=#00F6FF>孤勇狀態</color>：連鎖技能範圍和傷害提升。回合結束時，若目前孤勇值不少於<color=#00F6FF>8</color>點，孤勇值<color=#00F6FF>減半</color>（至少扣除8點），下回合<color=#00F6FF>繼續保持孤勇狀態</color>。",
  str_skill_desc_353155 = "消耗20點<link=\"30046\"><#FFAE07><u>孤勇值</u></color></link>，本回合進入<color=#00F6FF>孤勇狀態</color>：連鎖技能範圍和傷害提升。回合結束時，若目前孤勇值不少於<color=#00F6FF>8</color>點，孤勇值<color=#00F6FF>減半</color>（至少扣除8點），下回合<color=#00F6FF>繼續保持孤勇狀態</color>。",
