  str_skill_desc_366155 = "消耗16點<link=\"30047\"><#FFAE07><u>孤勇值</u></color></link>，本回合進入<color=#00F6FF>孤勇狀態</color>：連鎖技能範圍和傷害提升。回合結束時，若目前孤勇值不少於<color=#00F6FF>8</color>點，孤勇值<color=#00F6FF>減半</color>（至少扣除8點），下回合<color=#00F6FF>繼續保持孤勇狀態</color>。",
  str_skill_upgrade_refine_desc_16015511 = "裝備技能強化：孤勇狀態下，普通攻擊對非目標格的傷害為正常傷害的<color=#00F6FF>65%</color>。",
  str_skill_upgrade_refine_desc_16015512 = "主動技能強化：回合結束時若有<color=#00F6FF>8</color>點以上的孤勇值，孤勇值<color=#00F6FF>減半</color>（至少扣除8點），下回合<color=#00F6FF>繼續保持孤勇狀態</color>。",
  str_skill_upgrade_refine_desc_16015513 = "主動技能強化：消耗<color=#00F6FF>16</color>點孤勇值。",
  str_skill_upgrade_desc_16015313 = "主動技能強化：主動技能變為<color=#FFFF00>先制攻擊</color>，進入戰鬥即可使用。\n裝備技能強化：進入戰鬥後立即獲得<color=#FFFF00>2</color>點終結值。（覺醒1階段生效）",
  str_skill_upgrade_desc_16015316 = "主動技能強化：技能冷卻回合<color=#FFFF00>-1</color>。\n裝備技能強化：每次經過深色格子時，連鎖技能傷害係數增加<color=#FFFF00>2%</color>。（覺醒2階段生效）",
