  str_skill_desc_300153 = "任選<color=#00F6FF>4</color>個格子，召喚存在<color=#00F6FF>2</color>回合的空襲信標後進入<color=#00F6FF>終結狀態</color>，持續2回合。終結狀態下，自身普通攻擊<color=#00F6FF>可攻擊斜方向</color>，連鎖技能額外對空襲信標所在格子及其周圍4格造成目前連鎖技能一半倍率的傷害，對同一格子造成多次傷害時，後續每次最終傷害降低<color=#00F6FF>20%</color>。",
  str_skill_desc_306153 = "任選<color=#00F6FF>4</color>個格子，召喚存在<color=#00F6FF>2</color>回合的空襲信標後進入<color=#00F6FF>終結狀態</color>，持續2回合。終結狀態下，自身普通攻擊<color=#00F6FF>可攻擊斜方向</color>，連鎖技能額外對空襲信標所在格子及其周圍4格造成目前連鎖技能一半倍率的傷害，對同一格子造成多次傷害時，後續每次最終傷害降低<color=#00F6FF>20%</color>。",
  str_skill_desc_320153 = "任選<color=#00F6FF>4</color>個格子，召喚存在<color=#00F6FF>2</color>回合的空襲信標後進入<color=#00F6FF>終結狀態</color>，持續2回合。終結狀態下，自身普通攻擊<color=#00F6FF>可攻擊斜方向</color>，連鎖技能額外對空襲信標所在格子及其周圍4格造成目前連鎖技能一半倍率的傷害，對同一格子造成多次傷害時，後續每次最終傷害降低<color=#00F6FF>20%</color>。終結狀態期間額外獲得可以超過上限的<color=#00F6FF>5</color>點<link=\"300442\"><#FFAE07><u>終結值</u></color></link>。",
  str_skill_desc_326153 = "任選<color=#00F6FF>4</color>個格子，召喚存在<color=#00F6FF>2</color>回合的空襲信標後進入<color=#00F6FF>終結狀態</color>，持續2回合。終結狀態下，自身普通攻擊<color=#00F6FF>可攻擊斜方向</color>，連鎖技能額外對空襲信標所在格子及其周圍4格造成目前連鎖技能一半倍率的傷害，對同一格子造成多次傷害時，後續每次最終傷害降低<color=#00F6FF>20%</color>。終結狀態期間額外獲得可以超過上限的<color=#00F6FF>5</color>點<link=\"300442\"><#FFAE07><u>終結值</u></color></link>。",
  str_skill_desc_330153 = "任選<color=#00F6FF>4</color>個格子，召喚存在<color=#00F6FF>2</color>回合的空襲信標後進入<color=#00F6FF>終結狀態</color>，持續2回合。終結狀態下，自身普通攻擊<color=#00F6FF>可攻擊斜方向</color>，連鎖技能額外對空襲信標所在格子及其周圍4格造成目前連鎖技能一半倍率的傷害，對同一格子造成多次傷害時，後續每次最終傷害降低<color=#00F6FF>20%</color>。終結狀態期間額外獲得可以超過上限的<color=#00F6FF>5</color>點<link=\"300442\"><#FFAE07><u>終結值</u></color></link>。",
  str_skill_desc_336153 = "任選<color=#00F6FF>4</color>個格子，召喚存在<color=#00F6FF>2</color>回合的空襲信標後進入<color=#00F6FF>終結狀態</color>，持續2回合。終結狀態下，自身普通攻擊<color=#00F6FF>可攻擊斜方向</color>，連鎖技能額外對空襲信標所在格子及其周圍4格造成目前連鎖技能一半倍率的傷害，對同一格子造成多次傷害時，後續每次最終傷害降低<color=#00F6FF>20%</color>。終結狀態期間額外獲得可以超過上限的<color=#00F6FF>5</color>點<link=\"300442\"><#FFAE07><u>終結值</u></color></link>。",
  str_skill_desc_2001531 = "對<color=#00F6FF>周圍3圈</color>內最靠近的3個敵人造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2001532 = "對<color=#00F6FF>周圍4圈</color>內最靠近的4個敵人造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2001533 = "對<color=#00F6FF>周圍4圈</color>內的全體敵人造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_passive_name_410153 = "啟明之力量",
  str_skill_passive_name_413153 = "啟明之力量",
  str_skill_passive_name_420153 = "啟明之力量",
  str_skill_passive_name_423153 = "啟明之力量",
  str_skill_passive_name_426153 = "啟明之力量",
  str_skill_passive_name_430153 = "啟明之力量",
  str_skill_passive_name_433153 = "啟明之力量",
  str_skill_passive_name_436153 = "啟明之力量",
  str_skill_passive_desc_410153 = "可獲得<link=\"30043\"><#FFAE07><u>終結值</u></color></link>，每點終結值提高自身<color=#00F6FF>{1}</color>攻擊力。",
  str_skill_passive_desc_413153 = "可獲得<link=\"30043\"><#FFAE07><u>終結值</u></color></link>，每點終結值提高自身<color=#00F6FF>{1}</color>攻擊力。進入戰鬥立即獲得<color=#00F6FF>2</color>點終結值。",
  str_skill_passive_desc_420153 = "可獲得<link=\"300442\"><#FFAE07><u>終結值</u></color></link>，每點終結值提高自身<color=#00F6FF>{1}</color>攻擊力。每次經過深色格子，獲得<color=#00F6FF>1</color>點可超過上限的臨時終結值；進入極光時刻或我方回合結束後，額外點數便消失。",
  str_skill_passive_desc_423153 = "可獲得<link=\"300442\"><#FFAE07><u>終結值</u></color></link>，每點終結值提高自身<color=#00F6FF>{1}</color>攻擊力。進入戰鬥立即獲得<color=#00F6FF>2</color>點終結值。每次經過深色格子，獲得<color=#00F6FF>1</color>點可超過上限的臨時終結值；進入極光時刻或我方回合結束後，額外點數便消失。",
  str_skill_passive_desc_426153 = "可獲得<link=\"300442\"><#FFAE07><u>終結值</u></color></link>，每點終結值提高自身<color=#00F6FF>{1}</color>攻擊力。進入戰鬥立即獲得<color=#00F6FF>2</color>點終結值。每次經過深色格子，獲得<color=#00F6FF>1</color>點可超過上限的臨時終結值，並增加<color=#00F6FF>2%</color>連鎖技能傷害係數；進入極光時刻或我方回合結束後，額外點數和連鎖技能加成便消失。",
  str_skill_passive_desc_430153 = "可獲得<link=\"300442\"><#FFAE07><u>終結值</u></color></link>，每點終結值提高自身<color=#00F6FF>{1}</color>攻擊力，隊伍中的<color=#00F6FF>雷屬性</color>或<color=#00F6FF>啟光聯邦</color>光靈根據<color=#00F6FF>自身攻擊力</color>獲得一半終結值加成。每次經過深色格子，獲得<color=#00F6FF>1</color>點可超過上限的臨時終結值；進入極光時刻或我方回合結束後，額外點數便消失。",
  str_skill_passive_desc_433153 = "可獲得<link=\"300442\"><#FFAE07><u>終結值</u></color></link>，每點終結值提高自身<color=#00F6FF>{1}</color>攻擊力，隊伍中的<color=#00F6FF>雷屬性</color>或<color=#00F6FF>啟光聯邦</color>光靈根據<color=#00F6FF>自身攻擊力</color>獲得一半終結值加成。進入戰鬥立即獲得<color=#00F6FF>2</color>點終結值。每次經過深色格子，獲得<color=#00F6FF>1</color>點可超過上限的臨時終結值；進入極光時刻或我方回合結束後，額外點數便消失。",
  str_skill_passive_desc_436153 = "可獲得<link=\"300442\"><#FFAE07><u>終結值</u></color></link>，每點終結值提高自身<color=#00F6FF>{1}</color>攻擊力，隊伍中<color=#00F6FF>雷屬性</color>或<color=#00F6FF>啟光聯邦</color>的光靈根據<color=#00F6FF>自身攻擊力</color>獲得一半終結值的加成。進入戰鬥立即獲得<color=#00F6FF>2</color>點終結值。每次經過深色格子，獲得<color=#00F6FF>1</color>點可超過上限的臨時終結值，並增加<color=#00F6FF>2%</color>連鎖技能傷害係數；進入極光時刻或我方回合結束後，額外點數和連鎖技能加成便消失。",
  str_skill_upgrade_refine_desc_16015311 = "主動技能強化：進入終結狀態可獲<color=#00F6FF>6</color>點臨時終結值。",
  str_skill_upgrade_refine_desc_16015312 = "連鎖技能強化：傷害係數增加<color=#00F6FF>10%</color>。",
  str_skill_upgrade_refine_desc_16015313 = "主動技能強化：終結狀態下連鎖技能對同一格子造成多次傷害時，後續每次最終傷害降低<color=#00F6FF>15%</color>。",
  str_skill_desc_2501531 = "對<color=#00F6FF>周圍3圈</color>內最靠近的3個敵人造成<color=#00F6FF>150%</color>的傷害",
  str_skill_desc_2501532 = "對<color=#00F6FF>周圍4圈</color>內最靠近的4個敵人造成<color=#00F6FF>160%</color>的傷害。",
  str_skill_desc_2501533 = "對<color=#00F6FF>周圍4圈</color>內的全體敵人造成<color=#00F6FF>170%</color>的傷害。",
