  str_skill_passive_desc_453153 = "可獲得<link=\"300443\"><#FFAE07><u>終結值</u></color></link>，每點終結值提高自身<color=#00F6FF>3%</color>攻擊力，隊伍中的<color=#00F6FF>雷屬性</color>或<color=#00F6FF>啟光聯邦</color>光靈根據<color=#00F6FF>自身攻擊力</color>獲得一半終結值加成。進入戰鬥立即獲得<color=#00F6FF>2</color>點終結值。每次經過深色格子，獲得<color=#00F6FF>1</color>點可超過上限的臨時終結值；進入極光時刻或我方回合結束後，額外點數便消失。",
  str_skill_passive_desc_456153 = "可獲得<link=\"300443\"><#FFAE07><u>終結值</u></color></link>，每點終結值提高自身<color=#00F6FF>3%</color>攻擊力，隊伍中<color=#00F6FF>雷屬性</color>或<color=#00F6FF>啟光聯邦</color>的光靈根據<color=#00F6FF>自身攻擊力</color>獲得一半終結值的加成。進入戰鬥立即獲得<color=#00F6FF>2</color>點終結值。每次經過深色格子，獲得<color=#00F6FF>1</color>點可超過上限的臨時終結值，並增加<color=#00F6FF>2%</color>連鎖技能傷害係數；進入極光時刻或我方回合結束後，額外點數和連鎖技能加成便消失。",
  str_skill_name_290230101 = "克勞迪亞·落隕",
  str_skill_name_290230102 = "克勞迪亞·落隕",
  str_skill_name_290230103 = "克勞迪亞·落隕",
  str_skill_name_290230104 = "克勞迪亞·落隕",
  str_skill_name_290230201 = "克勞迪亞·跳劈",
  str_skill_name_290230202 = "克勞迪亞·跳劈",
  str_skill_name_290230203 = "克勞迪亞·跳劈",
  str_skill_name_290230301 = "克勞迪亞·斬絕",
  str_skill_name_290230401 = "基台現",
  str_skill_name_290240101 = "阿希爾·進襲",
  str_skill_desc_290230101 = "當克勞迪亞位於地面時，召喚敵人十字範圍內所有基台撞擊，對敵人造成多段傷害。",
  str_skill_desc_290230102 = "當克勞迪亞站在基台上，召喚敵人十字範圍內所有基台撞擊，若克勞迪亞處在該範圍內，則將敵人擊暈。",
  str_skill_desc_290230103 = "當克勞迪亞站在阿希爾身上時，召喚敵人十字範圍內所有基台撞擊，若阿希爾也在該範圍內，則將敵人擊暈並擊退。",
  str_skill_desc_290230104 = "若敵人十字範圍內無基台，則克勞迪亞在場景中心的5*5範圍內隨機位置召喚4枚基台，並在場景內距離敵人最遠的位置生成基台並瞬移過去。",
  str_skill_desc_290230201 = "若敵人處於攻擊範圍內，克勞迪亞瞬移至敵人身邊造成大量傷害並後撤一小段距離；若敵人不在攻擊範圍內，則在場景中心5*5範圍內生成基台並瞬移至場景內距離敵人最遠的位置。",
  str_skill_desc_290230202 = "若敵人處於攻擊範圍內，克勞迪亞瞬移至敵人身邊造成大量傷害並後撤一小段距離；若敵人不在攻擊範圍內，則在場景中心5*5範圍內生成基台並瞬移至場景內距離敵人最遠的位置。",
  str_skill_desc_290230203 = "若敵人處於攻擊範圍內，克勞迪亞瞬移至敵人身邊造成大量傷害並後撤一小段距離；若敵人不在攻擊範圍內，則在場景中心5*5範圍內生成基台並瞬移至場景內距離敵人最遠的位置。",
  str_skill_desc_290230301 = "在場中央和敵人腳下分別生成基台；瞬移至基台上，斬切並對全畫面範圍內敵人造成傷害。",
  str_skill_desc_290230401 = "回合開始時，在場景邊緣召喚至多10枚基台",
  str_skill_desc_290240101 = "阿希爾靠近攻擊範圍內的敵人造成一次傷害，並碾碎路徑上的所有基台；若攻擊範圍內沒有敵人，則在原地暫時蟄伏。",
  str_skill_name_290250101 = "犧之終結",
  str_skill_desc_290250101 = "米洛斯在場上隨機移動一段時間並重設經過的所有格子；移動結束後，米洛斯射擊玩家造成1次大量傷害。",
  str_skill_name_290250102 = "蜃像攻取",
  str_skill_desc_290250102 = "米洛斯移動的過程中若經過強化格子，則會在強化格子上召喚蜃像並對敵人造成1次傷害；米洛斯的印記層數愈多，蜃像造成的傷害愈高。",
  str_skill_name_290250201 = "洗新蜃像",
  str_skill_desc_290250201 = "米洛斯吸收場上所有的強化格子和弱化格子，然後向玩家射擊造成傷害；米洛斯每吸收1個強化格子會額外造成1次傷害；米洛斯的印記層數愈高，射擊造成的傷害愈高。",
  str_skill_name_390250101 = "厄孽·蜃像攻取",
  str_skill_desc_390250101 = "厄孽·米洛斯選取一條弱化格子數量最多的路徑移動5格，吸收經過的強化與弱化格子，每次吸收弱化格子都會召喚蜃像對目標造成一次傷害。若本次移動沒有吸收弱化格子或場上不存在弱化格子，則會在自身周圍3圈召喚7個弱化格子。",
  str_skill_name_390250102 = "厄孽·犧之終結",
  str_skill_desc_390250102 = "厄孽·米洛斯鎖定全畫面範圍內的目標進行射擊，造成傷害。",
  str_skill_name_390310106 = "厄孽·甜心之吻",
  str_skill_desc_390310106 = "厄孽·芭芭拉連線移動到離目標最遠位置，隨後造成除部分安全區外的大範圍傷害，並擊碎安全區以外的火屬性格子。",
  str_skill_name_390310107 = "厄孽·終音耀斑天引",
  str_skill_desc_390310107 = "厄孽·芭芭拉連線移動到距離目標最遠的位置，隨後在場地中心召喚夥伴，對全畫面範圍目標造成傷害與擊退。",
  str_skill_name_390320102 = "厄孽·顫慄協奏曲",
  str_skill_name_390320103 = "厄孽·阿比斯轟鳴曲",
  str_skill_desc_390320102 = "厄孽·克娜莉連線移動到可攻擊到目標的最遠位置，對周圍2圈內的所有目標造成傷害。若本次移動沒有攻擊到目標，則在場內隨機位置召喚觸手。",
