  str_skill_desc_2001561 = "<color=#00F6FF>執傘狀態</color>：對<color=#00F6FF>周圍1圈</color>造成<color=#00F6FF>{1}%</color>的傷害。\n<color=#00F6FF>空手狀態</color>：對最靠近的2名敵人造成<color=#00F6FF>150%</color>的傷害。",
  str_skill_desc_2001562 = "<color=#00F6FF>執傘狀態</color>：對<color=#00F6FF>菱形12格</color>造成<color=#00F6FF>{1}%</color>的傷害。\n<color=#00F6FF>空手狀態</color>：對最靠近的3名敵人造成<color=#00F6FF>160%</color>的傷害。",
  str_skill_desc_2001563 = "<color=#00F6FF>執傘狀態</color>：對<color=#00F6FF>周圍2圈</color>造成<color=#00F6FF>{1}%</color>的傷害。\n<color=#00F6FF>空手狀態</color>：對最靠近的4名敵人造成<color=#00F6FF>170%</color>的傷害。",
  str_skill_desc_2001564 = "<color=#00F6FF>執傘狀態</color>：對<color=#00F6FF>周圍1圈</color>造成<color=#00F6FF>{1}%</color>的傷害。\n<color=#00F6FF>空手狀態</color>：對最靠近的2名敵人造成<color=#00F6FF>150%</color>的傷害。",
  str_skill_desc_2001565 = "<color=#00F6FF>執傘狀態</color>：對<color=#00F6FF>菱形12格</color>造成<color=#00F6FF>{1}%</color>的傷害。\n<color=#00F6FF>空手狀態</color>：對最靠近的3名敵人造成<color=#00F6FF>160%</color>的傷害。",
  str_skill_desc_2001566 = "<color=#00F6FF>執傘狀態</color>：對<color=#00F6FF>周圍2圈</color>造成<color=#00F6FF>{1}%</color>的傷害。\n<color=#00F6FF>空手狀態</color>：對最靠近的4名敵人造成<color=#00F6FF>170%</color>的傷害。",
  str_skill_desc_300156 = "<color=#00F6FF>執傘狀態</color>：任選1個可行走的格子將傘拋出，對沿途格子造成<color=#00F6FF>80%</color>的傷害，並切換至<color=#00F6FF>空手狀態</color>。\n<color=#00F6FF>空手狀態</color>：將傘收回，對沿途格子造成<color=#00F6FF>640%</color>的傷害，並切換至<color=#00F6FF>執傘狀態</color>。\n若場上的傘被覆蓋或清除則切換至<color=#00F6FF>執傘狀態</color>，被敵方經過覆蓋時，技能冷卻回合數<color=#00F6FF>+1</color>。",
  str_skill_desc_3001560 = "<color=#00F6FF>執傘狀態</color>：任選1個可行走的格子將傘拋出，對沿途格子造成<color=#00F6FF>80%</color>的傷害，並切換至<color=#00F6FF>空手狀態</color>。\n<color=#00F6FF>空手狀態</color>：將傘收回，對沿途格子造成<color=#00F6FF>640%</color>的傷害，並切換至<color=#00F6FF>執傘狀態</color>。\n若場上的傘被覆蓋或清除則切換至<color=#00F6FF>執傘狀態</color>，被敵方經過覆蓋時，技能冷卻回合數<color=#00F6FF>+1</color>。",
