  str_skill_desc_3261560 = "<color=#00F6FF>執傘狀態</color>：任選1個可行走的格子將傘拋出，對沿途格子造成<color=#00F6FF>100%</color>的傷害，在落點處額外發動一次裝備技能，並切換至<color=#00F6FF>空手狀態</color>。\n<color=#00F6FF>空手狀態</color>：將傘收回，對沿途格子造成<color=#00F6FF>1000%</color>的傷害，並切換至<color=#00F6FF>執傘狀態</color>。\n若場上的傘被覆蓋或清除則切換至<color=#00F6FF>執傘狀態</color>，被敵方經過覆蓋時，技能冷卻回合數<color=#00F6FF>+1</color>。",
  str_skill_desc_330156 = "<color=#00F6FF>執傘狀態</color>：任選1個可行走的格子將傘拋出，對沿途格子造成<color=#00F6FF>80%</color>的傷害，並切換至<color=#00F6FF>空手狀態</color>。\n<color=#00F6FF>空手狀態</color>：將傘收回，對沿途格子造成<color=#00F6FF>640%</color>的傷害，並切換至<color=#00F6FF>執傘狀態</color>。\n若場上的傘被覆蓋或清除則切換至<color=#00F6FF>執傘狀態</color>，被我方|敵方經過覆蓋時，技能冷卻回合數<color=#00F6FF>-1</color>|<color=#00F6FF>+1</color>。",
  str_skill_desc_3301560 = "<color=#00F6FF>執傘狀態</color>：任選1個可行走的格子將傘拋出，對沿途格子造成<color=#00F6FF>80%</color>的傷害，並切換至<color=#00F6FF>空手狀態</color>。\n<color=#00F6FF>空手狀態</color>：將傘收回，對沿途格子造成<color=#00F6FF>640%</color>的傷害，並切換至<color=#00F6FF>執傘狀態</color>。\n若場上的傘被覆蓋或清除則切換至<color=#00F6FF>執傘狀態</color>，被我方|敵方經過覆蓋時，技能冷卻回合數<color=#00F6FF>-1</color>|<color=#00F6FF>+1</color>。",
