  str_skill_passive_desc_410156 = "任何情況下，從<color=#00F6FF>空手狀態</color>切換至<color=#00F6FF>執傘狀態</color>時，立即對自身<color=#00F6FF>周圍1圈</color>造成一次<color=#00F6FF>{1}</color>的傷害。",
  str_skill_passive_desc_420156 = "<color=#00F6FF>空手狀態</color>下普通攻擊<color=#00F6FF>可攻擊斜方向</color>的敵人。任何情況下，從<color=#00F6FF>空手狀態</color>切換至<color=#00F6FF>執傘狀態</color>時，立即對自身<color=#00F6FF>周圍1圈</color>造成一次<color=#00F6FF>{1}</color>的傷害。",
  str_skill_upgrade_desc_16015613 = "主動技能強化：扔出的傘對點選位置<color=#00F6FF>周圍1圈</color>額外造成一次裝備技能傷害。",
  str_skill_upgrade_desc_16015616 = "主動技能強化：主動技能傷害係數在<color=#00F6FF>執傘狀態</color>下提高至<color=#00F6FF>100%</color>，<color=#00F6FF>空手狀態</color>下提高至<color=#00F6FF>1000%</color>。",
  str_skill_upgrade_desc_15015712 = "主動技能強化：進入戰鬥時自帶<color=#00F6FF>2</color>點纖絲值。",
  str_skill_upgrade_desc_15015715 = "主動技能強化：進入戰鬥時自帶<color=#00F6FF>4</color>點纖絲值。",
