  str_skill_desc_300157 = "任選1格，消耗<color=#00F6FF>3</color>點<link=\"30050\"><#FFAE07><u>纖絲值</u></color></link>召喚<color=#00F6FF>真枝</color>，或消耗<color=#00F6FF>1</color>點<link=\"30050\"><#FFAE07><u>纖絲值</u></color></link>挪動<color=#00F6FF>真枝</color>，我方回合結束時收回真枝。移動期間真枝儘可能保持與早苗的<color=#00F6FF>相對位置固定</color>，對碰撞目標造成<color=#00F6FF>等同真枝攻擊力</color>無視防禦的傷害。真枝繼承早苗<color=#00F6FF>70%</color>的基礎攻擊力。",
