  str_skill_desc_3321570 = "任選1格，消耗<color=#00F6FF>3</color>點<link=\"30048\"><#FFAE07><u>纖絲值</u></color></link>召喚<color=#00F6FF>真枝</color>，或消耗<color=#00F6FF>1</color>點<link=\"30048\"><#FFAE07><u>纖絲值</u></color></link>挪動<color=#00F6FF>真枝</color>，我方回合結束時收回真枝。移動期間真枝儘可能保持與早苗的<color=#00F6FF>相對位置固定</color>，對碰撞目標造成<color=#00F6FF>等同真枝攻擊力</color>無視防禦的傷害。真枝繼承早苗<color=#00F6FF>70%</color>的基礎攻擊力。極光時刻期間可以額外<color=#00F6FF>挪動</color>真枝1次。",
  str_skill_desc_3051570 = "任選1格，消耗<color=#00F6FF>3</color>點<link=\"30049\"><#FFAE07><u>纖絲值</u></color></link>召喚<color=#00F6FF>真枝</color>，或消耗<color=#00F6FF>1</color>點<link=\"30049\"><#FFAE07><u>纖絲值</u></color></link>挪動<color=#00F6FF>真枝</color>，我方回合結束時收回真枝。移動期間真枝儘可能保持與早苗的<color=#00F6FF>相對位置固定</color>，對碰撞目標造成<color=#00F6FF>等同真枝攻擊力</color>無視防禦的傷害。真枝繼承早苗<color=#00F6FF>70%</color>的基礎攻擊力。",
  str_skill_desc_3151570 = "任選1格，消耗<color=#00F6FF>3</color>點<link=\"30049\"><#FFAE07><u>纖絲值</u></color></link>召喚<color=#00F6FF>真枝</color>，或消耗<color=#00F6FF>1</color>點<link=\"30049\"><#FFAE07><u>纖絲值</u></color></link>挪動<color=#00F6FF>真枝</color>，我方回合結束時收回真枝。移動期間真枝儘可能保持與早苗的<color=#00F6FF>相對位置固定</color>，對碰撞目標造成<color=#00F6FF>等同真枝攻擊力</color>無視防禦的傷害。真枝繼承早苗<color=#00F6FF>70%</color>的基礎攻擊力。",
  str_skill_desc_3251570 = "任選1格，消耗<color=#00F6FF>3</color>點<link=\"30049\"><#FFAE07><u>纖絲值</u></color></link>召喚<color=#00F6FF>真枝</color>，或消耗<color=#00F6FF>1</color>點<link=\"30049\"><#FFAE07><u>纖絲值</u></color></link>挪動<color=#00F6FF>真枝</color>，我方回合結束時收回真枝。移動期間真枝儘可能保持與早苗的<color=#00F6FF>相對位置固定</color>，對碰撞目標造成<color=#00F6FF>等同真枝攻擊力</color>無視防禦的傷害。真枝繼承早苗<color=#00F6FF>70%</color>的基礎攻擊力。",
  str_skill_desc_3351570 = "任選1格，消耗<color=#00F6FF>3</color>點<link=\"30049\"><#FFAE07><u>纖絲值</u></color></link>召喚<color=#00F6FF>真枝</color>，或消耗<color=#00F6FF>1</color>點<link=\"30049\"><#FFAE07><u>纖絲值</u></color></link>挪動<color=#00F6FF>真枝</color>，我方回合結束時收回真枝。移動期間真枝儘可能保持與早苗的<color=#00F6FF>相對位置固定</color>，對碰撞目標造成<color=#00F6FF>等同真枝攻擊力</color>無視防禦的傷害。真枝繼承早苗<color=#00F6FF>70%</color>的基礎攻擊力。極光時刻期間可以額外<color=#00F6FF>挪動</color>真枝1次。",
  str_skill_passive_desc_410157 = "真枝每次造成傷害時獲得1層絲戲印記，每層絲戲印記增加真枝<color=#00F6FF>{1}</color>繼承自早苗的攻擊力，上限30層。",
  str_skill_passive_desc_420157 = "真枝每次造成傷害時獲得1層絲戲印記，每層絲戲印記增加真枝<color=#00F6FF>{1}</color>繼承自早苗的攻擊力，上限30層。絲戲印記達到上限或單回合內真枝獲得至少<color=#00F6FF>5</color>層印記後，真枝能夠與早苗<color=#00F6FF>同時施放連鎖技能</color>。",
  str_skill_upgrade_desc_16015813 = "裝備技能強化：JOKER首次從隊員位變動至隊長位時，本回合普通攻擊傷害增加<color=#00F6FF>20%</color>。",
  str_skill_upgrade_desc_16015816 = "裝備技能強化：JOKER在隊長和隊員之間位置互換時，獲得1次更換隊長次數，每回合觸發1次。",
  str_skill_desc_300158 = "JOKER在進入戰鬥後自帶<link=\"30051\"><#FFAE07><u>【特別技能】</u></color></link>。任選1名敵人，對其造成<color=#00F6FF>{1}%</color>的傷害並將其<link=\"30052\"><#FFAE07><u>弱點揭明</u></color></link>層數<color=#00F6FF>翻倍</color>。目標佔格數愈多，主動技能傷害愈高。",
  str_skill_desc_320158 = "JOKER在進入戰鬥後自帶<link=\"30051\"><#FFAE07><u>【特別技能】</u></color></link>。任選1名敵人，對其造成<color=#00F6FF>{1}%</color>的傷害並將其<link=\"30052\"><#FFAE07><u>弱點揭明</u></color></link>層數<color=#00F6FF>翻倍</color>，若主動技能上回合就緒，改為層數<color=#00F6FF>*3</color>。目標佔格數愈多，主動技能傷害愈高。",
  str_skill_desc_3201580 = "JOKER在進入戰鬥後自帶<link=\"30051\"><#FFAE07><u>【特別技能】</u></color></link>。任選1名敵人，對其造成<color=#00F6FF>{1}%</color>的傷害並將其<link=\"30052\"><#FFAE07><u>弱點揭明</u></color></link>層數<color=#00F6FF>翻倍</color>，若主動技能上回合就緒，改為層數<color=#00F6FF>*3</color>。目標佔格數愈多，主動技能傷害愈高。",
  str_skill_desc_2001581 = "對<color=#00F6FF>周圍4圈</color>內最靠近的3名敵人造成<color=#00F6FF>{1}%</color>的傷害，對命中的敵人附加<color=#00F6FF>3層</color><link=\"30052\"><#FFAE07><u>弱點揭明</u></color></link>。",
  str_skill_desc_2001582 = "對<color=#00F6FF>周圍4圈</color>內最靠近的4名敵人造成<color=#00F6FF>{1}%</color>的傷害，對命中的敵人附加<color=#00F6FF>5層</color><link=\"30052\"><#FFAE07><u>弱點揭明</u></color></link>。",
  str_skill_desc_2001583 = "對<color=#00F6FF>周圍4圈</color>內所有敵人造成<color=#00F6FF>{1}%</color>的傷害，對命中的敵人附加<color=#00F6FF>7層</color><link=\"30052\"><#FFAE07><u>弱點揭明</u></color></link>。",
  str_skill_passive_desc_410158 = "每次擊殺敵人時，將其<link=\"30052\"><#FFAE07><u>弱點揭明</u></color></link>層數分攤給剩餘敵人，每名敵人最多獲得<color=#00F6FF>{1}</color>層。",
  str_skill_passive_desc_413158 = "每次擊殺敵人時，將其<link=\"30052\"><#FFAE07><u>弱點揭明</u></color></link>層數分攤給剩餘敵人，每名敵人最多獲得<color=#00F6FF>{1}</color>層。JOKER首次從隊員位變動至隊長位時，本回合普通攻擊傷害增加<color=#00F6FF>20%</color>。",
  str_skill_passive_desc_416158 = "每次擊殺敵人時，將其<link=\"30052\"><#FFAE07><u>弱點揭明</u></color></link>層數分攤給剩餘敵人，每名敵人最多獲得<color=#00F6FF>{1}</color>層。JOKER首次從隊員位變動至隊長位時，本回合普通攻擊傷害增加<color=#00F6FF>20%</color>。JOKER在隊長和隊員之間位置互換時，獲得1次更換隊長次數，每回合觸發1次。",
  str_skill_passive_desc_430158 = "每次擊殺敵人時，將其<link=\"30052\"><#FFAE07><u>弱點揭明</u></color></link>層數分攤給剩餘敵人，每名敵人最多獲得<color=#00F6FF>{1}</color>層。每次普通攻擊附加<color=#00F6FF>1</color>層<link=\"30052\"><#FFAE07><u>弱點揭明</u></color></link>。",
  str_skill_passive_desc_433158 = "每次擊殺敵人時，將其<link=\"30052\"><#FFAE07><u>弱點揭明</u></color></link>層數分攤給剩餘敵人，每名敵人最多獲得<color=#00F6FF>{1}</color>層。每次普通攻擊附加<color=#00F6FF>1</color>層<link=\"30052\"><#FFAE07><u>弱點揭明</u></color></link>。JOKER首次從隊員位變動至隊長位時，本回合普通攻擊傷害增加<color=#00F6FF>20%</color>。",
  str_skill_passive_desc_436158 = "每次擊殺敵人時，將其<link=\"30052\"><#FFAE07><u>弱點揭明</u></color></link>層數分攤給剩餘敵人，每名敵人最多獲得<color=#00F6FF>{1}</color>層。每次普通攻擊附加<color=#00F6FF>1</color>層<link=\"30052\"><#FFAE07><u>弱點揭明</u></color></link>。JOKER首次從隊員位變動至隊長位時，本回合普通攻擊傷害增加<color=#00F6FF>20%</color>。JOKER在隊長和隊員之間位置互換時，獲得1次更換隊長次數，每回合觸發1次。",
  str_skill_upgrade_desc_16015913 = "主動技能強化：主動技能變為<color=#FFFF00>先制攻擊</color>，進入戰鬥即可使用。",
  str_skill_upgrade_desc_16015916 = "裝備技能強化：QUEEN首次從隊員位變動至隊長位時，本回合普通攻擊傷害增加<color=#00F6FF>15%</color>。",
  str_skill_desc_300159 = "QUEEN在進入戰鬥後自帶<link=\"30051\"><#FFAE07><u>【特別技能】</u></color></link>。對<color=#00F6FF>全體</color>敵人造成1次<color=#00F6FF>{1}%</color>的傷害並附加<color=#00F6FF>6</color>層<link=\"30052\"><#FFAE07><u>弱點揭明</u></color></link>。",
  str_skill_desc_320159 = "QUEEN在進入戰鬥後自帶<link=\"30051\"><#FFAE07><u>【特別技能】</u></color></link>。對<color=#00F6FF>全體</color>敵人造成1次<color=#00F6FF>{1}%</color>的傷害並附加<color=#00F6FF>6</color>層<link=\"30052\"><#FFAE07><u>弱點揭明</u></color></link>，對水屬性的敵人改為<color=#00F6FF>12層</color>。",
  str_skill_desc_2001591 = "對<color=#00F6FF>周圍1圈</color>造成<color=#00F6FF>{1}%</color>的傷害。對命中的敵人附加<color=#00F6FF>2層</color><link=\"30052\"><#FFAE07><u>弱點揭明</u></color></link>，對水屬性的敵人改為<color=#00F6FF>4層</color>。",
  str_skill_desc_2001592 = "對<color=#00F6FF>米字形16格</color>造成<color=#00F6FF>{1}%</color>的傷害。對命中的敵人附加<color=#00F6FF>3層</color><link=\"30052\"><#FFAE07><u>弱點揭明</u></color></link>，對水屬性的敵人改為<color=#00F6FF>6層</color>。",
  str_skill_desc_2001593 = "對<color=#00F6FF>周圍2圈</color>造成<color=#00F6FF>{1}%</color>的傷害。對命中的敵人附加<color=#00F6FF>4層</color><link=\"30052\"><#FFAE07><u>弱點揭明</u></color></link>，對水屬性的敵人改為<color=#00F6FF>8層</color>。",
  str_skill_passive_desc_410159 = "普通攻擊變為2連擊，每次傷害為基礎傷害的<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_416159 = "普通攻擊變為2連擊，每次傷害為基礎傷害的<color=#00F6FF>{1}</color>。QUEEN首次從隊員位變動至隊長位時，本回合普通攻擊傷害增加<color=#00F6FF>15%</color>。",
  str_skill_passive_desc_430159 = "普通攻擊變為2連擊，每次傷害為基礎傷害的<color=#00F6FF>{1}</color>。每次普通攻擊附加<color=#00F6FF>1層</color><link=\"30052\"><#FFAE07><u>弱點揭明</u></color></link>，對水屬性的敵人改為<color=#00F6FF>2層</color>。",
  str_skill_passive_desc_436159 = "普通攻擊變為2連擊，每次傷害為基礎傷害的<color=#00F6FF>{1}</color>。每次普通攻擊附加<color=#00F6FF>1層</color><link=\"30052\"><#FFAE07><u>弱點揭明</u></color></link>，對水屬性的敵人改為<color=#00F6FF>2層</color>。QUEEN首次從隊員位變動至隊長位時，本回合普通攻擊傷害增加<color=#00F6FF>15%</color>。",
  str_skill_desc_300160 = "FOX在進入戰鬥後自帶<link=\"30051\"><#FFAE07><u>【特別技能】</u></color></link>。對<color=#00F6FF>周圍2圈</color>造成<color=#00F6FF>{1}%</color>的傷害並附加<color=#00F6FF>9</color>層<link=\"30052\"><#FFAE07><u>弱點揭明</u></color></link>。",
  str_skill_desc_320160 = "FOX在進入戰鬥後自帶<link=\"30051\"><#FFAE07><u>【特別技能】</u></color></link>。對<color=#00F6FF>周圍2圈</color>造成<color=#00F6FF>{1}%</color>的傷害並附加<color=#00F6FF>9</color>層<link=\"30052\"><#FFAE07><u>弱點揭明</u></color></link>，對火屬性的敵人改為<color=#00F6FF>18層</color>。",
  str_skill_desc_2001601 = "對<color=#00F6FF>縱向1列</color>造成<color=#00F6FF>{1}%</color>的傷害。對每個敵人附加<color=#00F6FF>1</color>層<link=\"30052\"><#FFAE07><u>弱點揭明</u></color></link>，對火屬性的敵人改為<color=#00F6FF>3</color>層。",
  str_skill_desc_2001602 = "對<color=#00F6FF>縱向3列</color>造成<color=#00F6FF>{1}%</color>的傷害。對每個敵人附加<color=#00F6FF>2</color>層<link=\"30052\"><#FFAE07><u>弱點揭明</u></color></link>，對火屬性的敵人改為<color=#00F6FF>4</color>層。",
  str_skill_desc_2001603 = "對<color=#00F6FF>縱向3列</color>造成<color=#00F6FF>{1}%</color>的傷害。對每個敵人附加<color=#00F6FF>3</color>層<link=\"30052\"><#FFAE07><u>弱點揭明</u></color></link>，對火屬性的敵人改為<color=#00F6FF>6</color>層。",
  str_skill_passive_desc_410160 = "每回合首次普通攻擊造成的傷害為正常傷害的<color=#00F6FF>{1}</color>倍。",
  str_skill_passive_desc_415160 = "每回合首次普通攻擊造成的傷害為正常傷害的<color=#00F6FF>{1}</color>倍。FOX首次從隊員位變動至隊長位時，本回合普通攻擊傷害增加<color=#00F6FF>15%</color>。",
  str_skill_passive_desc_430160 = "每次普通攻擊附加<color=#00F6FF>1</color>層<link=\"30052\"><#FFAE07><u>弱點揭明</u></color></link>，對火屬性敵人改為<color=#00F6FF>2</color>層。每回合首次普通攻擊造成的傷害與附加的<link=\"30052\"><#FFAE07><u>弱點揭明</u></color></link>層數為正常的<color=#00F6FF>{1}</color>倍。",
  str_skill_passive_desc_435160 = "每次普通攻擊附加<color=#00F6FF>1</color>層<link=\"30052\"><#FFAE07><u>弱點揭明</u></color></link>，對火屬性敵人改為<color=#00F6FF>2</color>層。每回合首次普通攻擊造成的傷害與附加的<link=\"30052\"><#FFAE07><u>弱點揭明</u></color></link>層數為正常的<color=#00F6FF>{1}</color>倍。FOX首次從隊員位變動至隊長位時，本回合普通攻擊傷害增加<color=#00F6FF>15%</color>。",
  str_skill_upgrade_desc_15016012 = "主動技能強化：主動技能變為<color=#FFFF00>先制攻擊</color>，進入戰鬥即可使用。",
  str_skill_upgrade_desc_15016015 = "裝備技能強化：FOX首次從隊員位變動至隊長位時，本回合普通攻擊傷害增加<color=#00F6FF>15%</color>。",
  str_skill_desc_300161 = "VIOLET在進入戰鬥後自帶<link=\"30051\"><#FFAE07><u>【特別技能】</u></color></link>。選擇1個格子，對<color=#00F6FF>菱形13格</color>造成<color=#00F6FF>{1}%</color>的傷害並附加<color=#00F6FF>9</color>層<link=\"30052\"><#FFAE07><u>弱點揭明</u></color></link>。",
  str_skill_desc_320161 = "VIOLET在進入戰鬥後自帶<link=\"30051\"><#FFAE07><u>【特別技能】</u></color></link>。選擇1個格子，對<color=#00F6FF>菱形13格</color>造成<color=#00F6FF>{1}%</color>的傷害並附加<color=#00F6FF>9</color>層<link=\"30052\"><#FFAE07><u>弱點揭明</u></color></link>，對森屬性的敵人改為<color=#00F6FF>18層</color>。",
  str_skill_desc_2001611 = "對<color=#00F6FF>縱向1列</color>造成<color=#00F6FF>{1}%</color>的傷害。對每個敵人附加<color=#00F6FF>2</color>層<link=\"30052\"><#FFAE07><u>弱點揭明</u></color></link>，對森屬性的敵人改為<color=#00F6FF>4</color>層。",
