  str_skill_passive_name_400165 = "太陽箭之領域",
  str_skill_passive_desc_400165 = "連鎖技能<color=#00F6FF>每次</color>命中目標時，在其<color=#00F6FF>周圍1圈</color>的隨機格子上留下<color=#00F6FF>太陽箭雷</color>，敵方經過時<color=#00F6FF>觸發爆炸</color>，對<color=#00F6FF>十字5格</color>造成琪爾<color=#00F6FF>{1}</color>攻擊力的傷害，可無視防禦。<color=#00F6FF>太陽箭雷</color>在<color=#00F6FF>觸發爆炸</color>或<color=#00F6FF>回合結束</color>後消失。",
  str_skill_passive_name_420165 = "太陽箭之領域",
  str_skill_passive_desc_420165 = "連鎖技能<color=#00F6FF>每次</color>命中目標時，在其<color=#00F6FF>周圍1圈</color>的隨機格子上留下<color=#00F6FF>太陽箭雷</color>，敵方經過或<color=#00F6FF>回合結束</color>時<color=#00F6FF>觸發爆炸</color>並消失，對<color=#00F6FF>十字5格</color>造成琪爾<color=#00F6FF>{1}</color>攻擊力的傷害，可無視防禦。",
