  str_skill_desc_326164 = "消耗<color=#00F6FF>2</color>點<link=\"30054\"><#FFAE07><u>煜魂值</u></color></link>，瞬移到<color=#00F6FF>十字形16格</color>內的任意位置，將瞬移位置<color=#00F6FF>前後2格</color>轉變為火屬性，並對<color=#00F6FF>沿途格子及面前1格</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_330164 = "消耗<color=#00F6FF>2</color>點<link=\"30053\"><#FFAE07><u>煜魂值</u></color></link>，瞬移到<color=#00F6FF>十字形16格</color>內的任意位置，將瞬移位置<color=#00F6FF>前後2格</color>轉變為火屬性，並對<color=#00F6FF>沿途格子及面前1格</color>造成<color=#00F6FF>{1}%</color>的傷害。如果命中敵人，獲得<color=#00F6FF>1</color>點<link=\"30053\"><#FFAE07><u>煜魂值</u></color></link>，每回合最多觸發<color=#00F6FF>1</color>次。",
  str_skill_desc_333164 = "消耗<color=#00F6FF>2</color>點<link=\"30054\"><#FFAE07><u>煜魂值</u></color></link>，瞬移到<color=#00F6FF>十字形16格</color>內的任意位置，將瞬移位置<color=#00F6FF>前後2格</color>轉變為火屬性，並對<color=#00F6FF>沿途格子及面前1格</color>造成<color=#00F6FF>{1}%</color>的傷害。如果命中敵人，獲得<color=#00F6FF>1</color>點<link=\"30054\"><#FFAE07><u>煜魂值</u></color></link>，每回合最多觸發<color=#00F6FF>1</color>次。",
  str_skill_desc_336164 = "消耗<color=#00F6FF>2</color>點<link=\"30054\"><#FFAE07><u>煜魂值</u></color></link>，瞬移到<color=#00F6FF>十字形16格</color>內的任意位置，將瞬移位置<color=#00F6FF>前後2格</color>轉變為火屬性，並對<color=#00F6FF>沿途格子及面前1格</color>造成<color=#00F6FF>{1}%</color>的傷害。如果命中敵人，獲得<color=#00F6FF>1</color>點<link=\"30054\"><#FFAE07><u>煜魂值</u></color></link>，每回合最多觸發<color=#00F6FF>2</color>次。",
  str_skill_passive_name_410164 = "克定輝映",
  str_skill_passive_desc_410164 = "卡蓮·煜魂對位於火屬性格子的敵人普通攻擊時，附加<color=#00F6FF>{1}</color>攻擊力的傷害，可無視防禦。",
  str_skill_upgrade_desc_16016413 = "主動技能強化：進入戰鬥時自帶<color=#00F6FF>2</color>點<link=\"30054\"><#FFAE07><u>煜魂值</u></color></link>。",
  str_skill_upgrade_desc_16016416 = "主動技能強化：如果命中敵人，獲得<color=#00F6FF>1</color>點<link=\"30054\"><#FFAE07><u>煜魂值</u></color></link>，每回合最多觸發<color=#00F6FF>2</color>次（覺醒3階段生效）。",
  str_skill_desc_5220011 = "選擇<color=#00F6FF>1</color>個可行走的格子，將其轉化為<color=#00F6FF>彩色格子</color>。",
