  str_skill_name_330168 = "極促噴泉",
  str_skill_desc_2001681 = "對最靠近的2名敵人造成<color=#00F6FF>{1}%</color>的傷害。在目標腳下1個隨機格子生成<link=\"30061\"><#FFAE07><u>花灑印記</u></color></link>。",
  str_skill_desc_2001682 = "對最靠近的3名敵人造成<color=#00F6FF>{1}%</color>的傷害。在目標腳下1個隨機格子生成<link=\"30061\"><#FFAE07><u>花灑印記</u></color></link>。",
  str_skill_desc_2001683 = "對最靠近的4名敵人造成<color=#00F6FF>{1}%</color>的傷害。在目標腳下1個隨機格子生成<link=\"30061\"><#FFAE07><u>花灑印記</u></color></link>。",
  str_skill_desc_300168 = "觸發場上所有的<link=\"30061\"><#FFAE07><u>花灑印記</u></color></link>，每個對<color=#00F6FF>十字5格</color>造成<color=#00F6FF>240%</color>的傷害，對同一目標造成多次傷害時遞減，最低為原效果的<color=#00F6FF>10%</color>。",
  str_skill_desc_320168 = "觸發場上所有的<link=\"30061\"><#FFAE07><u>花灑印記</u></color></link>，每個對<color=#00F6FF>方形9格</color>造成<color=#00F6FF>240%</color>的傷害，對同一目標造成多次傷害時遞減，最低為原效果的<color=#00F6FF>10%</color>。",
  str_skill_desc_330168 = "觸發場上所有的<link=\"30061\"><#FFAE07><u>花灑印記</u></color></link>，每個對<color=#00F6FF>方形9格</color>造成<color=#00F6FF>240%</color>的傷害，對同一目標造成多次傷害時遞減，最低為原效果的<color=#00F6FF>10%</color>。被<color=#00F6FF>3</color>個已觸發印記覆蓋的格子上如果沒有花灑印記，則生成1個新的花灑印記。",
  str_skill_passive_name_410168 = "滂球盾",
  str_skill_passive_name_415168 = "滂球盾",
  str_skill_passive_desc_410168 = "連線經過<link=\"30061\"><#FFAE07><u>花灑印記</u></color></link>時提供等同於虹霞基礎防禦力<color=#00F6FF>{1}</color>的護盾，持續1回合。",
  str_skill_passive_desc_415168 = "連線經過<link=\"30061\"><#FFAE07><u>花灑印記</u></color></link>時提供等同於虹霞基礎防禦力<color=#00F6FF>{1}</color>的護盾，持續1回合。每回合開始時，在場上隨機<color=#00F6FF>1</color>個水屬性格子上生成花灑印記。",
  str_skill_upgrade_desc_15016812 = "主動技能強化：主動技能變為<color=#FFFF00>先制攻擊</color>，進入戰鬥即可使用。",
  str_skill_upgrade_desc_15016815 = "裝備技能強化：每回合開始時在場上隨機<color=#00F6FF>1</color>個水屬性格子上生成花灑印記。",
