  str_skill_name_326167 = "組牌魔手",
  str_skill_desc_2001671 = "對<color=#00F6FF>周圍3圈</color>內最靠近的3名敵人造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2001672 = "對<color=#00F6FF>周圍3圈</color>內最靠近的4名敵人造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2001673 = "對<color=#00F6FF>周圍3圈</color>內的全體敵人造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_300167 = "傑諾在進入戰鬥後自帶<link=\"30058\"><#FFAE07><u>【起源之牌】</u></color></link>與<link=\"30039\"><#FFAE07><u>【理智系統】</u></color></link>。消耗<color=#00F6FF>{1}</color>點理智值隨機獲得1張起源之牌，回合內再次施放會提高<color=#00F6FF>5</color>點消耗。",
  str_skill_desc_303167 = "傑諾在進入戰鬥後自帶<link=\"30059\"><#FFAE07><u>【起源之牌】</u></color></link>與<link=\"30039\"><#FFAE07><u>【理智系統】</u></color></link>。消耗<color=#00F6FF>{1}</color>點理智值隨機獲得1張起源之牌，回合內再次施放會提高<color=#00F6FF>5</color>點消耗。",
  str_skill_desc_306167 = "傑諾在進入戰鬥後自帶<link=\"30060\"><#FFAE07><u>【起源之牌】</u></color></link>與<link=\"30039\"><#FFAE07><u>【理智系統】</u></color></link>。消耗<color=#00F6FF>{1}</color>點理智值隨機獲得1張起源之牌，回合內再次施放會提高<color=#00F6FF>5</color>點消耗。",
  str_skill_desc_320167 = "傑諾在進入戰鬥後自帶<link=\"30058\"><#FFAE07><u>【起源之牌】</u></color></link>與<link=\"30039\"><#FFAE07><u>【理智系統】</u></color></link>。消耗<color=#00F6FF>{1}</color>點理智值隨機獲得1張起源之牌，回合內再次施放會提高<color=#00F6FF>5</color>點消耗。同時受到「類聚同明」和「星月凌日」強化的光靈，理智值愈低，攻擊加成愈高，最大提高<color=#00F6FF>66.6%</color>。",
  str_skill_desc_323167 = "傑諾在進入戰鬥後自帶<link=\"30059\"><#FFAE07><u>【起源之牌】</u></color></link>與<link=\"30039\"><#FFAE07><u>【理智系統】</u></color></link>。消耗<color=#00F6FF>{1}</color>點理智值隨機獲得1張起源之牌，回合內再次施放會提高<color=#00F6FF>5</color>點消耗。同時受到「類聚同明」和「星月凌日」強化的光靈，理智值愈低，攻擊加成愈高，最大提高<color=#00F6FF>66.6%</color>。",
  str_skill_desc_326167 = "傑諾在進入戰鬥後自帶<link=\"30060\"><#FFAE07><u>【起源之牌】</u></color></link>與<link=\"30039\"><#FFAE07><u>【理智系統】</u></color></link>。消耗<color=#00F6FF>{1}</color>點理智值隨機獲得1張起源之牌，回合內再次施放會提高<color=#00F6FF>5</color>點消耗。同時受到「類聚同明」和「星月凌日」強化的光靈，理智值愈低，攻擊加成愈高，最大提高<color=#00F6FF>66.6%</color>。",
  str_skill_passive_name_410167 = "底牌回天",
  str_skill_passive_desc_410167 = "每次施放【起源之牌】時，為隊伍回復相當於傑諾基礎攻擊力<color=#00F6FF>{1}</color>的生命值，該效果不受理智系統影響。隊伍生命值愈低，回復效果愈高，最大翻倍。",
  str_skill_passive_name_413167 = "底牌回天",
  str_skill_passive_desc_413167 = "每次施放【起源之牌】時，為隊伍回復相當於傑諾基礎攻擊力<color=#00F6FF>{1}</color>的生命值，該效果不受理智系統影響。隊伍生命值愈低，回復效果愈高，最大翻倍。戰鬥開始時隨機獲得<color=#00F6FF>2</color>張牌。",
  str_skill_passive_name_416167 = "底牌回天",
  str_skill_passive_desc_416167 = "每次施放【起源之牌】時，為隊伍回復相當於傑諾基礎攻擊力<color=#00F6FF>{1}</color>的生命值，該效果不受理智系統影響。隊伍生命值愈低，回復效果愈高，最大翻倍。戰鬥開始時隨機獲得<color=#00F6FF>2</color>張牌。",
  str_skill_passive_name_430167 = "底牌回天",
  str_skill_passive_desc_430167 = "每次施放【起源之牌】時，為隊伍回復相當於傑諾基礎攻擊力<color=#00F6FF>{1}</color>的生命值，該效果不受理智系統影響。隊伍生命值愈低，回復效果愈高，最大翻倍。進入極光時刻時隨機獲得1張牌。",
  str_skill_passive_name_433167 = "底牌回天",
  str_skill_passive_desc_433167 = "每次施放【起源之牌】時，為隊伍回復相當於傑諾基礎攻擊力<color=#00F6FF>{1}</color>的生命值，該效果不受理智系統影響。隊伍生命值愈低，回復效果愈高，最大翻倍。戰鬥開始時隨機獲得<color=#00F6FF>2</color>張牌，進入極光時刻時隨機獲得1張牌。",
  str_skill_passive_name_436167 = "底牌回天",
  str_skill_passive_desc_436167 = "每次施放【起源之牌】時，為隊伍回復相當於傑諾基礎攻擊力<color=#00F6FF>{1}</color>的生命值，該效果不受理智系統影響。隊伍生命值愈低，回復效果愈高，最大翻倍。戰鬥開始時隨機獲得<color=#00F6FF>2</color>張牌，進入極光時刻時隨機獲得1張牌。",
  str_skill_upgrade_desc_16016713 = "進入戰鬥時隨機獲得<color=#00F6FF>2</color>張<link=\"30059\"><#FFAE07><u>【起源之牌】</u></color></link>。",
  str_skill_upgrade_desc_16016716 = "起源之牌技能強化：「異色雙輝」效果回復<color=#00F6FF>25%</color>已損失的理智值。",
  str_skill_name_3001670 = "星月凌日",
  str_skill_desc_3001670 = "<color=#00F6FF>目前隊尾</color>光靈額外獲得傑諾基礎攻擊力<color=#00F6FF>7%</color>的攻擊力。",
  str_skill_name_3001671 = "類聚同明",
  str_skill_desc_3001671 = "<color=#00F6FF>目前隊長</color>光靈獲得傑諾基礎攻擊力<color=#00F6FF>8%</color>的額外攻擊力。",
  str_skill_name_3001674 = "異色雙輝",
  str_skill_desc_3001674 = "本場戰鬥可更換隊長次數+1，同時回復<color=#00F6FF>25%</color>已損失理智值。",
  str_skill_name_30016740 = "異色雙輝",
  str_skill_desc_30016740 = "本場戰鬥可更換隊長次數+1，同時回復<color=#00F6FF>18%</color>已損失理智值。",
  str_skill_name_10071413 = "理智波動",
  str_skill_desc_10071413 = "碩腕會影響光靈的理智值。每回合開始時，每隻存活的碩腕降低2點理智值，死亡時回復3點理智值。",
  str_skill_upgrade_desc_16016613 = "主動技能強化：每波次開始獲得<color=#00F6FF>1</color>點誘餌值。",
  str_skill_upgrade_desc_16016616 = "主動技能強化：獵捕標記存在<color=#00F6FF>2/3</color>回合時，「凱羅」造成<color=#00F6FF>350%/500%</color>的傷害。",
  str_skill_passive_name_410166 = "雲浪",
  str_skill_passive_name_430166 = "雲浪",
  str_skill_passive_desc_410166 = "菲雅在<color=#00F6FF>水屬性</color>格子上移動時將快速滑行，對相鄰敵人造成傷害，在<link=\"30057\"><#FFAE07><u>轉彎</u></color></link>時對<color=#00F6FF>周圍1圈</color>造成傷害，並對目標附加持續1回合的潮濕效果：受到的剋制屬性傷害係數增加<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_430166 = "菲雅在<color=#00F6FF>水屬性</color>格子上移動時將快速滑行，對相鄰敵人造成傷害，在<link=\"30057\"><#FFAE07><u>轉彎</u></color></link>時對<color=#00F6FF>周圍1圈</color>造成傷害，並對目標附加持續1回合的潮濕效果：受到的剋制屬性傷害係數增加<color=#00F6FF>{1}</color>。潮濕效果對火屬性敵人提高<color=#00F6FF>50%</color>。",
  str_skill_name_300166 = "凱羅計畫",
  str_skill_name_320166 = "凱羅計畫",
  str_skill_name_303166 = "凱羅計畫",
