  str_skill_name_323166 = "凱羅計畫",
  str_skill_name_326166 = "凱羅計畫",
  str_skill_desc_300166 = "消耗<color=#00F6FF>1</color>點<link=\"30055\"><#FFAE07><u>誘餌值</u></color></link>，任選1個格子放置獵捕標記，或選擇1個獵捕標記喚出「凱羅」。獵捕標記存在<color=#00F6FF>0/1/2/3</color>回合時，「凱羅」對<color=#00F6FF>獵捕標記所在格/十字5格/菱形13格/方形25格</color>範圍造成<color=#00F6FF>150%/200%/250%/300%</color>的傷害。",
  str_skill_desc_320166 = "消耗<color=#00F6FF>1</color>點<link=\"30055\"><#FFAE07><u>誘餌值</u></color></link>，任選1個格子放置獵捕標記，或選擇1個獵捕標記喚出「凱羅」。獵捕標記存在<color=#00F6FF>0/1/2/3</color>回合時，「凱羅」對<color=#00F6FF>獵捕標記所在格/十字5格/菱形13格/方形25格</color>範圍造成<color=#00F6FF>150%/200%/250%/300%</color>的傷害，本回合目標降低<color=#00F6FF>5%</color>的基礎防禦，效果可疊加。",
  str_skill_desc_303166 = "消耗<color=#00F6FF>1</color>點<link=\"30056\"><#FFAE07><u>誘餌值</u></color></link>，任選1個格子放置獵捕標記，或選擇1個獵捕標記喚出「凱羅」。獵捕標記存在<color=#00F6FF>0/1/2/3</color>回合時，「凱羅」對<color=#00F6FF>獵捕標記所在格/十字5格/菱形13格/方形25格</color>範圍造成<color=#00F6FF>150%/200%/250%/300%</color>的傷害。",
  str_skill_desc_306166 = "消耗<color=#00F6FF>1</color>點<link=\"30056\"><#FFAE07><u>誘餌值</u></color></link>，任選1個格子放置獵捕標記，或選擇1個獵捕標記喚出「凱羅」。獵捕標記存在<color=#00F6FF>0/1/2/3</color>回合時，「凱羅」對<color=#00F6FF>獵捕標記所在格/十字5格/菱形13格/方形25格</color>範圍造成<color=#00F6FF>150%/200%/350%/500%</color>的傷害。",
  str_skill_desc_323166 = "消耗<color=#00F6FF>1</color>點<link=\"30056\"><#FFAE07><u>誘餌值</u></color></link>，任選1個格子放置獵捕標記，或選擇1個獵捕標記喚出「凱羅」。獵捕標記存在<color=#00F6FF>0/1/2/3</color>回合時，「凱羅」對<color=#00F6FF>獵捕標記所在格/十字5格/菱形13格/方形25格</color>範圍造成<color=#00F6FF>150%/200%/250%/300%</color>的傷害，本回合目標降低<color=#00F6FF>5%</color>的基礎防禦，效果可疊加。",
