  str_skill_desc_29039011 = "如果光靈不位於十字最大範圍內，則向光靈所在位置移動並在位於光靈相鄰4格時發動攻擊。",
  str_skill_desc_290390111 = "如果光靈不位於米字最大範圍內，則向光靈所在位置移動並在位於光靈周圍1圈時發動攻擊。",
