  str_skill_desc_291030102 = "如果尼珀里絲本體距離玩家更近，則本體與鏡像交換位置，並對沿途目標造成傷害",
  str_skill_desc_291030103 = "召喚鏡物，下回合鏡物會自殺並詛咒隨機光靈2回合",
