  str_skill_desc_2001302 = "令<color=#00F6FF>菱形12格</color>的<link=\"30062\"><#FFAE07><u>律法之像</u></color></link><color=#00F6FF>等級+1</color>。",
  str_skill_desc_2001303 = "令<color=#00F6FF>周圍2圈</color>的<link=\"30062\"><#FFAE07><u>律法之像</u></color></link><color=#00F6FF>等級+1</color>。",
  str_skill_name_300130 = "眾人入席",
  str_skill_desc_300130 = "選擇一個可行走的格子，將所選格及周圍2圈範圍內的<link=\"30062\"><#FFAE07><u>律法之像</u></color></link>全部<color=#00F6FF>摧毀</color>，並在所選格上生成1個新的律法之像，等級為已摧毀律法之像的<color=#00F6FF>等級之和</color>。若範圍內沒有律法之像，則會在所選格上生成1個1級律法之像。",
  str_skill_passive_name_400130 = "律法必報",
  str_skill_passive_desc_400130 = "每連線行走5格，在上一格所在位置生成1個1級<link=\"30062\"><#FFAE07><u>律法之像</u></color></link>。若已有律法之像，則使其<color=#00F6FF>等級+1</color>。",
