  str_skill_passive_name_430171 = "一擊而破",
  str_skill_desc_2001711 = "對<color=#00F6FF>十字形8格</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2001712 = "對<color=#00F6FF>十字形12格</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2001713 = "對<color=#00F6FF>十字形最大</color>範圍造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2201711 = "對<color=#00F6FF>十字形8格</color>造成<color=#00F6FF>{1}%</color>的傷害，遇到阻擋時會往兩側各擴散1格。",
  str_skill_desc_2201712 = "對<color=#00F6FF>十字形12格</color>造成<color=#00F6FF>{1}%</color>的傷害，遇到阻擋時會往兩側各擴散1格。",
  str_skill_desc_2201713 = "對<color=#00F6FF>十字形最大</color>造成<color=#00F6FF>{1}%</color>的傷害，遇到阻擋時會往兩側各擴散1格。",
  str_skill_desc_3001711 = "消耗<color=#00F6FF>2</color>點<link=\"30063\"><#FFAE07><u>銃禦值</u></color></link>並清空剩餘銃禦值，本回合連鎖技能階段結束後對<color=#00F6FF>周圍1圈</color>造成<color=#00F6FF>200%</color>的傷害。每清空1點銃禦值，最終傷害增加<color=#00F6FF>20%</color>。",
  str_skill_desc_3021711 = "消耗<color=#00F6FF>2</color>點<link=\"30064\"><#FFAE07><u>銃禦值</u></color></link>並清空剩餘銃禦值，本回合連鎖技能階段結束後對<color=#00F6FF>周圍1圈</color>造成<color=#00F6FF>200%</color>的傷害。每清空1點銃禦值，最終傷害增加<color=#00F6FF>20%</color>。",
  str_skill_desc_3051711 = "消耗<color=#00F6FF>2</color>點<link=\"30064\"><#FFAE07><u>銃禦值</u></color></link>並清空剩餘銃禦值，本回合連鎖技能階段結束後對<color=#00F6FF>周圍1圈</color>造成<color=#00F6FF>200%</color>的傷害。每清空1點銃禦值最終傷害增加<color=#00F6FF>25%</color>。",
  str_skill_passive_desc_400171 = "連線每經過1格森屬性格子或強化格子時，發現1處<color=#00F6FF>敵之弱點</color>，累積6處後下一次普通攻擊暴擊，造成<color=#00F6FF>120%~{1}</color>之間的隨機傷害，然後清空所有<color=#00F6FF>敵之弱點</color>。",
  str_skill_passive_desc_430171 = "連線每經過1格森屬性格子或強化格子時發現1處<color=#00F6FF>敵之弱點</color>，累積6處後下一次普通攻擊暴擊，造成<color=#00F6FF>120%~{1}</color>之間的隨機傷害，然後清空所有<color=#00F6FF>敵之弱點</color>，並獲得1點銃禦值。",
  str_skill_upgrade_desc_15017112 = "主動技能強化：戰鬥開始時獲得<color=#00F6FF>2</color>點銃禦值。",
  str_skill_upgrade_desc_15017115 = "主動技能強化：每清空1點銃禦值，最終傷害增加<color=#00F6FF>25%</color>。",
