  str_skill_desc_2001701 = "對<color=#00F6FF>周圍1圈</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2001702 = "對<color=#00F6FF>周圍1圈</color>及<color=#00F6FF>沿十字方向逐格蔓延</color>的雷屬性格子造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2001703 = "對<color=#00F6FF>周圍1圈</color>及<color=#00F6FF>沿8個方向逐格蔓延</color>的雷屬性格子造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_300170 = "選擇1個格子，然後在左右兩側選擇一個方向，半區內所有格子顏色沿選定方向推進1格，<color=#00F6FF>選中格所在列</color>全部生成雷屬性格子。",
  str_skill_desc_306170 = "選擇1個格子，然後在左右兩側選擇一個方向，半區內所有格子顏色沿選定方向推進1格，<color=#00F6FF>選中格所在列</color>全部生成雷屬性格子。",
  str_skill_desc_320170 = "選擇1個格子，然後在左右兩側選擇一個方向，半區內所有格子顏色沿選定方向推進1格。<color=#00F6FF>選中格所在列</color>全部生成雷屬性格子，同時對該列造成<color=#00F6FF>250%</color>的傷害。",
  str_skill_desc_326170 = "選擇1個格子，然後在左右兩側選擇一個方向，半區內所有格子顏色沿選定方向推進1格。<color=#00F6FF>選中格所在列</color>全部生成雷屬性格子，同時對該列造成<color=#00F6FF>250%</color>的傷害。",
  str_skill_desc_330170 = "選擇1個格子，然後在左右兩側選擇一個方向，半區內所有格子顏色沿選定方向推進1格。<color=#00F6FF>選中格所在列</color>全部生成雷屬性格子，同時對該列造成<color=#00F6FF>250%</color>的傷害。若選中格位於<color=#00F6FF>單格敵人</color>腳下，還會將目標沿選定方向強制位移1格。",
  str_skill_desc_336170 = "選擇1個格子，然後在左右兩側選擇一個方向，半區內所有格子顏色沿選定方向推進1格。<color=#00F6FF>選中格所在列</color>全部生成雷屬性格子，同時對該列造成<color=#00F6FF>250%</color>的傷害。若選中格位於<color=#00F6FF>單格敵人</color>腳下，還會將目標沿選定方向強制位移1格。",
  str_skill_passive_desc_410170 = "連鎖技能造成傷害時，目標距離愈遠，傷害愈高，每圈增加<color=#00F6FF>{1}</color>的最終傷害。",
  str_skill_passive_desc_420170 = "連鎖技能和主動技能造成傷害時，目標距離愈遠，傷害愈高，每圈增加<color=#00F6FF>{1}</color>的最終傷害。",
  str_skill_upgrade_desc_16017013 = "主動技能強化：主動技能變為<color=#FFFF00>先制攻擊</color>，進入戰鬥即可使用。",
  str_skill_upgrade_desc_16017016 = "主動技能強化：技能冷卻回合<color=#FFFF00>-1</color>。",
