  str_skill_desc_290370121 = "移動1格後，主砲發射震盪攻擊對前方4格範圍造成衝擊，對範圍內的目標造成傷害並擊退3格距離。",
  str_skill_desc_290370123 = "主砲發射震盪攻擊對前方4格範圍造成衝擊，對範圍內的目標造成傷害並擊退3格距離。",
  str_skill_name_290370122 = "超限主砲·震盪",
