  str_skill_name_290370151 = "超限",
  str_skill_desc_290370151 = "進入超限狀態，提升移動距離和攻擊力。",
  str_skill_name_490370401 = "緊急維修",
  str_skill_desc_490370401 = "生命值鎖定，進入緊急維修。先使用主砲將光靈擊退至場地邊緣，再為自身附加護盾，護盾1回合後將雙倍轉化為生命值。",
  str_skill_name_40004451 = "污染",
  str_skill_desc_40004451 = "彌染攻擊並擊退範圍內的目標。",
  str_skill_name_49004213 = "輪迴使者",
  str_skill_desc_49004213 = "麥格芬·斯摩為即將到來的白夜升潮積蓄力量，並召喚中鋒護衛自己。",
  str_skill_name_49004215 = "白夜升潮",
  str_skill_desc_49004215 = "麥格芬·斯摩對場景中的固定區域進行輪流轟炸，同時鎖定區域內的格子。",
  str_skill_name_400060101 = "戰力提升",
  str_skill_desc_400060101 = "擁抱者附身到周圍1圈內的暗鬼身上，為其提供護盾，同時強化其攻擊力和行動力。",
  str_skill_name_400060201 = "強化回復",
  str_skill_desc_400060201 = "靠近多恩周圍1圈時，可融入其體內，為其回復生命值和提高攻擊力，並為其添加護盾。",
  str_skill_desc_400071502 = "對位於自身米字形最大方向上的目標，造成基於目標最大生命值的百分比傷害。若自身周圍8個方向上沒有目標，則為自己添加防禦屏障。",
  str_skill_desc_400072502 = "對位於自身米字形最大方向上的目標，造成基於目標最大生命值的百分比傷害。若自身周圍8個方向上沒有目標，則為友軍單位回復生命值。",
  str_skill_desc_490050302 = "化變對範圍內的目標造成傷害並將其牽引至自己身邊。不論是否攻擊到目標，均會重設自身周圍2圈的格子。若攻擊到目標，則鎖定目標周圍1圈的格子。",
  str_skill_desc_491050301 = "化變對目標所在方向釋放1道寬度兩行的衝擊波，對命中目標造成傷害，並重設攻擊範圍內的格子。",
  str_skill_desc_491050302 = "化變對範圍內的目標造成傷害並將其牽引至自己身邊。不論是否攻擊到目標，均會重設自身周圍3圈的格子。",
  str_skill_desc_490028304 = "暗潮喚塔者召喚4個信標，隨後為所有信標回復生命值。",
  str_skill_desc_491028304 = "暗潮喚塔者召喚4個信標，隨後為所有信標回復生命值。",
  str_skill_desc_490025102 = "召喚1個狂暴的幽靈幻象幫助幽靈本體作戰，如果場上已有幻象，則會先召回現有的幻象，再召喚新的幻象。若成功召回幻象，則幽靈本體永久提升一定的攻擊力。",
  str_skill_desc_490025201 = "狂暴的幽靈造成2次攻擊，並召喚幻象協助自己作戰。",
  str_skill_name_491025203 = "幻象召回",
  str_skill_desc_491025203 = "如果場上存在幻象，則會將現有幻象召回，隨後回復生命值，提高攻擊力，且行動力提升效果消失。如果場上不存在幻象，則為自己提升行動力。",
  str_skill_name_215007811 = "普通攻擊",
