  str_skill_name_212005012 = "旋齒四方裂",
  str_skill_desc_212005012 = "對範圍內的目標造成傷害。",
  str_skill_name_213004911 = "跳斬",
  str_skill_desc_213004911 = "對範圍內的目標造成傷害。",
