  str_skill_desc_213004912 = "對周圍1圈內的目標造成傷害，同時重設範圍內的非水屬性格子。",
  str_skill_name_214009111 = "協奏琴音",
  str_skill_desc_214009111 = "施放時，場上每個水屬性格子在本回合為己方成員提供0.5%的攻擊力加成。",
  str_skill_name_214009112 = "粼粼悲嘆",
  str_skill_desc_214009112 = "對場內的目標造成傷害。",
  str_skill_name_214009121 = "協奏琴音",
  str_skill_desc_214009121 = "施放時，在本回合內使己方成員行動力+1，場上每個水屬性格子為己方成員提供0.5%的攻擊力加成。",
  str_skill_desc_490022306 = "無聊凝聚力量，準備施放十字大範圍火屬性攻擊，對命中的目標造成傷害和附帶灼燒，凝聚力量時召喚雙刀保護自己，召喚完成後為場內其他暗鬼提升行動力。",
  str_skill_desc_490022310 = "無聊凝聚力量，準備施放十字大範圍雷屬性攻擊，對命中的目標造成傷害和麻痺效果，凝聚力量時召喚雙刀保護自己，召喚完成後為場內其他暗鬼提升行動力。",
  str_skill_desc_490064302 = "月瀆能量外洩，對橫縱4列範圍造成傷害。",
  str_skill_desc_490060103 = "隨機對場上7個2*2範圍造成傷害，並在範圍內生成火焰。若命中光靈則改變其所在位置周圍1圈格子的屬性，並詛咒光靈隊伍中的隊長。",
  str_skill_desc_49006811 = "無形閃爍至棋盤邊緣且距離玩家較遠的位置，發動遠程攻擊。然後在與光靈連線的一定範圍內隨機投擲2隻無存和1隻爆裂。",
  str_skill_desc_49006812 = "無形向全場隨機位置投擲4隻無存。",
  str_skill_desc_490091202 = "朝目標上回合所在位置釋放光束衝擊，對路徑上及目標位置的目標造成傷害，若擊中目標，則詛咒光靈隊伍中的隊長。",
  str_skill_desc_490091203 = "對範圍內的目標造成傷害。",
  str_skill_desc_490006301 = "麥格芬扭曲並撕裂面前的空間，造成屬性傷害，若擊中光靈，則使光靈致盲。",
  str_skill_desc_490006302 = "麥格芬將光靈擊退，為即將到來的風暴潮蓄積力量。",
  str_skill_desc_490006304 = "麥格芬對固定區域進行輪流轟炸，並在每個區域內召喚禁技碣。",
  str_skill_desc_490006306 = "麥格芬對固定區域進行輪流轟炸，並在每個區域內召喚禁技碣。",
  str_skill_desc_491006304 = "麥格芬對固定區域進行輪流轟炸，並擊碎區域內的格子。",
  str_skill_desc_491006305 = "麥格芬對固定區域進行輪流轟炸，並擊碎區域內的格子。",
  str_skill_desc_491006302 = "麥格芬將光靈擊退，在場內召喚中鋒，並為即將到來的風暴潮蓄積力量。",
  str_skill_desc_492006306 = "麥格芬對固定區域進行輪流轟炸，並擊碎區域內的格子。",
  str_skill_desc_490110101 = "繆特對自身前方2格矩形最大範圍施放衝擊波，對範圍內的目標造成傷害，若命中目標，則回復自身生命值。",
  str_skill_desc_490110201 = "繆特對自身前方2格矩形最大範圍施放衝擊波，對範圍內的目標造成傷害，若命中目標，則使目標疲憊。",
  str_skill_name_490110301 = "索羅斯的號角",
  str_skill_desc_490110301 = "繆特使場內暗鬼的攻擊力和行動力提升。",
  str_skill_name_400040101 = "十字暗能",
  str_skill_desc_400040101 = "當暗潮喚塔者蓄能時，信標對十字範圍內的目標進行攻擊。",
  str_skill_name_810410092 = "暗礁之喚",
  str_skill_desc_810410092 = "召喚2枚特殊符文，一定回合後變為禁技碣。",
  str_skill_desc_490040103 = "舒默召喚雷電之力，對場上多個十字區域造成傷害，直接擊殺十字區域中間的敵人。",
  str_skill_desc_490040106 = "舒默召喚雷電之力，對場上多個十字區域造成傷害，並召喚數隻小型暗鬼。",
  str_skill_desc_490040108 = "舒默控制巨像施放音波攻擊全場目標，直接擊殺小型暗鬼，每擊殺一隻暗鬼則回復1%的生命值。",
  str_skill_desc_490067201 = "舒默控制巨像施放音波攻擊全場目標，並對場上特定位置進行轉色。",
  str_skill_desc_490067202 = "舒默施放狂暴的能量，攻擊全場的目標並對特定位置進行轉色。目標離舒默愈遠，受到的傷害愈高。",
  str_skill_desc_490021101 = "黑蹄在戰場上隨機位置召喚4個碎石，並在回合開始時光靈所處的位置附近召喚1個禁技碣。",
  str_skill_desc_490021102 = "黑蹄遠離玩家，並在玩家的相鄰位置召喚4個碎石。",
  str_skill_name_490310101 = "應援烈火",
  str_skill_desc_490310101 = "若敵人位於自身周圍2圈範圍內，對其造成傷害並擊退1格。",
  str_skill_name_490310102 = "應援呼喚",
