  str_skill_name_490310105 = "芭芭拉普通攻擊",
  str_skill_desc_490310105 = "靠近敵人進行攻擊並將其擊退。",
  str_skill_name_491018101 = "終音耀斑天引",
  str_skill_desc_491018101 = "敵人位於自身周圍1圈範圍內時，製造太陽風爆炸造成傷害，並以自身為中心擊退命中的敵人。",
  str_skill_name_491018102 = "蕾吉娜普通攻擊",
  str_skill_desc_491018102 = "移動到目標身邊進行攻擊。",
  str_skill_name_491105101 = "赤眼龍捲·小",
  str_skill_desc_491105101 = "若周圍2圈範圍內有敵人存在，遠離敵人一段距離並對其造成10次傷害。",
  str_skill_name_491105102 = "赤眼龍捲·大",
  str_skill_desc_491105102 = "若敵人位於自身2圈範圍外，鎖定敵人並對其造成20次傷害。",
  str_skill_name_491030101 = "醒山普通攻擊",
  str_skill_desc_491030101 = "靠近敵人進行攻擊。",
  str_skill_name_491030102 = "赤砂崩碎",
  str_skill_desc_491030102 = "對米字形最大範圍造成大量傷害。",
  str_skill_desc_490060101 = "將範圍內的目標撞擊至自身周圍，同時改變自身所在位置以及周圍3圈格子的屬性。",
  str_skill_upgrade_desc_16017313 = "主動技能強化：主動技能每造成1次傷害，減少1層凡客印記。\n裝備技能強化：凡客印記清空後，基礎攻擊力提高<color=#FFFF00>25%</color>。\n（覺醒2階段生效）",
