  str_skill_name_3361731 = "米洛斯之速決",
  str_skill_desc_3001731 = "任選1個格子，並在<color=#00F6FF>周圍2圈</color>內再次選擇1個格子確定一個矩形區域，<link=\"30065\"><#FFAE07><u>吸收</u></color></link>該區域上的<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>，並對區域內的敵人造成<color=#00F6FF>100%</color>的傷害。每吸收1個強化格子提高<color=#00F6FF>50%</color>最終傷害。",
  str_skill_desc_3061731 = "任選1個格子，並在<color=#00F6FF>周圍2圈</color>內再次選擇1個格子確定一個矩形區域，<link=\"30065\"><#FFAE07><u>吸收</u></color></link>該區域上的<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>，並對區域內的敵人造成<color=#00F6FF>100%</color>的傷害。每吸收1個強化格子提高<color=#00F6FF>50%</color>最終傷害。進入極光時刻後可再施放1次。",
