  str_skill_desc_3331731 = "任選1個格子，並在<color=#00F6FF>周圍2圈</color>內再次選擇1個格子確定一個矩形區域，<link=\"30065\"><#FFAE07><u>吸收</u></color></link>該區域上的<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>，並對區域內的敵人造成<color=#00F6FF>100%</color>的傷害。每吸收1個強化格子提高<color=#00F6FF>50%</color>最終傷害。每造成1次傷害或吸收1個強化格子，額外減少1層凡客印記。",
