  str_skill_passive_desc_410173 = "每當隊伍獲得（包括<link=\"30065\"><#FFAE07><u>吸收</u></color></link>）<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>時，立即對全場隨機<color=#00F6FF>1</color>個目標造成<color=#00F6FF>{1}</color>的傷害。",
  str_skill_passive_desc_420173 = "每當隊伍獲得（包括<link=\"30065\"><#FFAE07><u>吸收</u></color></link>）<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>時，立即對全場隨機<color=#00F6FF>1</color>個目標造成<color=#00F6FF>{1}</color>的傷害。進入戰鬥時獲得<color=#00F6FF>33</color>層凡客印記，每次獲得強化格子減少<color=#00F6FF>1</color>層，印記清空後本場戰鬥進入犄影態：基礎攻擊力提高<color=#00F6FF>20%</color>，普通攻擊可攻擊斜方向，裝備技能傷害變為<color=#00F6FF>2.5</color>倍，連鎖技能命中同一目標後傷害不衰減。",
  str_skill_passive_desc_423173 = "每當隊伍獲得（包括<link=\"30065\"><#FFAE07><u>吸收</u></color></link>）<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>時，立即對全場隨機<color=#00F6FF>1</color>個目標造成<color=#00F6FF>{1}</color>的傷害。進入戰鬥時獲得<color=#00F6FF>33</color>層凡客印記，每次獲得強化格子減少<color=#00F6FF>1</color>層，印記清空後本場戰鬥進入犄影態：基礎攻擊力提高<color=#00F6FF>25%</color>，普通攻擊可攻擊斜方向，裝備技能傷害變為<color=#00F6FF>2.5</color>倍，連鎖技能命中同一目標後傷害不衰減。",
