  str_skill_desc_2001723 = "對<color=#00F6FF>菱形12格</color>造成<color=#00F6FF>{1}%</color>的傷害。若位於<color=#00F6FF>快閃陣</color>外，則在目前位置生成一個<color=#00F6FF>菱形12格</color>範圍的快閃陣。",
