  str_skill_desc_3201721 = "瞬移到<link=\"30066\"><#FFAE07><u>快閃陣</u></color></link>內的任意位置，對該<color=#00F6FF>快閃陣</color>區域內的格子造成<color=#00F6FF>{1}%</color>的傷害。場上同時最多保留<color=#00F6FF>2</color>個快閃陣。",
  str_skill_desc_3031721 = "瞬移到<link=\"30067\"><#FFAE07><u>快閃陣</u></color></link>內的任意位置。場上同時最多保留<color=#00F6FF>3</color>個快閃陣。",
  str_skill_desc_3231721 = "瞬移到<link=\"30067\"><#FFAE07><u>快閃陣</u></color></link>內的任意位置，對該<color=#00F6FF>快閃陣</color>區域內的格子造成<color=#00F6FF>{1}%</color>的傷害。場上同時最多保留<color=#00F6FF>3</color>個快閃陣。",
  str_skill_desc_3061721 = "瞬移到<link=\"30068\"><#FFAE07><u>快閃陣</u></color></link>內的任意位置。場上同時最多保留<color=#00F6FF>3</color>個快閃陣。",
  str_skill_desc_3261721 = "瞬移到<link=\"30068\"><#FFAE07><u>快閃陣</u></color></link>內的任意位置，對該<color=#00F6FF>快閃陣</color>區域內的格子造成<color=#00F6FF>{1}%</color>的傷害。場上同時最多保留<color=#00F6FF>3</color>個快閃陣。",
  str_skill_passive_desc_410172 = "在<color=#00F6FF>快閃陣</color>內每移動1格，獲得等同於莉莉卡目前防禦力<color=#00F6FF>{1}</color>的護盾。",
  str_skill_passive_desc_430172 = "在<color=#00F6FF>快閃陣</color>內每移動1格，獲得等同於莉莉卡目前防禦力<color=#00F6FF>{1}</color>的護盾。回合結束時，對場上所有<color=#00F6FF>快閃陣</color>範圍造成等同於目前護盾值的真實傷害。",
  str_skill_upgrade_desc_16017213 = "主動技能強化：場上同時至多保留<color=#00F6FF>3</color>個快閃陣。",
  str_skill_upgrade_desc_16017216 = "主動技能強化：主動技能變為<color=#FFFF00>先制攻擊</color>，進入戰鬥即可使用。進入戰鬥時在初始位置生成一個<color=#00F6FF>菱形12格</color>的快閃陣。",
