  str_skill_desc_300169 = "對<color=#00F6FF>十字相鄰</color>的1名敵人造成<color=#00F6FF>300%</color>的傷害並擊退2格，若擊退過程中遇到<color=#00F6FF>阻擋</color>，還會使其額外受到<color=#00F6FF>200%</color>的傷害並<color=#00F6FF>眩暈</color>1回合。",
  str_skill_desc_305169 = "對<color=#00F6FF>十字相鄰</color>的1名敵人造成<color=#00F6FF>300%</color>的傷害並擊退3格，若擊退過程中遇到<color=#00F6FF>阻擋</color>，還會使其額外受到<color=#00F6FF>200%</color>的傷害並<color=#00F6FF>眩暈</color>1回合。",
  str_skill_desc_330169 = "對<color=#00F6FF>十字相鄰</color>的1名敵人造成<color=#00F6FF>300%</color>的傷害並擊退2格，若擊退過程中遇到<color=#00F6FF>阻擋</color>，還會使其額外受到<color=#00F6FF>200%</color>的傷害並<color=#00F6FF>眩暈</color>1回合；若阻擋為其他敵人，則該敵人也會受到傷害和眩暈。",
  str_skill_desc_335169 = "對<color=#00F6FF>十字相鄰</color>的1名敵人造成<color=#00F6FF>300%</color>的傷害並擊退3格，若擊退過程中遇到<color=#00F6FF>阻擋</color>，還會使其額外受到<color=#00F6FF>200%</color>的傷害並<color=#00F6FF>眩暈</color>1回合；若阻擋為其他敵人，則該敵人也會受到傷害和眩暈。",
