  str_skill_passive_name_420169 = "揮棒擊術",
  str_skill_passive_desc_410169 = "塞提的基礎攻擊力提高<color=#00F6FF>{1}</color>，每次連線塞提最多普通攻擊<color=#00F6FF>3</color>次。3次之後的普通攻擊改為獲得1點<color=#00F6FF>擊墜點</color>，每點擊墜點提高<color=#00F6FF>{2}</color>的主動技能傷害係數，施放主動技能後清空。",
  str_skill_passive_desc_420169 = "塞提的基礎攻擊力提高<color=#00F6FF>{1}</color>，每次連線塞提最多普通攻擊<color=#00F6FF>3</color>次，第3次普通攻擊傷害翻倍。3次之後的普通攻擊改為獲得1點<color=#00F6FF>擊墜點</color>，每點擊墜點提高<color=#00F6FF>{2}</color>的主動技能傷害係數，施放主動技能後清空。",
