  str_skill_upgrade_desc_16017516 = "主動技能強化：適癒球存在0/1/2回合時，我方經過時回復係數提高到<color=#FFFF00>40%/100%/250%</color>,\n透過主動技能吸收時，回復係數提高到<color=#FFFF00>80%/180%/400%</color>。",
