  str_skill_desc_30317511 = "消耗1點<link=\"30070\"><#FFAE07><u>立方能</u></color></link>，選擇1個可行走的格子召喚1顆<link=\"30072\"><#FFAE07><u>適癒球</u></color></link>，或者選擇場上存在的適癒球，將其吸收並根據存在回合數回復生命值。適癒球被敵人觸碰後消失。",
  str_skill_desc_30617511 = "消耗1點<link=\"30070\"><#FFAE07><u>立方能</u></color></link>，選擇1個可行走的格子召喚1顆<link=\"30073\"><#FFAE07><u>適癒球</u></color></link>，或者選擇場上存在的適癒球，將其吸收並根據存在回合數回復生命值。適癒球被敵人觸碰後消失。",
  str_skill_desc_32017511 = "消耗1點<link=\"30069\"><#FFAE07><u>立方能</u></color></link>，選擇1個可行走的格子召喚1顆<link=\"30072\"><#FFAE07><u>適癒球</u></color></link>，或者選擇場上存在的適癒球，將其吸收並根據存在回合數回復生命值。適癒球被敵人觸碰後消失並返還1點立方能。",
  str_skill_desc_32317511 = "消耗1點<link=\"30070\"><#FFAE07><u>立方能</u></color></link>，選擇1個可行走的格子召喚1顆<link=\"30072\"><#FFAE07><u>適癒球</u></color></link>，或者選擇場上存在的適癒球，將其吸收並根據存在回合數回復生命值。適癒球被敵人觸碰後消失並返還1點立方能。",
  str_skill_desc_32617511 = "消耗1點<link=\"30070\"><#FFAE07><u>立方能</u></color></link>，選擇1個可行走的格子召喚1顆<link=\"30073\"><#FFAE07><u>適癒球</u></color></link>，或者選擇場上存在的適癒球，將其吸收並根據存在回合數回復生命值。適癒球被敵人觸碰後消失並返還1點立方能。",
  str_skill_desc_33017511 = "消耗1點<link=\"30069\"><#FFAE07><u>立方能</u></color></link>，選擇1個可行走的格子召喚1顆<link=\"30072\"><#FFAE07><u>適癒球</u></color></link>，或者選擇場上存在的適癒球，將其吸收並根據存在回合數回復生命值。適癒球被敵人觸碰後會消失並返還1點立方能。阿克希亞還可以透過<link=\"30071\"><#FFAE07><u>偵控模組</u></color></link>召喚部分雷屬性光靈主動技能的召喚物。",
  str_skill_desc_33317511 = "消耗1點<link=\"30070\"><#FFAE07><u>立方能</u></color></link>，選擇1個可行走的格子召喚1顆<link=\"30072\"><#FFAE07><u>適癒球</u></color></link>，或者選擇場上存在的適癒球，將其吸收並根據存在回合數回復生命值。適癒球被敵人觸碰後會消失並返還1點立方能。阿克希亞還可以透過<link=\"30071\"><#FFAE07><u>偵控模組</u></color></link>召喚部分雷屬性光靈主動技能的召喚物。",
  str_skill_desc_33617511 = "消耗1點<link=\"30070\"><#FFAE07><u>立方能</u></color></link>，選擇1個可行走的格子召喚1顆<link=\"30073\"><#FFAE07><u>適癒球</u></color></link>，或者選擇場上存在的適癒球，將其吸收並根據存在回合數回復生命值。適癒球被敵人觸碰後會消失並返還1點立方能。阿克希亞還可以透過<link=\"30071\"><#FFAE07><u>偵控模組</u></color></link>召喚部分雷屬性光靈主動技能的召喚物。",
  str_skill_desc_330175111 = "消耗1點<color=#D1970C><b>立方能</b></color>，選擇1顆可行走的格子召喚1個適癒球，適癒球存在<color=#D1970C><b>0/1/2</b></color>回合時，光靈經過後，回復相當於阿克希亞<color=#D1970C><b>40%/100%/200%</b></color>攻擊力的生命值，或者選擇場上存在的適癒球，將其吸收並根據存在回合數回復阿克希亞<color=#D1970C><b>40%/100%/200%</b></color>攻擊力的生命值。適癒球被敵人觸碰後消失並返還1點立方能。",
  str_skill_desc_336175111 = "消耗1點<color=#D1970C><b>立方能</b></color>，選擇1顆可行走的格子召喚1個適癒球，適癒球存在<color=#D1970C><b>0/1/2</b></color>回合時，光靈經過後，回復相當於阿克希亞<color=#D1970C><b>40%/100%/250%</b></color>攻擊力的生命值，或者選擇場上存在的適癒球，將其吸收並根據存在回合數回復阿克希亞<color=#D1970C><b>80%/180%/400%</b></color>攻擊力的生命值。適癒球被敵人觸碰後消失並返還1點立方能。",
  str_skill_passive_name_4101751 = "三次方切換",
  str_skill_passive_desc_4101751 = "隊伍中的雷屬性光靈施放主動技能後，阿克希亞獲得<color=#00F6FF>1</color>層切換轉能。施放連鎖技能後清空所有層數，每層切換轉能對場上生命值最高的敵人造成<color=#00F6FF>{1}</color>的傷害。",
  str_skill_name_2001751 = "天工之援",
  str_skill_name_2001752 = "天工之援",
  str_skill_name_2001753 = "天工之援",
  str_skill_desc_2001751 = "為隊伍恢復等同於阿克希亞<color=#00F6FF>135%</color>攻擊力的生命值。",
  str_skill_desc_2001752 = "為隊伍恢復等同於阿克希亞<color=#00F6FF>160%</color>攻擊力的生命值。",
  str_skill_desc_2001753 = "為隊伍恢復等同於阿克希亞<color=#00F6FF>190%</color>攻擊力的生命值。",
  str_skill_name_29036011 = "蝕毒",
  str_skill_desc_29036011 = "當光靈位於惡面花周圍1圈時，對目標造成大量傷害，並疊加猛毒狀態。",
  str_skill_name_29036012 = "蟲引",
  str_skill_desc_29036012 = "當光靈遠離惡面花時，在場地周圍隨機位置召喚數隻黎精",
  str_skill_name_20006091 = "強化",
  str_skill_desc_20006091 = "靠近惡面花周圍1圈時，可融入其體內，為其提高攻擊力。",
  str_skill_name_200190101 = "提燈靈·共索",
  str_skill_desc_200190101 = "若提燈靈能夠在攻擊時穿越光靈，則造成傷害並與光靈形成鏈索，否則僅對光靈造成傷害並提升自己的行動力。",
  str_skill_name_290340101 = "阿斯摩太·魘汲鏈",
  str_skill_desc_290340101 = "阿斯摩太對範圍內的光靈進行攻擊，擊中後使用魘汲鏈與光靈相連，光靈被魘汲鏈連接時，每移動一格都會受到傷害。若攻擊時光靈已經被魘汲鏈連接，則會提高傷害並吸血。",
  str_skill_name_290341101 = "阿斯摩太·魘汲鏈",
  str_skill_desc_290341101 = "阿斯摩太對範圍內的光靈進行攻擊，擊中後使用魘汲鏈與光靈相連，魘汲鏈斷開時，將對光靈造成大量傷害。若攻擊時光靈已經被魘汲鏈連接，則會提高傷害並吸血。",
  str_skill_name_290340102 = "阿斯摩太·烈物化",
  str_skill_desc_290340102 = "若阿斯摩太無法攻擊到光靈，則使自己行動力提高直至攻擊到光靈為止。",
  str_skill_name_290340201 = "阿斯摩太·焚身貫",
  str_skill_desc_290340201 = "阿斯摩太瞬移至能夠攻擊至光靈但距離光靈最遠的位置，並對光靈進行攻擊。",
