  str_skill_passive_name_4351761 = "絨針基用",
  str_skill_desc_2001761 = "造成2次<color=#00F6FF>60%</color>的傷害，隨機分配到自身<color=#00F6FF>周圍3圈</color>內的敵人身上。每次傷害對目標附加1根<color=#00F6FF>南極光絨針</color>。對同一目標造成多次傷害時，從第2次起每次傷害減半。",
  str_skill_desc_2001762 = "造成3次<color=#00F6FF>80%</color>的傷害，隨機分配到自身<color=#00F6FF>周圍3圈</color>內的敵人身上。每次傷害對目標附加1根<color=#00F6FF>南極光絨針</color>。對同一目標造成多次傷害時，從第2次起每次傷害減半。",
  str_skill_desc_2001763 = "造成4次<color=#00F6FF>100%</color>的傷害，隨機分配到自身<color=#00F6FF>周圍3圈</color>內的敵人身上。每次傷害對目標附加1根<color=#00F6FF>南極光絨針</color>。對同一目標造成多次傷害時，從第2次起每次傷害減半。",
  str_skill_desc_3001761 = "將<color=#00F6FF>周圍2圈</color>所有敵人身上的<color=#00F6FF>南極光絨針</color>拔出，每根絨針對目標造成<color=#00F6FF>80%</color>傷害。",
  str_skill_desc_3021761 = "將<color=#00F6FF>周圍3圈</color>所有敵人身上的<color=#00F6FF>南極光絨針</color>拔出，每根絨針對目標造成<color=#00F6FF>80%</color>傷害。",
  str_skill_desc_3051761 = "將<color=#00F6FF>周圍3圈</color>所有敵人身上的<color=#00F6FF>南極光絨針</color>拔出，每根絨針對目標造成<color=#00F6FF>80%~120%</color>傷害。目標生命值越低傷害係數越高。",
  str_skill_desc_3201761 = "將<color=#00F6FF>周圍2圈</color>所有敵人身上的<color=#00F6FF>南極光絨針</color>拔出，每根絨針對目標造成<color=#00F6FF>80%</color>傷害並恢復等同於本次傷害<color=#00F6FF>10%</color>的生命值。",
  str_skill_desc_3221761 = "將<color=#00F6FF>周圍3圈</color>所有敵人身上的<color=#00F6FF>南極光絨針</color>拔出，每根絨針對目標造成<color=#00F6FF>80%</color>傷害並恢復等同於本次傷害<color=#00F6FF>10%</color>的生命值。",
  str_skill_desc_3251761 = "將<color=#00F6FF>周圍3圈</color>所有敵人身上的<color=#00F6FF>南極光絨針</color>拔出，每根絨針對目標造成<color=#00F6FF>80%~120%</color>傷害並恢復等同於本次傷害<color=#00F6FF>10%</color>的生命值。目標生命值越低傷害係數越高。",
  str_skill_desc_3301761 = "將<color=#00F6FF>周圍2圈</color>所有敵人身上的<color=#00F6FF>南極光絨針</color>拔出，每根絨針對目標造成<color=#00F6FF>80%</color>傷害並恢復等同於本次傷害<color=#00F6FF>10%~15%</color>的生命值。隊伍生命值越低恢復係數越高。",
  str_skill_desc_3321761 = "將<color=#00F6FF>周圍3圈</color>所有敵人身上的<color=#00F6FF>南極光絨針</color>拔出，每根絨針對目標造成<color=#00F6FF>80%</color>傷害並恢復等同於本次傷害<color=#00F6FF>10%~15%</color>的生命值。隊伍生命值越低恢復係數越高。",
  str_skill_desc_3351761 = "將<color=#00F6FF>周圍3圈</color>所有敵人身上的<color=#00F6FF>南極光絨針</color>拔出，每根絨針對目標造成<color=#00F6FF>80%~120%</color>傷害並恢復等同於本次傷害<color=#00F6FF>10%~15%</color>的生命值。目標生命值越低傷害係數越高，隊伍生命值越低恢復係數越高。",
  str_skill_passive_desc_4101761 = "貝爾塔每第<color=#00F6FF>{1}</color>次普通攻擊對目標附加<color=#00F6FF>1</color>根<color=#00F6FF>南極光絨針</color>。",
  str_skill_passive_desc_4151761 = "貝爾塔每第<color=#00F6FF>{1}</color>次普通攻擊對目標附加<color=#00F6FF>1</color>根<color=#00F6FF>南極光絨針</color>。",
  str_skill_passive_desc_4201761 = "貝爾塔每第<color=#00F6FF>{1}</color>次普通攻擊對目標附加<color=#00F6FF>1</color>根<color=#00F6FF>南極光絨針</color>。",
  str_skill_passive_desc_4251761 = "貝爾塔每第<color=#00F6FF>{1}</color>次普通攻擊對目標附加<color=#00F6FF>1</color>根<color=#00F6FF>南極光絨針</color>。",
  str_skill_passive_desc_4301761 = "貝爾塔每第<color=#00F6FF>{1}</color>次普通攻擊對目標附加<color=#00F6FF>1</color>根<color=#00F6FF>南極光絨針</color>。",
  str_skill_passive_desc_4351761 = "貝爾塔每第<color=#00F6FF>{1}</color>次普通攻擊對目標附加<color=#00F6FF>1</color>根<color=#00F6FF>南極光絨針</color>。",
  str_skill_upgrade_desc_15017612 = "主動技強化：技能範圍提升至<color=#FFFF00>周圍3圈</color>。",
  str_skill_upgrade_desc_15017615 = "主動技強化：目標生命值越低傷害係數越高，最高提升<color=#00F6FF>40%</color>傷害係數。",
  str_skill_name_290350103 = "癲蹄·地碎撞",
  str_skill_desc_290350103 = "癲蹄震碎腳下的格子，衝撞並擊退光靈，破壞途徑的碎石。光靈受到撞擊後會獲得疲憊效果",
  str_skill_name_290350104 = "癲蹄·滅破擊",
  str_skill_desc_290350104 = "癲蹄移動後重擊面前2格，造成巨額傷害並震碎格子",
  str_skill_desc_290350203 = "癲蹄震碎腳下的格子，衝撞並擊退光靈，破壞途徑的碎石。",
  str_skill_desc_290350204 = "癲蹄移動後重擊面前2格，造成大量傷害並震碎格子，光靈受到攻擊後會獲得疲憊效果。",
  str_skill_name_216003811 = "機甲震撼術！",
