  str_skill_name_91001641 = "強化",
  str_skill_desc_91001641 = "提高除自己以外所有暗鬼的行動力與攻擊力，效果疊加",
  str_skill_name_290290101 = "貪噬·衝碎",
  str_skill_desc_290290101 = "碾壓相鄰位置的光靈，造成無視防禦的巨額傷害並擊退1格；若光靈相鄰4格都被阻擋，則直接被擊殺。",
  str_skill_desc_290291131 = "碾壓相鄰位置的光靈，將光靈秒殺！",
  str_skill_name_290290104 = "貪噬·裂斷",
  str_skill_desc_290290104 = "若光靈不在相鄰位置，改為朝光靈目前位置移動1格，然後對頭部相鄰1圈範圍造成範圍傷害。",
  str_skill_name_290290100 = "蝕蟲身體",
  str_skill_desc_290290100 = "受到特殊能量保護的蝕蟲身軀，能使所有攻擊無效化。軀體具有自我複製的能力",
  str_skill_name_290290102 = "蝕蟲尾部",
  str_skill_desc_290290102 = "受到的傷害會傳遞給頭部",
