  str_skill_desc_303180 = "將最靠近的<color=#00F6FF>4</color>個水屬性格子轉變為森屬性。若主動技能上回合就緒，本回合轉色數量<color=#00F6FF>+1</color>。",
  str_skill_desc_305180 = "將最靠近的<color=#00F6FF>5</color>個水屬性格子轉變為森屬性。若主動技能上回合就緒，本回合轉色數量<color=#00F6FF>+1</color>。",
  str_skill_desc_3031801 = "將最靠近的<color=#00F6FF>4</color>個水屬性格子轉變為森屬性。若主動技能上回合就緒，本回合轉色數量<color=#00F6FF>+1</color>。",
  str_skill_desc_3051801 = "將最靠近的<color=#00F6FF>5</color>個水屬性格子轉變為森屬性。若主動技能上回合就緒，本回合轉色數量<color=#00F6FF>+1</color>。",
  str_skill_desc_310180 = "將最靠近的<color=#00F6FF>4</color>個水屬性格子轉變為森屬性，隨機對場上半數的敵人附加<color=#00F6FF>監測之記</color>。",
  str_skill_desc_313180 = "將最靠近的<color=#00F6FF>4</color>個水屬性格子轉變為森屬性，隨機對場上半數的敵人附加<color=#00F6FF>監測之記</color>。主動技能上回合就緒，本回合轉色數量<color=#00F6FF>+1</color>。",
  str_skill_desc_315180 = "將最靠近的<color=#00F6FF>5</color>個水屬性格子轉變為森屬性，隨機對場上半數的敵人附加<color=#00F6FF>監測之記</color>。主動技能上回合就緒，本回合轉色數量<color=#00F6FF>+1</color>。",
  str_skill_desc_3131801 = "將最靠近的<color=#00F6FF>4</color>個水屬性格子轉變為森屬性，隨機對場上半數的敵人附加<color=#00F6FF>監測之記</color>。主動技能上回合就緒，本回合轉色數量<color=#00F6FF>+1</color>。",
  str_skill_desc_3151801 = "將最靠近的<color=#00F6FF>5</color>個水屬性格子轉變為森屬性，隨機對場上半數的敵人附加<color=#00F6FF>監測之記</color>。主動技能上回合就緒，本回合轉色數量<color=#00F6FF>+1</color>。",
  str_skill_desc_330180 = "將最靠近的<color=#00F6FF>4</color>個水屬性格子轉變為森屬性，隨機對場上半數的敵人附加<color=#00F6FF>監測之記</color>，然後在最多<color=#00F6FF>3</color>個有監測之記的敵人腳下生成<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>。",
  str_skill_desc_333180 = "將最靠近的<color=#00F6FF>4</color>個水屬性格子轉變為森屬性，隨機對場上半數的敵人附加<color=#00F6FF>監測之記</color>，然後在最多<color=#00F6FF>3</color>個有監測之記的敵人腳下生成<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>。主動技能上回合就緒，本回合轉色數量<color=#00F6FF>+1</color>。",
  str_skill_desc_335180 = "將最靠近的<color=#00F6FF>5</color>個水屬性格子轉變為森屬性，隨機對場上半數的敵人附加<color=#00F6FF>監測之記</color>，然後在最多<color=#00F6FF>3</color>個有監測之記的敵人腳下生成<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>。主動技能上回合就緒，本回合轉色數量<color=#00F6FF>+1</color>。",
  str_skill_desc_3331801 = "將最靠近的<color=#00F6FF>4</color>個水屬性格子轉變為森屬性，隨機對場上半數的敵人附加<color=#00F6FF>監測之記</color>，然後在最多<color=#00F6FF>3</color>個有監測之記的敵人腳下生成<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>。主動技能上回合就緒，本回合轉色數量<color=#00F6FF>+1</color>。",
  str_skill_desc_3351801 = "將最靠近的<color=#00F6FF>5</color>個水屬性格子轉變為森屬性，隨機對場上半數的敵人附加<color=#00F6FF>監測之記</color>，然後在最多<color=#00F6FF>3</color>個有監測之記的敵人腳下生成<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>。主動技能上回合就緒，本回合轉色數量<color=#00F6FF>+1</color>。",
  str_skill_desc_2001801 = "對離自己最近且<color=#00F6FF>體型最小</color>的1個敵人，造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2001802 = "對離自己最近且<color=#00F6FF>體型最小</color>的1個敵人，造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2001803 = "對離自己最近且<color=#00F6FF>體型最小</color>的1個敵人，造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2201801 = "對離自己最近且<color=#00F6FF>體型最小</color>的1個敵人，造成<color=#00F6FF>{1}%</color>的傷害，同時附加<color=#00F6FF>監測之記</color>。",
  str_skill_desc_2201802 = "對離自己最近且<color=#00F6FF>體型最小</color>的1個敵人，造成<color=#00F6FF>{1}%</color>的傷害，同時附加<color=#00F6FF>監測之記</color>。",
  str_skill_desc_2201803 = "對離自己最近且<color=#00F6FF>體型最小</color>的1個敵人，造成<color=#00F6FF>{1}%</color>的傷害，同時附加<color=#00F6FF>監測之記</color>。",
  str_skill_passive_desc_410180 = "主動技能可以對敵人附加<color=#00F6FF>監測之記</color>：受到單體類型連鎖技能的最終傷害提高<color=#00F6FF>{1}</color>，持續到光靈行動結束。",
  str_skill_passive_desc_420180 = "主動技能和連鎖技能可以對敵人附加<color=#00F6FF>監測之記</color>：受到單體類型連鎖技能的最終傷害提高<color=#00F6FF>{1}</color>，持續到光靈行動結束。",
