  str_skill_desc_2001781 = "隨機對場上3個不同敵人造成<color=#00F6FF>100%</color>的傷害。",
  str_skill_desc_2001782 = "隨機對場上3個不同敵人造成<color=#00F6FF>120%</color>的傷害。",
  str_skill_desc_2001783 = "隨機對場上3個不同敵人造成<color=#00F6FF>140%</color>的傷害。",
  str_skill_desc_20017812 = "隨機對場上3個不同敵人造成<color=#00F6FF>100%</color>的傷害。若此次連線為水屬性格子，改為呼喚動物夥伴們攻擊各自的目標，目標可以相同。",
  str_skill_desc_20017822 = "隨機對場上3個不同敵人造成<color=#00F6FF>120%</color>的傷害。若此次連線為水屬性格子，改為呼喚動物夥伴們攻擊各自的目標，目標可以相同。",
  str_skill_desc_20017832 = "隨機對場上3個不同敵人造成<color=#00F6FF>140%</color>的傷害。若此次連線為水屬性格子，改為呼喚動物夥伴們攻擊各自的目標，目標可以相同。",
  str_skill_desc_3001780 = "呼喚三隻神奇動物夥伴，優先對各自目標造成<color=#00F6FF>200%</color>傷害。\n小毛球：狀態標誌最多。\n比卡：生命值最低。\n泥尊鷹：距離最遠。",
  str_skill_passive_name_410178 = "遣與蹤",
  str_skill_passive_name_420178 = "遣與蹤",
  str_skill_passive_name_430178 = "遣與蹤",
  str_skill_passive_name_436178 = "遣與蹤",
  str_skill_passive_desc_410178 = "若此次連線為水屬性格子，普通攻擊替換為：每移動一格，動物夥伴們會對各自的目標進行一次<color=#00F6FF>{1}</color>傷害的攻擊。\n動物夥伴們造成的所有傷害不享有連線加成。",
  str_skill_passive_desc_420178 = "若此次連線為水屬性格子，普通攻擊替換為：每移動一格，動物夥伴們會對各自的目標進行一次<color=#00F6FF>{1}</color>傷害的攻擊。\n動物夥伴們造成的所有傷害不享有連線加成。",
  str_skill_passive_desc_430178 = "若此次連線為水屬性格子，普通攻擊替換為：每移動一格，動物夥伴們會對各自的目標進行一次<color=#00F6FF>{1}</color>傷害的攻擊。\n動物夥伴們造成的所有傷害不享有連線加成，並在目標滿足對應條件後提高<color=#00F6FF>10%</color>的最終傷害。\n小毛球：狀態標誌數至少<color=#00F6FF>4</color>個。\n比卡：目前生命值低於<color=#00F6FF>30%</color>。\n泥尊鷹：間隔至少<color=#00F6FF>4</color>格。",
  str_skill_passive_desc_436178 = "若此次連線為水屬性格子，普通攻擊替換為：每移動一格，動物夥伴們會對各自的目標進行一次<color=#00F6FF>{1}</color>傷害的攻擊。\n動物夥伴們造成的所有傷害不享有連線加成，並在目標滿足對應條件後提高<color=#00F6FF>30%</color>的最終傷害。\n小毛球：狀態標誌數至少<color=#00F6FF>4</color>個。\n比卡：目前生命值低於<color=#00F6FF>30%</color>。\n泥尊鷹：間隔至少<color=#00F6FF>4</color>格。",
  str_skill_upgrade_desc_16017813 = "主動技能強化：主動技能變為<color=#FFFF00>先制攻擊</color>，進入戰鬥即可使用。",
  str_skill_upgrade_desc_16017816 = "裝備技能強化：動物夥伴們造成的所有傷害，在目標滿足對應條件後提高<color=#00F6FF>30%</color>的最終傷害。（覺醒3階段生效）",
