  str_skill_name_3361771 = "最高音域切換",
  str_skill_passive_name_410177 = "至天之韻",
  str_skill_desc_2001771 = "<color=#00F6FF>偶像狀態（5chain）</color>：為隊伍恢復相當於歌爾蒂<color=#00F6FF>140%</color>攻擊力的生命值。\n<color=#00F6FF>戰歌狀態（7chain）</color>：對<color=#00F6FF>全體</color>敵人造成<color=#00F6FF>120%</color>的傷害。",
  str_skill_desc_2001772 = "<color=#00F6FF>偶像狀態（9chain）</color>：為隊伍恢復相當於歌爾蒂<color=#00F6FF>170%</color>攻擊力的生命值。\n<color=#00F6FF>戰歌狀態（11chain）</color>：對<color=#00F6FF>全體</color>敵人造成<color=#00F6FF>150%</color>的傷害。",
  str_skill_desc_2001773 = "<color=#00F6FF>偶像狀態（13chain）</color>：為隊伍恢復相當於歌爾蒂<color=#00F6FF>210%</color>攻擊力的生命值。\n<color=#00F6FF>戰歌狀態（15chain）</color>：對<color=#00F6FF>全體</color>敵人造成<color=#00F6FF>180%</color>的傷害。",
  str_skill_desc_2201771 = "<color=#00F6FF>偶像狀態（5chain）</color>：為隊伍恢復相當於歌爾蒂<color=#00F6FF>140%</color>攻擊力的生命值，並隨機在<color=#00F6FF>1</color>個<color=#00F6FF>非森格子</color>上生成<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>。\n<color=#00F6FF>戰歌狀態（7chain）</color>：對<color=#00F6FF>全體</color>敵人造成<color=#00F6FF>120%</color>的傷害。",
  str_skill_desc_2201772 = "<color=#00F6FF>偶像狀態（9chain）</color>：為隊伍恢復相當於歌爾蒂<color=#00F6FF>170%</color>攻擊力的生命值，並隨機在<color=#00F6FF>2</color>個<color=#00F6FF>非森格子</color>上生成<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>。\n<color=#00F6FF>戰歌狀態（11chain）</color>：對<color=#00F6FF>全體</color>敵人造成<color=#00F6FF>150%</color>的傷害。",
  str_skill_desc_2201773 = "<color=#00F6FF>偶像狀態（13chain）</color>：為隊伍恢復相當於歌爾蒂<color=#00F6FF>210%</color>攻擊力的生命值，並隨機在<color=#00F6FF>3</color>個<color=#00F6FF>非森格子</color>上生成<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>。\n<color=#00F6FF>戰歌狀態（15chain）</color>：對<color=#00F6FF>全體</color>敵人造成<color=#00F6FF>180%</color>的傷害。",
  str_skill_desc_300177 = "本回合從<color=#00F6FF>偶像狀態</color>進入<color=#00F6FF>戰歌狀態</color>，<color=#00F6FF>下一次連線</color>可以穿過敵人所在的格子。\n<color=#00F6FF>偶像狀態</color>：無法進行普通攻擊，連鎖技能恢復生命值。\n<color=#00F6FF>戰歌狀態</color>：能夠進行普通攻擊，連鎖技能對<color=#00F6FF>所有敵人</color>造成傷害但施放條件+2。",
  str_skill_desc_303177 = "隨機在<color=#00F6FF>非森格子</color>上生成<color=#00F6FF>2</color>個<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>，本回合從<color=#00F6FF>偶像狀態</color>進入<color=#00F6FF>戰歌狀態</color>，<color=#00F6FF>下一次連線</color>可以穿過敵人所在的格子。\n<color=#00F6FF>偶像狀態</color>：無法進行普通攻擊，連鎖技能恢復生命值。\n<color=#00F6FF>戰歌狀態</color>：能夠進行普通攻擊，連鎖技能對<color=#00F6FF>所有敵人</color>造成傷害但施放條件+2。",
  str_skill_desc_306177 = "隨機在<color=#00F6FF>非森格子</color>上生成<color=#00F6FF>2</color>個<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>，本回合從<color=#00F6FF>偶像狀態</color>進入<color=#00F6FF>戰歌狀態</color>，<color=#00F6FF>下一次連線</color>可以穿過敵人所在的格子，若主動技能上回合準備就緒，上述效果在極光時刻內也會生效。\n<color=#00F6FF>偶像狀態</color>：無法進行普通攻擊，連鎖技能恢復生命值。\n<color=#00F6FF>戰歌狀態</color>：能夠進行普通攻擊，連鎖技能對<color=#00F6FF>所有敵人</color>造成傷害但施放條件+2。",
  str_skill_desc_3061771 = "隨機在<color=#00F6FF>非森格子</color>上生成<color=#00F6FF>2</color>個<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>，本回合從<color=#00F6FF>偶像狀態</color>進入<color=#00F6FF>戰歌狀態</color>，<color=#00F6FF>下一次連線</color>可以穿過敵人所在的格子，若主動技能上回合準備就緒，上述效果在極光時刻內也會生效。\n<color=#00F6FF>偶像狀態</color>：無法進行普通攻擊，連鎖技能恢復生命值。\n<color=#00F6FF>戰歌狀態</color>：能夠進行普通攻擊，連鎖技能對<color=#00F6FF>所有敵人</color>造成傷害但施放條件+2。",
  str_skill_desc_330177 = "本回合從<color=#00F6FF>偶像狀態</color>進入<color=#00F6FF>戰歌狀態</color>，<color=#00F6FF>下一次連線</color>可以穿過敵人所在的格子，並臨時將所有強化格子視為彩色格子。\n<color=#00F6FF>偶像狀態</color>：無法進行普通攻擊，連鎖技能恢復生命值。\n<color=#00F6FF>戰歌狀態</color>：能夠進行普通攻擊，連鎖技能對<color=#00F6FF>所有敵人</color>造成傷害但施放條件+2。",
  str_skill_desc_333177 = "隨機在<color=#00F6FF>非森格子</color>上生成<color=#00F6FF>2</color>個<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>，本回合從<color=#00F6FF>偶像狀態</color>進入<color=#00F6FF>戰歌狀態</color>，<color=#00F6FF>下一次連線</color>可以穿過敵人所在的格子，並臨時將所有強化格子視為彩色格子。\n<color=#00F6FF>偶像狀態</color>：無法進行普通攻擊，連鎖技能恢復生命值。\n<color=#00F6FF>戰歌狀態</color>：能夠進行普通攻擊，連鎖技能對<color=#00F6FF>所有敵人</color>造成傷害但施放條件+2。",
  str_skill_desc_336177 = "隨機在<color=#00F6FF>非森格子</color>上生成<color=#00F6FF>2</color>個<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>，本回合從<color=#00F6FF>偶像狀態</color>進入<color=#00F6FF>戰歌狀態</color>，<color=#00F6FF>下一次連線</color>可以穿過敵人所在的格子，並臨時將所有強化格子視為彩色格子，若主動技能上回合準備就緒，上述效果在極光時刻內也生效。\n<color=#00F6FF>偶像狀態</color>：無法進行普通攻擊，連鎖技能恢復生命值。\n<color=#00F6FF>戰歌狀態</color>：能夠進行普通攻擊，連鎖技能對<color=#00F6FF>所有敵人</color>造成傷害但施放條件+2。",
  str_skill_desc_3361771 = "隨機在<color=#00F6FF>非森格子</color>上生成<color=#00F6FF>2</color>個<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>，本回合從<color=#00F6FF>偶像狀態</color>進入<color=#00F6FF>戰歌狀態</color>，<color=#00F6FF>下一次連線</color>可以穿過敵人所在的格子，並臨時將所有強化格子視為彩色格子，若主動技能上回合準備就緒，上述效果在極光時刻內也生效。\n<color=#00F6FF>偶像狀態</color>：無法進行普通攻擊，連鎖技能恢復生命值。\n<color=#00F6FF>戰歌狀態</color>：能夠進行普通攻擊，連鎖技能對<color=#00F6FF>所有敵人</color>造成傷害但施放條件+2。",
  str_skill_passive_desc_410177 = "隊伍每獲得（包括<link=\"30065\"><#FFAE07><u>吸收</u></color></link>）<color=#00F6FF>{1}</color>個<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>，在距離最近的1個<color=#00F6FF>非森格子</color>上生成1個強化格子。",
  str_skill_upgrade_desc_16017713 = "主動技能強化強化：主動技能變為<color=#FFFF00>先制攻擊</color>，進入戰鬥即可使用。隨機在<color=#00F6FF>非森格子</color>上生成<color=#00F6FF>2</color>個<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>。",
  str_skill_upgrade_desc_16017716 = "主動技能強化：技能冷卻回合<color=#FFFF00>-1</color>。若主動技能上回合準備就緒，戰歌狀態下，<color=#00F6FF>極光時刻</color>內也可連線穿過敵人所在格子，並將<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>視為彩色格子。（覺醒3階段生效）",
  str_skill_desc_290420101 = "向光靈移動後，揮動前臂對前方兩格內的敵人造成傷害。",
  str_skill_desc_290420102 = "對全畫面範圍內的敵人造成傷害。",
  str_skill_name_200200101 = "蝳毒膜球",
  str_skill_desc_200200101 = "對範圍內的目標噴吐膜球造成傷害。膜球會濺射十字四格，對濺射範圍內的敵我目標附加中毒狀態。",
  str_skill_name_200210001 = "朦剎·襲刺",
  str_skill_desc_200210001 = "當朦垢倒數計時結束後，潛藏在其中的朦剎將會跳出來攻擊光靈，隨後重新潛入朦垢之中。",
  str_skill_name_200210101 = "朦剎·襲刺",
  str_skill_desc_200210101 = "當朦垢倒數計時結束後，潛藏在其中的朦剎將會跳出來攻擊光靈，隨後重新潛入朦垢之中。",
  str_skill_name_200210102 = "朦剎·襲刺",
  str_skill_desc_200210102 = "當朦垢倒數計時結束後，潛藏在其中的朦剎將會跳出來攻擊光靈，隨後重新潛入朦垢之中。",
  str_skill_name_290400101 = "博怒·力擊",
  str_skill_desc_290400101 = "博怒格爾登揮舞武器對攻擊範圍內的目標造成傷害。",
  str_skill_name_290400102 = "博怒·躍轟",
  str_skill_desc_290400102 = "博怒格爾登向著目標躍進，落地時重錘地面，對周圍一圈的目標造成大量傷害。",
  str_skill_name_290400103 = "博怒·怖爆",
  str_skill_desc_290400103 = "憤怒的博怒格爾登釋放強力的技能，對全畫面範圍內的目標造成傷害。",
  str_skill_name_5220012 = "療治溶膠",
  str_skill_desc_5220012 = "回復隊伍<color=#00F6FF>20%</color>最大生命值。",
  str_skill_name_5220013 = "軌跡分儀",
  str_skill_desc_5220013 = "啟動裝置，傳送至場上一個可行走的格子。",
  str_skill_name_290430101 = "戒衛·風凜",
  str_skill_desc_290430101 = "戒衛座透過連線自身與同場另一位傳說光靈的雙屬性格子移動，靠近目標並進行8方向普通攻擊，連線結束後對周圍1圈造成傷害。",
  str_skill_name_290440101 = "鎮魂·聖槍",
  str_skill_desc_290440101 = "鎮魂座透過連線自身與同場另一位傳說光靈的雙屬性格子移動，靠近目標並進行4方向普通攻擊，連線結束後對周圍1圈造成傷害。每普通攻擊3次，額外造成目標最大生命百分比的傷害。",
  str_skill_name_290450101 = "焚霜·隕絕",
  str_skill_desc_290450101 = "焚霜座透過連線自身與同場另一位傳說光靈的雙屬性格子朝遠離目標的位置移動，移動結束後對全畫面範圍內的目標造成傷害。",
  str_skill_name_290460101 = "童謠·崢嶸",
  str_skill_desc_290460101 = "童謠座透過連線自身與同場另一位傳說光靈的雙屬性格子朝遠離目標的位置移動，移動結束後對全畫面範圍內的目標造成傷害。",
  str_skill_name_2801101 = "指揮標記",
  str_skill_desc_2801101 = "光靈經過時收取，可增加玩家切換隊長的次數。",
  str_skill_name_5000881 = "利刃",
  str_skill_desc_5000881 = "光靈經過時收取，可提升光靈攻擊力",
  str_skill_name_5000891 = "護盾",
  str_skill_desc_5000891 = "光靈經過時收取，可提升光靈防禦力",
  str_skill_name_2002101 = "劍增益",
  str_skill_desc_2002101 = "拾取後進入沉默狀態，但攻擊力大幅提升",
  str_skill_desc_2002201 = "拾取後連鎖技能傷害增加8%",
  str_skill_upgrade_desc_15018312 = "主動技能強化：主動技能變為<color=#FFFF00>先制攻擊</color>，進入戰鬥即可使用。",
  str_skill_upgrade_desc_15018315 = "主動技能強化：效果重複執行次數變為<color=#00F6FF>2~5次</color>。（覺醒3階段生效）",
  str_skill_name_3001831 = "命懸苦",
  str_skill_name_3051831 = "命懸苦",
  str_skill_name_3201831 = "命懸苦",
  str_skill_name_3251831 = "命懸苦",
  str_skill_desc_3001831 = "任選1名敵人，使其在怪物回合開始前生命值<color=#00F6FF>強制不低於1點</color>。目標敵人隨機獲得1種效果：受到我方<color=#00F6FF>普通攻擊/連鎖技能/主動技能</color>的最終傷害提高<color=#00F6FF>5%/5%/7%</color>。",
  str_skill_desc_3201831 = "任選1名敵人，使其在怪物回合開始前生命值<color=#00F6FF>強制不低於1點</color>。目標敵人隨機獲得1種效果：受到我方<color=#00F6FF>普通攻擊/連鎖技能/主動技能</color>的最終傷害提高<color=#00F6FF>5%/5%/7%</color>，此效果重複執行<color=#00F6FF>1~3次</color>。",
  str_skill_desc_3251831 = "任選1名敵人，使其在怪物回合開始前生命值<color=#00F6FF>強制不低於1點</color>。目標敵人隨機獲得1種效果：受到我方<color=#00F6FF>普通攻擊/連鎖技能/主動技能</color>的最終傷害提高<color=#00F6FF>5%/5%/7%</color>，此效果重複執行<color=#00F6FF>2~5次</color>。",
  str_skill_name_2001831 = "萬應散",
  str_skill_name_2001832 = "萬應散",
  str_skill_name_2001833 = "萬應散",
  str_skill_desc_2001831 = "為隊伍回復相當於厘青<color=#00F6FF>155%</color>攻擊力的生命值。",
  str_skill_desc_2001832 = "為隊伍回復相當於厘青<color=#00F6FF>190%</color>攻擊力的生命值。",
  str_skill_desc_2001833 = "為隊伍回復相當於厘青<color=#00F6FF>225%</color>攻擊力的生命值。",
  str_skill_passive_desc_410183 = "厘青的普通攻擊不再直接造成傷害，改為對目標施加1層砂灸，回合結束時引爆，每層砂灸造成<color=#00F6FF>{1}</color>的傷害。砂灸持續<color=#00F6FF>2回合</color>並且每層單獨結算。",
  str_skill_passive_desc_430183 = "厘青的普通攻擊不再直接造成傷害，改為對目標施加1層砂灸，回合結束時引爆，每層砂灸造成<color=#00F6FF>{1}</color>的傷害，並且目標身上每層砂灸還會提高<color=#00F6FF>3%</color>的最終傷害。砂灸持續<color=#00F6FF>2回合</color>並且每層單獨結算。",
