  str_skill_desc_2001821 = "對<color=#00F6FF>周圍1圈</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2001822 = "若第1盞「淨龍輝」已亮，則判斷施放<color=#00F6FF>前一階</color>連鎖技能，否則使第1盞「淨龍輝」亮起，跳向<color=#00F6FF>菱形12格</color>範圍內最近且生命值最高的敵人，對<color=#00F6FF>方形9格</color>造成<color=#00F6FF>180%</color>的傷害。",
  str_skill_desc_2001823 = "若第2盞「淨龍輝」已亮，則判斷施放<color=#00F6FF>前一階</color>連鎖技能，否則使第2盞「淨龍輝」亮起，跳向<color=#00F6FF>菱形12格</color>範圍內最近且生命值最高的敵人，對<color=#00F6FF>菱形13格</color>造成<color=#00F6FF>180%</color>的傷害。",
  str_skill_desc_2001824 = "若第3盞「淨龍輝」已亮，則判斷施放<color=#00F6FF>前一階</color>連鎖技能，否則使第3盞「淨龍輝」亮起，跳向<color=#00F6FF>菱形12格</color>範圍內最近且生命值最高的敵人，對<color=#00F6FF>米字形17格</color>造成<color=#00F6FF>180%</color>的傷害。",
