  str_skill_desc_2061823 = "若第2盞「淨龍輝」已亮，則判斷施放<color=#00F6FF>前一階</color>連鎖技能，否則使第2盞「淨龍輝」亮起，跳向<color=#00F6FF>菱形12格</color>範圍內最近且生命值最高的敵人，對<color=#00F6FF>米字形17格</color>造成<color=#00F6FF>180%</color>的傷害。極光時刻期間施放條件減少至<color=#00F6FF>3</color>。",
