  str_skill_desc_3001821 = "<color=#00F6FF>3</color>盞<link=\"30074\"><#FFAE07><u>「淨龍輝」</u></color></link>亮起後主動技能就緒，選擇1個格子，對<color=#00F6FF>方形9格</color>造成<color=#00F6FF>300%</color>的傷害。施放後所有「淨龍輝」熄滅。",
