  str_skill_passive_desc_430182 = "主動技能發動時對<color=#00F6FF>全體</color>敵人造成<color=#00F6FF>{1}</color>的傷害。",
  str_skill_passive_desc_433182 = "主動技能發動時對<color=#00F6FF>全體</color>敵人造成<color=#00F6FF>{1}</color>的傷害。",
  str_skill_upgrade_desc_16018213 = "連鎖技能強化：極光時刻期間連鎖技能施放條件<color=#00F6FF>-6</color>。",
  str_skill_upgrade_desc_16018216 = "連鎖技能強化：<color=#00F6FF>2|3|4</color>階連鎖技能傷害範圍擴大至<color=#00F6FF>菱形13格|米字形17格|方形25格</color>。",
  str_skill_name_29041011 = "困",
  str_skill_desc_29041011 = "尤將要施放強大的幻術，將光靈拖入幻術空間。\n期間召喚若干固定軌道的子彈在場中飛行，玩家碰到後受到大量傷害。\n同時玩家可任意移動5次，每次移動僅限1格。",
  str_skill_name_29041012 = "束",
  str_skill_desc_29041012 = "當場上存在子彈時，尤會控制場上所有子彈飛向光靈，並造成傷害。\n當場上不存在子彈時，尤會分身並隱匿其中，一旦受到傷害，真假便知。",
  str_skill_name_29041013 = "實者之虛",
  str_skill_desc_29041013 = "當場上存在子彈時，尤會控制場上所有子彈飛向光靈，並造成傷害。\n當場上不存在子彈時，尤會分身並隱匿其中，一旦受到傷害，真假便知。",
  str_skill_name_29041014 = "言",
  str_skill_desc_29041014 = "移動後，尤及其分身會對其前方直線範圍內目標造成傷害。之後在原地留下一枚子彈。",
  str_skill_name_29041015 = "散",
  str_skill_desc_29041015 = "尤及其分身對全畫面範圍內目標造成傷害。",
  str_skill_name_20022013 = "撞擊",
  str_skill_desc_20022013 = "「文」將會對前方預警範圍內目標造成大量傷害。",
  str_skill_name_20022022 = "束",
  str_skill_desc_20022022 = "非幻境期間，尤會操控「字」作為子彈直接命中光靈。（光靈可在此期間消滅子彈以避免傷害）",
  str_skill_name_490310106 = "厄孽·甜心之吻",
  str_skill_desc_490310106 = "厄孽·芭芭拉造成除部分安全區外的大範圍傷害，並擊碎安全區以外的火屬性格子。",
  str_skill_name_490310107 = "厄孽·終音耀斑天引",
  str_skill_desc_490310107 = "厄孽·芭芭拉在場地中心召喚夥伴，對全畫面範圍目標造成傷害與擊退。",
  str_skill_desc_490023202 = "樊尼驅動能量對位於攻擊範圍的目標進行遠程攻擊，命中時還將使目標疲憊。",
  str_skill_desc_490023212 = "樊尼驅動能量對位於攻擊範圍的目標進行遠程攻擊，命中時還將使目標致盲。",
  str_skill_desc_480043414 = "瑪拉索爾召喚多隻爆裂進入戰場，爆裂的數量由瑪拉索爾在第一波次中累積的「爆裂行進」層數決定。",
  str_skill_desc_400012401 = "每回合召喚爆裂進入戰場。",
  str_skill_upgrade_desc_16018113 = "裝備技能強化：進入戰鬥時獲得5洞悉點，每波次開始時獲得<color=#00F6FF>5</color>洞悉點。",
  str_skill_upgrade_desc_16018116 = "裝備技能強化：獲得洞悉點的條件變為仲胥經過<color=#00F6FF>任意屬性的格子</color>。",
  str_skill_name_2001811 = "無情烈",
