  str_skill_name_330181123 = "長殷戰策",
  str_skill_desc_3001811 = "任選<color=#00F6FF>1</color>格召喚仲火，並轉為火屬性格子。仲火可以召喚在敵人腳下並跟隨該目標位移。<color=#00F6FF>連線移動之前</color>，仲火途徑的所有格子<color=#00F6FF>轉變為火屬性</color>。附著於敵人的仲火將在隊伍<color=#00F6FF>連線移動後</color>消失。",
