  str_skill_passive_desc_426181 = "獲得新主動技能：消耗<color=#00F6FF>{1}</color><link=\"30077\"><#FFAE07><u>洞悉點</u></color></link>，令1名<color=#00F6FF>非首領敵人</color>強制位移1格。回合內多次施放時，消耗的洞悉點遞增<color=#00F6FF>{1}</color>點。仲胥每經過1個<color=#00F6FF>格子</color>獲得1洞悉點。",
  str_skill_passive_desc_430181 = "獲得新主動技能：消耗<color=#00F6FF>{1}</color><link=\"30075\"><#FFAE07><u>洞悉點</u></color></link>，令1名<color=#00F6FF>非首領敵人</color>強制位移1格，或消耗8洞悉點<color=#00F6FF>移動仲火</color>1格。回合內多次施放時，移動<color=#00F6FF>敵人/仲火</color>消耗的洞悉點遞增<color=#00F6FF>{1}/8</color>點。仲胥每經過1個<color=#00F6FF>火屬性格子</color>獲得1洞悉點。",
  str_skill_passive_desc_433181 = "獲得新主動技能：消耗<color=#00F6FF>{1}</color><link=\"30076\"><#FFAE07><u>洞悉點</u></color></link>，令1名<color=#00F6FF>非首領敵人</color>強制位移1格，或消耗8洞悉點<color=#00F6FF>移動仲火</color>1格。回合內多次施放時，移動<color=#00F6FF>敵人/仲火</color>消耗的洞悉點遞增<color=#00F6FF>{1}/8</color>點。仲胥每經過1個<color=#00F6FF>火屬性格子</color>獲得1洞悉點。",
  str_skill_passive_desc_436181 = "獲得新主動技能：消耗<color=#00F6FF>{1}</color><link=\"30077\"><#FFAE07><u>洞悉點</u></color></link>，令1名<color=#00F6FF>非首領敵人</color>強制位移1格，或消耗8洞悉點<color=#00F6FF>移動仲火</color>1格。回合內多次施放時，移動<color=#00F6FF>敵人/仲火</color>消耗的洞悉點遞增<color=#00F6FF>{1}/8</color>點。仲胥每經過1個<color=#00F6FF>格子</color>獲得1洞悉點。",
  str_skill_desc_15011312 = "將場上所有單格非首領的敵人朝右擊退1格，並對場上全體敵人造成傷害。",
  str_skill_desc_15011313 = "將場上所有單格非首領的敵人朝上擊退1格，並對場上全體敵人造成傷害。",
  str_skill_desc_15011314 = "將場上所有單格非首領的敵人朝左擊退1格，並對場上全體敵人造成傷害。",
  str_skill_desc_15011315 = "將場上所有單格非首領的敵人朝下擊退1格，並對場上全體敵人造成傷害。",
  str_skill_desc_14008112 = "對全體敵人造成傷害，並牽引到自身周圍。",
  str_skill_desc_15001812 = "製造太陽風爆炸，對全體敵人造成傷害，並以自身為中心將命中的敵人向四周擊退。",
  str_skill_name_200230101 = "仄助強癒",
  str_skill_desc_200230101 = "仄助為2圈範圍內的其他暗鬼回復生命值。其他暗鬼在仄助技能範圍內佔據的格子愈多，受到的回復效果愈強。",
  str_skill_desc_29048011 = "從目標所在位置的地下鑽出，擊退目標並造成傷害。",
  str_skill_upgrade_desc_16018413 = "主動技能強化：主動技能變為<color=#FFFF00>先制攻擊</color>，進入戰鬥即可使用。初始點選範圍變為周圍2圈。",
  str_skill_upgrade_desc_16018416 = "解鎖<color=#FFFF00>新主動技能</color>：極光時刻下使用，瞬移至周圍1圈內的指定位置。",
  str_skill_name_2001841 = "鶴羽蟒銳",
  str_skill_name_2001842 = "鶴羽蟒銳",
  str_skill_name_2001843 = "鶴羽蟒銳",
  str_skill_desc_2001841 = "對<color=#00F6FF>菱形12格</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2001842 = "對<color=#00F6FF>米字形16格</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2001843 = "對<color=#00F6FF>周圍2圈</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_name_2201841 = "鶴羽蟒銳",
  str_skill_name_2201842 = "鶴羽蟒銳",
  str_skill_name_2201843 = "鶴羽蟒銳",
  str_skill_desc_2201841 = "對<color=#00F6FF>菱形12格</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2201842 = "對<color=#00F6FF>米字形16格</color>造成<color=#00F6FF>{1}%</color>的傷害，在範圍內隨機<color=#00F6FF>1</color>個格子上生成<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>。",
  str_skill_desc_2201843 = "對<color=#00F6FF>周圍2圈</color>造成<color=#00F6FF>{1}%</color>的傷害，在範圍內隨機<color=#00F6FF>2</color>個格子上生成<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>。",
  str_skill_name_300184 = "幻惑絕塵",
  str_skill_name_303184 = "幻惑絕塵",
  str_skill_desc_300184 = "瞬移至<color=#00F6FF>菱形12格</color>內的指定位置。只要落點為<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>，即可在<color=#00F6FF>菱形12格</color>內再次選擇落點。吸收所有經過的強化格子，每次吸收時還會對周圍菱形12格造成<color=#00F6FF>100%</color>的傷害。",
  str_skill_desc_303184 = "瞬移至<color=#00F6FF>周圍2圈</color>內的指定位置。只要落點為<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>，即可在<color=#00F6FF>菱形12格</color>內再次選擇落點。吸收所有經過的強化格子，每次吸收時還會對周圍菱形12格造成<color=#00F6FF>100%</color>的傷害。",
  str_skill_name_306184 = "疾幻絕塵",
  str_skill_desc_306184 = "極光時刻下使用：瞬移至<color=#00F6FF>周圍1圈</color>內的指定位置。",
  str_skill_passive_name_410184 = "言絕之祕",
  str_skill_passive_name_430184 = "言絕之祕",
  str_skill_passive_desc_410184 = "每當隊伍透過主動技能位移後，對周圍<color=#00F6FF>菱形12格</color>造成<color=#00F6FF>{1}</color>的傷害。每吸收1個強化格子，提高下一次<color=#00F6FF>{2}</color>的最終傷害。",
  str_skill_passive_desc_430184 = "每當隊伍透過主動技能位移後，對周圍<color=#00F6FF>菱形12格</color>造成<color=#00F6FF>{1}</color>的傷害，並在範圍內隨機生成1個<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>。每吸收1個強化格子，提高下一次<color=#00F6FF>{2}</color>的最終傷害。",
  str_skill_name_280061101 = "布洛克·砲台",
  str_skill_desc_280061101 = "發射空投，選擇一個可行走的格子，在該格子上召喚<color=#00F6FF>砲台機關</color>。",
  str_skill_name_280061102 = "布洛克·牽引",
  str_skill_desc_280061102 = "發射空投，選擇一個可行走的格子並於上召喚<color=#00F6FF>牽引機</color>。",
  str_skill_name_280061103 = "布洛克·火焰",
  str_skill_desc_280061103 = "發射空投，選擇一個可行走的格子，在該格子上召喚<color=#00F6FF>火焰機關</color>。",
  str_skill_name_280061104 = "布洛克·銷毀",
  str_skill_desc_280061104 = "選擇一個布洛克8號召喚的機關，將其銷毀。",
  str_skill_name_280061105 = "布洛克·急修",
  str_skill_desc_280061105 = "緊急修復！回復布洛克8號3格生命值。",
  str_skill_desc_140127101 = "最多選擇4個格子（可以選擇深淵格子）放置紙鶴，同時將該格子轉為彩色。隊伍經過紙鶴時，紙鶴消失。",
