  str_skill_desc_2001851 = "對最靠近的2個敵人造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2001852 = "對最靠近的3個敵人造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2001853 = "對最靠近的4個敵人造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_3001851 = "瞬移到<color=#00F6FF>十字形12格</color>內的任意位置。",
  str_skill_desc_3001852 = "累積<color=#00F6FF>8</color>層青影之力後解鎖：任選1名敵人，瞬移到目標<color=#00F6FF>周圍1圈</color>內最近的位置。",
  str_skill_desc_3361852 = "累積<color=#00F6FF>5</color>層青影之力後解鎖：任選1名敵人，瞬移到目標<color=#00F6FF>周圍1圈</color>內最近的位置。",
  str_skill_passive_desc_410185 = "每當隊伍透過主動技能位移後，對<color=#00F6FF>周圍1圈</color>生命值最低的敵人造成<color=#00F6FF>{1}</color>的傷害。",
  str_skill_passive_desc_416185 = "每當隊伍透過主動技能位移後，對<color=#00F6FF>周圍1圈</color>生命值最低的敵人造成<color=#00F6FF>{1}</color>的傷害，並獲得<color=#00F6FF>1</color>層青影之力。每層青影之力增加<color=#00F6FF>5%</color>傷害率。",
  str_skill_passive_desc_420185 = "每當隊伍透過主動技能位移後，對<color=#00F6FF>周圍1圈</color>生命值最低的敵人造成<color=#00F6FF>{1}</color>的傷害。凱雅的主動技能啟動本效果時最終傷害提高<color=#00F6FF>60%</color>。",
  str_skill_passive_desc_426185 = "每當隊伍透過主動技能位移後，對<color=#00F6FF>周圍1圈</color>生命值最低的敵人造成<color=#00F6FF>{1}</color>的傷害，並獲得<color=#00F6FF>1</color>層青影之力。凱雅的主動技能啟動本效果時最終傷害提高<color=#00F6FF>60%</color>。每層青影之力增加<color=#00F6FF>5%</color>傷害率。",
  str_skill_passive_desc_430185 = "每當隊伍透過主動技能位移後，對<color=#00F6FF>周圍1圈</color>生命值最低的敵人造成<color=#00F6FF>{1}</color>的傷害，並獲得<color=#00F6FF>1</color>層青影之力。凱雅的主動技能啟動本效果時最終傷害提高<color=#00F6FF>60%</color>。",
  str_skill_passive_desc_432185 = "每當隊伍透過主動技能位移後，對<color=#00F6FF>周圍1圈</color>生命值最低的敵人造成<color=#00F6FF>{1}</color>的傷害，並獲得<color=#00F6FF>1</color>層青影之力。凱雅的主動技能啟動本效果時最終傷害提高<color=#00F6FF>60%</color>。",
  str_skill_passive_desc_436185 = "每當隊伍透過主動技能位移後，對<color=#00F6FF>周圍1圈</color>生命值最低的敵人造成<color=#00F6FF>{1}</color>的傷害，並獲得<color=#00F6FF>1</color>層青影之力。凱雅的主動技能啟動本效果時最終傷害提高<color=#00F6FF>60%</color>。每層青影之力增加<color=#00F6FF>5%</color>傷害率。",
  str_skill_upgrade_desc_15018512 = "主動技能強化：解鎖青影瞬至所需層數降至<color=#00F6FF>5</color>。（覺醒3階段生效）",
  str_skill_upgrade_desc_15018515 = "裝備技能強化：每觸發一次裝備技能，獲得<color=#00F6FF>1</color>層青影之力，每層增加凱雅裝備技能<color=#00F6FF>5%</color>傷害率。",
  str_skill_name_28005016 = "牽引機",
  str_skill_desc_28005016 = "將前方小範圍內的暗鬼往牽引機所在方位牽引1格，每個暗鬼每回合僅限被牽引機牽引一次。",
  str_skill_name_400054101 = "力拔",
  str_skill_desc_400054101 = "對範圍內目標造成傷害，同時擊碎範圍內所有格子，摧毀範圍內所有布洛克8號召喚的機關。",
  str_skill_desc_5410100 = "使用長槍對位於攻擊範圍內的暗鬼進行攻擊。",
  str_skill_desc_888426101 = "玩家連續3次施放主動技能後，召喚1個白夜城長槍兵進入戰場。",
  str_skill_desc_4100002 = "每回合召喚火屬性雙刀進入戰場，當場上火屬性雙刀數量達到4隻時，則不再召喚。",
  str_skill_desc_4100004 = "每回合召喚雷屬性雙刀進入戰場，當場上雷屬性雙刀數量達到4隻時，則不再召喚。",
  str_skill_desc_4100005 = "每回合召喚鳴灼進入戰場，當場上鳴灼數量達到2隻時，則不再召喚。",
  str_skill_desc_4100006 = "每回合召喚鳴灼進入戰場，當場上存在鳴灼時，則不再召喚。",
  str_skill_desc_5401005 = "鳴灼在魔械兵附近隨機位置召喚火雨，造成屬性傷害並使目標進入灼燒狀態。",
  str_skill_name_290470111 = "鐐裁機鎧·轟殺",
  str_skill_desc_290470111 = "利用巨錘引導暗能，對全畫面範圍的目標造成巨額傷害。如果光靈處於衛域範圍內，本次攻擊會將光靈生命值強制扣至1點。",
  str_skill_name_290470121 = "鐐裁機鎧·追獵",
  str_skill_desc_290470121 = "若目標處於衛域範圍內，移動至目標身邊造成近戰傷害。若目標處於衛域範圍外，將位於同一行列的目標鉤至身邊。",
  str_skill_desc_290470122 = "若目標處於衛域範圍內，移動至目標身邊造成近戰傷害。若目標處於衛域範圍外，將位於同一行列的目標鉤至身邊。",
  str_skill_name_290470131 = "鐐裁機鎧·震逐",
  str_skill_desc_290470131 = "揮動巨錘發出擾動能量，造成全畫面範圍傷害。如果玩家處於衛域範圍內，則會被能量彈射擊退至場景邊緣。",
  str_skill_name_290490101 = "四騎士·輪戰",
  str_skill_desc_290490101 = "位移至離目標最近的四騎士的對角格上（如果離目標最近的是自己，則會原地位移），隨後攻擊周圍1圈範圍內的目標。",
  str_skill_desc_290490103 = "位移至離目標最近的四騎士所在格子的對角格上（如果離目標最近的是自己，則會原地位移），隨後攻擊周圍1圈範圍內的目標，並為光靈附加易傷，每層易傷降低光靈2%防禦力。",
  str_skill_desc_290490107 = "攻擊周圍1圈範圍內的目標。",
  str_skill_name_290490102 = "四騎士·閃擊",
  str_skill_desc_290490102 = "和其他四騎士分散位移至地圖邊緣，隨後對目標發動攻擊。",
  str_skill_desc_290490108 = "原地攻擊目標。",
  str_skill_name_290550101 = "魔犬哈提．藍炎",
  str_skill_desc_290550101 = "魔犬哈提損失15%現有生命值，位移至菱形12格內距離敵方目標最近的位置，隨後對周圍1圈內的敵方目標造成傷害，若命中目標，則回復15%已損失的生命值。",
  str_skill_name_290550111 = "魔犬哈提．藍炎+",
  str_skill_desc_290550111 = "魔犬哈提損失15%現有生命值，位移至周圍2圈內距離敵方目標最近的位置，隨後對周圍1圈內的敵方目標造成傷害，若命中目標，則回復15%已損失的生命值。",
  str_skill_name_290550121 = "魔犬哈提．藍炎++",
  str_skill_desc_290550121 = "魔犬哈提損失15%現有生命值，位移至周圍2圈內距離敵方目標最近的位置，隨後對周圍2圈內的敵方目標造成傷害，若命中目標，則回復15%已損失的生命值。",
  str_skill_name_290550102 = "魔犬哈提．幽焰",
