  str_skill_name_3331892 = "過熱戰技",
  str_skill_desc_3001890 = "從自身周圍<color=#00F6FF>十字4格</color>中選擇1格，對該方向<color=#00F6FF>扇形2排</color>造成<color=#00F6FF>100%</color>的傷害。",
  str_skill_desc_3001891 = "從自身周圍<color=#00F6FF>十字4格</color>中選擇1格，對該方向<color=#00F6FF>扇形2排</color>造成<color=#00F6FF>100%</color>的傷害。熱值會提高傷害範圍和傷害率，最多對<color=#00F6FF>扇形7排</color>造成<color=#00F6FF>400%</color>的傷害。技能施放完畢後清空熱值。",
  str_skill_desc_3001892 = "從自身周圍<color=#00F6FF>十字4格</color>中選擇1格，對該方向<color=#00F6FF>扇形2排</color>造成<color=#00F6FF>100%</color>的傷害。熱值會提高傷害範圍和傷害率，最多對<color=#00F6FF>扇形7排</color>造成<color=#00F6FF>400%</color>的傷害。技能施放完畢後清空熱值。",
  str_skill_desc_3061891 = "從自身周圍<color=#00F6FF>十字4格</color>中選擇1格，對該方向<color=#00F6FF>扇形2排</color>造成<color=#00F6FF>100%</color>的傷害。熱值會提高傷害範圍和傷害率，最多對<color=#00F6FF>扇形7排</color>造成<color=#00F6FF>400%</color>的傷害。技能施放完畢後清空熱值。若選擇自身所在格，不造成傷害，改為增加<color=#00F6FF>35</color>點熱值。",
  str_skill_desc_3061892 = "從自身周圍<color=#00F6FF>十字4格</color>中選擇1格，對該方向<color=#00F6FF>扇形2排</color>造成<color=#00F6FF>100%</color>的傷害。熱值會提高傷害範圍和傷害率，最多對<color=#00F6FF>扇形7排</color>造成<color=#00F6FF>400%</color>的傷害。技能施放完畢後清空熱值。若選擇自身所在格，不造成傷害，改為增加<color=#00F6FF>35</color>點熱值。",
  str_skill_desc_3301892 = "本回合過熱狀態下仍可以普通攻擊，回合結束後清空熱值。",
  str_skill_desc_3331892 = "將熱值提升至<color=#00F6FF>100</color>，本回合過熱狀態下仍可以普通攻擊，回合結束後清空熱值。",
