  str_skill_desc_2001901 = "對<color=#00F6FF>周圍2圈</color>內最近的2個敵人造成<color=#00F6FF>140%</color>的傷害。",
  str_skill_desc_2001902 = "對<color=#00F6FF>周圍2圈</color>內最近的2個敵人造成<color=#00F6FF>155%</color>的傷害。",
  str_skill_desc_2001903 = "對<color=#00F6FF>周圍2圈</color>內最近的2個敵人造成<color=#00F6FF>160%</color>的傷害。",
  str_skill_desc_2001933 = "對<color=#00F6FF>周圍2圈</color>內最近的2個敵人造成<color=#00F6FF>160%</color>的傷害。每當火屬性光靈施放主動技能後觸發條件<color=#00F6FF>+1</color>，同時命中目標+1或範圍擴大<color=#00F6FF>1</color>圈。",
  str_skill_desc_3001901 = "將最靠近的<color=#00F6FF>4</color>個森屬性格子轉變為火屬性。",
  str_skill_desc_3001902 = "將最靠近的<color=#00F6FF>4</color>個森屬性格子轉變為火屬性。若主動技能上回合就緒，本回合轉色數量<color=#00F6FF>+1</color>。",
  str_skill_desc_3001903 = "將最靠近的<color=#00F6FF>5</color>個森屬性格子轉變為火屬性。若主動技能上回合就緒，本回合轉色數量<color=#00F6FF>+1</color>。",
  str_skill_desc_3021901 = "將最靠近的<color=#00F6FF>4</color>個森屬性格子轉變為火屬性。若主動技能上回合就緒，本回合轉色數量<color=#00F6FF>+1</color>。",
  str_skill_desc_3051901 = "將最靠近的<color=#00F6FF>5</color>個森屬性格子轉變為火屬性。若主動技能上回合就緒，本回合轉色數量<color=#00F6FF>+1</color>。",
  str_skill_passive_name_410189 = "加熱轟擊",
  str_skill_passive_name_420189 = "加熱轟擊",
  str_skill_passive_name_430189 = "加熱轟擊",
  str_skill_passive_name_433189 = "加熱轟擊",
  str_skill_passive_name_410190 = "耀暇衛戍",
  str_skill_passive_name_420190 = "耀暇衛戍",
  str_skill_passive_name_430190 = "耀暇衛戍",
  str_skill_passive_desc_410189 = "零恩的普通攻擊會根據<link=\"30078\"><#FFAE07><u>熱值</u></color></link>獲得最大<color=#00F6FF>{1}</color>的傷害加成，熱值越高加成效率越高。熱值達到<color=#00F6FF>100</color>點會進入過熱狀態，無法普通攻擊。",
  str_skill_passive_desc_420189 = "零恩的普通攻擊會根據<link=\"30078\"><#FFAE07><u>熱值</u></color></link>獲得最大<color=#00F6FF>{1}</color>的傷害加成，熱值越高加成效率越高。熱值達到<color=#00F6FF>100</color>點會進入過熱狀態，無法普通攻擊，但連鎖技能的最終傷害提高<color=#00F6FF>30%</color>。",
  str_skill_passive_desc_430189 = "零恩的普通攻擊會根據<link=\"30078\"><#FFAE07><u>熱值</u></color></link>獲得最大<color=#00F6FF>{1}</color>的傷害加成，熱值越高加成效率越高。熱值達到<color=#00F6FF>100</color>點會進入過熱狀態，無法普通攻擊，但連鎖技能的最終傷害提高<color=#00F6FF>30%</color>。",
  str_skill_passive_desc_433189 = "零恩的普通攻擊會根據<link=\"30078\"><#FFAE07><u>熱值</u></color></link>獲得最大<color=#00F6FF>{1}</color>的傷害加成，熱值越高加成效率越高。熱值達到<color=#00F6FF>100</color>點會進入過熱狀態，無法普通攻擊，但連鎖技能的最終傷害提高<color=#00F6FF>30%</color>。",
  str_skill_passive_desc_410190 = "連鎖技能造成傷害的<color=#00F6FF>50%</color>轉化為護盾，該值不超過馬太攻擊力的<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_420190 = "連鎖技能造成傷害的<color=#00F6FF>50%</color>轉化為護盾，該值不超過馬太攻擊力的<color=#00F6FF>{1}</color>。每當火屬性光靈施放主動技能時，獲得等同於馬太攻擊力<color=#00F6FF>10%</color>的護盾。",
  str_skill_passive_desc_430190 = "連鎖技能造成傷害的<color=#00F6FF>50%</color>轉化為護盾，該值不超過馬太攻擊力的<color=#00F6FF>{1}</color>。每當火屬性光靈施放主動技能時，獲得等同於馬太攻擊力<color=#00F6FF>10%</color>的護盾。",
  str_skill_upgrade_desc_16018613 = "主動技能強化：主動技能變為<color=#FFFF00>先制攻擊</color>，進入戰鬥即可使用。",
  str_skill_upgrade_desc_16018616 = "主動技能強化：可連線格子數<color=#00F6FF>+1</color>。",
  str_skill_name_2001861 = "輝落洞穿",
  str_skill_name_2001862 = "輝落洞穿",
