  str_skill_desc_2001861 = "對<color=#00F6FF>縱向1列</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2001862 = "對<color=#00F6FF>縱向3列</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2001863 = "對<color=#00F6FF>縱向3列</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_passive_name_410186 = "耀眼揮灑",
  str_skill_passive_name_430186 = "耀眼揮灑",
  str_skill_passive_desc_410186 = "蒂娜每回合首次造成的傷害提高<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_430186 = "蒂娜每回合首次造成的傷害提高<color=#00F6FF>{1}</color>。若上回合蒂娜未出戰，本回合效果翻倍。",
  str_skill_name_3001861 = "聖光安息",
