  str_skill_name_3261861 = "聖光安息",
  str_skill_desc_3001861 = "蒂娜進入夢遊，無視格子顏色至多連線<color=#00F6FF>3</color>格，將<color=#00F6FF>經過的格子</color>轉為水屬性，然後回到起點。",
  str_skill_desc_3061861 = "蒂娜進入夢遊，無視格子顏色至多連線<color=#00F6FF>4</color>格，將<color=#00F6FF>經過的格子</color>轉為水屬性，然後回到起點。",
  str_skill_desc_3201861 = "蒂娜進入夢遊，無視格子顏色至多連線<color=#00F6FF>3</color>格，將<color=#00F6FF>起點和經過的格子</color>轉為水屬性，然後回到起點。可以額外將連線終點落在敵人身上，以對其造成<color=#00F6FF>200%</color>傷害，並不回到起點。",
  str_skill_desc_3261861 = "蒂娜進入夢遊，無視格子顏色至多連線<color=#00F6FF>4</color>格，將<color=#00F6FF>起點和經過的格子</color>轉為水屬性，然後回到起點。可以額外將連線終點落在敵人身上，以對其造成<color=#00F6FF>200%</color>傷害，並不回到起點。",
  str_skill_upgrade_desc_16018913 = "主動技能強化：過熱戰技變為<color=#FFFF00>先制攻擊</color>，發動後熱值提升至<color=#00F6FF>100</color>。（覺醒3階段生效）",
  str_skill_upgrade_desc_16018916 = "主動技能強化：可選擇自身所在格，不造成傷害而改為增加<color=#00F6FF>35</color>點熱值。（覺醒1階段生效）",
  str_skill_upgrade_desc_15019012 = "主動技能強化：上回合技能就緒，本回合轉色數量<color=#FFFF00>+1</color>。",
  str_skill_upgrade_desc_15019015 = "主動技能強化：轉換格子數量增加<color=#FFFF00>1個</color>。",
  str_skill_upgrade_refine_desc_16001111 = "裝備技能強化：最多對敵人附加<color=#00F6FF>7</color>層龍牙印記。",
  str_skill_upgrade_refine_desc_16001112 = "<color=#00F6FF>新增主動技能變體I</color>：<color=#FFFF00>施放後技能冷卻回合-1</color>。瞬移到<color=#FFFF00>周圍3圈</color>內的指定位置，對<color=#FFFF00>周圍1圈</color>造成<color=#FFFF00>200%</color>的傷害，並附加2層龍牙印記（若擊殺敵人，則範圍內其他敵人的印記層數增加至上限）。",
  str_skill_upgrade_refine_desc_16001113 = "<color=#00F6FF>新增主動技能變體II</color>：<color=#FFFF00>施放後技能冷卻回合+1</color>。瞬移到<color=#FFFF00>任意</color>位置，對<color=#FFFF00>周圍3圈</color>造成<color=#FFFF00>360%</color>的傷害，並附加2層龍牙印記（若擊殺敵人，則範圍內其他敵人的印記層數增加至上限）。",
  str_skill_desc_3300111 = "<color=#FFFF00>施放後技能冷卻回合-1</color>。瞬移到<color=#FFFF00>周圍3圈</color>內的指定位置，對<color=#FFFF00>周圍1圈</color>造成<color=#FFFF00>200%</color>的傷害，並附加2層龍牙印記（若擊殺敵人，則範圍內其他敵人的印記層數增加至上限）。",
  str_skill_desc_3300112 = "<color=#FFFF00>施放後技能冷卻回合+1</color>。瞬移到<color=#FFFF00>任意</color>位置，對<color=#FFFF00>周圍3圈</color>造成<color=#FFFF00>360%</color>的傷害，並附加2層龍牙印記（若擊殺敵人，則範圍內其他敵人的印記層數增加至上限）。",
  str_skill_upgrade_desc_16019113 = "獲得新主動技能；消耗隊伍目前生命值的<color=#00F6FF>10%</color>，對<color=#00F6FF>周圍1圈</color>造成250%的傷害。",
  str_skill_upgrade_desc_16019116 = "主動技能強化：技能冷卻回合-1。",
