  str_skill_desc_2001911 = "跳向<color=#00F6FF>菱形12格</color>範圍內最近且生命值最高的敵人，對<color=#00F6FF>方形9格</color>造成<color=#00F6FF>150%</color>的傷害。",
  str_skill_desc_2001912 = "跳向<color=#00F6FF>菱形12格</color>範圍內最近且生命值最高的敵人，對<color=#00F6FF>菱形13格</color>造成<color=#00F6FF>160%</color>的傷害。",
  str_skill_desc_2001913 = "跳向<color=#00F6FF>菱形12格</color>範圍內最近且生命值最高的敵人，對<color=#00F6FF>米字17格</color>造成<color=#00F6FF>170%</color>的傷害。",
  str_skill_desc_2301911 = "跳向<color=#00F6FF>菱形12格</color>範圍內最近且生命值最高的敵人，對<color=#00F6FF>方形9格</color>造成<color=#00F6FF>150%</color>的傷害。生命值低於40%時，跳躍範圍擴大至<color=#00F6FF>周圍2圈</color>",
  str_skill_desc_2301912 = "跳向<color=#00F6FF>菱形12格</color>範圍內最近且生命值最高的敵人，對<color=#00F6FF>菱形13格</color>造成<color=#00F6FF>160%</color>的傷害。生命值低於40%時，跳躍範圍擴大至<color=#00F6FF>周圍2圈</color>",
  str_skill_desc_2301913 = "跳向<color=#00F6FF>菱形12格</color>範圍內最近且生命值最高的敵人，對<color=#00F6FF>米字17格</color>造成<color=#00F6FF>170%</color>的傷害。生命值低於40%時，跳躍範圍擴大至<color=#00F6FF>周圍2圈</color>",
  str_skill_name_3001911 = "幽延逐焰",
  str_skill_name_3201911 = "幽延逐焰",
  str_skill_name_32019111 = "幽延逐焰",
  str_skill_desc_3001911 = "在周圍<color=#00F6FF>菱形24格</color>內選擇1名敵人，位移到距離該敵人最近的格子上，對其造成<color=#00F6FF>150%</color>的傷害。",
  str_skill_desc_3201911 = "在周圍<color=#00F6FF>菱形24格</color>內選擇1名敵人，位移到距離該敵人最近的格子上，對其造成<color=#00F6FF>150%</color>的傷害。若主動技能於上個回合就緒，本回合可選擇範圍擴大為<color=#00F6FF>周圍4圈</color>",
  str_skill_desc_32019112 = "在周圍<color=#00F6FF>菱形24格</color>內選擇1名敵人，位移到距離該敵人最近的格子上，對其造成<color=#00F6FF>150%</color>的傷害。若主動技能於上個回合就緒，本回合可選擇範圍擴大為<color=#00F6FF>周圍4圈</color>，傷害提高至<color=#00F6FF>200%</color>。",
  str_skill_desc_32019113 = "在周圍<color=#00F6FF>菱形24格</color>內選擇1名敵人，位移到距離該敵人最近的格子上，對十字5格造成<color=#00F6FF>150%</color>的傷害。若主動技能於上個回合就緒，本回合可選擇範圍擴大為<color=#00F6FF>周圍4圈</color>，傷害提高至<color=#00F6FF>200%</color>。",
  str_skill_name_3001912 = "幽焰共顫",
  str_skill_name_3061912 = "幽焰共顫",
  str_skill_desc_3001912 = "消耗隊伍目前生命值的<color=#00F6FF>10%</color>，對<color=#00F6FF>周圍1圈</color>造成{1}%的傷害。",
  str_skill_passive_name_410191 = "魂燃利爪",
  str_skill_passive_desc_410191 = "隊伍生命值越低，哈提造成的傷害越高，在隊伍生命值不超過<color=#00F6FF>30%</color>時，可達到最大加成<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_4101911 = "隊伍生命值越低，哈提造成的傷害越高，在隊伍生命值不超過<color=#00F6FF>30%</color>時，可達到最大加成<color=#00F6FF>60%</color>。",
  str_skill_upgrade_refine_desc_16019111 = "裝備技能強化：隊伍生命值不超過30%時獲得<color=#00F6FF>60%</color>的最大加成。",
  str_skill_upgrade_refine_desc_16019112 = "主動技能新增效果：若於上個回合就緒，本回合可選擇範圍擴大為周圍4圈，<color=#00F6FF>傷害提高至200%</color>。",
  str_skill_upgrade_refine_desc_16019113 = "主動技能強化：從對目標造成單體傷害變更為對<color=#00F6FF>目標格子周圍十字5格</color>造成傷害。",
