  str_skill_name_3401932 = "嘯空而上．變體II",
  str_skill_desc_2001931 = "對<color=#00F6FF>十字8格</color>範圍造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2001932 = "對<color=#00F6FF>菱形12格</color>範圍造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_20019333 = "對<color=#00F6FF>周圍1圈</color>和<color=#00F6FF>十字形最大</color>範圍造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2201931 = "對<color=#00F6FF>十字8格</color>範圍造成<color=#00F6FF>{1}%</color>的傷害。對十字方向上的敵人造成的傷害提高30%。",
  str_skill_desc_2201932 = "對<color=#00F6FF>菱形12格</color>範圍造成<color=#00F6FF>{1}%</color>的傷害。對十字方向上的敵人造成的傷害提高30%。",
  str_skill_desc_2201933 = "對<color=#00F6FF>周圍1圈</color>和<color=#00F6FF>十字形最大</color>範圍造成<color=#00F6FF>{1}%</color>的傷害。對十字方向上的敵人造成的傷害提高30%。",
  str_skill_desc_3001931 = "選擇1個方向攻擊，對該方向上的所有敵人造成<color=#00F6FF>160%</color>的傷害。",
  str_skill_desc_3051931 = "選擇1個方向攻擊，對該方向上的所有敵人造成<color=#00F6FF>200%</color>的傷害。",
  str_skill_desc_3301931 = "選擇1個方向攻擊，對該方向上的所有敵人造成<color=#00F6FF>160%</color>的傷害。目標距離越遠，傷害越高，每圈增加<color=#00F6FF>10%</color>的最終傷害。",
  str_skill_desc_3351931 = "選擇1個方向攻擊，對該方向上的所有敵人造成<color=#00F6FF>200%</color>的傷害。目標距離越遠，傷害越高，每圈增加<color=#00F6FF>10%</color>的最終傷害。",
  str_skill_desc_3401931 = "<color=#FFFF00>施放後技能冷卻回合+1</color>。選擇1個方向攻擊，對該方向上的全部敵人造成160%的傷害，並與隊伍中<color=#FFFF00>前一名</color>隊員交換位置，目標距離越遠，傷害越高，每圈增加10%的最終傷害。<color=#FFFF00>若選擇外圈的格子，克莉絲汀會往前移動1格再施放技能</color>。",
  str_skill_desc_3451931 = "<color=#FFFF00>施放後技能冷卻回合+1</color>。選擇1個方向攻擊，對該方向上的全部敵人造成200%的傷害，並與隊伍中<color=#FFFF00>前一名</color>隊員交換位置，目標距離越遠，傷害越高，每圈增加10%的最終傷害。<color=#FFFF00>若選擇外圈的格子，克莉絲汀會往前移動1格再施放技能</color>。",
  str_skill_desc_3401932 = "<color=#FFFF00>施放後技能冷卻回合-1</color>。<color=#FFFF00>不進行攻擊</color>，與隊伍中<color=#FFFF00>後一名</color>隊員交換位置，<color=#FFFF00>下次主動技能造成的傷害增加50%</color>，重複施放時傷害加成不疊加。",
  str_skill_passive_name_410193 = "透流",
  str_skill_passive_name_430193 = "透流",
  str_skill_passive_desc_410193 = "普通攻擊會貫穿敵人，對敵人身後1格的目標造成<color=#00F6FF>{1}</color>傷害。",
  str_skill_passive_desc_430193 = "普通攻擊會貫穿敵人，對敵人身後1格的目標造成<color=#00F6FF>{1}</color>傷害。",
  str_skill_passive_desc_4401933 = "普通攻擊會貫穿敵人，對敵人身後1格上的目標造成<color=#00F6FF>60%</color>的傷害。當克莉絲汀在隊伍中的位置改變時，本場戰鬥可更換隊長次數<color=#00F6FF>+1</color>，每回合最多觸發1次。",
  str_skill_upgrade_refine_desc_15019311 = "<color=#00F6FF>新增主動技能變體I</color>：<color=#FFFF00>施放後技能冷卻回合+1</color>。選擇1個方向攻擊，對該方向上的全部敵人造成傷害，並與隊伍中<color=#FFFF00>前一名</color>隊員交換位置，目標距離越遠，傷害越高，每圈增加10%的最終傷害。<color=#FFFF00>若選擇外圈的格子，克莉絲汀會往前移動1格再施放技能</color>。",
  str_skill_upgrade_refine_desc_15019312 = "<color=#00F6FF>新增主動技能變體II</color>：<color=#FFFF00>施放後技能冷卻回合-1</color>。<color=#FFFF00>不進行攻擊</color>，與隊伍中<color=#FFFF00>後一名</color>隊員交換位置，<color=#FFFF00>下次主動技能造成的傷害增加50%</color>，重複施放時傷害加成不疊加。",
  str_skill_upgrade_refine_desc_15019313 = "裝備技能強化：當克莉絲汀在隊伍中的位置改變時，更換隊長次數+1，每回合最多觸發1次。",
  str_skill_upgrade_desc_15019312 = "主動技能強化：主動技能變為<color=#FFFF00>先制攻擊</color>，進入戰鬥即可使用。",
  str_skill_upgrade_desc_15019315 = "主動技能強化：主動技能傷害增加<color=#FFFF00>40%</color>。",
  str_skill_upgrade_refine_desc_14004811 = "裝備技能強化：敵人腳下每有1個雷屬性格子，傷害加成提升<color=#00F6FF>1%</color>。",
  str_skill_upgrade_refine_desc_14004812 = "主動技能強化：範圍中心格子傷害加倍。",
  str_skill_upgrade_refine_desc_14004813 = "主動技能強化：若主動技能上回合就緒，本回合可選擇範圍變為<color=#00F6FF>周圍2圈</color>。",
  str_skill_passive_desc_4400481 = "烈雀對位於雷屬性格子上的敵人的傷害增加<color=#00F6FF>10%</color>，敵人腳下每有1個雷屬性格子，傷害加成提升<color=#00F6FF>1%</color>，隊伍中其他雷屬性光靈獲得<color=#00F6FF>一半</color>的加成。",
  str_skill_name_3400482 = "奇行鵲閃",
  str_skill_name_3420482 = "奇行鵲閃",
  str_skill_name_3400483 = "奇行鵲閃",
  str_skill_name_3420483 = "奇行鵲閃",
  str_skill_desc_3400482 = "選擇1個格子，對<color=#00F6FF>菱形13格</color>造成<color=#00F6FF>250%</color>的傷害，對中心格子造成的傷害加倍。",
  str_skill_desc_3420482 = "選擇1個格子，對<color=#00F6FF>菱形13格</color>造成<color=#00F6FF>250%</color>的傷害，對中心格子造成的傷害加倍，同時將敵人所處位置至多1個格子轉成雷屬性。",
  str_skill_desc_3400483 = "選擇1個格子，對<color=#00F6FF>菱形13格</color>造成<color=#00F6FF>250%</color>的傷害，對中心格子造成的傷害加倍。若主動技能上回合就緒，本回合可選擇範圍變為<color=#00F6FF>周圍2圈</color>。",
  str_skill_desc_3420483 = "選擇1個格子，對<color=#00F6FF>菱形13格</color>造成<color=#00F6FF>250%</color>的傷害，對中心格子造成的傷害加倍，同時將敵人所處位置至多1個格子轉成雷屬性。若主動技能上回合就緒，本回合可選擇範圍變為<color=#00F6FF>周圍2圈</color>。",
  str_skill_upgrade_refine_desc_15009811 = "連鎖技能強化：連鎖技能傷害係數增加<color=#00F6FF>15%/20%/20%</color>。",
  str_skill_upgrade_refine_desc_15009812 = "裝備技能強化：割裂印記最高可疊加<color=#00F6FF>10層</color>，每層提高6%傷害。",
  str_skill_upgrade_refine_desc_15009813 = "主動技能強化：主動技能傷害係數提高到<color=#00F6FF>500%</color>。若主動技能選擇的敵人不可被位移，施放後<color=#00F6FF>技能冷卻回合-1</color>。",
  str_skill_desc_2009811 = "對<color=#00F6FF>周圍3圈</color>內的3名敵人造成<color=#00F6FF>150%</color>的傷害",
  str_skill_desc_2009821 = "對<color=#00F6FF>周圍3圈</color>內的4名敵人造成<color=#00F6FF>160%</color>的傷害。",
  str_skill_desc_2009831 = "對<color=#00F6FF>周圍3圈</color>內的所有敵人造成<color=#00F6FF>170%</color>的傷害。",
  str_skill_desc_3300981 = "從自身<color=#00F6FF>周圍3圈</color>內選擇1個敵人，對其造成<color=#00F6FF>500%</color>的傷害，若該敵人為單格且可擊退，則將其移動到攻擊範圍內的所選位置。若敵人不可擊退，施放後<color=#00F6FF>技能冷卻回合-1</color>。擊殺帶有印記的目標時，對其<color=#00F6FF>周圍1圈</color>的敵人造成庫絲庫塔<color=#00F6FF>40%</color>攻擊力的無視防禦的傷害。",
  str_skill_desc_3350981 = "任選1個敵人，對其造成<color=#00F6FF>500%</color>的傷害，若該敵人為單格且可擊退，則將其移動到攻擊範圍內的所選位置。若敵人不可擊退，施放後<color=#00F6FF>技能冷卻回合-1</color>。擊殺帶有印記的目標時，對其<color=#00F6FF>周圍1圈</color>的敵人造成庫絲庫塔<color=#00F6FF>40%</color>攻擊力的無視防禦的傷害。",
  str_skill_desc_3200331 = "隨機對場上的敵人造成<color=#00F6FF>5</color>次<color=#00F6FF>95%</color>的傷害，所在位置<color=#00F6FF>周圍1圈</color>內每有1個水屬性格子，再額外攻擊1次。對每個目標首次造成的傷害<color=#00F6FF>加倍</color>。",
  str_skill_desc_3250331 = "隨機對場上的敵人造成<color=#00F6FF>6</color>次<color=#00F6FF>95%</color>的傷害，所在位置<color=#00F6FF>周圍12格</color>內每有1個水屬性格子，再額外攻擊1次。對每個目標首次造成的傷害<color=#00F6FF>加倍</color>。",
  str_skill_passive_desc_4300331 = "薇絲每次造成傷害都會獲得1層瞄定印記，每層印記增加<color=#00F6FF>2.5%</color>的傷害（連鎖技能增加<color=#00F6FF>5%</color>），回合結束後印記層數歸零。",
  str_skill_passive_desc_4300332 = "薇絲每次造成傷害都會獲得1層瞄定印記，每層印記增加<color=#00F6FF>2.5%</color>的傷害（連鎖技能增加<color=#00F6FF>5%</color>），並提高薇絲0.5%的基礎攻擊力，回合結束後印記層數歸零。",
  str_skill_upgrade_refine_desc_15003311 = "裝備技能強化：每層印記增加<color=#00F6FF>2.5%</color>的傷害（連鎖技能增加<color=#00F6FF>5%</color>）。",
  str_skill_upgrade_refine_desc_15003312 = "主動技能強化：對每個目標首次造成的傷害<color=#00F6FF>加倍</color>。",
  str_skill_upgrade_refine_desc_15003313 = "裝備技能強化：每層印記提高<color=#00F6FF>0.5%</color>的基礎攻擊力。",
  str_skill_desc_340093 = "瞬移到<color=#00F6FF>周圍3圈</color>內的任意位置，對<color=#00F6FF>周圍1圈</color>內的敵人造成<color=#00F6FF>250%</color>的傷害，範圍內只有1個敵人時傷害加倍。每擊殺1個敵人，最終傷害增加<color=#00F6FF>15%</color>，可累積10次。每擊殺5個敵人，可選擇的瞬移範圍擴大一圈。",
  str_skill_desc_346093 = "瞬移到<color=#00F6FF>周圍3圈</color>內的任意位置，對<color=#00F6FF>周圍1圈</color>內的敵人造成<color=#00F6FF>250%</color>的傷害，範圍內只有1個敵人時傷害加倍。每擊殺1個敵人，最終傷害增加<color=#00F6FF>15%</color>，可累積10次。主動技能擊殺敵人後可再次使用，每回合限1次。每擊殺5個敵人，可選擇的瞬移範圍擴大一圈。",
  str_skill_passive_desc_4300931 = "施放連鎖技能或主動技能後，若目標生命值低於<color=#00F6FF>30%</color>，則對其追加造成1次<color=#00F6FF>120%</color>攻擊的無視防禦的傷害。追擊後若目標生命值低於彌加德的攻擊力，則將其斬殺。",
  str_skill_passive_desc_4300932 = "施放連鎖技能或主動技能後，若目標生命值低於<color=#00F6FF>30%</color>，則對其追加造成1次<color=#00F6FF>120%</color>攻擊的無視防禦的傷害。追擊後若目標生命值低於彌加德攻擊力的250%，則將其斬殺。",
  str_skill_upgrade_refine_desc_16009311 = "裝備技能強化：追擊傷害提高到<color=#00F6FF>120%</color>。",
  str_skill_upgrade_refine_desc_16009312 = "主動技能強化：主動技能每獲得<color=#00F6FF>5次</color>傷害加成，可選擇範圍擴大<color=#00F6FF>一圈</color>。",
  str_skill_upgrade_refine_desc_16009313 = "裝備技能強化：追擊後若目標生命值低於彌加德攻擊力的<color=#00F6FF>250%</color>，則將其斬殺。",
  str_skill_upgrade_refine_desc_15001811 = "裝備技能強化：主動技能和連鎖技能對距離越近的敵人傷害越高，傷害最多增加<color=#00F6FF>110%</color>。",
  str_skill_upgrade_refine_desc_15001812 = "連鎖技能強化：連鎖技能傷害係數增加<color=#00F6FF>10%/15%/20%</color>。",
  str_skill_upgrade_refine_desc_15001813 = "裝備技能強化：裝備技能生效範圍擴大至<color=#00F6FF>5圈</color>以內。",
  str_skill_passive_desc_440018 = "<color=#00F6FF>周圍1圈</color>範圍內每有1個敵人，提高<color=#00F6FF>5%</color>攻擊力。主動技能和連鎖技能對距離越近的敵人傷害越高，傷害最多增加<color=#00F6FF>110%</color>。與敵人距離超過3圈則無加成。",
  str_skill_passive_desc_450018 = "<color=#00F6FF>周圍1圈</color>範圍內每有1個敵人，提高<color=#00F6FF>5%</color>攻擊力。主動技能和連鎖技能對距離越近的敵人傷害越高，傷害最多增加<color=#00F6FF>110%</color>。與敵人距離超過5圈則無加成。",
  str_skill_desc_2400181 = "對<color=#00F6FF>縱向1列</color>造成<color=#00F6FF>115%</color>的傷害。",
  str_skill_desc_2400182 = "對<color=#00F6FF>縱向3列</color>造成<color=#00F6FF>125%</color>的傷害。",
  str_skill_desc_2400183 = "對<color=#00F6FF>縱向5列</color>造成<color=#00F6FF>130%</color>的傷害。",
  str_skill_upgrade_refine_desc_16006411 = "主動技能強化：戰鬥開始時，技能冷卻回合<color=#00F6FF>-2</color>。",
  str_skill_upgrade_refine_desc_16006412 = "裝備技能強化：自身施放主動技能時可儲備<color=#00F6FF>5</color>顆彈藥；任意光靈施放主動技能可儲備<color=#00F6FF>1</color>顆彈藥。",
  str_skill_upgrade_refine_desc_16006413 = "裝備技能強化：可手動切換選擇連鎖技能是否消耗彈藥。",
  str_skill_passive_desc_440064 = "可<link=\"30079\"><#FFAE07><u>儲備彈藥</u></color></link>。連鎖技能每造成1次傷害，消耗1顆彈藥（超載狀態下每次最多消耗<color=#00F6FF>3</color>顆）。每消耗1顆彈藥增加<color=#00F6FF>30%</color>的最終傷害。",
  str_skill_desc_341064 = "進入超載狀態，雷霆的連鎖技能傷害增加<color=#00F6FF>50%</color>，且對最近的1個敵人造成2次傷害，持續2回合。戰鬥開始時，技能冷卻回合<color=#00F6FF>-2</color>。",
  str_skill_upgrade_refine_desc_16001911 = "維多利亞在進入戰鬥後自帶<link=\"30039\"><#FFAE07><u>【理智系統】</u></color></link>。\n<color=#00F6FF>新增主動技能變體I</color>：<color=#FFFF00>施放後技能冷卻回合-1</color>。對範圍內最多3個敵人造成<color=#FFFF00>300%</color>的傷害，僅有1個敵人時造成<color=#FFFF00>300%</color>的無視防禦的傷害，目標每有1層流血，最終傷害增加10%。恢復本次傷害一定比例的生命值，<color=#FFFF00>並失去等同於本次恢復生命值比例的理智值</color>。",
  str_skill_upgrade_refine_desc_16001912 = "主動技能強化：主動技能可額外攻擊1個敵人。",
  str_skill_upgrade_refine_desc_16001913 = "<color=#00F6FF>新增主動技能變體II</color>：<color=#FFFF00>施放後技能冷卻回合+1</color>。對範圍內最多4個敵人造成250%的傷害，僅有1個敵人時造成250%的無視防禦的傷害，目標每有1層流血，最終傷害增加10%。恢復本次傷害一定比例的生命值，<color=#FFFF00>並恢復等同於本次恢復生命值比例的理智值</color>。",
  str_skill_desc_3200192 = "<color=#FFFF00>施放後技能冷卻回合-1</color>。對周圍3圈最多3個敵人造成<color=#FFFF00>300%</color>的傷害，僅有1個敵人時造成<color=#FFFF00>300%</color>的無視防禦的傷害，目標每有1層流血，最終傷害增加10%。恢復本次傷害25%的生命值，<color=#FFFF00>並失去等同於本次恢復生命值比例的理智值</color>。",
  str_skill_desc_3200191 = "<color=#FFFF00>施放後技能冷卻回合+1</color>。對周圍3圈最多3個敵人造成250%的傷害，僅有1個敵人時造成250%的無視防禦的傷害，目標每有1層流血，最終傷害增加10%。恢復本次傷害25%的生命值，<color=#FFFF00>並恢復等同於本次恢復生命值比例的理智值</color>。",
