  str_skill_desc_343019 = "對<color=#00F6FF>周圍3圈</color>最多4個敵人造成<color=#00F6FF>250%</color>的傷害，僅有1個敵人時造成<color=#00F6FF>250%</color>的無視防禦的傷害，目標每有1層流血，最終傷害增加10%。恢復本次傷害35%的生命值。",
  str_skill_desc_346019 = "對最近的4個敵人造成<color=#00F6FF>250%</color>的傷害，僅有1個敵人時造成<color=#00F6FF>250%</color>的無視防禦的傷害，目標每有1層流血，最終傷害增加10%。恢復本次傷害35%的生命值。",
  str_skill_name_290510101 = "鑽探場域施放",
  str_skill_desc_290510101 = "鑽探者隨機選擇一個較空曠的區域移動，期間對相鄰4格造成放電傷害。移動結束時，在2圈範圍內生成固定數量的「鏈場」和「協場」。",
  str_skill_desc_290511102 = "鑽探者隨機選擇一處空曠區域移動，期間對相鄰4格造成放電傷害。移動結束時，生成固定數量的「鏈場」和「協場」。",
  str_skill_desc_290511103 = "行動開始時，在周圍生成固定數量的「鏈場」和「協場」。",
  str_skill_name_290510102 = "鑽探者場域鏈組",
  str_skill_desc_290510102 = "鑽探者吸收場上的「鏈場」，原地組裝成鑽探者平台，造成全場傷害。",
  str_skill_name_290510203 = "鑽探者場域協擊",
  str_skill_desc_290510203 = "鑽探者利用鑽探者平台鎖定光靈位置，引導離玩家最近的5個協場對玩家造成傷害。能量累積倒數2。",
  str_skill_desc_290510213 = "鑽探者利用鑽探者平台鎖定光靈位置，引導離玩家最近的3個協場對玩家造成傷害。能量累積倒數1。",
  str_skill_name_290510204 = "鑽探者平台自爆",
  str_skill_desc_290510204 = "能量累積完畢，鑽探者平台發動自爆，對全場造成大量傷害。",
  str_skill_name_290510123 = "操作中",
  str_skill_desc_290510123 = "鑽探者從平台後方操作。鑽探者與鑽探者平台的生命值獨立計算。",
  str_skill_desc_290511101 = "鑽探者向玩家所在位置移動，期間對相鄰4格造成放電傷害。移動結束時，在相鄰4格處生成「協場」。",
  str_skill_desc_290511203 = "鑽探者利用鑽探平台鎖定光靈位置，引導所有協場對玩家造成傷害。協場越多，玩家受到的傷害越高。",
  str_skill_desc_290512101 = "鑽探者專心發掘，回合開始時在周邊範圍生成少量鏈場和協場。",
  str_skill_upgrade_desc_16019913 = "主動技能強化：主動技能變為<color=#FFFF00>先制攻擊</color>，進入戰鬥即可使用。",
  str_skill_upgrade_desc_16019916 = "裝備技能強化：鶯歌對擁有開放性傷口的目標造成傷害時，每處無視其<color=#00F6FF>5%</color>防禦力。（覺醒3階段生效）",
