  str_skill_desc_2201991 = "對開放性傷口最多且生命值最高的1名敵人造成<color=#00F6FF>{1}%</color>的傷害，否則攻擊最靠近的敵人。",
  str_skill_desc_2201992 = "對開放性傷口最多且生命值最高的1名敵人造成<color=#00F6FF>{1}%</color>的傷害，否則攻擊最靠近的敵人。",
  str_skill_desc_2201993 = "對開放性傷口最多且生命值最高的1名敵人造成<color=#00F6FF>{1}%</color>的傷害，否則攻擊最靠近的敵人。",
