  str_skill_passive_name_436199 = "特別重彈裝填",
  str_skill_passive_desc_410199 = "鶯歌的普通攻擊每<color=#00F6FF>隔一次</color>造成傷害，普通攻擊倍率提升至<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_420199 = "鶯歌的普通攻擊每<color=#00F6FF>隔一次</color>造成傷害，普通攻擊倍率提升至<color=#00F6FF>{1}</color>，並附加1處開放性傷口（最多20處）。鶯歌對擁有開放性傷口的目標造成傷害時，每處提升<color=#00F6FF>3%</color>的連鎖技能最終傷害。",
  str_skill_passive_desc_430199 = "鶯歌的普通攻擊每<color=#00F6FF>隔一次</color>造成傷害，普通攻擊倍率提升至<color=#00F6FF>{1}</color>，並附加1處開放性傷口（最多20處）。鶯歌對擁有開放性傷口的目標造成傷害時，每處無視其<color=#00F6FF>3%</color>防禦力，且能提升<color=#00F6FF>3%</color>的連鎖技能最終傷害。",
  str_skill_passive_desc_436199 = "鶯歌的普通攻擊每<color=#00F6FF>隔一次</color>造成傷害，普通攻擊倍率提升至<color=#00F6FF>{1}</color>，並附加1處開放性傷口（最多20處）。鶯歌對擁有開放性傷口的目標造成傷害時，每處無視其<color=#00F6FF>5%</color>防禦力，且能提升<color=#00F6FF>3%</color>的連鎖技能最終傷害。",
  str_skill_desc_1601751002 = "十字稜鏡格子",
  str_skill_desc_160175102 = "消耗<color=#00F6FF>3</color>點立方能，任選1個格子轉化為十字稜鏡格子。",
  str_skill_name_3400231 = "阿比斯轟鳴曲·變體I",
  str_skill_name_3430231 = "阿比斯轟鳴曲·變體I",
  str_skill_name_3400232 = "阿比斯轟鳴曲·變體II",
  str_skill_name_3430232 = "阿比斯轟鳴曲·變體II",
  str_skill_desc_3400231 = "<color=#FFFF00>施放後技能冷卻回合-2</color>。對全體敵人造成<color=#FFFF00>250%</color>的傷害。此變體無法觸發裝備技能的恐懼效果。",
  str_skill_desc_3430231 = "<color=#FFFF00>施放後技能冷卻回合-2</color>。對全體敵人造成<color=#FFFF00>250%</color>的傷害。此變體無法觸發裝備技能的恐懼效果。",
  str_skill_desc_3400232 = "<color=#FFFF00>施放後技能冷卻回合+2</color>。對全體敵人<color=#FFFF00>施加1回合<link=\"10003\"><#FFAE07><u>恐懼</u></color></link>狀態</color>，並造成<color=#FFFF00>550%</color>的傷害。",
  str_skill_desc_3430232 = "<color=#FFFF00>施放後技能冷卻回合+2</color>。對全體敵人<color=#FFFF00>施加1回合<link=\"10003\"><#FFAE07><u>恐懼</u></color></link>狀態</color>，並造成<color=#FFFF00>550%</color>的傷害。",
  str_skill_passive_desc_440023 = "施放連鎖技能可獲得1層顫慄印記，最多<color=#00F6FF>5</color>層。每層印記增加<color=#00F6FF>20%</color>主動技能傷害。使用主動技能可<link=\"10003\"><#FFAE07><u>恐懼</u></color></link>等同於印記層數的敵人<color=#00F6FF>1</color>回合，<color=#00F6FF>印記不會清空</color>。若施放連鎖技能前已有5層印記，本次連鎖技能額外對最靠近的1名敵人造成傷害。克娜莉對<link=\"10003\"><#FFAE07><u>恐懼</u></color></link>狀態下的敵人最終傷害增加15%。",
  str_skill_upgrade_refine_desc_16002311 = "<color=#00F6FF>新增主動技能變體I</color>：<color=#FFFF00>施放後技能冷卻回合-2</color>。對全體敵人造成<color=#FFFF00>250%</color>的傷害。此變體無法觸發裝備技能的恐懼效果。",
  str_skill_upgrade_refine_desc_16002312 = "裝備技能強化：克娜莉對恐懼狀態下的敵人<color=#00F6FF>最終傷害增加15%</color>。",
  str_skill_upgrade_refine_desc_16002313 = "<color=#00F6FF>新增主動技能變體II</color>：<color=#FFFF00>施放後技能冷卻回合+2</color>。對全體敵人<color=#FFFF00>施加1回合<link=\"10003\"><#FFAE07><u>恐懼</u></color></link>狀態</color>，並造成<color=#FFFF00>550%</color>的傷害。",
  str_skill_name_290520101 = "梟桀之襲",
  str_skill_desc_290520101 = "向光靈移動，並造成大量傷害，隨後移動至遠離目標的位置。",
  str_skill_name_290520102 = "梟桀之襲",
  str_skill_desc_290520102 = "移動後，對範圍內的光靈造成傷害。",
