  str_skill_desc_3400901 = "<color=#FFFF00>施放後技能冷卻回合+1</color>。對全體敵人造成<color=#FFFF00>{1}%</color>的傷害<color=#FFFF00>並造成暈眩</color>。",
  str_skill_desc_3420901 = "<color=#FFFF00>施放後技能冷卻回合+1</color>。對全體敵人造成<color=#FFFF00>{1}%</color>的傷害<color=#FFFF00>並造成暈眩</color>。",
  str_skill_desc_3400902 = "<color=#FFFF00>施放後技能冷卻回合-1</color>。對全體敵人造成<color=#FFFF00>{1}%</color>的傷害。",
  str_skill_desc_3420902 = "<color=#FFFF00>施放後技能冷卻回合-1</color>。對全體敵人造成<color=#FFFF00>{1}%</color>的傷害。",
  str_skill_passive_desc_440090 = "芭芭拉對位於火屬性格子上的敵人傷害增加<color=#00F6FF>10%</color>；敵人腳下每有1個火屬性格子，傷害加成提升<color=#00F6FF>1%</color>；隊伍中其他火屬性光靈獲得<color=#00F6FF>一半</color>的加成。",
  str_skill_upgrade_refine_desc_15009011 = "裝備技能強化：敵人腳下每有1個火屬性格子，傷害加成提升<color=#00F6FF>1%</color>。",
  str_skill_upgrade_refine_desc_15009012 = "<color=#00F6FF>新增主動技能變體I</color>：<color=#FFFF00>施放後技能冷卻回合+1</color>。對全體敵人造成<color=#FFFF00>600%</color>的傷害<color=#FFFF00>並造成暈眩</color>。",
  str_skill_upgrade_refine_desc_15009013 = "<color=#00F6FF>新增主動技能變體II</color>：<color=#FFFF00>施放後技能冷卻回合-1</color>。對全體敵人造成<color=#FFFF00>450%</color>的傷害。",
  str_skill_name_5000961 = "連結",
  str_skill_desc_5000961 = "光靈進入地刺2圈範圍時自動連結，離開地刺4圈範圍後中斷連結。連結期間地刺為玩家分擔50%的傷害。",
  str_skill_desc_4001531 = "施放技能將3圈範圍內的敵人擊退1格，並將其所在格子轉化為雷屬性格子。",
  str_skill_desc_4001751 = "施放技能後，玩家在本回合內每受到1次傷害，就生成1個與隊長同屬性的格子，並為隊伍回復少量生命值。",
