  str_skill_desc_2001921 = "對<color=#00F6FF>菱形12格</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2001922 = "對<color=#00F6FF>米字形16格</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2001923 = "對<color=#00F6FF>周圍2圈</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_3001920 = "選擇1個格子，對<color=#00F6FF>菱形13格</color>造成<color=#00F6FF>270%</color>攻擊力的傷害。",
  str_skill_desc_34019200 = "選擇1個格子，對<color=#00F6FF>菱形13格</color>造成<color=#00F6FF>270%</color>攻擊力的傷害。在傷害範圍內隨機生成<color=#00F6FF>2</color>個<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>，並會根據當下的<color=#00F6FF>棘印</color>層數強化技能效果：\n<color=#00F6FF>大於9層</color>：傷害範圍擴大至方形25格。\n<color=#00F6FF>大於19層</color>：技能冷卻回合-1。\n<color=#00F6FF>大於29層</color>：該技能發動時對全體敵人造成270%的傷害。",
  str_skill_desc_34019201 = "選擇1個格子，對<color=#00F6FF>菱形13格</color>造成<color=#00F6FF>270%</color>攻擊力的傷害。在傷害範圍內隨機生成<color=#00F6FF>2</color>個<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>，並會根據當下的<color=#00F6FF>棘印</color>層數強化技能效果：\n<color=#00F6FF>大於9層</color>：傷害範圍擴大至方形25格。\n<color=#00F6FF>大於19層</color>：技能冷卻回合-1。\n<color=#00F6FF>大於29層</color>：該技能發動時對全體敵人造成270%的傷害。",
