  str_skill_desc_3401921 = "消耗<color=#00F6FF>5</color>層棘印：本回合普通攻擊可攻擊斜方向，普通攻擊傷害增加<color=#00F6FF>20%</color>（重複施放可疊加）。不視為施放主動技能。",
  str_skill_passive_name_410192 = "荊印在身",
