  str_skill_passive_desc_416192 = "隊伍每獲得1個<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>（包含<link=\"30065\"><#FFAE07><u>吸收</u></color></link>），可獲得1層<color=#00F6FF>棘印</color>，每層棘印增加<color=#00F6FF>{1}</color>的連鎖技能傷害率。每波次開始時獲得<color=#00F6FF>5</color>層棘印。",
  str_skill_passive_desc_430192 = "隊伍每獲得1個<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>（包含<link=\"30065\"><#FFAE07><u>吸收</u></color></link>），可獲得1層<color=#00F6FF>棘印</color>，每層棘印增加<color=#00F6FF>{1}</color>的連鎖技能傷害率。",
  str_skill_passive_desc_436192 = "隊伍每獲得1個<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>（包含<link=\"30065\"><#FFAE07><u>吸收</u></color></link>），可獲得1層<color=#00F6FF>棘印</color>，每層棘印增加<color=#00F6FF>{1}</color>的連鎖技能傷害率。每波次開始時獲得<color=#00F6FF>5</color>層棘印。",
  str_skill_passive_desc_440192 = "隊伍每獲得1個<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>（包含<link=\"30065\"><#FFAE07><u>吸收</u></color></link>），可獲得1層<color=#00F6FF>棘印</color>，每層棘印增加<color=#00F6FF>3%</color>的連鎖技能傷害率。",
  str_skill_passive_desc_446192 = "隊伍每獲得1個<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>（包含<link=\"30065\"><#FFAE07><u>吸收</u></color></link>），可獲得1層<color=#00F6FF>棘印</color>，每層棘印增加<color=#00F6FF>3%</color>的連鎖技能傷害率。每波次開始時獲得<color=#00F6FF>5</color>層棘印。",
  str_skill_upgrade_refine_desc_16019211 = "裝備技能強化：每層棘印增加<color=#00F6FF>3%</color>的連鎖技能傷害率。",
  str_skill_upgrade_refine_desc_16019212 = "裝備技能強化：戰鬥開始時獲得<color=#00F6FF>5</color>層棘印。",
  str_skill_upgrade_refine_desc_16019213 = "主動技能強化：在傷害範圍內隨機生成<color=#00F6FF>2</color>個<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>。",
  str_skill_passive_desc_440193 = "隊伍每獲得1個<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>（包含<link=\"30065\"><#FFAE07><u>吸收</u></color></link>），可獲得1層<color=#00F6FF>棘印</color>，每層棘印增加<color=#00F6FF>3%</color>的連鎖技能傷害率。戰鬥開始時獲得<color=#00F6FF>5</color>層棘印。",
  str_skill_passive_desc_446193 = "隊伍每獲得1個<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>（包含<link=\"30065\"><#FFAE07><u>吸收</u></color></link>），可獲得1層<color=#00F6FF>棘印</color>，每層棘印增加<color=#00F6FF>3%</color>的連鎖技能傷害率。戰鬥開始和每波次開始時獲得<color=#00F6FF>5</color>層棘印。",
  str_skill_upgrade_desc_16019213 = "主動技能強化：主動技能變為<color=#FFFF00>先制攻擊</color>，進入戰鬥即可使用。",
  str_skill_upgrade_desc_16019216 = "裝備技能強化：每波次開始時獲得<color=#00F6FF>5</color>層棘印。",
  str_skill_name_5010152 = "鼓舞",
  str_skill_desc_5010152 = "影遊者移動到友方單位最多的區域，為全場友軍目標施加強勢印記，擁有印記的友軍目標可提高攻擊。",
  str_skill_name_888450061 = "暗礁之刹",
  str_skill_desc_888450061 = "召喚一個朦刹，每經過2回合，朦刹會攻擊光靈。",
  str_skill_desc_888450081 = "攝輪吸取自身及周圍1圈內同屬性格子的能量，隨後釋放能量球攻擊全體敵人，傷害隨吸收的格子數量而提高。擊中光靈後，再經過2回合，於光靈所在位置生成危險區域。",
  str_skill_upgrade_refine_desc_13004611 = "裝備技能強化：每層奚笑印記對基汀的普通攻擊傷害加成<color=#00F6FF>翻倍</color>。",
  str_skill_upgrade_refine_desc_13004613 = "裝備技能強化：基汀每次普通攻擊有<color=#00F6FF>35%</color>機率為敵人施加1層奚笑印記。",
  str_skill_passive_desc_4400461 = "擊殺帶有奚笑印記的敵人後，所有剩餘敵人的印記層數<color=#00F6FF>+1</color>。每層印記增加雷屬性光靈<color=#00F6FF>1.8%</color>普通攻擊傷害，基汀自身受到的加成<color=#00F6FF>翻倍</color>。",
  str_skill_desc_340046 = "戰鬥開始時，技能冷卻回合<color=#00F6FF>-2</color>。任選1個格子放置分身，牽引分身<color=#00F6FF>周圍3圈</color>的敵人，並對擁有5層印記的敵人施加<link=\"10006\"><#FFAE07><u>緩慢</u></color></link>狀態，持續2回合。",
  str_skill_desc_342046 = "戰鬥開始時，技能冷卻回合<color=#00F6FF>-2</color>。任選1個格子放置分身，牽引分身<color=#00F6FF>周圍3圈</color>的敵人，並對擁有4層印記的敵人施加2回合<link=\"10006\"><#FFAE07><u>緩慢</u></color></link>狀態，對6層印記的敵人施加1回合<link=\"10004\"><#FFAE07><u>麻痺</u></color></link>狀態。",
  str_skill_desc_345046 = "戰鬥開始時，技能冷卻回合<color=#00F6FF>-2</color>。任選1個格子放置分身，牽引<color=#00F6FF>全體</color>敵人，並對擁有4層印記的敵人施加2回合<link=\"10006\"><#FFAE07><u>緩慢</u></color></link>狀態，對6層印記的敵人施加<color=#00F6FF>1</color>回合<link=\"10004\"><#FFAE07><u>麻痺</u></color></link>狀態。",
  str_skill_passive_desc_4400463 = "擊殺帶有奚笑印記的敵人後，所有剩餘敵人的印記層數<color=#00F6FF>+1</color>。每層印記增加雷屬性光靈<color=#00F6FF>2%</color>普通攻擊傷害，基汀自身受到的加成<color=#00F6FF>翻倍</color>。基汀每次普通攻擊有<color=#00F6FF>35%</color>機率對敵人施加1層奚笑印記。",
  str_skill_upgrade_refine_desc_16006011 = "裝備技能強化：午時狀態下，普通攻擊的濺射傷害提升至<color=#00F6FF>60%</color>。",
  str_skill_upgrade_refine_desc_16006012 = "裝備技能強化：午時狀態下，普通攻擊傷害額外增加<color=#00F6FF>5%</color>。",
  str_skill_upgrade_refine_desc_16006013 = "連鎖技能強化：午時狀態下，連鎖技能範圍擴大1圈。",
  str_skill_passive_desc_4400601 = "午時狀態下，普通攻擊傷害增加<color=#00F6FF>20%</color>，同時普通攻擊對敵人周圍<color=#00F6FF>十字形4格</color>的目標造成<color=#00F6FF>60%</color>的<link=\"30015\"><#FFAE07><u>濺射</u></color></link>傷害。",
  str_skill_passive_desc_4400602 = "午時狀態下，普通攻擊傷害增加<color=#00F6FF>25%</color>，同時普通攻擊對敵人周圍<color=#00F6FF>十字形4格</color>的目標造成<color=#00F6FF>60%</color>的<link=\"30015\"><#FFAE07><u>濺射</u></color></link>傷害。",
  str_skill_desc_243601 = "對<color=#00F6FF>周圍2圈</color>內的4名敵人造成<color=#00F6FF>155%</color>傷害。午時狀態下，範圍擴大1圈。",
  str_skill_desc_243602 = "對<color=#00F6FF>周圍3圈</color>內的4名敵人造成<color=#00F6FF>160%</color>傷害。午時狀態下，範圍擴大1圈。",
  str_skill_desc_243603 = "對<color=#00F6FF>周圍4圈</color>內的4名敵人造成<color=#00F6FF>175%</color>傷害。午時狀態下，範圍擴大1圈。",
