  str_skill_desc_2002001 = "對<color=#00F6FF>周圍3圈</color>內的3個敵人造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2002002 = "對<color=#00F6FF>周圍4圈</color>內的3名敵人造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2002003 = "對最靠近的3個敵人造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2102001 = "對<color=#00F6FF>周圍3圈</color>內的3個敵人造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2102002 = "對<color=#00F6FF>周圍4圈</color>內的3名敵人造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2102003 = "對最靠近的3個敵人造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_300200 = "任選最多2名敵人造成<color=#00F6FF>{1}%</color>的傷害。所選格及沿途所有格子上的敵人向該區域中心位置<link=\"30081\"><#FFAE07><u>靠攏</u></color></link>。如果只點選1名敵人，則該敵人只會受到傷害，不會產生位移。",
  str_skill_desc_305200 = "任選最多2名敵人造成<color=#00F6FF>{1}%</color>的傷害，所選格及沿途所有格子上的敵人向該區域中心位置<link=\"30081\"><#FFAE07><u>靠攏</u></color></link>。如果只點選1名敵人，則該敵人只會受到傷害，不會產生位移。每牽引敵人<color=#00F6FF>1</color>格，最終傷害增加<color=#00F6FF>10%</color>。",
  str_skill_desc_320200 = "任選最多2名敵人造成<color=#00F6FF>{1}%</color>的傷害。所選格及沿途所有格子上的敵人向該區域中心位置<link=\"30081\"><#FFAE07><u>靠攏</u></color></link>。如果只點選1名敵人，則阿納托利自身視為另一名目標向中心靠攏。",
  str_skill_desc_325200 = "任選最多2名敵人造成<color=#00F6FF>{1}%</color>的傷害，所選格及沿途所有格子上的敵人向該區域中心位置<link=\"30081\"><#FFAE07><u>靠攏</u></color></link>。如果只點選1名敵人，則阿納托利自身視為另一名目標向中心靠攏。每牽引敵人<color=#00F6FF>1</color>格，最終傷害增加<color=#00F6FF>10%</color>。",
  str_skill_passive_desc_410200 = "阿納托利的連鎖技能對目標相鄰的隨機敵人額外造成<color=#00F6FF>{1}</color>的傷害。",
  str_skill_passive_desc_430200 = "阿納托利的連鎖技能對目標相鄰的隨機敵人額外造成<color=#00F6FF>{1}</color>的傷害。全隊所有<color=#00F6FF>單體傷害類型</color>的連鎖技能對<link=\"30082\"><#FFAE07><u>聚集</u></color></link>的敵人造成的最終傷害提高<color=#00F6FF>7%</color>。",
  str_skill_upgrade_desc_15020012 = "主動技能強化：主動技能變為<color=#FFFF00>先制攻擊</color>，進入戰鬥即可使用。",
  str_skill_upgrade_desc_15020015 = "主動技能強化：敵人每被牽引<color=#00F6FF>1</color>格，最終傷害增加<color=#00F6FF>10%</color>。",
  str_skill_name_290530101 = "駭黷印記",
  str_skill_desc_290530101 = "對目標直接造成傷害，並在目標所在格子生成印記。",
  str_skill_name_290530102 = "駭黷突撞",
  str_skill_desc_290530102 = "向目標所在方向突進最多2格，對沿途和終點周圍十字四格範圍內的目標造成傷害。若駭黷突撞未命中目標，赫利俄斯會追加施放「駭黷印記」。",
  str_skill_desc_290530312 = "朝目標方向突進最多2格，對沿途和終點周圍十字四格範圍內的目標造成傷害。",
  str_skill_name_290530103 = "駭黷躍撲",
  str_skill_desc_290530103 = "若目標處於技能範圍內，赫利俄斯會躍至目標身邊，落地時造成大量傷害並擊退目標。若駭黷躍撲未能擊中目標，或目標未處於駭黷躍撲的技能範圍內，赫利俄斯會追加施放「駭黷印記」。",
  str_skill_name_290530104 = "駭黷狂襲",
  str_skill_desc_290530104 = "赫利俄斯沿著「駭黷印記」的生成順序，依次突進至印記位置，隨後突進至目標周圍，對沿途和終點一定範圍內的目標造成高額傷害，並同時將一部分瘀傷值轉化為生命值。",
  str_skill_name_215009011 = "普通攻擊",
  str_skill_desc_215009011 = "移動後對範圍內的敵人發動一次攻擊。",
  str_skill_name_11150713 = "危域源泉",
  str_skill_desc_11150713 = "回到危險區域內可回復部分生命值，並永久強化自身。",
  str_skill_name_290530302 = "駭黷突撞",
  str_skill_desc_290530302 = "朝目標方向突進最多2格，對沿途和終點周圍十字四格範圍內的目標造成傷害。",
  str_skill_desc_11150313 = "神祕的光之結晶，經過其所在格子時可觸發。觸發後會召喚雷電攻擊所有目標（包含光靈）。",
  str_skill_name_290500102 = "捕食",
  str_skill_name_290500112 = "捕食·產卵",
  str_skill_name_290500103 = "圍獵",
  str_skill_name_290500113 = "圍獵+",
  str_skill_name_290500104 = "群集徵召",
  str_skill_name_290500114 = "群集徵召+",
  str_skill_desc_290500102 = "盤絲蛛后飛撲向牠的食物，佈下蛛網鎖定格子，並對光靈造成傷害。",
  str_skill_desc_290500112 = "盤絲蛛后飛撲向牠的食物，佈下蛛網鎖定格子，並對光靈造成傷害，同時在場上召喚蛛卵。",
  str_skill_desc_290500103 = "盤絲蛛后用蛛網鎖定光靈周圍的格子，並召集子嗣撲向光靈造成傷害。",
  str_skill_desc_290500113 = "盤絲蛛后用蛛網鎖定光靈周圍的格子，並召集子嗣撲向光靈造成傷害。鎖定的格子1回合後會恢復原狀。",
  str_skill_desc_290500104 = "盤絲蛛后召集子嗣發動攻擊，子嗣會佈下蛛網鎖定大量格子。",
  str_skill_desc_290500114 = "盤絲蛛后召集子嗣發動攻擊，子嗣會佈下蛛網鎖定大量格子。鎖定的格子1回合後會恢復原狀。",
  str_skill_name_200240102 = "巡視",
  str_skill_name_200240103 = "捕食",
  str_skill_name_200240104 = "群集徵召",
  str_skill_desc_200240102 = "盤絲子嗣在蛛網的領地內巡視，發現敵人會立刻攻擊。",
  str_skill_desc_200240103 = "盤絲子嗣飛撲向牠的食物，力求以力量一擊斃命。",
  str_skill_desc_200240104 = "受到蛛后的召集，盤絲子嗣以群集的形式發起進攻。",
  str_skill_name_290530204 = "駭黷狂襲",
  str_skill_desc_290530204 = "赫利俄斯沿著「駭黷印記」的生成順序，依次突進至印記位置，隨後突進至目標周圍，對沿途和終點一定範圍內的目標造成高額傷害。同時，赫利俄斯會清除場上的駭黷印記，並根據清除的印記數量，將部分瘀傷值轉化為生命值。",
  str_skill_name_290530404 = "駭黷狂襲",
  str_skill_desc_290530404 = "赫利俄斯沿著「駭黷印記」的生成順序，依次突進至印記位置，隨後突進至目標周圍，對沿途和終點一定範圍內的目標造成高額傷害，並同時將一部分瘀傷值轉化為生命值。",
  str_skill_upgrade_desc_16020113 = "主動技能強化：<color=#FFFF00>「舊日魂呼」</color>技能變為<color=#FFFF00>先制攻擊</color>，進入戰鬥即可使用。",
  str_skill_upgrade_desc_16020116 = "主動技能強化：<color=#FFFF00>「芭芭雅嘎繭生」</color>技能冷卻回合<color=#FFFF00>-1</color>。",
  str_skill_upgrade_refine_desc_16020111 = "裝備技能強化：擁有護盾時的傷害基礎加成提升為<color=#FFFF00>15%</color>。",
  str_skill_upgrade_refine_desc_16020112 = "主動技能強化：<color=#FFFF00>「舊日魂呼」</color>獲得的護盾值提升為自身生命值的<color=#FFFF00>90%</color>。",
  str_skill_upgrade_refine_desc_16020113 = "裝備技能強化：當生命值達到最低時額外獲得最高的<color=#00F6FF>10%</color>傷害加成。",
  str_skill_name_2002011 = "餘烈無情",
