  str_skill_desc_2002012 = "對<color=#00F6FF>米字形16格</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2002013 = "對<color=#00F6FF>周圍2圈</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_passive_name_410201 = "薇羅妮卡相協",
  str_skill_passive_desc_410201 = "擁有護盾時，蜜雅·滌魂造成的所有傷害提高<color=#00F6FF>{1}</color>，並根據護盾值獲得額外傷害加成。當護盾值達全隊最大生命值的50%時，額外獲得最高的<color=#00F6FF>10%</color>傷害加成。",
  str_skill_passive_name_420201 = "薇羅妮卡相協",
  str_skill_passive_desc_420201 = "擁有護盾時，蜜雅·滌魂造成的所有傷害提高<color=#00F6FF>{1}</color>，並根據護盾值和當下的生命值百分比獲得額外傷害加成。當護盾值達到全隊最大生命值的50%時，額外獲得最高的<color=#00F6FF>10%</color>傷害加成；當生命值達到最低時，額外獲得最高的<color=#00F6FF>5%</color>傷害加成。",
  str_skill_passive_desc_4202011 = "擁有護盾時，蜜雅·滌魂造成的所有傷害提高<color=#00F6FF>15%</color>，並根據護盾值和當下的生命值百分比獲得額外傷害加成。當護盾值達到全隊最大生命值的50%時，額外獲得最高的<color=#00F6FF>10%</color>傷害加成；當生命值達到最低時，額外獲得最高的<color=#00F6FF>5%</color>傷害加成。",
  str_skill_passive_desc_4432011 = "擁有護盾時，蜜雅·滌魂造成的所有傷害提高<color=#00F6FF>15%</color>，並根據護盾值和當下的生命值百分比獲得額外傷害加成。當護盾值達到全隊最大生命值的50%時，額外獲得最高的<color=#00F6FF>10%</color>傷害加成；當生命值達到最低時，額外獲得最高的<color=#00F6FF>10%</color>傷害加成。",
