  str_skill_desc_3222031 = "消耗隊伍最大生命值的<color=#00F6FF>15%</color>，本回合連線的第一個格子視為<color=#00F6FF>彩色格子</color>。生命值不足時無法施放。",
  str_skill_desc_3252031 = "消耗隊伍最大生命值的<color=#00F6FF>10%</color>，本回合連線的第一個格子視為<color=#00F6FF>彩色格子</color>。生命值不足時無法施放。",
