  str_skill_passive_desc_430203 = "每當隊伍因為<color=#00F6FF>光靈的主動技能效果而損失生命值</color>時，獲得加晴<color=#00F6FF>{1}</color>基礎攻擊力的護盾。由加晴觸發該效果時，護盾量<color=#00F6FF>翻倍</color>。",
