  str_skill_name_3362022 = "破暗錚襲",
  str_skill_desc_2002021 = "對<color=#00F6FF>米字形16格</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2002022 = "對<color=#00F6FF>米字形24格</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2002023 = "對<color=#00F6FF>米字形最大</color>範圍造成<color=#00F6FF>{1}%</color>傷害，並在範圍中最遠的隨機1個可行走格子生成1把滅暗斷刃。該效果每回合最多觸發1次。\n\n",
  str_skill_desc_3002021 = "戰鬥開始時，技能冷卻回合<color=#00F6FF>-3</color>。從自身<color=#00F6FF>周圍3圈</color>內任選1個敵人所在的格子，造成<color=#00F6FF>500%</color>傷害，隨後在點選位置周圍2圈隨機<color=#00F6FF>3</color>個可行走格子生成滅暗斷刃。每拾取1把滅暗斷刃，技能冷卻回合<color=#00F6FF>-1</color>。",
  str_skill_desc_3032021 = "從自身<color=#00F6FF>周圍3圈</color>內任選1個敵人所在的格子，造成<color=#00F6FF>500%</color>傷害，隨後在點選位置周圍2圈隨機<color=#00F6FF>3</color>個可行走格子生成滅暗斷刃。每拾取1把滅暗斷刃，技能冷卻回合<color=#00F6FF>-1</color>。",
  str_skill_desc_3202021 = "戰鬥開始時，技能冷卻回合<color=#00F6FF>-3</color>。從自身<color=#00F6FF>周圍3圈</color>內任選1個敵人所在的格子，造成<color=#00F6FF>500%</color>加目標<color=#00F6FF>最大</color>生命值<color=#00F6FF>4%</color>的傷害（附加傷害受屬性剋制修正），隨後在點選位置周圍2圈隨機<color=#00F6FF>3</color>個可行走格子生成滅暗斷刃。每拾取1把滅暗斷刃，技能冷卻回合<color=#00F6FF>-1</color>。",
  str_skill_desc_3232021 = "從自身<color=#00F6FF>周圍3圈</color>內任選1個敵人所在的格子，造成<color=#00F6FF>500%</color>加目標<color=#00F6FF>最大</color>生命值<color=#00F6FF>4%</color>的傷害（附加傷害受屬性剋制修正），隨後在點選位置周圍2圈隨機<color=#00F6FF>3</color>個可行走格子生成滅暗斷刃。每拾取1把滅暗斷刃，技能冷卻回合<color=#00F6FF>-1</color>。",
  str_skill_desc_3402021 = "戰鬥開始時，技能冷卻回合<color=#00F6FF>-3</color>。任選自身<color=#00F6FF>周圍3圈</color>內1個敵人腳下的格子，造成<color=#00F6FF>500%</color>並附加目標<color=#00F6FF>最大</color>生命值<color=#00F6FF>4%</color>的傷害（附加傷害受屬性剋制修正），隨後在選擇位置周圍2圈隨機<color=#00F6FF>3</color>個可行走格子生成滅暗斷刃。每拾取/收回1柄滅暗斷刃，技能冷卻回合<color=#00F6FF>-1</color>。",
  str_skill_desc_3432021 = "任選自身<color=#00F6FF>周圍3圈</color>內1個敵人腳下的格子，造成<color=#00F6FF>500%</color>並附加目標<color=#00F6FF>最大</color>生命值<color=#00F6FF>4%</color>的傷害（附加傷害受屬性剋制修正），隨後在選擇位置周圍2圈隨機<color=#00F6FF>3</color>個可行走格子生成滅暗斷刃。每拾取/收回1柄滅暗斷刃，技能冷卻回合<color=#00F6FF>-1</color>。",
  str_skill_desc_3402022 = "戰鬥開始時，技能冷卻回合<color=#00F6FF>-3</color>。任選自身<color=#00F6FF>周圍3圈</color>內1個敵人腳下的格子，造成<color=#00F6FF>650%</color>並附加目標<color=#00F6FF>最大</color>生命值<color=#00F6FF>4%</color>的傷害（附加傷害受屬性剋制修正），隨後在選擇位置周圍2圈隨機<color=#00F6FF>3</color>個可行走格子生成滅暗斷刃。每拾取/收回1柄滅暗斷刃，技能冷卻回合<color=#00F6FF>-1</color>。",
  str_skill_desc_3432022 = "任選自身<color=#00F6FF>周圍3圈</color>內1個敵人腳下的格子，造成<color=#00F6FF>650%</color>並附加目標<color=#00F6FF>最大</color>生命值<color=#00F6FF>4%</color>的傷害（附加傷害受屬性剋制修正），隨後在選擇位置周圍2圈隨機<color=#00F6FF>3</color>個可行走格子生成滅暗斷刃。每拾取/收回1柄滅暗斷刃，技能冷卻回合<color=#00F6FF>-1</color>。",
  str_skill_desc_3402023 = "戰鬥開始時，技能冷卻回合<color=#00F6FF>-3</color>。從自身<color=#00F6FF>周圍3圈</color>內任選1個敵人所在的格子，造成<color=#00F6FF>650%</color>加目標<color=#00F6FF>最大</color>生命值<color=#00F6FF>4%</color>的傷害（附加傷害受屬性剋制修正），隨後在點選位置周圍2圈隨機<color=#00F6FF>3</color>個可行走格子生成滅暗斷刃。若擊殺目標，則在目標位置再生成1把滅暗斷刃。每拾取或收回1把滅暗斷刃，技能冷卻回合<color=#00F6FF>-1</color>。",
  str_skill_desc_3432023 = "從自身<color=#00F6FF>周圍3圈</color>內任選1個敵人所在的格子，造成<color=#00F6FF>650%</color>加目標<color=#00F6FF>最大</color>生命值<color=#00F6FF>4%</color>的傷害（附加傷害受屬性剋制修正），隨後在點選位置周圍2圈隨機<color=#00F6FF>3</color>個可行走格子生成滅暗斷刃。若擊殺目標，則在目標位置再生成1把滅暗斷刃。每拾取或收回1把滅暗斷刃，技能冷卻回合<color=#00F6FF>-1</color>。",
  str_skill_desc_3302022 = "任選<color=#00F6FF>1</color>把滅暗斷刃，將之收回。",
  str_skill_desc_3362022 = "任選<color=#00F6FF>1</color>把滅暗斷刃，將之收回。",
  str_skill_passive_name_410202 = "光之所至",
  str_skill_passive_name_420202 = "光之所至",
  str_skill_passive_name_430202 = "光之所至",
  str_skill_passive_desc_410202 = "每拾取1把滅暗斷刃，可累積1層「碎夜鳴能」；下次普通攻擊消耗1層「碎夜鳴能」，對目標額外造成<color=#00F6FF>當下</color>生命值<color=#00F6FF>{1}</color>的傷害（追加傷害最低為基礎攻擊力的<color=#00F6FF>{2}</color>，最高為<color=#00F6FF>{3}</color>）。",
  str_skill_passive_desc_420202 = "每拾取1把滅暗斷刃，可累積1層「碎夜鳴能」；下次普通攻擊消耗1層「碎夜鳴能」，對目標額外造成<color=#00F6FF>當下</color>生命值<color=#00F6FF>{1}</color>的傷害（追加傷害最低為基礎攻擊力的<color=#00F6FF>{2}</color>，最高為<color=#00F6FF>{3}</color>）。",
  str_skill_passive_desc_430202 = "每拾取或收回1把滅暗斷刃，可累積1層「碎夜鳴能」；下次普通攻擊消耗1層「碎夜鳴能」，對目標額外造成<color=#00F6FF>當下</color>生命值<color=#00F6FF>{1}</color>的傷害（追加傷害最低為基礎攻擊力的<color=#00F6FF>{2}</color>，最高為<color=#00F6FF>{3}</color>）。",
  str_skill_passive_desc_440202 = "每拾取/收回1柄滅暗斷刃可累積1層碎夜鳴能，下次普通攻擊消耗1層碎夜鳴，能對目標額外造成<color=#00F6FF>目前</color>生命值<color=#00F6FF>4%</color>的傷害（附加傷害不低於基礎攻擊力的<color=#00F6FF>150%</color>，不高於<color=#00F6FF>600%</color>）。",
  str_skill_upgrade_desc_16020213 = "主動技能強化：<color=#FFFF00>「長日無盡」</color>技能變為<color=#FFFF00>先制攻擊</color>，進入戰鬥即可使用。",
  str_skill_upgrade_desc_16020216 = "主動技能強化：<color=#FFFF00>「破暗錚襲」</color>技能冷卻回合數<color=#FFFF00>-1</color>（覺醒3階段生效）。",
  str_skill_upgrade_refine_desc_16020211 = "裝備技能強化：附加傷害的上限提升，不高於自身攻擊力的<color=#00F6FF>600%</color>。",
  str_skill_upgrade_refine_desc_16020212 = "主動技能強化：傷害提升至<color=#00F6FF>650%</color>。",
  str_skill_upgrade_refine_desc_16020213 = "主動技能強化：若擊殺目標，則在目標位置再生成1把滅暗斷刃。",
  str_skill_upgrade_refine_desc_15007811 = "裝備技能強化：敵人腳下每有1個森屬性格子，傷害加成提升<color=#00F6FF>1%</color>。",
  str_skill_upgrade_refine_desc_15007812 = "主動技能強化：範圍中心格子傷害加倍。",
  str_skill_upgrade_refine_desc_15007813 = "主動技能強化：若主動技能上回合就緒，本回合可選擇範圍變為<color=#00F6FF>周圍2圈</color>。",
  str_skill_passive_desc_4400781 = "知更對位於森屬性格子上的敵人的傷害增加<color=#00F6FF>10%</color>，敵人腳下每有1個森屬性格子，傷害加成提升<color=#00F6FF>1%</color>，隊伍中其他森屬性光靈獲得<color=#00F6FF>一半</color>的加成。",
