  str_skill_desc_3420782 = "選擇1個格子，對<color=#00F6FF>菱形13格</color>造成<color=#00F6FF>250%</color>的傷害，對中心格子造成兩倍傷害，同時將敵人所處位置最多1個格子轉成<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>。。",
  str_skill_desc_3400783 = "選擇1個格子，對<color=#00F6FF>菱形13格</color>造成<color=#00F6FF>250%</color>的傷害，對中心格子造成的傷害加倍。若主動技能上回合就緒，本回合可選擇範圍變為<color=#00F6FF>周圍2圈</color>。",
  str_skill_desc_3420783 = "選擇1個格子，對<color=#00F6FF>菱形13格</color>造成<color=#00F6FF>250%</color>的傷害，對中心格子造成兩倍傷害，同時將敵人所處位置最多1個格子轉成<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>。若主動技能上回合就緒，本回合可選擇範圍變為<color=#00F6FF>周圍2圈</color>。",
  str_skill_upgrade_refine_desc_15007511 = "裝備技能強化：普通攻擊附加中毒的機率提升為<color=#00F6FF>80%</color>。",
