  str_skill_desc_2202041 = "對最靠近的2名目標造成<color=#00F6FF>{1}%</color>的傷害。若只有1名目標，傷害提高<color=#00F6FF>50%</color>。",
  str_skill_desc_2202042 = "對最靠近的2名目標造成<color=#00F6FF>{1}%</color>的傷害。若只有1名目標，傷害提高<color=#00F6FF>50%</color>。",
  str_skill_desc_2202043 = "對最靠近的2名目標造成<color=#00F6FF>{1}%</color>的傷害。若只有1名目標，傷害提高<color=#00F6FF>50%</color>。",
  str_skill_desc_2302041 = "對最靠近的2名目標造成<color=#00F6FF>{1}%</color>的傷害。對3圈內的目標造成的傷害提高<color=#00F6FF>30%</color>；若只有1名目標，傷害提高<color=#00F6FF>50%</color>。",
  str_skill_desc_2302042 = "對最靠近的2名目標造成<color=#00F6FF>{1}%</color>的傷害。對3圈內的目標造成的傷害提高<color=#00F6FF>30%</color>；若只有1名目標，傷害提高<color=#00F6FF>50%</color>。",
  str_skill_desc_2302043 = "對最靠近的2名目標造成<color=#00F6FF>{1}%</color>的傷害。對3圈內的目標造成的傷害提高<color=#00F6FF>30%</color>；若只有1名目標，傷害提高<color=#00F6FF>50%</color>。",
  str_skill_desc_2502041 = "對最靠近的2名目標造成<color=#00F6FF>140%</color>的傷害。對3圈內的目標造成的傷害提高<color=#00F6FF>30%</color>；若只有1名目標，傷害提高<color=#00F6FF>65%</color>。",
  str_skill_desc_2502042 = "對最靠近的2名目標造成<color=#00F6FF>155%</color>的傷害。對3圈內的目標造成的傷害提高<color=#00F6FF>30%</color>；若只有1名目標，傷害提高<color=#00F6FF>65%</color>。",
  str_skill_desc_2502043 = "對最靠近的2名目標造成<color=#00F6FF>170%</color>的傷害。對3圈內的目標造成的傷害提高<color=#00F6FF>30%</color>；若只有1名目標，傷害提高<color=#00F6FF>65%</color>。",
  str_skill_desc_3002041 = "選擇1名目標使其進入<link=\"30083\"><#FFAE07><u>聖決</u></color></link>狀態，並施加等同於<color=#00F6FF>約書亞攻擊力200%</color>的聖決值。目標若無生命上限，則改為直接造成<color=#00F6FF>200%</color>無視防禦的傷害。對目標重複施放可累加聖決值，一旦目標的聖決值超過當下生命值，將受到無視護盾的斬殺傷害（仍受鎖血影響）。",
  str_skill_desc_3032041 = "選擇1名目標使其進入<link=\"30083\"><#FFAE07><u>聖決</u></color></link>狀態，並施加等同於<color=#00F6FF>約書亞攻擊力250%</color>的聖決值。目標若無生命上限，則改為直接造成<color=#00F6FF>250%</color>無視防禦的傷害。對目標重複施放可累加聖決值，一旦目標的聖決值超過當下生命值，將受到無視護盾的斬殺傷害（仍受鎖血影響）。",
  str_skill_desc_3062041 = "選擇1名目標使其進入<link=\"30083\"><#FFAE07><u>聖決</u></color></link>狀態，並施加等同於<color=#00F6FF>約書亞攻擊力250%+目標生命上限3%</color>的聖決值（不低於約書亞攻擊力<color=#00F6FF>120%</color>）。目標若無生命上限，則改為直接造成<color=#00F6FF>370%</color>無視防禦的傷害。對目標重複施放可累加聖決值，一旦目標的聖決值超過當下生命值，將受到無視護盾的斬殺傷害（仍受鎖血影響）。",
  str_skill_passive_desc_4102041 = "約書亞對<link=\"30083\"><#FFAE07><u>聖決</u></color></link>狀態的敵人造成無視所有護盾的<color=#00F6FF>{1}</color>傷害，並全部轉化為聖決值。",
  str_skill_upgrade_refine_desc_16020411 = "裝備技能強化：對聖決狀態目標造成的所有傷害提升為<color=#00F6FF>124%</color>。",
  str_skill_upgrade_refine_desc_16020412 = "連鎖技能強化：只有1名目標時，傷害提高<color=#00F6FF>65%</color>。",
  str_skill_upgrade_refine_desc_16020413 = "主動技能強化：有聖決狀態目標死亡時，立刻重設主動技能的冷卻時間。",
  str_skill_desc_3502041 = "選擇1名目標使其進入<link=\"30083\"><#FFAE07><u>聖決</u></color></link>狀態，並施加等同於<color=#00F6FF>約書亞攻擊力200%</color>的聖決值。目標若無生命上限，則改為直接造成<color=#00F6FF>200%</color>無視防禦的傷害。對目標重複施放可累加聖決值，一旦目標的聖決值超過當下生命值，將受到無視護盾的斬殺傷害（仍受鎖血影響）。有聖決狀態的目標死亡時，立刻重設主動技能的冷卻時間。",
  str_skill_desc_3532041 = "選擇1名目標使其進入<link=\"30083\"><#FFAE07><u>聖決</u></color></link>狀態，並施加等同於<color=#00F6FF>約書亞攻擊力250%</color>的聖決值。目標若無生命上限，則改為直接造成<color=#00F6FF>250%</color>無視防禦的傷害。對目標重複施放可累加聖決值，一旦目標的聖決值超過當下生命值，將受到無視護盾的斬殺傷害（仍受鎖血影響）。有聖決狀態的目標死亡時，立刻重設主動技能的冷卻時間。",
  str_skill_desc_3562041 = "選擇1名目標使其進入<link=\"30083\"><#FFAE07><u>聖決</u></color></link>狀態，並施加等同於<color=#00F6FF>約書亞攻擊力250%+目標生命上限3%</color>的聖決值（不低於約書亞攻擊力<color=#00F6FF>120%</color>）。目標若無生命上限，則改為直接造成<color=#00F6FF>370%</color>無視防禦的傷害。對目標重複施放可累加聖決值，一旦目標的聖決值超過當下生命值，將受到無視護盾的斬殺傷害（仍受鎖血影響）。有聖決狀態的目標死亡時，立刻重設主動技能的冷卻時間。",
  str_skill_passive_desc_4502041 = "約書亞對<link=\"30083\"><#FFAE07><u>聖決</u></color></link>狀態的敵人造成無視所有護盾的<color=#00F6FF>124%</color>傷害，並全部轉化為聖決值。",
