  str_skill_desc_2302052 = "對<color=#00F6FF>米字形16格</color>造成<color=#00F6FF>{1}%</color>的傷害，範圍內損壞格子的持續回合<color=#00F6FF>-2</color>。",
  str_skill_desc_2302053 = "對<color=#00F6FF>米字形24格</color>範圍造成<color=#00F6FF>{1}%</color>的傷害，範圍內損壞格子的持續回合<color=#00F6FF>-3</color>。",
  str_skill_desc_2362051 = "對<color=#00F6FF>周圍1圈</color>造成<color=#00F6FF>{1}%</color>的傷害，範圍內損壞格子的持續回合<color=#00F6FF>-2</color>。",
  str_skill_desc_2362052 = "對<color=#00F6FF>米字形16格</color>造成<color=#00F6FF>{1}%</color>的傷害，範圍內損壞格子的持續回合<color=#00F6FF>-3</color>。",
  str_skill_desc_2362053 = "對<color=#00F6FF>米字形24格</color>範圍造成<color=#00F6FF>{1}%</color>的傷害，範圍內損壞格子的持續回合<color=#00F6FF>-4</color>。",
  str_skill_desc_3002051 = "任選1個非損壞格子，在該位置生成1個持續9回合的損壞格子，之後將其<color=#00F6FF>十字相鄰4格</color>轉成水屬性。",
  str_skill_desc_3052051 = "任選1個非損壞格子，在該位置生成1個持續9回合的損壞格子，之後將其<color=#00F6FF>十字相鄰4格</color>轉成水屬性。",
  str_skill_passive_name_410205 = "見禮",
  str_skill_passive_name_430205 = "見禮",
  str_skill_passive_desc_410205 = "白蘭 · 浣心在水屬性格子上不會發動普通攻擊。每移動經過1個水屬性格子，若其<color=#00F6FF>十字相鄰4格</color>上有敵人，則獲得1層見禮印記，每層印記增加<color=#00F6FF>{1}</color>連鎖技能傷害率，同時使連鎖技能觸發條件<color=#00F6FF>-1</color>。連鎖技能施放後清空層數。",
  str_skill_passive_desc_430205 = "白蘭 · 浣心在水屬性格子上不會發動普通攻擊。每移動經過1個水屬性格子，若其<color=#00F6FF>十字相鄰4格</color>上有敵人或損壞格子，則獲得1層見禮印記，每層印記增加<color=#00F6FF>{1}</color>連鎖技能傷害率，同時使連鎖技能觸發條件<color=#00F6FF>-1</color>。連鎖技能施放後清空層數。",
  str_skill_upgrade_desc_15020512 = "主動技能強化：主動技能變為<color=#FFFF00>先制攻擊</color>，進入戰鬥即可使用。",
  str_skill_upgrade_desc_15020515 = "連鎖技能強化：使連鎖技能範圍內的損壞格子持續回合減少<color=#FFFF00>2/3/4</color>。（覺醒2階段生效）。",
  str_skill_passive_desc_440097 = "普通攻擊變為2連擊，每次傷害為基礎傷害的<color=#00F6FF>60%</color>。每次攻擊有<color=#00F6FF>20%</color>的機率使傷害增加<color=#00F6FF>50%</color>，每1次COMBO額外增加<color=#00F6FF>1%</color>的觸發機率，最高不超過50%。",
  str_skill_name_3400971 = "凜厲剔·變體I",
  str_skill_name_3400972 = "凜厲剔·變體II",
  str_skill_name_3420971 = "凜厲剔·變體I",
  str_skill_name_3420972 = "凜厲剔·變體II",
  str_skill_desc_3400971 = "<color=#FFFF00>施放後技能冷卻回合+1</color>。瞬移至任意位置，對起點和終點之間矩形範圍內的敵人造成傷害。矩形空間越小，造成的傷害越高，最高可造成<color=#00F6FF>600%</color>傷害。",
  str_skill_desc_3400972 = "<color=#FFFF00>施放後技能冷卻回合-1</color>。瞬移到<color=#FFFF00>周圍3圈</color>任意位置，對起點和終點之間矩形範圍內的敵人造成傷害。矩形空間越小，造成的傷害越高，最高可造成<color=#00F6FF>360%</color>傷害。",
  str_skill_desc_3420971 = "<color=#FFFF00>施放後技能冷卻回合+1</color>。瞬移至任意位置，對起點和終點之間矩形範圍內的敵人造成傷害。矩形空間越小，造成的傷害越高，最高可造成<color=#00F6FF>720%</color>傷害。",
  str_skill_desc_3420972 = "<color=#FFFF00>施放後技能冷卻回合-1</color>。瞬移到<color=#FFFF00>周圍3圈</color>任意位置，對起點和終點之間矩形範圍內的敵人造成傷害。矩形空間越小，造成的傷害越高，最高可造成<color=#00F6FF>480%</color>傷害。",
  str_skill_upgrade_refine_desc_15009711 = "<color=#00F6FF>新增主動技能變體I</color>：<color=#FFFF00>施放後技能冷卻回合+1</color>。瞬移至任意位置，對起點和終點之間矩形範圍內的敵人造成傷害。矩形空間越小，造成的傷害越高，主動技能造成傷害增加<color=#FFFF00>120%</color>。",
  str_skill_upgrade_refine_desc_15009712 = "裝備技能強化：每1次COMBO額外增加<color=#00F6FF>1%</color>的傷害增加觸發機率，最高不超過50%。",
  str_skill_upgrade_refine_desc_15009713 = "<color=#00F6FF>新增主動技能變體II</color>：<color=#FFFF00>施放後技能冷卻回合-1</color>。瞬移到<color=#FFFF00>周圍3圈</color>任意位置，對起點和終點之間矩形範圍內的敵人造成傷害。矩形空間越小，造成的傷害越高，主動技能造成傷害降低<color=#FFFF00>120%</color>。",
  str_skill_upgrade_refine_desc_16002711 = "主動技能強化：主動技能傷害係數提升為<color=#00F6FF>360%</color>。",
  str_skill_upgrade_refine_desc_16002712 = "裝備技能強化：施放主動技能時獲得<color=#00F6FF>2</color>層靜雷印記。",
  str_skill_upgrade_refine_desc_16002713 = "裝備技能強化：普通攻擊時消耗1層靜雷印記對敵人造成當下生命值<color=#00F6FF>2.5%</color>的額外傷害，該傷害不低於米迦勒攻擊力的<color=#00F6FF>50%</color>。",
  str_skill_desc_3400271 = "衝刺到所選位置，對沿途及相鄰格子的敵人造<color=#00F6FF>360%</color>的傷害，額外造成敵人<color=#00F6FF>5%</color>現有生命值的傷害。",
  str_skill_desc_3430271 = "衝刺到所選位置，對沿途及鄰格敵人造成<color=#00F6FF>360%</color>傷害，額外傷害敵人<color=#00F6FF>5%</color>生命值，並根據位移距離，在所選位置立刻施放1次連鎖技能。",
  str_skill_desc_3400272 = "衝刺到所選位置，對沿途及相鄰格子的敵人造<color=#00F6FF>360%</color>的傷害，額外造成敵人<color=#00F6FF>5%</color>現有生命值的傷害。",
  str_skill_desc_3430272 = "衝刺到所選位置，對沿途及鄰格敵人造成<color=#00F6FF>360%</color>傷害，額外傷害敵人<color=#00F6FF>5%</color>生命值，並根據位移距離，在所選位置立刻施放1次連鎖技能。",
  str_skill_desc_4400271 = "每回合開始施放連鎖技能時各獲得1層靜雷印記，施放主動技能時獲得2層。普通攻擊時消耗1層印記對敵人造成當下生命值<color=#00F6FF>2.5%</color>的額外傷害。",
  str_skill_desc_440027 = "每回合開始、施放連鎖技能時各獲得1層靜雷印記，施放主動技能時獲得2層。普通攻擊時消耗1層印記對敵人造成當下生命值<color=#00F6FF>2.5%</color>的額外傷害，該傷害不低於米迦勒攻擊力的<color=#00F6FF>50%</color>。",
  str_skill_name_490250101 = "末逐·洗新蜃像",
  str_skill_desc_490250101 = "末逐·米洛斯吸收周圍2圈內的弱化格子與強化格子，並對周圍1圈內的目標造成傷害；根據吸收數量增幅本次傷害。",
  str_skill_name_490250102 = "末逐·犧之終結",
  str_skill_desc_490250102 = "末逐·米洛斯吸收場上所有的弱化格子與強化格子，然後向光靈射擊造成傷害；每吸收1個會額外造成1次傷害。",
  str_skill_name_490250103 = "末逐·洗新蜃像+",
  str_skill_desc_490250103 = "末逐·米洛斯吸收周圍2圈內的弱化格子與強化格子，並對周圍1圈內的目標造成傷害；根據吸收數量增幅本次傷害。",
  str_skill_name_490250104 = "末逐·犧之終結+",
  str_skill_desc_490250104 = "末逐·米洛斯吸收場上所有的弱化格子與強化格子，然後向光靈射擊造成傷害；每吸收1個會額外造成1次傷害。",
  str_skill_upgrade_refine_desc_16002811 = "裝備技能強化：恢復係數提升為<color=#00F6FF>1.8%</color>。",
  str_skill_upgrade_refine_desc_16002812 = "主動技能強化：恢復係數提升為<color=#00F6FF>250%</color>。",
  str_skill_upgrade_refine_desc_16002813 = "主動技能強化：隊伍生命值越低，恢復效果越高，最高提供<color=#00F6FF>100%加成</color>。",
  str_skill_passive_desc_450028 = "每當地圖生成水格子時，每個格子為隊伍恢復等同於拉斐爾最大生命值<color=#00F6FF>1.8%</color>的生命值。隊伍生命值越低，恢復效果越高，最多提供<color=#00F6FF>100%加成</color>。",
  str_skill_desc_350028 = "為隊伍回復相當於拉斐爾攻擊力<color=#00F6FF>250%</color>的生命值，同時重設<color=#00F6FF>所有非水屬性</color>的格子。",
  str_skill_desc_356028 = "為隊伍回復相當於拉斐爾攻擊力<color=#00F6FF>250%</color>的生命值，同時重設<color=#00F6FF>所有非水屬性</color>的格子，<color=#00F6FF>小機率</color>生成水屬性格子。",
  str_skill_desc_360028 = "為隊伍回復相當於拉斐爾攻擊力<color=#00F6FF>250%</color>的生命值，同時重設<color=#00F6FF>所有非水屬性</color>的格子。隊伍生命值越低，恢復效果越高，最高提供<color=#00F6FF>100%加成</color>。",
  str_skill_desc_366028 = "為隊伍回復相當於拉斐爾攻擊力<color=#00F6FF>250%</color>的生命值，同時重設<color=#00F6FF>所有非水屬性</color>的格子，並<color=#00F6FF>低機率</color>生成水屬性格子。隊伍生命值越低，恢復效果越高，最高提供<color=#00F6FF>100%加成</color>。",
  str_skill_upgrade_refine_desc_15007011 = "主動技能強化：傷害係數提升為<color=#00F6FF>100%</color>。",
  str_skill_upgrade_refine_desc_15007012 = "裝備技能強化：傷害係數提升為<color=#00F6FF>60%</color>。",
  str_skill_upgrade_refine_desc_15007013 = "主動技能強化：每次造成傷害有<color=#00F6FF>25%</color>機率為敵人附加1層<link=\"10002\"><#FFAE07><u>灼燒</u></color></link>。",
  str_skill_desc_350070 = "隨機對場上的敵人造成<color=#00F6FF>5</color>次<color=#00F6FF>100%</color>的傷害，所在位置<color=#00F6FF>周圍1圈</color>內每有1個火屬性格子，再額外攻擊1次。",
  str_skill_desc_355070 = "隨機對場上的敵人造成<color=#00F6FF>6</color>次<color=#00F6FF>100%</color>的傷害，所在位置<color=#00F6FF>周圍12格</color>每有1個火屬性格子，再額外攻擊1次。",
  str_skill_desc_360070 = "隨機對場上的敵人造成<color=#00F6FF>5</color>次<color=#00F6FF>100%</color>的傷害，所在位置<color=#00F6FF>周圍1圈</color>內每有1個火屬性格子，再額外攻擊1次。每次造成傷害有<color=#00F6FF>25%</color>機率為敵人附加1層<link=\"10002\"><#FFAE07><u>灼燒</u></color></link>。",
  str_skill_desc_365070 = "隨機對場上的敵人造成<color=#00F6FF>6</color>次<color=#00F6FF>100%</color>的傷害，所在位置<color=#00F6FF>周圍12格</color>每有1個火屬性格子，再額外攻擊1次。每次造成傷害有<color=#00F6FF>25%</color>機率為敵人附加1層<link=\"10002\"><#FFAE07><u>灼燒</u></color></link>。",
  str_skill_passive_desc_450070 = "普通攻擊有<color=#00F6FF>75%</color>機率觸發1次紅龍攻擊，傷害為莉奧娜普通攻擊傷害的<color=#00F6FF>60%</color>，並附加1層<link=\"10002\"><#FFAE07><u>灼燒</u></color></link>，持續2回合。",
  str_skill_desc_400140110 = "當光靈開始移動後，碩腕會蜷縮起來躲避攻擊，並為米倫·戈蒂埃恢復生命值。",
  str_skill_upgrade_desc_16020713 = "裝備技能強化：觸發所需漣漪波層數降低至5；消耗漣漪波層數降低至5的倍數。（覺醒1階段生效）",
  str_skill_upgrade_desc_16020716 = "主動技能強化：選擇的格子轉為水屬性。",
