  str_skill_name_3362071 = "夢醒與群舞",
  str_skill_desc_3002071 = "任選1個格子，讓該列上的水屬性格子向所選格<link=\"30084\"><#FFAE07><u>聚攏</u></color></link>。",
  str_skill_desc_3062071 = "任選1個格子，將該格轉為水屬性後，讓該列上的水屬性格子向所選格<link=\"30084\"><#FFAE07><u>聚攏</u></color></link>。",
  str_skill_desc_3202071 = "任選1個格子，讓該列上的水屬性格子向所選格<link=\"30084\"><#FFAE07><u>聚攏</u></color></link>，重複點選可切換<color=#00F6FF>行/列</color>範圍。",
  str_skill_desc_3262071 = "任選1個格子，將該格轉為水屬性後，讓該列上的水屬性格子向所選格<link=\"30084\"><#FFAE07><u>聚攏</u></color></link>，重複點選可切換<color=#00F6FF>行/列</color>範圍。",
  str_skill_desc_3302071 = "任選1個格子，讓該列上的水屬性格子向所選格<link=\"30084\"><#FFAE07><u>聚攏</u></color></link>，重複點選可切換<color=#00F6FF>行/列</color>範圍。主動技能範圍內每有1個水屬性格子則獲得1層漣漪波。",
  str_skill_desc_3362071 = "任選1個格子，將該格轉為水屬性後，讓該列上的水屬性格子向所選格<link=\"30084\"><#FFAE07><u>聚攏</u></color></link>，重複點選可切換<color=#00F6FF>行/列</color>範圍。主動技能範圍內每有1個水屬性格子則獲得1層漣漪波。",
  str_skill_passive_name_410207 = "朝暮漣漪",
  str_skill_passive_desc_410207 = "隊伍內光靈本回合首次施放主動技能時希南獲得1層<link=\"30085\"><#FFAE07><u>漣漪波</u></color></link>，獲得時若漣漪波層數不小於7，消耗漣漪波恢復等同希南最大生命值<color=#00F6FF>{1}</color>的生命值。",
  str_skill_passive_name_416207 = "朝暮漣漪",
  str_skill_passive_desc_416207 = "隊伍內光靈本回合首次施放主動技能時希南獲得1層<link=\"30086\"><#FFAE07><u>漣漪波</u></color></link>，獲得時若漣漪波層數不小於5，消耗漣漪波恢復等同希南最大生命值<color=#00F6FF>{1}</color>的生命值。",
  str_skill_desc_350025 = "選擇<color=#00F6FF>3列</color>或<color=#00F6FF>3行</color>造成<color=#00F6FF>300%</color>傷害並擊退敵人，中間行或列傷害為兩側的1.7倍。重設範圍內<color=#00F6FF>非火屬性</color>格子。",
  str_skill_desc_356025 = "選擇<color=#00F6FF>3列</color>或<color=#00F6FF>3行</color>造成<color=#00F6FF>300%</color>傷害並擊退敵人，中間行或列傷害為兩側的1.7倍。重設範圍內<color=#00F6FF>非火屬性</color>格子，<color=#00F6FF>小機率</color>生成火屬性格子。",
  str_skill_desc_360025 = "選擇<color=#00F6FF>3列</color>或<color=#00F6FF>3行</color>造成<color=#00F6FF>340%</color>傷害並擊退敵人，中間行或列傷害為兩側的1.7倍。重設範圍內<color=#00F6FF>非火屬性</color>格子。",
  str_skill_desc_366025 = "選擇<color=#00F6FF>3列</color>或<color=#00F6FF>3行</color>造成<color=#00F6FF>340%</color>傷害並擊退敵人，中間行或列傷害為兩側的1.7倍。重設範圍內<color=#00F6FF>非火屬性</color>格子，<color=#00F6FF>小機率</color>生成火屬性格子。",
  str_skill_passive_desc_440025 = "普通攻擊<color=#00F6FF>可攻擊斜方向</color>，普通攻擊附加攻擊力<color=#00F6FF>12%</color>的傷害，可無視防禦。",
  str_skill_upgrade_refine_desc_16002511 = "裝備技能強化：傷害係數提升為<color=#00F6FF>12%</color>。",
  str_skill_upgrade_refine_desc_16002512 = "主動技能強化：中間行或列的傷害提升為<color=#00F6FF>1.7</color>倍。",
  str_skill_upgrade_refine_desc_16002513 = "主動技能強化：傷害係數提升為<color=#00F6FF>340%</color>。",
