  str_skill_upgrade_desc_16020613 = "主動技能強化：主動技能變為<color=#FFFF00>先制攻擊</color>，進入戰鬥即可使用。",
  str_skill_upgrade_desc_16020616 = "主動技能強化：技能冷卻回合<color=#FFFF00>-1</color>。",
  str_skill_upgrade_refine_desc_15002411 = "裝備技能強化：傷害係數提升為<color=#00F6FF>65%</color>。",
  str_skill_upgrade_refine_desc_15002412 = "主動技能強化：兩處連鎖技能的最終傷害均增加<color=#00F6FF>35%</color>。",
  str_skill_upgrade_refine_desc_15002413 = "連鎖技能強化：施放主動技能的回合，連鎖觸發所需格子數量<color=#00F6FF>-1</color>。",
  str_skill_passive_desc_440024 = "普通攻擊對位於火屬性格子上的敵人額外造成<color=#00F6FF>65%</color>的傷害。",
  str_skill_desc_340024 = "標記1個格子。本次連線格子數量達到觸發連鎖技能所需格子數量的<color=#00F6FF>1.5</color>倍時，則在標記位置施放1次連鎖技能（兩處連鎖技能的最終傷害均增加<color=#00F6FF>35%</color>）。",
  str_skill_desc_342024 = "標記1個格子。本次連線格子數量達到觸發連鎖技能所需格子數量的<color=#00F6FF>1.5</color>倍時，則在標記位置施放1次連鎖技能（兩處連鎖技能的最終傷害均增加<color=#00F6FF>35%</color>）。",
  str_skill_desc_345024 = "標記1個格子。本次連線格子數量達到觸發連鎖技能所需格子數量的<color=#00F6FF>1.5</color>倍時，則在標記位置施放1次連鎖技能（兩處連鎖技能的最終傷害均增加<color=#00F6FF>35%</color>）。",
  str_skill_desc_240241 = "對<color=#00F6FF>周圍1圈</color>造成<color=#00F6FF>140%</color>的傷害。施放主動技能的回合，連鎖觸發所需格子數量<color=#00F6FF>-1</color>。",
  str_skill_desc_240242 = "對<color=#00F6FF>菱形12格</color>造成<color=#00F6FF>145%</color>的傷害。施放主動技能的回合，連鎖觸發所需格子數量<color=#00F6FF>-1</color>。",
  str_skill_desc_240243 = "對<color=#00F6FF>米字形16格</color>造成<color=#00F6FF>155%</color>的傷害。施放主動技能的回合，連鎖觸發所需格子數量<color=#00F6FF>-1</color>。",
  str_skill_name_290560101 = "神女蝴蝶·藤刺",
  str_skill_desc_290560101 = "向光靈移動後，對前方1排或1列範圍內目標造成傷害。",
  str_skill_name_290560102 = "神女蝴蝶·授粉",
  str_skill_desc_290560102 = "向光靈移動後，對自身周圍菱形12格範圍內所有目標造成傷害，並附加毒素，同時催化範圍內植物成長。",
  str_skill_name_290560103 = "神女蝴蝶·彌爆",
  str_skill_desc_290560103 = "瞄準光靈並對光靈周圍菱形12格範圍內所有目標造成傷害，並附加毒素，同時催化範圍內植物成長（必中）。",
  str_skill_name_200260101 = "薩黛絲妖蟄伏",
  str_skill_desc_200260101 = "處於幼年型態，光靈無法攻擊。",
  str_skill_name_200260201 = "薩黛絲妖生長",
  str_skill_desc_200260201 = "處於變態期，光靈可以攻擊，但薩黛絲妖還無法攻擊光靈。",
  str_skill_name_200260301 = "薩黛絲妖異詭蜇",
  str_skill_desc_200260301 = "瞄準並對光靈造成傷害，附加毒素。",
  str_skill_name_53310002 = "神女蝴蝶·授粉",
  str_skill_desc_53310002 = "催化自身周圍菱形12格範圍內植物成長。",
  str_skill_desc_3300051 = "<color=#FFFF00>施放後技能冷卻回合+1</color>。對<color=#00F6FF>全體</color>敵人造成<color=#00F6FF>{1}%</color>的傷害，敵人生命值百分比越低，傷害越高（最高增加100%）。每層靈魂造成的衝擊傷害提升至130%。",
  str_skill_desc_3300052 = "<color=#FFFF00>施放後技能冷卻回合-1</color>。對<color=#00F6FF>全體</color>敵人造成<color=#00F6FF>{1}%</color>的傷害，敵人生命百分比越低，傷害越高（最高增加100%）。光靈主動技能擊殺敵人後不會獲得靈魂。",
  str_skill_desc_3360051 = "<color=#FFFF00>施放後技能冷卻回合+1</color>。對<color=#00F6FF>全體</color>敵人造成<color=#00F6FF>{1}%</color>的傷害，敵人生命值百分比越低，傷害越高（最高增加100%）。每層靈魂造成的衝擊傷害提升至130%。",
  str_skill_desc_3360052 = "<color=#FFFF00>施放後技能冷卻回合-1</color>。對<color=#00F6FF>全體</color>敵人造成<color=#00F6FF>{1}%</color>的傷害，敵人生命百分比越低，傷害越高（最高增加100%）。光靈主動技能擊殺敵人後不會獲得靈魂。",
  str_skill_passive_desc_443005 = "<color=#00F6FF>光靈</color>主動技能擊殺敵人後獲得1層靈魂，最大<color=#00F6FF>8</color>層。每層靈魂對單個敵人施放1次<color=#00F6FF>100%</color>攻擊力的衝擊，並增加蜜雅<color=#00F6FF>5%</color>的連鎖傷害和<color=#00F6FF>3%</color>的普通攻擊傷害。",
  str_skill_upgrade_refine_desc_16000511 = "<color=#00F6FF>新增主動技能變體I</color>：<color=#FFFF00>施放後技能冷卻回合+1</color>。每層靈魂造成的衝擊傷害提升至130%。",
  str_skill_upgrade_refine_desc_16000512 = "<color=#00F6FF>新增主動技能變體II</color>：<color=#FFFF00>施放後技能冷卻回合-1</color>。光靈主動技能擊殺敵人後不會獲得靈魂。",
  str_skill_upgrade_refine_desc_16000513 = "裝備技能強化：靈魂層數上限提升至<color=#00F6FF>8</color>層。",
  str_skill_desc_8001201 = "立即在附近召喚一隻影鬼。",
  str_skill_desc_8001441 = "全場大量召喚灰蟲，並為自身累積30層提供攻擊力的能量印記。",
  str_skill_desc_800128107 = "暗潮喚塔者瞬移到目標附近，獲得一定數量的次數護盾，並且準備施放大範圍攻擊。本回合暗潮喚塔者的防禦力大幅下降！",
  str_skill_desc_8001391 = "使用粗壯的尾部攻擊自身攻擊範圍內的目標，造成2次傷害。",
  str_skill_desc_800141 = "使用尾部凝聚能量尖刺，遠程攻擊位於攻擊範圍內的目標，造成2次傷害。",
  str_skill_desc_800139 = "使用粗壯的尾部攻擊自身攻擊範圍內的目標。",
  str_skill_desc_800140 = "使用尾部凝聚能量尖刺，遠程攻擊位於攻擊範圍內的目標。",
  str_skill_name_52200191 = "醒轉·域",
