  str_skill_desc_5010832 = "攻擊範圍內的目標，並為目標施加1層破裂印記。印記層數越多，目標防禦越低。",
  str_skill_desc_5010841 = "發出怒吼，對范圍內的敵方目標施加20層破裂印記，印記層數越多，目標防禦越低。",
