  str_skill_desc_200310102 = "劈砍敵人造成傷害，然後踢擊敵人再次造成少量傷害並擊退敵人。",
  str_skill_name_200310103 = "戰友激勵",
  str_skill_desc_200310103 = "增加周圍2圈內啟光士兵的行動力，並將自己和範圍內啟光士兵累積的部分瘀傷值轉化為生命值。",
  str_skill_name_200290103 = "L5型機槍壓制",
  str_skill_desc_200290103 = "敵人處於周圍20格範圍時，使用連發槍對敵人造成傷害。",
  str_skill_name_200290104 = "L5型突進衝擊",
  str_skill_desc_200290104 = "敵人不處於周圍20格範圍時，朝著十字方向上距離敵人最近的位置衝撞，隨後對終點前方的敵人造成傷害並擊退2格。",
  str_skill_name_200300101 = "扇形火焰噴射",
  str_skill_desc_200300101 = "對前方扇形範圍內的所有目標造成傷害並添加1層灼燒效果，並在範圍內可行走的格子上生成火焰。",
  str_skill_name_200340103 = "污蠱戰掃",
  str_skill_desc_200340103 = "揮動武器對前方敵人造成傷害。",
  str_skill_name_200340104 = "污蠱戰突",
  str_skill_desc_200340104 = "突刺武器對前方敵人造成傷害。",
  str_skill_name_200270101 = "啟光戰地急救法",
  str_skill_desc_200270101 = "為自身十字相鄰4格內生命值最低的啟光士兵恢復生命值，並將自己累積的部分瘀傷值轉化為生命值。",
  str_skill_name_200280101 = "呼叫支援",
  str_skill_desc_200280101 = "召喚1名啟光士兵進入戰場。",
  str_skill_upgrade_desc_16020913 = "主動技能強化：主動技能變為<color=#FFFF00>先制攻擊</color>，進入戰鬥即可使用。",
  str_skill_upgrade_desc_16020916 = "主動技能強化：技能冷卻回合<color=#FFFF00>-1</color>。",
  str_skill_name_2002091 = "陣列衝擊",
  str_skill_name_2002092 = "陣列衝擊",
  str_skill_name_2002093 = "陣列衝擊",
  str_skill_name_2002094 = "陣列衝擊",
  str_skill_desc_2002091 = "跳向<color=#00F6FF>菱形12格</color>範圍內最近且生命值最高的敵人，對<color=#00F6FF>方形9格</color>造成<color=#00F6FF>150%</color>的傷害。",
  str_skill_desc_2002092 = "跳向<color=#00F6FF>菱形12格</color>範圍內最近且生命值最高的敵人，對<color=#00F6FF>菱形13格</color>造成<color=#00F6FF>160%</color>的傷害。",
  str_skill_desc_2002093 = "跳向<color=#00F6FF>菱形12格</color>範圍內最近且生命值最高的敵人，對<color=#00F6FF>米字17格</color>造成<color=#00F6FF>170%</color>的傷害。",
  str_skill_desc_2002094 = "跳向<color=#00F6FF>菱形12格</color>範圍內最近且生命值最高的敵人，對<color=#00F6FF>方形25格</color>造成<color=#00F6FF>200%</color>的傷害。單次連線中每造成1次傷害觸發條件-1。",
  str_skill_name_3002091 = "巡弋雷鳴",
  str_skill_name_3002092 = "巡弋雷鳴·變體II",
  str_skill_name_3002093 = "巡弋雷鳴·變體I",
  str_skill_name_3062091 = "巡弋雷鳴",
  str_skill_name_3062092 = "巡弋雷鳴·變體II",
  str_skill_name_3062093 = "巡弋雷鳴·變體I",
  str_skill_desc_3002091 = "任選1格，對方形25格造成<color=#00F6FF>200%</color>的傷害。若自身位於所選範圍內，最終傷害提高<color=#00F6FF>30%</color>。",
  str_skill_desc_3002092 = "<color=#FFFF00>施放後技能冷卻回合-1</color>。任選1格，對方形9格造成<color=#00F6FF>100%</color>的傷害。若自身位於所選範圍內，最終傷害提高<color=#00F6FF>30%</color>。",
  str_skill_desc_3002093 = "<color=#FFFF00>施放後技能冷卻回合+1</color>。對全部格子造成300%的傷害，最終傷害提高<color=#00F6FF>30%</color>。",
  str_skill_desc_3062091 = "任選1格，對方形25格造成<color=#00F6FF>200%</color>的傷害。若自身位於所選範圍內，最終傷害提高<color=#00F6FF>30%</color>。",
  str_skill_desc_3062092 = "<color=#FFFF00>施放後技能冷卻回合-1</color>。任選1格，對方形9格造成<color=#00F6FF>100%</color>的傷害。若自身位於所選範圍內，最終傷害提高<color=#00F6FF>30%</color>。",
  str_skill_desc_3062093 = "<color=#FFFF00>施放後技能冷卻回合+1</color>。對全部格子造成<color=#00F6FF>300%</color>的傷害，最終傷害提高<color=#00F6FF>30%</color>。",
  str_skill_passive_name_410209 = "雷鳴霆勢",
  str_skill_passive_name_420209 = "雷鳴霆勢",
  str_skill_passive_name_430209 = "雷鳴霆勢",
  str_skill_passive_desc_410209 = "遭到主動技能攻擊的敵人會連續<color=#00F6FF>2回合</color>進入雷鳴狀態，我方每連線移動1格就會對周圍<color=#00F6FF>菱形12格</color>範圍內雷鳴狀態下的敵人造成<color=#00F6FF>{1}</color>的傷害。",
  str_skill_passive_desc_420209 = "遭到主動技能攻擊的敵人會連續<color=#00F6FF>2回合</color>進入雷鳴狀態，我方每連線移動1格就會對周圍<color=#00F6FF>菱形12格</color>範圍內雷鳴狀態下的敵人造成<color=#00F6FF>{1}</color>的傷害。",
  str_skill_passive_desc_430209 = "普通攻擊可攻擊<color=#00F6FF>十字8格</color>的敵人。遭到主動技能攻擊的敵人會連續<color=#00F6FF>2回合</color>進入雷鳴狀態，我方每連線移動1格就會對周圍<color=#00F6FF>菱形12格</color>範圍內雷鳴狀態下的敵人造成<color=#00F6FF>{1}</color>的傷害。",
  str_skill_passive_desc_440209 = "普通攻擊可攻擊<color=#00F6FF>十字8格</color>的敵人。遭到主動技能攻擊的敵人會連續<color=#00F6FF>2回合</color>進入雷鳴狀態，我方每連線移動1格就會對周圍<color=#00F6FF>菱形12格</color>範圍內雷鳴狀態下的敵人造成<color=#00F6FF>50%</color>的傷害。",
  str_skill_upgrade_refine_desc_16020911 = "裝備技能強化：傷害係數提升為<color=#00F6FF>50%</color>",
  str_skill_upgrade_refine_desc_16020912 = "<color=#00F6FF>新增主動技能變體I</color>：<color=#FFFF00>施放後技能冷卻回合+1</color>。對全部格子造成<color=#00F6FF>300%</color>的傷害，最終傷害提高<color=#00F6FF>30%</color>。",
  str_skill_upgrade_refine_desc_16020913 = "<color=#00F6FF>新增主動技能變體II</color>：<color=#FFFF00>施放後技能冷卻回合-1</color>。任選1格，對方形9格造成<color=#00F6FF>100%</color>的傷害。若自身位於所選範圍內，則最終傷害提高30%。",
  str_skill_desc_320116 = "任選1個敵人，對其造成<color=#00F6FF>{1}%</color>的傷害並標記該目標。弗勞爾本回合施放連鎖技能時，對標記目標額外造成1次傷害。主動技能如在上回合就緒，則本回合的最終傷害提高<color=#00F6FF>35%</color>。",
  str_skill_desc_323116 = "任選1個敵人，對其造成<color=#00F6FF>{1}%</color>的傷害並標記該目標。弗勞爾本回合施放連鎖技能時，對標記目標額外造成1次傷害。主動技能如在上回合就緒，則本回合的最終傷害提高<color=#00F6FF>35%</color>。",
  str_skill_upgrade_desc_16011113 = "裝備技能強化：晶礦生成範圍提升至周圍1/2/3圈。",
  str_skill_upgrade_desc_16011116 = "主動技能強化：主動技能變為<color=#FFFF00>先制攻擊</color>，進入戰鬥即可使用。",
  str_skill_desc_300111 = "對<color=#00F6FF>全體</color>敵人造成<color=#00F6FF>{1}%</color>的傷害，敵人數量越少傷害越高，最高提升至2倍。",
  str_skill_desc_303111 = "對<color=#00F6FF>全體</color>敵人造成<color=#00F6FF>{1}%</color>的傷害，敵人數量越少傷害越高，最高提升至2倍。",
  str_skill_desc_320111 = "對<color=#00F6FF>全體</color>敵人造成<color=#00F6FF>{1}%</color>的傷害，敵人數量越少傷害越高，最高提升至2倍。<color=#00F6FF>施放主動技能</color>與<color=#00F6FF>進入極光時刻時</color>標記目前位置，若本回合觸發裝備技能生成晶礦，則標記位置也觸發1次裝備技能。",
  str_skill_desc_323111 = "對<color=#00F6FF>全體</color>敵人造成<color=#00F6FF>{1}%</color>的傷害，敵人數量越少傷害越高，最高提升至2倍。<color=#00F6FF>施放主動技能</color>與<color=#00F6FF>進入極光時刻時</color>標記目前位置，若本回合觸發裝備技能生成晶礦，則標記位置也觸發1次裝備技能。",
  str_skill_passive_name_416111 = "石心感應",
  str_skill_passive_name_436111 = "石心感應",
  str_skill_passive_desc_410111 = "敵方回合開始前，若本回合拜里厄施放過連鎖技能，則在<color=#00F6FF>連鎖技能範圍內</color>生成晶礦，持續1回合。敵人<link=\"30091\"><#FFAE07><u>觸碰</u></color></link>晶礦時，對其造成<color=#00F6FF>{1}</color>無視防禦的傷害（該傷害受屬性剋制修正）。",
  str_skill_passive_desc_430111 = "敵方回合開始前，若本回合拜里厄施放過連鎖技能，則在<color=#00F6FF>連鎖技能範圍內</color>生成晶礦，持續1回合。敵人<link=\"30091\"><#FFAE07><u>觸碰</u></color></link>晶礦時，對其造成<color=#00F6FF>{1}</color>無視防禦的傷害（該傷害受屬性剋制修正）。連線每增加1格，觸碰傷害增加<color=#00F6FF>10%</color>，達到20格後不再增加。",
  str_skill_passive_desc_416111 = "敵方回合開始前，若本回合拜里厄施放過連鎖技能，則在自身<color=#00F6FF>周圍1/2/3圈</color>生成晶礦，持續1回合。敵人<link=\"30091\"><#FFAE07><u>觸碰</u></color></link>晶礦時，對其造成<color=#00F6FF>{1}</color>無視防禦的傷害（該傷害受屬性剋制修正）。",
  str_skill_passive_desc_436111 = "敵方回合開始前，若本回合拜里厄施放過連鎖技能，則在自身<color=#00F6FF>周圍1/2/3圈</color>生成晶礦，持續1回合。敵人<link=\"30091\"><#FFAE07><u>觸碰</u></color></link>晶礦時，對其造成<color=#00F6FF>{1}</color>無視防禦的傷害（該傷害受屬性剋制修正）。連線每增加1格，觸碰傷害增加<color=#00F6FF>10%</color>，達到20格後不再增加。",
  str_skill_desc_2001161 = "對最靠近的2名敵人造成<color=#00F6FF>{1}%</color>的傷害，同時對其周圍<color=#00F6FF>十字形4格</color>造成<color=#00F6FF>30%</color>的<link=\"30015\"><#FFAE07><u>濺射</u></color></link>傷害。",
  str_skill_desc_2001162 = "對最靠近的2名敵人造成<color=#00F6FF>{1}%</color>的傷害，同時對其周圍<color=#00F6FF>十字形4格</color>造成<color=#00F6FF>30%</color>的<link=\"30015\"><#FFAE07><u>濺射</u></color></link>傷害。",
  str_skill_desc_2001163 = "對最靠近的2名敵人造成<color=#00F6FF>{1}%</color>的傷害，同時對其周圍<color=#00F6FF>十字形4格</color>造成<color=#00F6FF>30%</color>的<link=\"30015\"><#FFAE07><u>濺射</u></color></link>傷害。",
  str_skill_desc_2061161 = "對最近的2個敵人造成<color=#00F6FF>{1}%</color>的傷害，同時對其周圍<color=#00F6FF>十字形4格</color>造成<color=#00F6FF>30%</color>的<link=\"30015\"><#FFAE07><u>濺射</u></color></link>傷害。攻擊標記目標無視其全部防禦力。",
  str_skill_desc_2061162 = "對最近的2個敵人造成<color=#00F6FF>{1}%</color>的傷害，同時對其周圍<color=#00F6FF>十字形4格</color>造成<color=#00F6FF>30%</color>的<link=\"30015\"><#FFAE07><u>濺射</u></color></link>傷害。攻擊標記目標無視其全部防禦力。",
  str_skill_desc_2061163 = "對最近的2個敵人造成<color=#00F6FF>{1}%</color>的傷害，同時對其周圍<color=#00F6FF>十字形4格</color>造成<color=#00F6FF>30%</color>的<link=\"30015\"><#FFAE07><u>濺射</u></color></link>傷害。攻擊標記目標無視其全部防禦力。",
