  str_skill_desc_2201162 = "對最近的2個敵人造成<color=#00F6FF>{1}%</color>的傷害，同時對其周圍<color=#00F6FF>十字形4格</color>造成<color=#00F6FF>30%</color>的<link=\"30015\"><#FFAE07><u>濺射</u></color></link>傷害。攻擊標記目標無視其40%防禦力。",
  str_skill_desc_2201163 = "對最近的2個敵人造成<color=#00F6FF>{1}%</color>的傷害，同時對其周圍<color=#00F6FF>十字形4格</color>造成<color=#00F6FF>30%</color>的<link=\"30015\"><#FFAE07><u>濺射</u></color></link>傷害。攻擊標記目標無視其40%防禦力。",
