  str_skill_desc_303116 = "任選1個敵人，對其造成<color=#00F6FF>{1}%</color>的傷害並標記該目標。弗勞爾連鎖技能本回合對標記目標額外造成1次傷害。<color=#00F6FF>進入極光時刻</color>或<color=#00F6FF>擊敗標記目標</color>時，主動技能可再次施放。",
