  str_skill_passive_name_430116 = "機工大師",
  str_skill_passive_desc_410116 = "弗勞爾對生命值低於50%的敵人造成的所有傷害提高<color=#00F6FF>{1}</color>（若目標沒有生命值上限，則該效果直接生效）。",
  str_skill_passive_desc_430116 = "弗勞爾對生命值低於50%的敵人造成的所有傷害提高<color=#00F6FF>{1}</color>（若目標沒有生命值上限，則該效果直接生效）。攻擊標記目標時額外獲得<color=#00F6FF>{2}</color>加成。",
  str_skill_upgrade_desc_16011613 = "連鎖技能強化：連鎖技能攻擊標記目標無視其全部防禦力。（覺醒2階段生效）",
