  str_skill_passive_name_415210 = "迴斬殘願",
  str_skill_desc_20021011 = "造成2次<color=#00F6FF>130%</color>的傷害。隨機分配到自身<color=#00F6FF>周圍3圈</color>內的敵人身上。對同一目標造成多次傷害時，從第2次起每次傷害減半。",
  str_skill_desc_2002102 = "造成3次<color=#00F6FF>135%</color>的傷害。隨機分配到自身<color=#00F6FF>周圍3圈</color>內的敵人身上。對同一目標造成多次傷害時，從第2次起每次傷害減半。",
  str_skill_desc_2002103 = "造成4次<color=#00F6FF>140%</color>的傷害。隨機分配到自身<color=#00F6FF>周圍3圈</color>內的敵人身上。對同一目標造成多次傷害時，從第2次起每次傷害減半。",
  str_skill_desc_3002101 = "在周圍<color=#00F6FF>4</color>方向中任選一個方向衝刺，遇到阻擋後停止，對<color=#00F6FF>面前1格</color>的敵人造成1次<color=#00F6FF>{1}%</color>的傷害。",
