  str_skill_passive_desc_410210 = "喬瑟琳每次普通攻擊和連鎖技能命中敵人後附加1層殘願，最大<color=#00F6FF>6</color>層。主動技能對<color=#00F6FF>面前1格</color>的敵人額外造成其殘願層數次<color=#00F6FF>{1}</color>攻擊力的傷害，之後清空層數。",
  str_skill_passive_desc_415210 = "喬瑟琳每次普通攻擊和連鎖技能命中敵人後附加1層殘願，最大<color=#00F6FF>8</color>層。主動技能對<color=#00F6FF>面前1格</color>的敵人額外造成其殘願層數次<color=#00F6FF>{1}</color>攻擊力的傷害，之後清空層數。",
