  str_skill_upgrade_desc_15021015 = "裝備技能強化：殘願層數上限提升至<color=#FFFF00>8</color>。",
  str_skill_name_200330110 = "靈感控制",
  str_skill_desc_200330110 = "呪悚遠離玩家位置。在隊伍移動結束後立即讓隊伍位置發生偏移，影響隊伍連鎖技能施放範圍。",
  str_skill_name_200330121 = "血腥奉獻",
  str_skill_desc_200330121 = "呪悚燃燒自身剩餘生命值到剩下1點，對玩家造成無視防禦力的真實傷害。燃燒的生命值將直接決定最終傷害值。技能僅會施放1次。",
  str_skill_upgrade_refine_desc_15021011 = "裝備技能強化：傷害係數提升為<color=#00F6FF>36%</color>。",
  str_skill_upgrade_refine_desc_15021012 = "主動技能強化：目標身上每有4層殘願，則對以自身為中心的<color=#00F6FF>周圍2圈</color>內的所有敵人造成1次120%的傷害。",
  str_skill_upgrade_refine_desc_15021013 = "主動技能強化：主動技能和裝備技能觸發的傷害對貫穿格造成全部傷害。",
  str_skill_passive_desc_440210 = "喬瑟琳每次普通攻擊和連鎖技能命中敵人後附加1層殘願，最大<color=#00F6FF>8</color>層。主動技能對<color=#00F6FF>面前1格</color>的敵人額外造成其殘願層數次<color=#00F6FF>36%</color>攻擊力的傷害，之後清空層數。",
