  str_skill_name_70010982 = "末逐·雷電之力",
  str_skill_name_70010983 = "末逐·巨像音嘯",
  str_skill_desc_70010981 = "末逐·吞噬者舒默對自身十字範圍的目標造成傷害。",
  str_skill_desc_70010982 = "末逐·吞噬者舒默召喚雷電之力對場上多個區域造成傷害並附加麻痺效果。",
  str_skill_desc_70010983 = "末逐·吞噬者舒默控制巨像施放音波攻擊，攻擊全場的目標並將光靈牽引至周圍。",
  str_skill_name_290610101 = "移進衝擊",
