  str_skill_name_290610102 = "引擎加速",
  str_skill_desc_290610102 = "當前方空曠，則加大馬力向前快速推進。",
  str_skill_name_290610103 = "全角轟炸",
  str_skill_desc_290610103 = "對位與機甲周圍的光靈單位造成傷害與擊退效果，同時對城牆造成傷害。",
  str_skill_name_290610104 = "高溫噴焰",
  str_skill_desc_290610104 = "強力攻城，對前方光靈單位和城牆造成大量傷害。",
  str_skill_name_290610105 = "污蠱機師",
  str_skill_desc_290610105 = "癱瘓狀態下需要修理自己的組件，維修結束後重新部署攻城行動。",
  str_skill_name_280240101 = "驅離轟擊",
  str_skill_desc_280240101 = "痛擊要塞閘門前的敵方單位，使其陷入癱瘓狀態。",
  str_skill_name_290570101 = "瑪德昂多·冒濺",
  str_skill_name_290570102 = "瑪德昂多·噴澤",
  str_skill_name_290570103 = "瑪德昂多·渦沼",
  str_skill_desc_290570101 = "瑪德昂多在大泥潭中下潛並在距離光靈最近的位置冒出，對周圍2圈造成傷害並在場上生成多個泥潭",
  str_skill_desc_290570102 = "瑪德昂多在大泥潭中下潛並在距離光靈最近的位置冒出，對面前2列造成傷害，並留下多個泥潭",
  str_skill_desc_290570103 = "吸入全場格子並對光靈造成傷害，然後重設全場格子並將光靈隨機位移至泥潭上",
  str_skill_desc_290570104 = "瑪拉索爾召喚2隻呪悚進入戰場。",
  str_skill_upgrade_desc_16021213 = "主動技能強化：主動技能變為<color=#FFFF00>先制攻擊</color>，進入戰鬥即可使用。\n主動技能圈定的矩形區域內，隨機2個非森屬性格子轉為森屬性。",
  str_skill_upgrade_desc_16021216 = "主動技能強化：第二次可點選範圍擴大到<color=#00F6FF>周圍四圈</color>。",
  str_skill_desc_3002121 = "任選1個格子，並在<color=#00F6FF>周圍3圈</color>內再次選擇1個格子，圈定一個矩形區域。將兩個點選格轉為森屬性。若隊伍位於矩形區域內，為隊伍回復相當於安頓<color=#00F6FF>250%</color>攻擊力的生命值。",
  str_skill_desc_3032121 = "任選1個格子，並在<color=#00F6FF>周圍3圈</color>內再次選擇1個格子，圈定一個矩形區域。將兩個點選格轉為森屬性，並將矩形區域內隨機2個非森屬性格子轉為森屬性。若隊伍位於矩形區域內，為隊伍回復相當於安頓<color=#00F6FF>250%</color>攻擊力的生命值。",
  str_skill_desc_3062121 = "任選1個格子，並在<color=#00F6FF>周圍4圈</color>內再次選擇1個格子，圈定一個矩形區域。將兩個點選格轉為森屬性，並將矩形區域內隨機2個非森屬性格子轉為森屬性。若隊伍位於矩形區域內，為隊伍回復相當於安頓<color=#00F6FF>250%</color>攻擊力的生命值。",
  str_skill_desc_3202121 = "任選1個格子，並在<color=#00F6FF>周圍3圈</color>內再次選擇1個格子，確定一個矩形區域。將兩個點選格轉變為森屬性<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>，若隊伍位於矩形區域內，為隊伍恢復相當於安頓<color=#00F6FF>250%</color>攻擊力的生命值。",
  str_skill_desc_3232121 = "任選1個格子，並在<color=#00F6FF>周圍3圈</color>內再次選擇1個格子，圈定一個矩形區域。將兩個點選格轉為森屬性<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>，並將矩形區域內隨機2個非森屬性格子轉為森屬性。若隊伍位於矩形區域內，為隊伍回復相當於安頓<color=#00F6FF>250%</color>攻擊力的生命值。",
  str_skill_desc_3262121 = "任選1個格子，並在<color=#00F6FF>周圍4圈</color>內再次選擇1個格子，圈定一個矩形區域。將兩個點選格轉為森屬性<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>，並將矩形區域內隨機2個非森屬性格子轉為森屬性。若隊伍位於矩形區域內，為隊伍回復相當於安頓<color=#00F6FF>250%</color>攻擊力的生命值。",
  str_skill_desc_2002121 = "對<color=#00F6FF>縱向1列</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2002122 = "對<color=#00F6FF>縱向3列</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2002123 = "對<color=#00F6FF>縱向3列</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_passive_desc_410212 = "隊伍每在森屬性格子上連線移動1格或透過其他方式<link=\"30092\"><#FFAE07><u>位移</u></color></link>1格，為隊伍恢復相當於安頓<color=#00F6FF>{1}</color>攻擊力的生命值。",
  str_skill_passive_desc_430212 = "隊伍每在森屬性格子上連線移動1格或透過其他方式<link=\"30092\"><#FFAE07><u>位移</u></color></link>1格，為隊伍恢復相當於安頓<color=#00F6FF>{1}</color>攻擊力的生命值。隊伍生命值越低恢復效果越高，最多提高<color=#00F6FF>100%</color>。",
