  str_skill_name_80020042 = "恐嚇",
  str_skill_desc_80020042 = "當光靈處於自身米字形範圍內時，位移至光靈身邊，造成傷害並擊退光靈。攻擊會受到障礙阻擋。",
  str_skill_name_80020052 = "猶豫",
  str_skill_desc_80020052 = "身處場外，玩家僅能使用非指向性單體攻擊造成傷害，免疫爆破和普通攻擊傷害。場上敵人受到傷害也會同步傳遞給伊倫汀。",
  str_skill_name_2002111 = "雪凝冰錐",
