  str_skill_name_30321101 = "霜染天穹",
  str_skill_name_30321102 = "冰塑樹影",
  str_skill_desc_2002111 = "對最靠近的2個敵人造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2002112 = "對最靠近的2個敵人造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2002113 = "對最靠近的2個敵人造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_30021101 = "將最靠近的<color=#00F6FF>2</color>個雷屬性格子轉變為水屬性。該技能施放後，「冰塑樹影」的技能冷卻回合+1。",
  str_skill_desc_30021102 = "將最靠近的<color=#00F6FF>2</color>個森屬性格子轉變為水屬性。該技能施放後，「霜染天穹」的技能冷卻回合+1。",
  str_skill_desc_30021103 = "將最靠近的<color=#00F6FF>3</color>個雷屬性格子轉變為水屬性。該技能施放後，「冰塑樹影」的技能冷卻回合+1。",
  str_skill_desc_30021104 = "將最靠近的<color=#00F6FF>3</color>個森屬性格子轉變為水屬性。該技能施放後，「霜染天穹」的技能冷卻回合+1。",
  str_skill_desc_30021105 = "將最靠近的<color=#00F6FF>4</color>個雷屬性格子轉變為水屬性。該技能施放後，「冰塑樹影」的技能冷卻回合+1。",
  str_skill_desc_30021106 = "將最靠近的<color=#00F6FF>4</color>個森屬性格子轉變為水屬性。該技能施放後，「霜染天穹」的技能冷卻回合+1。",
  str_skill_desc_30321101 = "將最靠近的<color=#00F6FF>2</color>個雷屬性格子轉變為水屬性。該技能施放後，下一次主動技能轉換格子數量提升至<color=#00F6FF>3</color>個，「冰塑樹影」的技能冷卻回合+1。",
  str_skill_desc_30321102 = "將最靠近的<color=#00F6FF>2</color>個森屬性格子轉變為水屬性。該技能施放後，下一次主動技能轉換格子數量提升至<color=#00F6FF>3</color>個，「霜染天穹」的技能冷卻回合+1。",
  str_skill_desc_30621103 = "將最接近的<color=#00F6FF>3</color>個雷屬性格子轉為水屬性。該技能施放後，「冰塑樹影」的技能冷卻回合+1。若回合開始時兩個主動技能都未就緒，則將離隊伍最近的<color=#00F6FF>1</color>個非水屬性格子轉為水屬性<link=\"30093\"><#FFAE07><u>深色格子</u></color></link>。",
  str_skill_desc_30621104 = "將最接近的<color=#00F6FF>3</color>個森屬性格子轉為水屬性。該技能施放後，「霜染天穹」的技能冷卻回合+1。若回合開始時兩個主動技能都未就緒，則將離隊伍最近的<color=#00F6FF>1</color>個非水屬性格子轉為<color=#00F6FF>水屬性</color><link=\"30093\"><#FFAE07><u>深色格子</u></color></link>。",
  str_skill_passive_name_410211 = "雪域療癒",
  str_skill_passive_name_420211 = "雪域療癒",
  str_skill_passive_name_430211 = "雪域療癒",
  str_skill_passive_desc_410211 = "普通攻擊變為二連擊，每次傷害為基礎傷害的<color=#00F6FF>一半</color>。每<color=#00F6FF>7</color>次普通攻擊可以為隊伍恢復自身攻擊力<color=#00F6FF>{1}</color>的生命值。",
  str_skill_passive_desc_420211 = "普通攻擊變為二連擊，每次傷害為基礎傷害的<color=#00F6FF>一半</color>。每<color=#00F6FF>7</color>次普通攻擊可以為隊伍恢復自身攻擊力<color=#00F6FF>{1}</color>的生命值。進入極光時刻時，立刻為隊伍恢復自身攻擊力<color=#00F6FF>100%</color>的生命值。",
  str_skill_passive_desc_430211 = "普通攻擊可攻擊斜方向，對十字方向敵人變為二連擊，每次傷害為基礎傷害的<color=#00F6FF>一半</color>。每<color=#00F6FF>7</color>次普通攻擊可以為隊伍恢復自身攻擊力<color=#00F6FF>{1}</color>的生命值。進入極光時刻時，立刻為隊伍恢復自身攻擊力<color=#00F6FF>100%</color>的生命值。",
  str_skill_upgrade_desc_16021113 = "主動技能強化：轉換格子數量提升至<color=#FFFF00>3個</color>。",
  str_skill_upgrade_desc_16021116 = "主動技能強化：若回合開始時兩個主動技能都<color=#00F6FF>未就緒</color>，則將離隊伍最近的1個非水屬性格子轉為水屬性深色格子。",
  str_skill_name_200350101 = "震地",
  str_skill_name_200350102 = "痛擊",
  str_skill_name_200350103 = "碎顱",
  str_skill_name_200350104 = "舐血",
  str_skill_desc_200350101 = "雹凜砸向地面，對十字形最大範圍的敵人造成多次傷害並擊退到最遠處。",
  str_skill_desc_200350102 = "若敵人位於自身周圍1圈，雹凜對敵人造成傷害並擊退一格。",
  str_skill_desc_200350103 = "若敵人位於雹凜周圍特定範圍內且對應的十字方向上無阻擋，雹凜迅速靠近敵人並重擊造成傷害，對中心區域敵人造成的傷害更高並會附加眩暈。",
  str_skill_desc_200350104 = "若附近沒有敵人，雹凜會恢復生命值。",
  str_skill_name_200360102 = "赤腐惡靈·迫逐",
  str_skill_desc_200360102 = "瞬移到玩家身邊，對面前1格範圍內的目標造成多次傷害，並附加擊退效果。瞬移距離越遠則攻擊次數越少。",
  str_skill_name_290213101 = "遺跡永存",
  str_skill_name_290213102 = "守護裁決",
  str_skill_name_290213103 = "定位威脅",
  str_skill_desc_290213101 = "施展一次瞬移並造成傷害，之後將光靈周圍1圈範圍內隨機3個格子轉變為森屬性格子。",
  str_skill_desc_290213102 = "施展一次瞬移並造成傷害，之後將光靈周圍1圈範圍內隨機3個格子轉變為雷屬性格子。",
  str_skill_desc_290213103 = "吸收自身周圍2圈範圍內的水屬性格子能量，對光靈進行攻擊（吸收的格子數量越多，傷害越高）。",
  str_skill_desc_200270201 = "恢復啟光步話兵的生命值，並將自己累積的部分瘀傷值轉化為生命值。",
  str_skill_desc_200280201 = "召喚2名啟光戰兵進入戰場。",
  str_skill_desc_200280202 = "召喚1名啟光戰兵和1名啟光軍士進入戰場。",
  str_skill_desc_200280301 = "召喚2名啟光火焰噴射手進入戰場。",
  str_skill_desc_200280302 = "召喚1名啟光火焰噴射手和1名啟光軍士進入戰場。",
  str_skill_name_290280111 = "山鬼·橫切",
  str_skill_desc_290280111 = "山鬼向目標移動，揮動榮角刀橫切造成傷害。",
  str_skill_name_290280121 = "山鬼·亂舞",
  str_skill_desc_290280121 = "原地施放刀刃亂舞，對攻擊範圍內的目標造成傷害。",
  str_skill_name_290280131 = "山鬼·牙突",
  str_skill_desc_290280131 = "跟隨榮角刀的引導，突刺至目標身邊，並造成兩段傷害。",
  str_skill_name_290280141 = "山鬼·四擲",
  str_skill_desc_290280141 = "山鬼的本體行動前，向四方向射出榮角刀；榮角刀會對沿途的目標造成傷害。",
  str_skill_name_290280151 = "山鬼·刀取",
  str_skill_desc_290280151 = "山鬼的本體行動前，收回場上所有榮角刀；榮角刀會對沿途的目標造成傷害。",
  str_skill_name_290280112 = "橫切",
  str_skill_desc_290280112 = "靠近距離最近的暗鬼，揮動榮角刀橫切暗鬼造成大量傷害。",
  str_skill_name_290280122 = "亂舞",
  str_skill_desc_290280122 = "向暗鬼密集的位置移動，施放刀刃亂舞，對一定範圍內的所有暗鬼造成傷害。",
  str_skill_name_700110233 = "末逐·炎獅掏心",
  str_skill_name_700110234 = "末逐·增壓拳",
  str_skill_name_700110235 = "末逐·渦輪潮吸",
  str_skill_desc_700110233 = "移動後攻擊四周目標。",
  str_skill_desc_700110234 = "使用範圍拳法，對菱形12格造成傷害。",
  str_skill_desc_700110235 = "拳套增壓的吸引力將敵人牽引至附近，再使用毀滅一擊造成傷害。",
  str_skill_name_700110413 = "末逐·雷神",
  str_skill_name_700110414 = "末逐·正道威嚴",
  str_skill_name_700110415 = "末逐·帝國雷霆",
  str_skill_desc_700110413 = "移動後攻擊四周目標。",
  str_skill_desc_700110414 = "移動後在米字形16格召喚雷電打擊，對敵人造成傷害。",
  str_skill_desc_700110415 = "對全畫面範圍內的敵人造成一次傷害，並附加10%目前生命值的傷害。",
  str_skill_desc_700110416 = "移動後在米字形16格召喚雷電打擊，對敵人造成傷害。",
  str_skill_desc_700110417 = "對全畫面範圍內的敵人造成一次傷害，並附加15%目前生命值的傷害。",
  str_skill_name_111807112 = "古卷祕語",
  str_skill_desc_111807112 = "拾取後提升攻擊力與防禦力。",
  str_skill_name_111807113 = "古卷拾取者",
  str_skill_desc_111807113 = "拾取場上的皮紙古卷。",
  str_skill_name_111807111 = "古卷召喚者",
  str_skill_desc_111807111 = "在場上隨機位置召喚3個皮紙古卷。",
  str_skill_name_111807212 = "古卷召喚者",
  str_skill_desc_111807212 = "在場上隨機位置召喚5個皮紙古卷。",
  str_skill_name_2002131 = "定位威脅",
  str_skill_name_2102131 = "定位威脅",
  str_skill_desc_2002131 = "對最近的1個敵人造成<color=#00F6FF>{1}%</color>的傷害，根據連鎖數量提供傷害加成。",
  str_skill_desc_2102131 = "對最近的1個敵人造成3次傷害，每次為原傷害的30%，受自身本回合普通攻擊次數加成影響。",
  str_skill_name_300213 = "領域控制",
  str_skill_desc_300213 = "任選1格暫時隱藏屬性，隨後以該格為中心形成<color=#00F6FF>方形25格</color>範圍的領域，在<color=#00F6FF>15秒</color>倒數計時期間可持續點選調換相鄰格子的屬性，倒數計時結束時將剩餘空格子轉為<color=#00F6FF>雷屬性</color>。整場戰鬥只能施放一次。",
  str_skill_name_302213 = "領域控制",
  str_skill_desc_302213 = "任選1格暫時隱藏其屬性，隨後以其為中心形成<color=#00F6FF>方形25格</color>範圍的領域，在<color=#00F6FF>15秒</color>倒數計時期間可持續點選調換相鄰格子的屬性，倒數結束時將剩餘空格轉變為<color=#00F6FF>雷屬性</color>。進入戰鬥/第二波次時各獲得一次施放機會。",
  str_skill_name_305213 = "領域控制",
  str_skill_desc_305213 = "任選1格暫時隱藏其屬性，隨後以其為中心形成<color=#00F6FF>方形25格</color>範圍的領域，在<color=#00F6FF>15秒</color>倒數計時期間可持續點選調換相鄰格子的屬性，倒數結束時將剩餘空格轉變為<color=#00F6FF>雷屬性</color>。進入戰鬥/第二波次/第7回合時各獲得一次施放機會。",
  str_skill_passive_name_410213 = "粉碎時刻",
  str_skill_passive_desc_410213 = "若連擊數達到<color=#00F6FF>{1}</color>，本次連鎖技能調整為3次傷害，每次為原傷害的30%，受自身本回合普通攻擊次數加成影響。",
  str_skill_passive_name_420213 = "粉碎時刻",
  str_skill_passive_desc_420213 = "若連擊數達到<color=#00F6FF>{1}</color>，本次連鎖技能調整為3次傷害，每次為原傷害的30%，受自身本回合普通攻擊次數加成影響。且<color=#00F6FF>無視連線屬</color>性均可施放。",
  str_skill_passive_name_430213 = "粉碎時刻",
  str_skill_passive_desc_430213 = "若連擊數達到<color=#00F6FF>{1}</color>，則本次連鎖技能調整為3次傷害，每次為原傷害的30%，受自身本回合普通攻擊次數加成影響，且<color=#00F6FF>無視連線屬性</color>均可施放。連線後補充格子時，將本次連線的第N格轉為雷屬性，N為剩餘回合數。",
  str_skill_upgrade_desc_15021312 = "主動技能強化：進入第二波次時獲得一次施放機會。",
  str_skill_upgrade_desc_15021315 = "主動技能強化：進入第7回合時獲得一次施放機會。",
  str_skill_name_53520212 = "召喚",
  str_skill_desc_53520212 = "優先攻擊自身周圍的光靈，若周圍無光靈則召喚更多白夜長槍兵協助作戰。",
  str_skill_name_53520213 = "鼓舞",
  str_skill_desc_53520213 = "優先攻擊自身周圍的光靈，若周圍無光靈則鼓舞自身周圍的白夜兵，提升其攻擊力。",
  str_skill_name_53520411 = "定位威脅",
  str_skill_desc_53520411 = "吸收自身周圍2圈的水屬性格子後，對敵人造成傷害，吸收的格子數量越多傷害越。",
  str_skill_name_53520412 = "定位威脅",
  str_skill_desc_53520412 = "吸收自身周圍2圈的火屬性格子後，對敵人造成傷害，吸收的格子數量越多傷害越高。",
  str_skill_name_53520413 = "定位威脅",
  str_skill_desc_53520413 = "吸收自身周圍2圈的森屬性格子後，對敵人造成傷害，吸收的格子數量越多傷害越高。",
  str_skill_name_5352031 = "致命爆炸",
  str_skill_desc_5352031 = "每流逝一段時間後爆炸，對全場所有單位造成傷害效果。",
  str_skill_name_29089011 = "「審判長」之叩",
  str_skill_name_29089012 = "「審判長」之判",
  str_skill_name_29089014 = "「審判長」之叩",
  str_skill_desc_29089011 = "朝目標上回合所在位置釋放聖光，對沿途及相鄰格的目標造成傷害，傷害數值隨目標的「成見」層數提高。",
  str_skill_desc_29089012 = "鎖定目標位置並造成大量傷害，傷害數值隨目標的「成見」層數提高。",
  str_skill_desc_29089014 = "朝目標上回合所在位置釋放聖光，對沿途及相鄰格的目標造成傷害，傷害數值隨目標的「成見」層數提高。在固定位置召喚陪審聖雕。",
  str_skill_name_29089021 = "「審判長」之叩",
  str_skill_desc_29089021 = "朝目標上回合所在位置釋放聖光，對沿途及相鄰格的目標造成傷害，傷害數值隨目標的「成見」層數提高。",
  str_skill_name_290580101 = "混沌衝擊",
  str_skill_name_290580102 = "指尖能量",
  str_skill_name_290580103 = "邁向毀滅",
  str_skill_name_290580104 = "命途終結",
