  str_skill_desc_290580102 = "進行一次瞬移後對玩家造成傷害並擊退2格。",
  str_skill_desc_290580103 = "標記目標周圍2圈範圍的區域，怪物回合開始時對標記區域造成高額傷害並擊退3格。",
  str_skill_desc_290580104 = "進入蓄力狀態，怪物回合開始前若未被位移或擊退，對玩家造成高額傷害。",
  str_skill_desc_2905801011 = "對前方扇形範圍內的所有目標造成傷害。",
  str_skill_desc_2905801021 = "進行一次瞬移後對玩家造成傷害。",
  str_skill_desc_2905801031 = "標記目標周圍2圈範圍的區域，怪物回合開始時對標記區域造成高額傷害。",
