  str_skill_passive_desc_420187 = "若自身<color=#00F6FF>周圍1圈</color>內部沒有敵人，主動技能和連鎖技能的每段均有<color=#00F6FF>25%</color>機率造成<color=#00F6FF>{1}</color>倍傷害。",
  str_skill_passive_desc_430187 = "若自身<color=#00F6FF>周圍1圈</color>內部沒有敵人，主動技能和連鎖技能的每段均有<color=#00F6FF>25%</color>機率造成<color=#00F6FF>{1}</color>倍傷害。若自身<color=#00F6FF>周圍2圈</color>內沒有敵人，機率提升為<color=#00F6FF>50%</color>。",
