  str_skill_desc_306188 = "任選<color=#00F6FF>2</color>個格子轉為火屬性，對2個格子沿途及相鄰格子造成<color=#00F6FF>{1}%</color>的傷害，斬殺範圍內生命值低於<color=#00F6FF>15%</color>的非首領敵人。",
  str_skill_passive_desc_410188 = "本回合內，對每個相對朝向的首次普通攻擊會暴擊，造成<color=#00F6FF>{1}</color>的傷害。",
  str_skill_passive_desc_420188 = "本回合內，對每個相對朝向的首次普通攻擊會暴擊，造成<color=#00F6FF>{1}</color>的傷害。進入極光時刻時，重設所有普通攻擊方向的暴擊計數。",
  str_skill_passive_desc_430188 = "普通攻擊<color=#00F6FF>可攻擊斜方向</color>。本回合內，對每個相對朝向的首次普通攻擊會暴擊，造成<color=#00F6FF>{1}</color>的傷害。進入極光時刻時，重設所有普通攻擊方向的暴擊計數。",
