  str_skill_desc_2301333 = "造成4次<color=#00F6FF>145%</color>的傷害，隨機分配到<color=#00F6FF>周圍3圈</color>內的敵人身上，同時對其周圍<color=#00F6FF>十字形4格</color>造成<color=#00F6FF>25%</color>的<link=\"30015\"><#FFAE07><u>濺射</u></color></link>傷害。對同一目標造成多次傷害時，第2次起每次傷害減半。朵露每施放1次主動技能，連鎖技能傷害次數<color=#00F6FF>+1</color>。",
  str_skill_desc_2361331 = "造成2次<color=#00F6FF>130%</color>的傷害，隨機分配到<color=#00F6FF>周圍3圈</color>內的敵人身上，同時對其周圍<color=#00F6FF>十字形4格</color>造成<color=#00F6FF>30%</color>的<link=\"30015\"><#FFAE07><u>濺射</u></color></link>傷害。對同一目標造成多次傷害時，第2次起每次傷害減半。朵露每施放1次主動技能，連鎖技能傷害次數<color=#00F6FF>+1</color>。",
  str_skill_desc_2361332 = "造成3次<color=#00F6FF>140%</color>的傷害，隨機分配到<color=#00F6FF>周圍3圈</color>內的敵人身上，同時對其周圍<color=#00F6FF>十字形4格</color>造成<color=#00F6FF>30%</color>的<link=\"30015\"><#FFAE07><u>濺射</u></color></link>傷害。對同一目標造成多次傷害時，第2次起每次傷害減半。朵露每施放1次主動技能，連鎖技能傷害次數<color=#00F6FF>+1</color>。",
  str_skill_desc_2361333 = "造成4次<color=#00F6FF>145%</color>的傷害，隨機分配到<color=#00F6FF>周圍3圈</color>內的敵人身上，同時對其周圍<color=#00F6FF>十字形4格</color>造成<color=#00F6FF>30%</color>的<link=\"30015\"><#FFAE07><u>濺射</u></color></link>傷害。對同一目標造成多次傷害時，第2次起每次傷害減半。朵露每施放1次主動技能，連鎖技能傷害次數<color=#00F6FF>+1</color>。",
