  str_skill_passive_desc_420215 = "伊莎在<link=\"30093\"><#FFAE07><u>深色格子</u></color></link>上的普通攻擊造成3次<color=#00F6FF>{1}</color>的傷害。伊莎的普通攻擊對同一敵人累積造成<color=#00F6FF>7次</color>傷害後，額外造成1次等同於伊莎<color=#00F6FF>100%</color>攻擊力的傷害。",
  str_skill_passive_desc_430215 = "伊莎在<link=\"30093\"><#FFAE07><u>深色格子</u></color></link>上的普通攻擊造成3次<color=#00F6FF>{1}</color>的傷害。伊莎的普通攻擊、連鎖技能對同一敵人累積造成<color=#00F6FF>7次</color>傷害後，額外造成1次等同於伊莎<color=#00F6FF>100%</color>攻擊力的傷害。主動技能命中目標後立即觸發一次額外傷害。",
