  str_skill_desc_300215 = "選擇1個敵人腳下的格子，再從周圍4方向中選擇1個方向，將非首領敵人朝選擇的方向強制位移1格並造成{1}%的傷害，同時在選擇的格子上生成<link=\"30093\"><#FFAE07><u>深色格子</u></color></link>。",
  str_skill_upgrade_refine_desc_15021511 = "裝備技能強化：位於<link=\"30093\"><#FFAE07><u>深色格子</u></color></link>上的普通攻擊造成3次傷害，每次傷害係數提升為<color=#00F6FF>65%</color>。",
  str_skill_upgrade_refine_desc_15021512 = "裝備技能新增效果：當伊莎與麗蓓卡（不低於覺醒1階段）同隊時，伊莎裝備技能造成的額外傷害會對目標<color=#00F6FF>附加1層浸體</color>。",
  str_skill_upgrade_refine_desc_15021513 = "裝備技能強化：額外傷害的觸發條件<color=#00F6FF>降低到6次</color>。",
  str_skill_passive_desc_440215 = "伊莎在<link=\"30093\"><#FFAE07><u>深色格子</u></color></link>上的普通攻擊造成3次<color=#00F6FF>65%</color>的傷害。伊莎的普通攻擊、連鎖技能對同一敵人累積造成<color=#00F6FF>7次</color>傷害後，額外造成1次等同於伊莎<color=#00F6FF>100%</color>攻擊力的傷害。主動技能命中目標後立即觸發一次額外傷害。",
  str_skill_passive_desc_445215 = "伊莎在<link=\"30093\"><#FFAE07><u>深色格子</u></color></link>上的普通攻擊造成3次<color=#00F6FF>65%</color>的傷害。伊莎的普通攻擊、連鎖技能對同一敵人累積造成<color=#00F6FF>7次</color>傷害後，額外造成1次等同於伊莎<color=#00F6FF>150%</color>攻擊力的傷害。主動技能命中目標後立即觸發一次額外傷害。",
  str_skill_passive_desc_450215 = "伊莎在<link=\"30093\"><#FFAE07><u>深色格子</u></color></link>上的普通攻擊造成3次<color=#00F6FF>65%</color>的傷害。伊莎的普通攻擊、連鎖技能對同一敵人累積造成<color=#00F6FF>7次</color>傷害後，額外造成1次等同於伊莎<color=#00F6FF>100%</color>攻擊力的傷害。主動技能命中目標後立即觸發一次額外傷害。若伊莎與麗蓓卡（不低於覺醒1階段）同隊，造成傷害時還會<color=#00F6FF>附加1層浸體</color>。",
  str_skill_passive_desc_455215 = "伊莎在<link=\"30093\"><#FFAE07><u>深色格子</u></color></link>上的普通攻擊造成3次<color=#00F6FF>65%</color>的傷害。伊莎的普通攻擊、連鎖技能對同一敵人累積造成<color=#00F6FF>7次</color>傷害後，額外造成1次等同於伊莎<color=#00F6FF>150%</color>攻擊力的傷害。主動技能命中目標後立即觸發一次額外傷害。若伊莎與麗蓓卡（不低於覺醒1階段）同隊，造成傷害時還會<color=#00F6FF>附加1層浸體</color>。",
  str_skill_passive_desc_460215 = "伊莎在<link=\"30093\"><#FFAE07><u>深色格子</u></color></link>上的普通攻擊造成3次<color=#00F6FF>65%</color>的傷害。伊莎的普通攻擊、連鎖技能對同一敵人累積造成<color=#00F6FF>6次</color>傷害後，額外造成1次等同於伊莎<color=#00F6FF>100%</color>攻擊力的傷害。主動技能命中目標後立即觸發一次額外傷害。若伊莎與麗蓓卡（不低於覺醒1階段）同隊，造成傷害時還會<color=#00F6FF>附加1層浸體</color>。",
