  str_skill_desc_3002141 = "選擇1個格子轉為水屬性<link=\"30093\"><#FFAE07><u>深色格子</u></color></link>，同時將距離該格最近的<color=#00F6FF>3</color>個水屬性格子轉為水屬性深色格子。",
