  str_skill_passive_name_430214 = "毒液擴散",
  str_skill_passive_desc_430214 = "每次經過深色格子時對<color=#00F6FF>菱形12格</color>範圍內附加<link=\"30094\"><#FFAE07><u>浸體</u></color></link>效果，怪物回合開始時，每層浸體對目標造成攻擊力<color=#00F6FF>{1}</color>的傷害。被連鎖技能攻擊到的敵人本回合浸體傷害無視防禦。",
