  str_skill_upgrade_desc_16021416 = "主動技能強化：將距離點選格最近的<color=#FFFF00>5</color>個水屬性格子轉為水屬性深色格子。",
  str_skill_upgrade_refine_desc_16021411 = "裝備技能強化：每層浸體對目標造成麗蓓卡攻擊力<color=#00F6FF>40%</color>的傷害。",
  str_skill_upgrade_refine_desc_16021412 = "連鎖技能強化：連鎖技能對範圍內的目標附加<color=#00F6FF>2</color>層浸體。",
  str_skill_upgrade_refine_desc_16021413 = "主動技能強化：施放主動技能時對附有浸體效果的目標觸發一次傷害，傷害加倍。",
  str_skill_passive_desc_440214 = "每次經過深色格子時對<color=#00F6FF>菱形12格</color>範圍內附加<link=\"30094\"><#FFAE07><u>浸體</u></color></link>效果，怪物回合開始時，每層浸體對目標造成攻擊力<color=#00F6FF>40%</color>的傷害。被連鎖技能攻擊到的敵人本回合浸體傷害無視防禦。",
  str_skill_desc_3402141 = "選擇1個格子轉為水屬性<link=\"30093\"><#FFAE07><u>深色格子</u></color></link>，同時將距離該格最近的<color=#00F6FF>3</color>個水屬性格子轉變為水屬性深色格子，之後對全畫面範圍內附有浸體效果的目標觸發一次傷害，傷害翻倍。",
