  str_skill_desc_2002163 = "對最靠近的4個敵人造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2202161 = "對最近2名敵人造成<color=#00F6FF>{1}%</color>的傷害，隨後對「四方佈雷陣」內隨機1名敵人再造成1次傷害。",
  str_skill_desc_2202162 = "對最近3名敵人造成<color=#00F6FF>{1}%</color>的傷害，隨後對「四方佈雷陣」內隨機1名敵人再造成1次傷害。",
  str_skill_desc_2202163 = "對最近4名敵人造成<color=#00F6FF>{1}%</color>的傷害，隨後對「四方佈雷陣」內隨機1名敵人再造成1次傷害。",
  str_skill_desc_300216 = "消耗3枚<link=\"30095\"><#FFAE07><u>工備</u></color></link>，任選1個格子，在<color=#00F6FF>方形9格</color>範圍內生成「四方佈雷陣」，持續<color=#00F6FF>2</color>回合。璇極在「四方佈雷陣」內普通攻擊<color=#00F6FF>可攻擊斜方向</color>。",
  str_skill_desc_303216 = "消耗3枚<link=\"30095\"><#FFAE07><u>工備</u></color></link>，任選1個格子，在<color=#00F6FF>方形25格</color>範圍內生成「四方佈雷陣」，持續<color=#00F6FF>3</color>回合。璇極在「四方佈雷陣」內普通攻擊<color=#00F6FF>可攻擊斜方向</color>。",
  str_skill_passive_desc_410216 = "璇極在「四方佈雷陣」內造成的傷害提升<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_416216 = "璇極在「四方佈雷陣」內造成的傷害提升<color=#00F6FF>{1}</color>，場上每多存在一個「四方佈雷陣」，傷害額外提升<color=#00F6FF>5%</color>。回合結束時，若璇極位於「四方佈雷陣」內，獲得1枚工備。",
  str_skill_passive_desc_430216 = "璇極在「四方佈雷陣」內造成的傷害提升<color=#00F6FF>{1}</color>。璇極每次施放連鎖技能後，若位於「四方佈雷陣」內，提升<color=#00F6FF>4%</color>基礎攻擊力，該效果最高可疊加5層，若回合結束時位於「四方佈雷陣」外，層數減半。",
  str_skill_passive_desc_436216 = "璇極在「四方佈雷陣」內造成的傷害提升<color=#00F6FF>{1}</color>，場上每多存在一個「四方佈雷陣」，傷害額外提升<color=#00F6FF>5%</color>。回合結束時，若璇極位於「四方佈雷陣」內，獲得1枚工備。璇極每次施放連鎖技能後，若位於「四方佈雷陣」內，提升<color=#00F6FF>4%</color>基礎攻擊力，該效果最高可疊加5層，若回合結束時位於「四方佈雷陣」外，層數減半。",
  str_skill_upgrade_desc_16021613 = "主動技能強化：「四方佈雷陣」範圍擴大至<color=#00F6FF>方形25格</color>，持續<color=#00F6FF>3</color>回合。",
  str_skill_upgrade_desc_16021616 = "裝備技能強化：場上每多存在一個「四方佈雷陣」，傷害額外提升<color=#00F6FF>5%</color>。回合結束時，若璇極位於「四方佈雷陣」內，獲得1枚工備。",
  str_skill_name_53820323 = "光靈靠近後爆炸，若無人靠近，則會在幾回合後自爆，並在附近產生若干個火焰。",
  str_skill_name_200400103 = "腹火突擊",
  str_skill_name_200400104 = "腹火突擊",
  str_skill_desc_200400103 = "橫向移動並噴出火焰，對前方目標造成傷害，遇到阻擋時停止移動。",
  str_skill_desc_200400104 = "橫向移動並噴出火焰，對前方目標造成傷害，遇到阻擋時停止移動。",
  str_skill_name_290570123 = "瑪德昂多·吞噬",
  str_skill_desc_290570123 = "瑪德昂多從大泥潭中心冒出吞噬一切，並對光靈造成傷害。",
  str_skill_name_290620102 = "空間切割·緯",
  str_skill_desc_290620102 = "邪劍衝到我方附近劈砍造成傷害，同時在我方周圍橫向切割出3格長的禁壁，然後自身瞬移至新位置。",
  str_skill_name_290620104 = "空間切割·經",
  str_skill_desc_290620104 = "邪劍衝到我方附近劈砍造成傷害，同時在我方周圍縱向切割出3格長的禁壁，然後自身瞬移至新位置。",
  str_skill_name_290620106 = "生人勿近",
  str_skill_desc_290620106 = "邪劍對周圍1圈內的敵人造成傷害並擊退至最遠，同時在自身周圍1圈邊緣切出禁壁。",
  str_skill_name_800400011 = "驅邪機關",
  str_skill_desc_800400011 = "踩踏驅邪機關可以消除場上所有禁壁。",
  str_skill_desc_2900273 = "對任意位置光靈造成傷害並召喚黑金者。",
  str_skill_desc_2000303 = "靠近罪靈黑金者周圍1圈時，繳交金幣為其恢復生命。",
  str_skill_desc_2000304 = "靠近伊斯塔萬周圍1圈時，繳交金幣為其恢復生命。",
  str_skill_desc_200381101 = "移動範圍擴大，移動至目標附近並對其造成2次傷害。移動可越過障礙物。",
  str_skill_desc_200411101 = "移動後攻擊目標2次，擊退目標並留下炸彈，隨後後撤最多3格距離。如果範圍內沒有目標，下回合行動力提升。",
  str_skill_desc_200371101 = "對十字3格距離內的敵人造成傷害並擊退，在擊退前位置留下炸彈。",
  str_skill_upgrade_desc_16021913 = "主動技能強化：進入戰鬥時獲得<color=#00F6FF>5</color>點影賦。\n裝備技能強化：【落棋】技能可點選範圍擴大為周圍2圈。",
  str_skill_upgrade_desc_16021916 = "獲得新主動技能：任選<color=#00F6FF>2</color>個格子，交換兩格上的深色格子，若所選格中包含「影棋」，也會移動到另一個格子。",
  str_skill_name_2002191 = "燼滅爪襲",
  str_skill_name_2002192 = "燼滅爪襲",
  str_skill_name_2002193 = "燼滅爪襲",
  str_skill_desc_2002191 = "對<color=#00F6FF>周圍2圈</color>內最近的4名敵人造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2002192 = "對<color=#00F6FF>周圍3圈</color>內最近的4名敵人造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2002193 = "對<color=#00F6FF>周圍4圈</color>內最靠近的4個敵人造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_name_3002191 = "易位王影",
  str_skill_name_3302191 = "易位王影",
  str_skill_name_3032191 = "易位王影",
  str_skill_name_3332191 = "易位王影",
  str_skill_name_3062191 = "虛影轉移",
  str_skill_desc_3002191 = "選擇1名<color=#00F6FF>己方隊友</color>，消耗<color=#00F6FF>2</color>點<link=\"30096\"><#FFAE07><u>影賦</u></color></link>使其本回合內的<color=#00F6FF>連鎖技能施放次數+1</color>（效果不可疊加）。額外連鎖技能施放時，隊友的攻擊力為伊斯塔萬·沓痕攻擊力的<color=#00F6FF>100%</color>，同時伊斯塔萬·沓痕本回合不會施放連鎖技能。本場戰鬥內，每對同一名己方隊友施放1次主動技能，影賦消耗+1。",
  str_skill_desc_3302191 = "選擇1名<color=#00F6FF>己方隊友</color>，消耗<color=#00F6FF>2</color>點<link=\"30096\"><#FFAE07><u>影賦</u></color></link>使其本回合內的<color=#00F6FF>連鎖技能施放次數+1</color>（效果不可疊加）。額外連鎖技能施放時，隊友的攻擊力為伊斯塔萬·沓痕攻擊力的<color=#00F6FF>100%</color>，同時伊斯塔萬·沓痕本回合不會施放連鎖技能；也可以消耗<color=#00F6FF>2</color>點影賦，選擇場上的「影棋」施放主動技能，本回合則由影棋代替伊斯塔萬·沓痕施放連鎖技能，且最終傷害提高<color=#00F6FF>50%</color>。對影棋施放固定消耗2點影賦。本場戰鬥內，每對同一名己方隊友施放1次主動技能，影賦消耗+1。",
  str_skill_desc_3032191 = "選擇1名<color=#00F6FF>己方隊友</color>，消耗<color=#00F6FF>2</color>點<link=\"30097\"><#FFAE07><u>影賦</u></color></link>使其本回合內的<color=#00F6FF>連鎖技能施放次數+1</color>（效果不可疊加）。額外連鎖技能施放時，隊友的攻擊力為伊斯塔萬·沓痕攻擊力的<color=#00F6FF>100%</color>，同時伊斯塔萬·沓痕本回合不會施放連鎖技能。本場戰鬥內，每對同一名己方隊友施放1次主動技能，影賦消耗+1。",
  str_skill_desc_3332191 = "選擇1名<color=#00F6FF>己方隊友</color>，消耗<color=#00F6FF>2</color>點<link=\"30097\"><#FFAE07><u>影賦</u></color></link>使其本回合內的<color=#00F6FF>連鎖技能施放次數+1</color>（效果不可疊加）。額外連鎖技能施放時，隊友的攻擊力為伊斯塔萬·沓痕攻擊力的<color=#00F6FF>100%</color>，同時伊斯塔萬·沓痕本回合不會施放連鎖技能；也可以消耗<color=#00F6FF>2</color>點影賦，選擇場上的「影棋」施放主動技能，本回合則由影棋代替伊斯塔萬·沓痕施放連鎖技能，且最終傷害提高<color=#00F6FF>50%</color>。對影棋施放固定消耗2點影賦。本場戰鬥內，每對同一名己方隊友施放1次主動技能，影賦消耗+1。",
  str_skill_desc_3062191 = "任選<color=#00F6FF>2</color>個格子，交換兩格上的深色格子，若所選格中包含「影棋」，也會移動到另一個格子。",
