  str_skill_passive_name_423219 = "故影升格",
  str_skill_passive_desc_410219 = "進入戰鬥時，伊斯塔萬·沓痕在隊伍周圍召喚1枚「影棋」，可操控影棋施放技能。\n【落棋】：瞬移至周圍<color=#00F6FF>菱形12格</color>內可行走的格子，並對<color=#00F6FF>周圍2圈</color>內最近的4名敵人造成<color=#00F6FF>{1}</color>的傷害。",
  str_skill_passive_desc_420219 = "進入戰鬥時，伊斯塔萬·沓痕在隊伍周圍召喚1枚「影棋」，可操控影棋施放技能，影棋在回合結束時在所在位置生成<link=\"30093\"><#FFAE07><u>深色格子</u></color></link>。\n【落棋】：瞬移至周圍<color=#00F6FF>菱形12格</color>內可行走的格子，並對<color=#00F6FF>周圍2圈</color>內最近的4名敵人造成<color=#00F6FF>{1}</color>的傷害。",
  str_skill_passive_desc_403219 = "進入戰鬥時，伊斯塔萬·沓痕在隊伍周圍召喚1枚「影棋」，可操控影棋施放技能。\n【落棋】：瞬移至周圍<color=#00F6FF>2圈</color>內可行走的格子，並對<color=#00F6FF>周圍2圈</color>內最近的4名敵人造成<color=#00F6FF>{1}</color>的傷害。",
