  str_skill_desc_160219119 = "瞬移至周圍<color=#00F6FF>2圈</color>內可行走的格子，並對<color=#00F6FF>周圍2圈</color>內最近的4名敵人造成<color=#00F6FF>100%</color>的傷害。",
  str_skill_desc_160219120 = "瞬移至周圍<color=#00F6FF>菱形12格</color>內可行走的格子，並對<color=#00F6FF>周圍2圈</color>內最近的4名敵人造成<color=#00F6FF>110%</color>的傷害。",
  str_skill_desc_160219121 = "瞬移至周圍<color=#00F6FF>2圈</color>內可行走的格子，並對<color=#00F6FF>周圍2圈</color>內最近的4名敵人造成<color=#00F6FF>110%</color>的傷害。",
  str_skill_upgrade_refine_desc_16021911 = "裝備技能強化：【落棋】技能傷害提升為<color=#00F6FF>110%</color>。",
  str_skill_upgrade_refine_desc_16021912 = "主動技能強化：若選擇對「影棋」施放主動技能，該回合內影棋施放連鎖技能的最終傷害加成提升為<color=#00F6FF>60%</color>。",
  str_skill_upgrade_refine_desc_16021913 = "主動技能強化：每波次開始時<color=#00F6FF>+2</color>點影賦。",
  str_skill_passive_desc_450219 = "進入戰鬥時，伊斯塔萬·沓痕在隊伍周圍召喚1枚「影棋」，可操控影棋施放技能，影棋在回合結束時在所在位置生成<link=\"30093\"><#FFAE07><u>深色格子</u></color></link>。\n【落棋】：瞬移至周圍<color=#00F6FF>菱形12格</color>內可行走的格子，並對<color=#00F6FF>周圍2圈</color>內最近的4名敵人造成<color=#00F6FF>110%</color>的傷害。",
  str_skill_passive_desc_453219 = "進入戰鬥時，伊斯塔萬·沓痕在隊伍周圍召喚1枚「影棋」，可操控影棋施放技能，影棋在回合結束時在所在位置生成<link=\"30093\"><#FFAE07><u>深色格子</u></color></link>。\n【落棋】：瞬移至周圍<color=#00F6FF>2圈</color>內可行走的格子，並對<color=#00F6FF>周圍2圈</color>內最近的4名敵人造成<color=#00F6FF>110%</color>的傷害。",
  str_skill_desc_3602191 = "選擇1名<color=#00F6FF>己方隊友</color>，消耗<color=#00F6FF>2</color>點<link=\"30096\"><#FFAE07><u>影賦</u></color></link>使其本回合內的<color=#00F6FF>連鎖技能施放次數+1</color>（效果不可疊加）。額外連鎖技能施放時，隊友的攻擊力為伊斯塔萬·沓痕攻擊力的<color=#00F6FF>100%</color>，同時伊斯塔萬·沓痕本回合不會施放連鎖技能；也可以消耗<color=#00F6FF>2</color>點影賦，選擇場上的「影棋」施放主動技能，本回合則由影棋代替伊斯塔萬·沓痕施放連鎖技能，且最終傷害提高<color=#00F6FF>60%</color>。對影棋施放固定消耗2點影賦。本場戰鬥內，每對同一名己方隊友施放1次主動技能，影賦消耗+1。",
  str_skill_desc_3632191 = "選擇1名<color=#00F6FF>己方隊友</color>，消耗<color=#00F6FF>2</color>點<link=\"30097\"><#FFAE07><u>影賦</u></color></link>使其本回合內的<color=#00F6FF>連鎖技能施放次數+1</color>（效果不可疊加）。額外連鎖技能施放時，隊友的攻擊力為伊斯塔萬·沓痕攻擊力的<color=#00F6FF>100%</color>，同時伊斯塔萬·沓痕本回合不會施放連鎖技能；也可以消耗<color=#00F6FF>2</color>點影賦，選擇場上的「影棋」施放主動技能，本回合則由影棋代替伊斯塔萬·沓痕施放連鎖技能，且最終傷害提高<color=#00F6FF>60%</color>。對影棋施放固定消耗2點影賦。本場戰鬥內，每對同一名己方隊友施放1次主動技能，影賦消耗+1。",
  str_skill_desc_3702191 = "選擇1名<color=#00F6FF>己方隊友</color>，消耗<color=#00F6FF>2</color>點<link=\"30099\"><#FFAE07><u>影賦</u></color></link>使其本回合內的<color=#00F6FF>連鎖技能施放次數+1</color>（效果不可疊加）。額外連鎖技能施放時，隊友的攻擊力為伊斯塔萬·沓痕攻擊力的<color=#00F6FF>100%</color>，同時伊斯塔萬·沓痕本回合不會施放連鎖技能；也可以消耗<color=#00F6FF>2</color>點影賦，選擇場上的「影棋」施放主動技能，本回合則由影棋代替伊斯塔萬·沓痕施放連鎖技能，且最終傷害提高<color=#00F6FF>60%</color>。對影棋施放固定消耗2點影賦。本場戰鬥內，每對同一名己方隊友施放1次主動技能，影賦消耗+1。",
  str_skill_desc_3732191 = "選擇1名<color=#00F6FF>己方隊友</color>，消耗<color=#00F6FF>2</color>點<link=\"30098\"><#FFAE07><u>影賦</u></color></link>使其本回合內的<color=#00F6FF>連鎖技能施放次數+1</color>（效果不可疊加）。額外連鎖技能施放時，隊友的攻擊力為伊斯塔萬·沓痕攻擊力的<color=#00F6FF>100%</color>，同時伊斯塔萬·沓痕本回合不會施放連鎖技能；也可以消耗<color=#00F6FF>2</color>點影賦，選擇場上的「影棋」施放主動技能，本回合則由影棋代替伊斯塔萬·沓痕施放連鎖技能，且最終傷害提高<color=#00F6FF>60%</color>。對影棋施放固定消耗2點影賦。本場戰鬥內，每對同一名己方隊友施放1次主動技能，影賦消耗+1。",
  str_skill_name_2002201 = "慧眼識珠",
