  str_skill_name_3022201 = "八面臨光",
  str_skill_desc_20022011 = "造成2次<color=#00F6FF>125%</color>的傷害。隨機分配到自身<color=#00F6FF>周圍3圈</color>內的敵人身上。對同一目標造成多次傷害時，從第2次起每次傷害減半。",
  str_skill_desc_2002202 = "造成3次<color=#00F6FF>130%</color>的傷害。隨機分配到自身<color=#00F6FF>周圍3圈</color>內的敵人身上。對同一目標造成多次傷害時，從第2次起每次傷害減半。",
  str_skill_desc_2002203 = "造成4次<color=#00F6FF>135%</color>的傷害。隨機分配到自身<color=#00F6FF>周圍3圈</color>內的敵人身上。對同一目標造成多次傷害時，從第2次起每次傷害減半。",
  str_skill_desc_3002201 = "將最近的<color=#00F6FF>2</color>個雷屬性格子轉為水屬性深色格子。",
  str_skill_desc_3002202 = "將最近的<color=#00F6FF>2</color>個雷屬性格子轉為水屬性深色格子。若主動技能上回合就緒，本回合轉色數量<color=#00F6FF>+1</color>。",
  str_skill_desc_3052201 = "將最近的<color=#00F6FF>3</color>個雷屬性格子轉為水屬性深色格子。若主動技能上回合就緒，本回合轉色數量<color=#00F6FF>+1</color>。",
  str_skill_desc_3052202 = "將最近的<color=#00F6FF>3</color>個雷屬性格子轉為水屬性深色格子。若主動技能上回合就緒，本回合轉色數量<color=#00F6FF>+1</color>。",
  str_skill_passive_name_410220 = "開門霓虹",
  str_skill_passive_name_420220 = "開門霓虹",
  str_skill_passive_name_430220 = "開門霓虹",
  str_skill_passive_desc_410220 = "每回合開始時，對場上最遠的1名敵人施加<color=#00F6FF>鑑定</color>效果，持續1回合。帶有鑑定效果的目標每受到1次單體連鎖技能攻擊，便會額外受到1次相當於維吉爾攻擊力<color=#00F6FF>{1}</color>的傷害。",
  str_skill_passive_desc_420220 = "每回合開始時，對場上最遠的1名敵人施加<color=#00F6FF>鑑定</color>效果，持續1回合。進入極光時刻時，該效果額外生效1次。帶有鑑定效果的目標每受到1次單體類型連鎖技能攻擊，便會額外受到1次相當於維吉爾攻擊力<color=#00F6FF>{1}</color>的傷害。",
  str_skill_passive_desc_430220 = "每回合開始時，對場上最遠的1名敵人施加<color=#00F6FF>鑑定</color>效果，持續1回合。進入極光時刻時，該效果額外生效1次。帶有鑑定效果的目標每受到1次單體類型連鎖技能攻擊，便會額外受到1次相當於維吉爾攻擊力<color=#00F6FF>{1}</color>的追擊傷害。目標受到維吉爾連鎖技能攻擊時，追擊傷害翻倍。",
  str_skill_upgrade_desc_15022012 = "主動技能強化：若上回合技能就緒，本回合額外將1個雷屬性格子轉為水屬性深色格子。",
  str_skill_upgrade_desc_15022015 = "主動技能強化：水屬性深色格子轉換數量增加1個。",
  str_skill_desc_290910114 = "移動後對固定範圍造成傷害，並附加3層「融體」效果。",
  str_skill_desc_290910124 = "移動後對固定範圍造成傷害，附加3層「融體」效果，並召喚大量「毒痕」。",
  str_skill_name_16021911 = "普通攻擊",
  str_skill_desc_16021911 = "移動後施放普通攻擊，一擊斃命。",
  str_skill_desc_16021912 = "移動後施放連鎖技能，對每個目標造成最大生命值40%的傷害。",
