  str_skill_desc_2002181 = "以固定的順序對<color=#00F6FF>周圍2圈</color>內的敵人造成3次<color=#00F6FF>150%</color>的傷害。對同一目標造成多次傷害時，從第2次起，每次傷害減半。",
  str_skill_desc_2002182 = "以固定的順序對<color=#00F6FF>周圍3圈</color>內的敵人造成4次<color=#00F6FF>155%</color>的傷害。對同一目標造成多次傷害時，從第2次起，每次傷害減半。",
  str_skill_desc_2002183 = "以固定的順序對<color=#00F6FF>周圍3圈</color>內的敵人造成5次<color=#00F6FF>165%</color>的傷害。對同一目標造成多次傷害時，從第2次起，每次傷害減半。",
  str_skill_desc_2002184 = "以固定的順序對<color=#00F6FF>周圍2圈</color>內的敵人造成3次<color=#00F6FF>150%</color>的傷害。對同一目標造成多次傷害時，從第2次起，每次傷害減半。對最遠的目標再追加造成1次傷害。",
  str_skill_desc_2002185 = "以固定的順序對<color=#00F6FF>周圍3圈</color>內的敵人造成4次<color=#00F6FF>155%</color>的傷害。對同一目標造成多次傷害時，從第2次起，每次傷害減半。對最遠的目標再追加造成1次傷害。",
  str_skill_desc_2002186 = "以固定的順序對<color=#00F6FF>周圍3圈</color>內的敵人造成5次<color=#00F6FF>165%</color>的傷害。對同一目標造成多次傷害時，從第2次起，每次傷害減半。對最遠的目標再追加造成1次傷害。",
  str_skill_desc_2202181 = "以固定的順序對<color=#00F6FF>周圍2圈</color>內的敵人造成3次<color=#00F6FF>150%</color>的傷害。對同一目標造成多次傷害時，從第2次起，每次傷害減半。本次連線每經過1個深色格子，連鎖技能範圍擴大1圈。",
  str_skill_desc_2202182 = "以固定的順序對<color=#00F6FF>周圍3圈</color>內的敵人造成4次<color=#00F6FF>155%</color>的傷害。對同一目標造成多次傷害時，從第2次起，每次傷害減半。本次連線每經過1個深色格子，連鎖技能範圍擴大1圈。",
  str_skill_desc_2202183 = "以固定的順序對<color=#00F6FF>周圍3圈</color>內的敵人造成5次<color=#00F6FF>165%</color>的傷害。對同一目標造成多次傷害時，從第2次起，每次傷害減半。本次連線每經過1個深色格子，連鎖技能範圍擴大1圈。",
  str_skill_desc_2202184 = "以固定的順序對<color=#00F6FF>周圍2圈</color>內的敵人造成3次<color=#00F6FF>150%</color>的傷害。對同一目標造成多次傷害時，從第2次起，每次傷害減半。對最遠的目標再追加造成1次傷害，不計算衰減次數。本次連線每經過1個深色格子，連鎖技能範圍擴大1圈。",
  str_skill_desc_2202185 = "以固定的順序對<color=#00F6FF>周圍3圈</color>內的敵人造成4次<color=#00F6FF>155%</color>的傷害。對同一目標造成多次傷害時，從第2次起，每次傷害減半。對最遠的目標再追加造成1次傷害，不計算衰減次數。本次連線每經過1個深色格子，連鎖技能範圍擴大1圈。",
  str_skill_desc_2202186 = "以固定的順序對<color=#00F6FF>周圍3圈</color>內的敵人造成5次<color=#00F6FF>165%</color>的傷害。對同一目標造成多次傷害時，從第2次起，每次傷害減半。對最遠的目標再追加造成1次傷害，不計算衰減次數。本次連線每經過1個深色格子，連鎖技能範圍擴大1圈。",
  str_skill_desc_3002181 = "選擇1個格子轉為水屬性<link=\"30093\"><#FFAE07><u>深色格子</u></color></link>，並對<color=#00F6FF>十字形5格</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_30021811 = "選擇1個格子轉為水屬性<link=\"30093\"><#FFAE07><u>深色格子</u></color></link>，並對<color=#00F6FF>菱形13格</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_3402181 = "<color=#FFFF00>施放後技能冷卻回合-1</color>。選擇1個格子，對<color=#00F6FF>十字形5格</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_3412181 = "<color=#FFFF00>施放後技能冷卻回合-1</color>。選擇1個格子，對<color=#00F6FF>菱形13格</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_3402182 = "選擇1個格子轉為水屬性<link=\"30093\"><#FFAE07><u>深色格子</u></color></link>，並對<color=#00F6FF>十字形5格</color>造成<color=#00F6FF>{1}%</color>的傷害。當下每擁有5點資本，額外獲得1點分紅。",
  str_skill_desc_3412182 = "選擇1個格子轉為水屬性<link=\"30093\"><#FFAE07><u>深色格子</u></color></link>，並對<color=#00F6FF>菱形13格</color>造成<color=#00F6FF>{1}%</color>的傷害。當下每擁有5點資本，額外獲得1點分紅。",
  str_skill_desc_30021812 = "選擇1個格子轉為水屬性<link=\"30093\"><#FFAE07><u>深色格子</u></color></link>，並對<color=#00F6FF>十字形5格</color>造成<color=#00F6FF>150%</color>的傷害。",
  str_skill_desc_300218112 = "選擇1個格子轉為水屬性<link=\"30093\"><#FFAE07><u>深色格子</u></color></link>，並對<color=#00F6FF>菱形13格</color>造成<color=#00F6FF>150%</color>的傷害。",
  str_skill_desc_34021812 = "<color=#FFFF00>施放後技能冷卻回合-1</color>。選擇1個格子，對<color=#00F6FF>十字形5格</color>造成<color=#00F6FF>150%</color>的傷害。",
  str_skill_desc_34121812 = "<color=#FFFF00>施放後技能冷卻回合-1</color>。選擇1個格子，對<color=#00F6FF>菱形13格</color>造成<color=#00F6FF>150%</color>的傷害。",
  str_skill_desc_34021822 = "選擇1個格子轉為水屬性<link=\"30093\"><#FFAE07><u>深色格子</u></color></link>，並對<color=#00F6FF>十字形5格</color>造成<color=#00F6FF>150%</color>的傷害。當下每擁有5點資本，額外獲得1點分紅。",
  str_skill_desc_34121822 = "選擇1個格子轉為水屬性<link=\"30093\"><#FFAE07><u>深色格子</u></color></link>，並對<color=#00F6FF>菱形13格</color>造成<color=#00F6FF>150%</color>的傷害。當下每擁有5點資本，額外獲得1點分紅。",
  str_skill_passive_desc_410218 = "涉在進入戰鬥後自帶<link=\"510218\"><#FFAE07><u>【投資戰略】</u></color></link>，可累積資本選擇投資戰略，解鎖戰鬥能力。（投資戰略中「霧氣驅使」「一擲億金」「資本打擊」在裝備等級提升至3/6/10後解鎖）",
  str_skill_passive_desc_413218 = "涉在進入戰鬥後自帶<link=\"513218\"><#FFAE07><u>【投資戰略】</u></color></link>，可累積資本選擇投資戰略，解鎖戰鬥能力。第二輪投資結束後，接下來每獲得1點資本，涉的攻擊力便提升1%，最多折算40點。（投資戰略中「霧氣驅使」「一擲億金」「資本打擊」在裝備等級提升至3/6/10後解鎖）",
  str_skill_passive_desc_416218 = "涉在進入戰鬥後自帶<link=\"516218\"><#FFAE07><u>【投資戰略】</u></color></link>，可累積資本選擇投資戰略，解鎖戰鬥能力。戰鬥一開始便擁有5點資本，第二輪投資結束後，接下來每獲得1點資本，涉的攻擊力便提升1%，最多折算40點。（投資戰略中「霧氣驅使」「一擲億金」「資本打擊」在裝備等級提升至3/6/10後解鎖）",
  str_skill_passive_desc_430218 = "涉在進入戰鬥後自帶<link=\"530218\"><#FFAE07><u>【投資戰略】</u></color></link>，可累積資本選擇投資戰略，解鎖戰鬥能力。第一輪投資完成後，可繼續第二輪投資，獲得第一輪未獲得的戰鬥能力。（投資戰略中「霧氣驅使」「一擲億金」「資本打擊」在裝備等級提升至3/6/10後解鎖）",
  str_skill_passive_desc_433218 = "涉在進入戰鬥後自帶<link=\"533218\"><#FFAE07><u>【投資戰略】</u></color></link>，可累積資本選擇投資戰略，解鎖戰鬥能力。第一輪投資完成後，可繼續第二輪投資，獲得第一輪未獲得的戰鬥能力。第二輪投資結束後，接下來每獲得1點資本，涉的攻擊力便提升1%，最多折算40點。（投資戰略中「霧氣驅使」「一擲億金」「資本打擊」在裝備等級提升至3/6/10後解鎖）",
  str_skill_passive_desc_436218 = "涉在進入戰鬥後自帶<link=\"536218\"><#FFAE07><u>【投資戰略】</u></color></link>，可累積資本選擇投資戰略，解鎖戰鬥能力。第一輪投資完成後，可繼續第二輪投資，獲得第一輪未獲得的戰鬥能力。戰鬥一開始便擁有5點資本，第二輪投資結束後，接下來每獲得1點資本，涉的攻擊力便提升1%，最多折算40點。（投資戰略中「霧氣驅使」「一擲億金」「資本打擊」在裝備等級提升至3/6/10後解鎖）",
  str_skill_upgrade_desc_16021813 = "裝備技能強化：第二輪投資結束後，接下來每獲得1點資本，涉的攻擊力便提升1%，最多折算40點。（覺醒3解鎖）",
  str_skill_upgrade_desc_16021816 = "戰鬥一開始便擁有5點資本，施放主動技能時，當下每擁有5點資本，額外獲得1點分紅。",
  str_skill_name_53920111 = "普通攻擊",
  str_skill_desc_53920111 = "移動後對敵人發動普通攻擊，造成大量傷害。",
  str_skill_desc_53920112 = "移動後對周圍2圈內的敵人造成傷害。",
  str_skill_desc_53920214 = "隊伍經過深色格子時，涉會對周圍2圈內的敵人造成2次傷害",
  str_skill_upgrade_refine_desc_16021811 = "<color=#00F6FF>新增主動技能變體</color>：<color=#FFFF00>施放後技能冷卻回合-1</color>。主動技能不會生成水屬性深色格子，只造成傷害。",
  str_skill_upgrade_refine_desc_16021812 = "主動技能強化：傷害提升<color=#00F6FF>30%</color>。",
  str_skill_upgrade_refine_desc_16021813 = "裝備技能強化：投資戰略中第二輪的資本需求減少1點。",
  str_skill_name_70011191 = "末逐·噬魔吞卷",
  str_skill_desc_70011191 = "當目標處於範圍內時，吞噬前方兩圈內光靈與「鬼」，對光靈造成傷害，隨後將光靈吐至場地邊緣。",
  str_skill_name_70011192 = "末逐·噬魔鬼滅",
  str_skill_desc_70011192 = "當目標處於範圍內時，對目標造成大量傷害，並秒殺目標周圍的「鬼」。",
  str_skill_name_70011193 = "末逐·噬魔鬼呼軍陣",
  str_skill_desc_70011193 = "當目標處於範圍內時，召喚大量的「鬼」，並強化場上所有的「鬼」。",
  str_skill_name_70011195 = "末逐·噬魔吞卷",
  str_skill_desc_70011195 = "當目標處於範圍內時，吞噬前方兩圈內光靈與「鬼」，對光靈造成真實傷害，吞噬的「鬼」數量越多傷害越高，隨後將光靈吐至場地邊緣。",
  str_skill_name_200440103 = "斷裂打擊",
  str_skill_name_200450103 = "連續爆破",
  str_skill_name_200460103 = "武裝突襲",
  str_skill_name_200460104 = "全滅打擊",
  str_skill_desc_200440103 = "揮動武器對光靈造成傷害。",
  str_skill_desc_200450103 = "對十字最大範圍內的光靈造成傷害。",
  str_skill_desc_200460103 = "移動後對光靈造成傷害。",
  str_skill_desc_200460104 = "移動後朝著光靈所在位置施放穿透攻擊，不分敵我造成傷害後扣減自身的生命值。",
  str_skill_name_8004003 = "光靈靠近後爆炸，若無人靠近，則會在幾回合後自爆，並在附近產生長度為1格的禁壁。",
  str_skill_desc_8004039 = "本回合傷害爆發：雙刀使用手中的利刃對位於攻擊範圍內的目標進行2次攻擊，傷害極高。",
  str_skill_name_8004039 = "雙斬+",
  str_skill_desc_8004055 = "邪劍衝到我方附近劈砍造成傷害，同時在我方周圍橫向切割出5格長的禁壁，然後自身瞬移至新位置。",
  str_skill_desc_8004057 = "邪劍衝到我方附近劈砍造成傷害，同時在我方周圍縱向切割出5格長的禁壁，然後自身瞬移至新位置。",
  str_skill_desc_8004051 = "邪劍衝到我方附近劈砍造成傷害，同時在我方周圍橫向切割出3格長的禁壁，然後自身瞬移回原位。",
  str_skill_desc_8004053 = "邪劍衝到我方附近劈砍造成傷害，同時在我方周圍縱向切割出3格長的禁壁，然後自身瞬移回原位。",
  str_skill_name_8004012 = "喚·追蜂蔓靶+",
  str_skill_desc_8004012 = "每回合召喚1隻「追蜂」和1隻「蔓靶」進入戰場。",
  str_skill_desc_8004022 = "踩踏驅邪機關後，下回合開始光靈周圍的禁壁將重新擴大為周圍3圈。",
  str_skill_desc_8004040 = "踩踏驅邪機關可以在敵人周圍召喚禁壁。",
  str_skill_desc_8004050 = "踩踏驅邪機關可以消除周圍2圈內的禁壁。",
  str_skill_name_290640101 = "踐踏萬物",
  str_skill_name_290640102 = "功率輸出",
  str_skill_name_290640103 = "組件更迭",
  str_skill_desc_290640101 = "移動後，消耗自身生命值和所有機械護甲層數，對身前2格範圍內的目標發動攻擊；若目標與布勞格姆相鄰，則將其向後擊退1格。攻擊後，根據所消耗的機械護甲層數恢復自身生命值。",
  str_skill_desc_290640102 = "對前方扇形範圍內的所有目標造成傷害，離目標越近傷害越高。",
  str_skill_desc_290640103 = "布勞格姆蓄積力量永久提升自身攻擊力、防禦力和生命值上限，同時獲得一定的機械護甲層數。",
  str_skill_name_29063011 = "風速壓迫",
