  str_skill_name_29063013 = "軀體改造",
  str_skill_desc_29063011 = "向光靈移動後，對前方2格範圍內的目標造成傷害。",
  str_skill_desc_29063012 = "數據打擊",
  str_skill_desc_29063013 = "尤利西斯會利用守護者·原型對任意位置的光靈造成傷害。",
