  str_skill_desc_2002212 = "布林對<color=#00F6FF>米字形16格</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2002213 = "布林對<color=#00F6FF>米字形24格</color>造成<color=#00F6FF>{1}%</color>的傷害。",
