  str_skill_name_346221 = "死亡賦值",
  str_skill_desc_300221 = "選定1個格子，在該格子<color=#00F6FF>周圍1圈</color>選擇3個格子轉為<link=\"30093\"><#FFAE07><u>深色格子</u></color></link>。布林對該範圍造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_306221 = "選定1個格子，在該格子周圍<color=#00F6FF>菱形12格</color>選擇4個格子轉為<link=\"30093\"><#FFAE07><u>深色格子</u></color></link>。布林對該範圍造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_320221 = "選定1個格子，在該格子<color=#00F6FF>周圍1圈</color>選擇3個格子轉為<link=\"30093\"><#FFAE07><u>深色格子</u></color></link>。布林對該範圍造成<color=#00F6FF>{1}%</color>的傷害，每造成1次傷害，獲得1點運算值。",
  str_skill_desc_326221 = "選定1個格子，在該格子周圍<color=#00F6FF>菱形12格</color>選擇4個格子轉為<link=\"30093\"><#FFAE07><u>深色格子</u></color></link>。布林對該範圍造成<color=#00F6FF>{1}%</color>的傷害，每造成1次傷害，獲得1點運算值。",
  str_skill_desc_340221 = "選定1個格子，在該格子<color=#00F6FF>周圍1圈</color>選擇3個格子轉為<link=\"30093\"><#FFAE07><u>深色格子</u></color></link>。布林對該範圍造成<color=#00F6FF>250%</color>的傷害，每造成1次傷害，獲得1點運算值。",
  str_skill_desc_346221 = "選定1個格子，在該格子周圍<color=#00F6FF>菱形12格</color>選擇4個格子轉為<link=\"30093\"><#FFAE07><u>深色格子</u></color></link>。布林對該範圍造成<color=#00F6FF>250%</color>的傷害，每造成1次傷害，獲得1點運算值。",
  str_skill_passive_name_410221 = "奈米魔術數",
  str_skill_passive_name_430221 = "奈米魔術數",
  str_skill_passive_name_440221 = "奈米魔術數",
  str_skill_passive_name_443221 = "奈米魔術數",
  str_skill_passive_desc_410221 = "每次經過<link=\"30093\"><#FFAE07><u>深色格子</u></color></link>，便獲得1點運算值。每點運算值增加布林<color=#00F6FF>{1}</color>的傷害，回合結束時保留一半的運算值。",
  str_skill_passive_desc_430221 = "每次經過<link=\"30093\"><#FFAE07><u>深色格子</u></color></link>，便獲得1點運算值。每點運算值增加布林<color=#00F6FF>{1}</color>的傷害，回合結束時保留一半的運算值。若行動結束時運算值至少有<color=#00F6FF>3</color>點，布林額外對受過布林最多次傷害的敵人造成1次<color=#00F6FF>100%</color>的傷害。",
  str_skill_passive_desc_440221 = "每次經過<link=\"30093\"><#FFAE07><u>深色格子</u></color></link>，便獲得1點運算值。每點運算值增加布林<color=#00F6FF>6%</color>的傷害，回合結束時保留一半的運算值。若行動結束時運算值至少有<color=#00F6FF>3</color>點，布林額外對受過布林最多次傷害的敵人造成1次<color=#00F6FF>100%</color>的傷害。",
  str_skill_passive_desc_443221 = "每次經過<link=\"30093\"><#FFAE07><u>深色格子</u></color></link>，便獲得1點運算值。每點運算值增加布林<color=#00F6FF>6%</color>的傷害，回合結束時保留一半的運算值。若行動結束時運算值至少有<color=#00F6FF>3</color>點，布林額外對受過布林最多次傷害的敵人造成1次<color=#00F6FF>120%</color>的傷害。",
  str_skill_upgrade_refine_desc_16022111 = "裝備技能強化：每點運算值增加布林<color=#00F6FF>6%</color>的傷害。",
  str_skill_upgrade_refine_desc_16022112 = "主動技能強化：技能傷害係數提升<color=#00F6FF>30%</color>。",
  str_skill_upgrade_refine_desc_16022113 = "裝備技能強化：布林造成的額外傷害提升至<color=#00F6FF>120%</color>。",
