  str_skill_desc_802402 = "覆滅城池的泥石流殘留，可以清除任意1格的堅石和禁壁",
  str_skill_desc_802403 = "星辰移動時留下的露水，使用後可以增加光靈7點行動值",
  str_skill_desc_802404 = "遙遠神祕東方的火藥武器，將1圈範圍內的敵人擊退到最遠並造成傷害",
  str_skill_desc_802405 = "草藥可以救人，亦可下毒。眩暈目標1回合",
