  str_skill_desc_8024150 = "攫取器對周圍的敵人造成其生命上限30%的傷害，消耗5點行動值。",
  str_skill_desc_8024151 = "攫取器進行自我維修，回復生命上限25%的生命值，消耗3點行動值。",
