  str_skill_desc_2002233 = "對<color=#00F6FF>菱形24格</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_3002231 = "在自身周圍8個方向中選擇1個方向，將該方向前後<color=#00F6FF>所有格子</color>轉為雷屬性，並優先沿著選擇的方向生成<color=#00F6FF>3</color>個<link=\"30093\"><#FFAE07><u>深色格子</u></color></link>。",
  str_skill_desc_3062231 = "在自身周圍8個方向中選擇1個方向，將該方向前後<color=#00F6FF>所有格子</color>轉為雷屬性，並優先沿著選擇的方向生成<color=#00F6FF>5</color>個<link=\"30093\"><#FFAE07><u>深色格子</u></color></link>。",
  str_skill_passive_desc_410223 = "辰霓的普通攻擊變為攻擊場上與隊伍生命值百分比相差最大的目標，造成隊伍平均攻擊力<color=#00F6FF>{1}</color>的傷害。",
  str_skill_passive_desc_420223 = "辰霓的普通攻擊變為攻擊場上與隊伍生命值百分比相差最大的目標，造成隊伍平均攻擊力<color=#00F6FF>{1}</color>的傷害。每次經過<link=\"30093\"><#FFAE07><u>深色格子</u></color></link>時額外觸發1次<color=#00F6FF>1.5</color>倍的傷害效果。",
  str_skill_passive_desc_430223 = "辰霓的普通攻擊變為攻擊場上與隊伍生命值百分比相差最大的目標，造成隊伍平均攻擊力<color=#00F6FF>{1}</color>的傷害。每次經過<link=\"30093\"><#FFAE07><u>深色格子</u></color></link>時額外觸發1次<color=#00F6FF>1.5</color>倍的傷害效果。造成傷害時，目標的生命值百分比與隊伍差距越大，該傷害越高，最多提高<color=#00F6FF>50%</color>。",
  str_skill_name_70011211 = "末逐·王霸之氣",
  str_skill_name_70011212 = "末逐·狂怒浪潮",
  str_skill_upgrade_desc_15022412 = "主動技能變為<color=#FFFF00>先制攻擊</color>，進入戰鬥即可使用。進入戰鬥後獲得10點守祟淨火。",
  str_skill_upgrade_desc_15022415 = "裝備技能強化：經過任意屬性的格子皆可獲得守祟淨火。",
  str_skill_name_2002241 = "祟火炎槌",
  str_skill_name_2002242 = "祟火炎槌",
  str_skill_name_2002243 = "祟火炎槌",
  str_skill_name_300224 = "突擊有方",
  str_skill_name_3002241 = "突擊有方·變體I",
  str_skill_name_3002242 = "突擊有方·變體II",
  str_skill_passive_name_410224 = "同力協契",
  str_skill_passive_name_412224 = "同力協契",
  str_skill_passive_name_415224 = "同力協契",
  str_skill_desc_2002241 = "丟出阿丁，對最近的敵人所在的距離自己最近的格子造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2002242 = "丟出阿丁，對最近的敵人所在的距離自己最近的格子造成<color=#00F6FF>{1}%</color>的傷害，並對其周圍<color=#00F6FF>十字形4格</color>造成30%濺射傷害。",
  str_skill_desc_2002243 = "丟出阿丁，對最近的敵人所在的距離自己最近的格子造成<color=#00F6FF>{1}%</color>的傷害，並對其<color=#00F6FF>周圍1圈</color>造成30%濺射傷害。",
  str_skill_desc_300224 = "選擇1個格子作為自身本回合施放連鎖技能的中心位置，且本回合連鎖技能觸發條件-3。",
  str_skill_desc_3002241 = "<color=#FFFF00>施放後技能冷卻回合-1</color>。施放後本回合不施放連鎖技能，普通攻擊可攻擊斜方向，每次普通攻擊獲得2點守祟淨火。",
  str_skill_desc_3002242 = "<color=#FFFF00>施放後技能冷卻回合+1</color>。選擇1個格子作為自身本回合施放連鎖技能的中心位置，並造成<color=#00F6FF>100%</color>的傷害，每點守祟淨火增加10%傷害。自身本回合連鎖技能觸發條件-3，並附加擊退效果。",
  str_skill_passive_desc_410224 = "在火屬性格子上每移動1格，獲得1點守祟淨火，每點提升下次連鎖技能<color=#00F6FF>{1}</color>的傷害，連鎖技能施放後清空。",
  str_skill_passive_desc_412224 = "在火屬性格子上每移動1格，獲得1點守祟淨火，每點提升下次連鎖技能<color=#00F6FF>{1}</color>的傷害，連鎖技能施放後清空。進入戰鬥後獲得10點守祟淨火。",
  str_skill_passive_desc_415224 = "每移動1格，獲得1點守祟淨火，每點提升下次連鎖技能<color=#00F6FF>{1}</color>的傷害，連鎖技能施放後清空。進入戰鬥後獲得10點守祟淨火。",
  str_skill_desc_9997040 = "任選2個格子轉為彩色格子，每消除1個格子獲得1點充能，累積60點充能後獲得1次使用次數。最多儲存2次。",
  str_skill_desc_9997041 = "選擇3*3範圍，消除其中的水屬性格子，每消除1個格子獲得1點充能，累積50點充能後獲得1次使用次數。最多儲存3次。",
  str_skill_desc_9997042 = "選擇3*3範圍，消除其中的火屬性格子，每消除1個格子獲得1點充能，累積50點充能後獲得1次使用次數。最多儲存3次。",
  str_skill_desc_9997043 = "選擇3*3範圍，消除其中的森屬性格子，每消除1個格子獲得1點充能，累積50點充能後獲得1次使用次數。最多儲存3次。",
  str_skill_desc_9997044 = "選擇3*3範圍，消除其中的雷屬性格子，每消除1個格子獲得1點充能，累積50點充能後獲得1次使用次數。最多儲存3次。",
  str_skill_desc_9997045 = "重設全場格子，每消除1個格子獲得1點充能，累積80點充能後獲得1次使用次數。最多儲存3次。",
  str_skill_desc_9997046 = "任選1個屬性，重設全場該屬性格子，每消除1個格子獲得1點充能，累積80點充能後獲得1次使用次數。最多儲存2次。",
  str_skill_desc_9997047 = "任選1個格子，消除距離其最近的4個同屬性格子，每消除1個格子獲得1點充能，累積60點充能後獲得1次使用次數。最多儲存3次。",
  str_skill_name_5066101 = "萬色寶石",
  str_skill_desc_5066101 = "將場上所有格子轉為彩色格子。",
  str_skill_name_5060801 = "破壁者",
  str_skill_desc_5060801 = "消耗2回合，立即施放1次等級2的陣營支援技能，每回合只能使用1次。",
  str_skill_name_20047011 = "鑿牆穿體",
  str_skill_desc_20047011 = "移動後攻擊十字相鄰4格上的目標，之後穿過目標位移到其周圍的格子上，優先選擇目標身後1格。",
  str_skill_name_5412015 = "喚·影妖",
  str_skill_desc_5412015 = "每回合召喚影妖進入戰場。",
  str_skill_name_9997040 = "光輝大劍",
  str_skill_name_9997046 = "光耀之盾",
  str_skill_name_9997047 = "光輝長槍",
  str_skill_desc_5064701 = "選擇5*5範圍，消除其中的水屬性格子，每消除1個格子獲得1點充能，累積40點充能後獲得1次使用次數。最多儲存3次。",
  str_skill_desc_5064702 = "選擇5*5範圍，消除其中的火屬性格子，每消除1個格子獲得1點充能，累積40點充能後獲得1次使用次數。最多儲存3次。",
  str_skill_desc_5064703 = "選擇5*5範圍，消除其中的森屬性格子，每消除1個格子獲得1點充能，累積40點充能後獲得1次使用次數。最多儲存3次。",
  str_skill_desc_5064704 = "選擇5*5範圍，消除其中的雷屬性格子，每消除1個格子獲得1點充能，累積40點充能後獲得1次使用次數。最多儲存3次。",
  str_skill_name_5411002 = "龍佑之舞",
  str_skill_desc_5411002 = "對菱形24格範圍造成傷害。",
  str_skill_name_5411003 = "喚·祟靈",
  str_skill_desc_5411003 = "召喚2隻祟靈·鼠輩進入戰場。",
  str_skill_desc_5411012 = "麥格芬·斯摩為即將到來的白夜升潮蓄積力量，並在身前召喚若干影妖。",
  str_skill_desc_5411020 = "格茲德在場景中的隨機位置召喚4個不會移動的格茲德僕從。",
  str_skill_desc_5411021 = "格茲德攻擊範圍的目標，並為目標施加1層破裂印記。印記層數越高，目標防禦越低。同時召喚2個格茲德僕從。",
  str_skill_desc_5411022 = "格茲德怒吼，對範圍內的敵方目標施加2層破裂印記，印記層數越高，目標防禦越低。同時召喚2個格茲德僕從。",
  str_skill_desc_5411023 = "格茲德引爆目標身上的破裂印記，對其造成大量傷害。印記層數越多，傷害越高。同時召喚2個格茲德僕從。",
  str_skill_desc_5411025 = "格茲德在場景中隨機區域召喚4個僕從，僕從不會移動。",
  str_skill_desc_5411026 = "格茲德瘋狂攻擊範圍的目標2次，並為目標施加2層破裂印記。印記層數越高，目標防禦越低。同時召喚2個格茲德僕從。",
  str_skill_desc_5411027 = "格茲德最後的怒吼，對範圍內的目標施加3層破裂印記。印記層數越高，目標防禦越低。同時召喚2個格茲德僕從。",
  str_skill_desc_5411004 = "召喚藏兵困籠。",
