  str_skill_desc_5065501 = "消除後，本回合內連鎖技能傷害提升35%。",
  str_skill_desc_5065601 = "消除後，隨機1個空裔特別裝具獲得1次使用次數。",
  str_skill_desc_5065801 = "消除後，獲得3點總回合數。",
  str_skill_name_29093013 = "新年步伐",
  str_skill_desc_29093013 = "年獸向前躍進3格，在落點對一圈範圍造成傷害並向兩側擊退，躍至門口會摧毀大門進入",
  str_skill_name_7001125103 = "末逐·怒吼",
  str_skill_desc_7001125103 = "末逐·癲蹄對全場光靈造成傷害，提高自身行動力並召喚碎石。",
  str_skill_name_7001125104 = "末逐·地碎撞",
  str_skill_desc_7001125104 = "末逐·癲蹄生成若干弱化格子，衝撞並擊退光靈，破壞途徑的碎石。",
  str_skill_name_7001125105 = "末逐·滅破擊",
  str_skill_desc_7001125105 = "末逐·癲蹄移動後重擊面前2格，造成巨額傷害並生成弱化格子。",
  str_skill_name_7001126103 = "末逐·釋放壞情緒",
  str_skill_desc_7001126103 = "末逐·錢德菈遠離光靈移動後，對2圈範圍內的光靈造成傷害。",
  str_skill_name_7001126104 = "末逐·負面情緒投射",
  str_skill_desc_7001126104 = "末逐·錢德菈對全場光靈造成傷害。",
  str_skill_name_80150311 = "堅石",
  str_skill_desc_80150311 = "堅石在這裡已經阻擋得夠久了，消耗2點行動值把它清掉吧。",
  str_skill_name_290940103 = "幽火長矛",
  str_skill_desc_290940103 = "阿伊讓對光靈造成傷害，並在光靈十字最大範圍上的棋盤最外圈生成幽火。",
  str_skill_name_290940104 = "灼熱爆破",
  str_skill_desc_290940104 = "阿伊讓對自身周圍2圈內的光靈造成傷害。",
  str_skill_name_290940105 = "憤怒隕石",
  str_skill_desc_290940105 = "阿伊讓向光靈上回合所在位置召喚隕石攻擊，造成秒殺傷害。摧毀範圍中心格子，同時在十字4格生成損壞格子。",
  str_skill_name_200480103 = "焚魂幽火",
  str_skill_desc_200480103 = "幽火對範圍內光靈造成傷害並瞬移至棋盤另一側。若無法攻擊到玩家，則沿著棋盤最外圈順時針瞬移2格。",
  str_skill_name_300226 = "你蛙補天",
  str_skill_name_200226 = "呱殺",
  str_skill_passive_name_400226 = "聽取蛙聲一片",
  str_skill_desc_300226 = "夢境中的白蛙王子能夠平息噴發的火山、修補天空中的黑色裂隙。而在現實中，牠也想用自己的溫柔療癒同伴……你問有什麼用？可愛就是最大的用處！",
  str_skill_desc_200226 = "顯示白蛙王子決意的一呱，響徹整個艾斯特拉！……你問有什麼用？可愛就是最大的用處！",
  str_skill_passive_desc_400226 = "這蛙聲是大自然的心跳，是艾斯特拉的呼吸，是無盡黑暗中的一束光。聽到了嗎？牠正在邀請同伴加入這場盛大的慶典，一起唱出呱呱的讚歌！……你問有什麼用？大家一起呱呱就是最大的用處！",
  str_skill_name_54350081 = "禮砲護衛",
  str_skill_desc_54350081 = "保護國王，禮砲有責！禮砲將在光靈連鎖後退場。",
  str_skill_upgrade_desc_16022513 = "主動技能強化：主動技能變為<color=#FFFF00>先制攻擊</color>，進入戰鬥即可使用。對範圍內的敵人額外造成1處破綻。",
  str_skill_upgrade_desc_16022516 = "裝備技能強化：經過<link=\"30093\"><#FFAE07><u>深色格子</u></color></link>時，有50%機率額外生成1個破綻。",
