  str_skill_desc_340225 = "任選1格，對該方向的錐形範圍造成<color=#00F6FF>250%</color>的傷害，並以該方向對範圍內的敵人造成1個破綻。",
  str_skill_desc_343225 = "任選1格，對該方向的錐形範圍造成<color=#00F6FF>250%</color>的傷害，並以該方向對範圍內的敵人造成2個破綻。",
  str_skill_passive_desc_410225 = "經過<link=\"30093\"><#FFAE07><u>深色格子</u></color></link>時，提亞拉對場上生命值最高的敵人離自己最近的方向造成1個破綻。普通攻擊和連鎖技能每次往該方向造成傷害時，擊破破綻並造成<color=#00F6FF>{1}</color>的傷害。敵人死亡時，破綻會轉移到最近的其他敵人身上；當敵人每個方向都是破綻時，再次造成破綻會觸發一半的擊破傷害。",
  str_skill_passive_desc_416225 = "經過<link=\"30093\"><#FFAE07><u>深色格子</u></color></link>時，提亞拉對場上生命值最高的敵人離自己最近的方向造成1個破綻（有50%機率額外造成1個）。普通攻擊和連鎖技能每次往該方向造成傷害時，擊破破綻並造成<color=#00F6FF>{1}</color>的傷害。敵人死亡時，破綻會轉移到最近的其他敵人身上；當敵人每個方向都是破綻時，再次造成破綻會觸發一半的擊破傷害。",
  str_skill_passive_desc_430225 = "經過<link=\"30093\"><#FFAE07><u>深色格子</u></color></link>時，提亞拉對場上生命值最高的敵人離自己最近的方向造成1個破綻。普通攻擊和連鎖技能每次往該方向造成傷害時，擊破破綻並造成<color=#00F6FF>{1}</color>的<link=\"30015\"><#FFAE07><u>濺射</u></color></link>傷害，並對濺射範圍造成<color=#00F6FF>{2}</color>的傷害。敵人死亡時，破綻會轉移到最近的其他敵人身上；當敵人每個方向都是破綻時，再次造成破綻會觸發一半的擊破傷害。",
  str_skill_passive_desc_436225 = "經過<link=\"30093\"><#FFAE07><u>深色格子</u></color></link>時，提亞拉對場上生命值最高的敵人離自己最近的方向造成1個破綻（有50%的機率額外造成1處）。普通攻擊和連鎖技能每次往該方向造成傷害時，擊破破綻並造成<color=#00F6FF>{1}</color>的<link=\"30015\"><#FFAE07><u>濺射</u></color></link>傷害，並對濺射範圍造成<color=#00F6FF>{2}</color>的傷害。敵人死亡時，破綻會轉移到最近的其他敵人身上；當敵人每個方向都是破綻時，再次造成破綻會觸發一半的擊破傷害。",
  str_skill_passive_desc_440225 = "經過<link=\"30093\"><#FFAE07><u>深色格子</u></color></link>時，提亞拉對場上生命值最高的敵人離自己最近的方向造成1個破綻。普通攻擊和連鎖技能每次往該方向造成傷害時，擊破破綻並造成<color=#00F6FF>230%</color>的<link=\"30015\"><#FFAE07><u>濺射</u></color></link>傷害，並對濺射範圍造成<color=#00F6FF>100%</color>的傷害。敵人死亡時，破綻會轉移到最近的其他敵人身上；當敵人每個方向都是破綻時，再次造成破綻會觸發一半的擊破傷害。",
  str_skill_passive_desc_446225 = "經過<link=\"30093\"><#FFAE07><u>深色格子</u></color></link>時，提亞拉對場上生命值最高的敵人離自己最近的方向造成1個破綻（有50%的機率額外造成1處）。普通攻擊和連鎖技能每次往該方向造成傷害時，擊破破綻並造成<color=#00F6FF>230%</color>的<link=\"30015\"><#FFAE07><u>濺射</u></color></link>傷害，並對濺射範圍造成<color=#00F6FF>100%</color>的傷害。敵人死亡時，破綻會轉移到最近的其他敵人身上；當敵人每個方向都是破綻時，再次造成破綻會觸發一半的擊破傷害。",
  str_skill_passive_desc_4402253 = "經過<link=\"30093\"><#FFAE07><u>深色格子</u></color></link>和進入極光時刻時，提亞拉對場上生命值最高的敵人離自己最近的方向造成1個破綻。普通攻擊和連鎖技能每次往該方向造成傷害時，擊破破綻並造成<color=#00F6FF>230%</color>的<link=\"30015\"><#FFAE07><u>濺射</u></color></link>傷害，並對濺射範圍造成<color=#00F6FF>100%</color>的傷害。敵人死亡時，破綻會轉移到最近的其他敵人身上；當敵人每個方向都是破綻時，再次造成破綻會觸發一半的擊破傷害。",
  str_skill_passive_desc_4462253 = "經過<link=\"30093\"><#FFAE07><u>深色格子</u></color></link>和進入極光時刻時，提亞拉對場上生命值最高的敵人離自己最近的方向造成1個破綻（有50%的機率額外造成1處）。普通攻擊和連鎖技能每次往該方向造成傷害時，擊破破綻並造成<color=#00F6FF>230%</color>的<link=\"30015\"><#FFAE07><u>濺射</u></color></link>傷害，並對濺射範圍造成<color=#00F6FF>100%</color>的傷害。敵人死亡時，破綻會轉移到最近的其他敵人身上；當敵人每個方向都是破綻時，再次造成破綻會觸發一半的擊破傷害。",
  str_skill_upgrade_refine_desc_16022511 = "裝備技能強化：擊破破綻造成的傷害提升為<color=#00F6FF>230%</color>。",
  str_skill_upgrade_refine_desc_16022512 = "主動技能強化：技能傷害係數提高<color=#00F6FF>50%</color>。",
  str_skill_upgrade_refine_desc_16022513 = "裝備技能強化：進入極光時刻時，對場上生命值最高的敵人離自己最近的方向造成1個破綻。",
  str_skill_desc_70011272 = "月瀆能量外洩，對橫縱4列範圍造成傷害。",
  str_skill_desc_70011273 = "月瀆化為月輪，對範圍內的目標造成傷害，同時位移至場地另一側。位移後，鎖定自身周圍1圈的格子，鎖定的格子無法轉色。",
