  str_skill_name_290501144 = "末逐·群集徵召",
  str_skill_desc_290501142 = "盤絲蛛后飛撲向牠的食物，佈下蛛網鎖定格子，並對光靈造成傷害。鎖定的格子1回合後會恢復原狀。",
  str_skill_desc_290501143 = "盤絲蛛后用蛛網鎖定光靈周圍的格子，並召集子嗣撲向光靈造成傷害。鎖定的格子1回合後會恢復原狀。",
  str_skill_desc_290501144 = "盤絲蛛后召集子嗣發動攻擊，子嗣會佈下蛛網鎖定大量格子。鎖定的格子1回合後會恢復原狀。",
