  str_skill_name_290950109 = "茛撲",
  str_skill_desc_290950105 = "胡蘿蔔·刺茛對光靈造成多次傷害；光靈生命值越低，造成的傷害越高。",
  str_skill_desc_290950106 = "胡蘿蔔·刺茛高速旋轉，對自身周圍造成多次傷害。每次傷害有機率使光靈向逆時針或向外擊退1格。命中光靈後，後續傷害降低。",
  str_skill_desc_290950107 = "胡蘿蔔·刺茛對光靈造成多次傷害；光靈生命值越低，造成的傷害越高。",
  str_skill_desc_290950108 = "若光靈不位於茛撲技能範圍內，胡蘿蔔·刺茛高速旋轉，對自身周圍造成多次傷害。每次傷害有機率使光靈向逆時針或向外擊退1格。命中光靈後，後續傷害降低。",
  str_skill_desc_290950109 = "若光靈位於茛撲技能範圍內，胡蘿蔔·刺茛會召喚巨大胡蘿蔔下砸，對光靈造成傷害並附帶2格擊退。",
  str_skill_name_80060401 = "矛盾尖刺",
  str_skill_desc_80060401 = "回合結束時對上面停留的怪物造成大量傷害，且額外造成1層流血效果。似曾相識的尖刺，但這次經過可不會受到傷害。",
