  str_skill_desc_2002271 = "對最靠近的2個敵人造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2002272 = "對最靠近的2個敵人造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2002273 = "對最靠近的2個敵人造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_20022712 = "對最靠近的2名敵人造成<color=#00F6FF>{1}%</color>傷害。透支狀態下可以施放，不造成傷害，但會對目標施加1層鷹爪印記。",
  str_skill_desc_20022722 = "對最靠近的2名敵人造成<color=#00F6FF>{1}%</color>傷害。透支狀態下可以施放，不造成傷害，但會對目標施加2層鷹爪印記。",
  str_skill_desc_20022732 = "對最靠近的2名敵人造成<color=#00F6FF>{1}%</color>傷害。透支狀態下可以施放，不造成傷害，但會對目標施加3層鷹爪印記。",
  str_skill_desc_2202271 = "對最靠近的2名敵人造成<color=#00F6FF>{1}%</color>傷害。透支狀態下可以施放，不造成傷害，但會對目標施加1層鷹爪印記。",
  str_skill_desc_2202272 = "對最靠近的2名敵人造成<color=#00F6FF>{1}%</color>傷害。透支狀態下可以施放，不造成傷害，但會對目標施加2層鷹爪印記。",
  str_skill_desc_2202273 = "對最靠近的2名敵人造成<color=#00F6FF>{1}%</color>傷害。透支狀態下可以施放，不造成傷害，但會對目標施加3層鷹爪印記。",
  str_skill_desc_3002271 = "將最靠近的<color=#00F6FF>3</color>個非雷屬性格子轉為雷屬性，並在其中<color=#00F6FF>1</color>個隨機位置生成深色格子。\n主動技能下次就緒前可再次施放，施放後主動技能冷卻回合+1，蕾切爾進入<color=#00F6FF>透支狀態</color>，該狀態下無法施放普通攻擊和連鎖技能，主動技能就緒後解除透支狀態。",
  str_skill_desc_3032271 = "將最靠近的<color=#00F6FF>3</color>個非雷屬性格子轉為雷屬性，並在其中<color=#00F6FF>1</color>個隨機位置生成深色格子。\n主動技能下次就緒前可再次施放，轉色格子數<color=#00F6FF>+2</color>並額外生成<color=#00F6FF>1</color>個深色格子，施放後主動技能冷卻回合+1，蕾切爾進入<color=#00F6FF>透支狀態</color>，該狀態下無法施放普通攻擊和連鎖技能，主動技能就緒後解除透支狀態。",
  str_skill_desc_3062271 = "將最靠近的<color=#00F6FF>3</color>個非雷屬性格子轉為雷屬性，並在其中<color=#00F6FF>2</color>個隨機位置生成深色格子。\n主動技能下次就緒前可再次施放，轉色格子數<color=#00F6FF>+2</color>並額外生成<color=#00F6FF>1</color>個深色格子，施放後主動技能冷卻回合+1，蕾切爾進入<color=#00F6FF>透支狀態</color>，該狀態下無法施放普通攻擊和連鎖技能，主動技能就緒後解除透支狀態。",
  str_skill_desc_3002272 = "將最靠近的<color=#00F6FF>3</color>個非雷屬性格子轉為雷屬性，並在其中<color=#00F6FF>1</color>個隨機位置生成深色格子。\n施放後主動技能冷卻回合+1，蕾切爾進入<color=#00F6FF>透支狀態</color>，該狀態下無法施放普通攻擊和連鎖技能，主動技能就緒後解除透支狀態。",
  str_skill_desc_3032272 = "將最靠近的<color=#00F6FF>5</color>個非雷屬性格子轉為雷屬性，並在其中<color=#00F6FF>2</color>個隨機位置生成深色格子。\n施放後主動技能冷卻回合+1，蕾切爾進入<color=#00F6FF>透支狀態</color>，該狀態下無法施放普通攻擊和連鎖技能，主動技能就緒後解除透支狀態。",
  str_skill_desc_3062272 = "將最靠近的<color=#00F6FF>5</color>個非雷屬性格子轉為雷屬性，並在其中<color=#00F6FF>3</color>個隨機位置生成深色格子。\n施放後主動技能冷卻回合+1，蕾切爾進入<color=#00F6FF>透支狀態</color>，該狀態下無法施放普通攻擊和連鎖技能，主動技能就緒後解除透支狀態。",
  str_skill_passive_name_410227 = "全息三角殺陣",
  str_skill_passive_name_420227 = "全息三角殺陣",
  str_skill_passive_name_430227 = "全息三角殺陣",
  str_skill_passive_desc_410227 = "經過<link=\"30093\"><#FFAE07><u>深色格子</u></color></link>時，對最靠近的目標施加<color=#00F6FF>3</color>層鷹爪印記。敵人回合開始時，每有1層印記，便對目標造成蕾切爾目前攻擊力<color=#00F6FF>{1}</color>的傷害，回合結束時層數減半。若目標被擊殺，則將一半的鷹爪印記轉移到最靠近的其他敵人身上。",
  str_skill_passive_desc_420227 = "經過<link=\"30093\"><#FFAE07><u>深色格子</u></color></link>時，對最靠近的目標施加<color=#00F6FF>3</color>層鷹爪印記。敵人回合開始時，每有1層印記，便對目標造成蕾切爾目前攻擊力<color=#00F6FF>{1}</color>的傷害，回合結束時層數減半。若目標被擊殺，則將一半的鷹爪印記轉移到最靠近的其他敵人身上。",
  str_skill_passive_desc_430227 = "經過<link=\"30093\"><#FFAE07><u>深色格子</u></color></link>時，對最靠近的目標施加<color=#00F6FF>3</color>層鷹爪印記。敵人回合開始時，每有1層印記，便對目標造成蕾切爾目前攻擊力<color=#00F6FF>{1}</color>的傷害，回合結束時層數減半。若目標被擊殺，則將一半的鷹爪印記轉移到最靠近的其他敵人身上。若蕾切爾處於<color=#00F6FF>透支狀態</color>，每連線移動1格，自身攻擊力提高<color=#00F6FF>3%</color>。",
  str_skill_passive_desc_440227 = "經過<link=\"30093\"><#FFAE07><u>深色格子</u></color></link>時，對最靠近的目標施加<color=#00F6FF>3</color>層鷹爪印記。敵人回合開始時，每有1層印記，便對目標造成蕾切爾目前攻擊力<color=#00F6FF>80%</color>的傷害，回合結束時層數減半。若目標被擊殺，則將一半的鷹爪印記轉移到最靠近的其他敵人身上。若蕾切爾處於<color=#00F6FF>透支狀態</color>，每連線移動1格，自身攻擊力提高<color=#00F6FF>3%</color>。",
  str_skill_passive_desc_460227 = "經過<link=\"30093\"><#FFAE07><u>深色格子</u></color></link>時，對最靠近的目標施加<color=#00F6FF>3</color>層鷹爪印記。敵人回合開始時，每有1層印記，便對目標造成蕾切爾目前攻擊力<color=#00F6FF>80%</color>的傷害，回合結束時層數減半。若目標被擊殺，則將一半的鷹爪印記轉移到最靠近的其他敵人身上。若蕾切爾處於<color=#00F6FF>透支狀態</color>，每連線移動1格，自身攻擊力提高<color=#00F6FF>4%</color>。",
  str_skill_desc_3502271 = "將最靠近的<color=#00F6FF>3</color>個非雷屬性格子轉為雷屬性，並在其中<color=#00F6FF>1</color>個隨機位置生成深色格子，對最靠近的目標施加<color=#00F6FF>2</color>層鷹爪印記。\n主動技能下次就緒前可再次施放，施放後主動技能冷卻回合+1，蕾切爾進入<color=#00F6FF>透支狀態</color>，該狀態下無法施放普通攻擊和連鎖技能，主動技能就緒後解除透支狀態。",
  str_skill_desc_3532271 = "將最靠近的<color=#00F6FF>3</color>個非雷屬性格子轉為雷屬性，並在其中<color=#00F6FF>1</color>個隨機位置生成深色格子，對最靠近的目標施加<color=#00F6FF>2</color>層鷹爪印記。\n主動技能下次就緒前可再次施放，轉色格子數<color=#00F6FF>+2</color>並額外生成<color=#00F6FF>1</color>個深色格子，施放後主動技能冷卻回合+1，蕾切爾進入<color=#00F6FF>透支狀態</color>，該狀態下無法施放普通攻擊和連鎖技能，主動技能就緒後解除透支狀態。",
  str_skill_desc_3562271 = "將最靠近的<color=#00F6FF>3</color>個非雷屬性格子轉為雷屬性，並在其中<color=#00F6FF>2</color>個隨機位置生成深色格子，對最靠近的目標施加<color=#00F6FF>2</color>層鷹爪印記。\n主動技能下次就緒前可再次施放，轉色格子數<color=#00F6FF>+2</color>並額外生成<color=#00F6FF>1</color>個深色格子，施放後主動技能冷卻回合+1，蕾切爾進入<color=#00F6FF>透支狀態</color>，該狀態下無法施放普通攻擊和連鎖技能，主動技能就緒後解除透支狀態。",
  str_skill_desc_3502272 = "將最靠近的<color=#00F6FF>3</color>個非雷屬性格子轉為雷屬性，並在其中<color=#00F6FF>1</color>個隨機位置生成深色格子，對最靠近的目標施加<color=#00F6FF>2</color>層鷹爪印記。\n施放後主動技能冷卻回合+1，蕾切爾進入<color=#00F6FF>透支狀態</color>，該狀態下無法施放普通攻擊和連鎖技能，主動技能就緒後解除透支狀態。",
  str_skill_desc_3532272 = "將最靠近的<color=#00F6FF>5</color>個非雷屬性格子轉為雷屬性，並在其中<color=#00F6FF>2</color>個隨機位置生成深色格子，對最靠近的目標施加<color=#00F6FF>2</color>層鷹爪印記。\n施放後主動技能冷卻回合+1，蕾切爾進入<color=#00F6FF>透支狀態</color>，該狀態下無法施放普通攻擊和連鎖技能，主動技能就緒後解除透支狀態。",
  str_skill_desc_3562272 = "將最靠近的<color=#00F6FF>5</color>個非雷屬性格子轉為雷屬性，並在其中<color=#00F6FF>3</color>個隨機位置生成深色格子，對最靠近的目標施加<color=#00F6FF>2</color>層鷹爪印記。\n施放後主動技能冷卻回合+1，蕾切爾進入<color=#00F6FF>透支狀態</color>，該狀態下無法施放普通攻擊和連鎖技能，主動技能就緒後解除透支狀態。",
  str_skill_upgrade_desc_16022713 = "主動技能強化：主動技能下次就緒前再次施放，轉色格子數<color=#FFFF00>+2</color>並額外生成<color=#FFFF00>1</color>個深色格子。",
  str_skill_upgrade_desc_16022716 = "主動技能強化：生成深色格子數量<color=#FFFF00>+1</color>。",
  str_skill_upgrade_refine_desc_16022711 = "裝備技能強化：敵人回合開始時，每有1層印記對目標造成蕾切爾目前攻擊力<color=#00F6FF>80%</color>的傷害。",
  str_skill_upgrade_refine_desc_16022712 = "主動技能強化：施放後對最靠近的目標施加<color=#00F6FF>2</color>層鷹爪印記。",
  str_skill_upgrade_refine_desc_16022713 = "裝備技能強化：若蕾切爾處於透支狀態，每連線移動1格，自身攻擊力提高<color=#00F6FF>4%</color>。",
  str_skill_upgrade_desc_15022812 = "主動技能強化：主動技能變為<color=#FFFF00>先制攻擊</color>，進入戰鬥即可使用。\n【斑斕祕技】<color=#FFFF00>先制攻擊</color>覺醒1階段生效。",
  str_skill_upgrade_desc_15022815 = "主動技能【什錦轟炸】強化：可點選格子數<color=#FFFF00>+1</color>。",
  str_skill_desc_10071120 = "朝目標上回合所在位置施放光束衝擊，對路徑上及目標位置的目標造成傷害。",
  str_skill_desc_10071130 = "將範圍內的目標擊退至場地中間位置。",
  str_skill_name_54550920 = "碩腕·避害",
  str_skill_desc_54550920 = "在光靈施放連鎖技能前，碩腕會蜷縮起來躲避攻擊，同時吞噬所在位置的強化格子。",
  str_skill_name_29097013 = "普通攻擊",
  str_skill_desc_29097013 = "移動後對前方光靈造成傷害。",
  str_skill_name_29097014 = "熔岩衝擊",
  str_skill_desc_29097014 = "朝光靈所在方向造成扇形大範圍傷害並生成碎石。",
  str_skill_name_29097015 = "熾熱咆哮",
  str_skill_desc_29097015 = "對全畫面造成3次傷害，每次擊退1格；若無法被擊退則受到更高傷害。",
  str_skill_name_2002281 = "甘美奇袭",
  str_skill_name_2002282 = "甘美奇袭",
  str_skill_name_2002283 = "甘美奇袭",
  str_skill_desc_2002281 = "澤塔放出「科南」，「科南」在周圍菱形12格內尋找最靠近的敵人，規劃路徑前往並自爆，對十字5格造成<color=#00F6FF>150%</color>的傷害。",
  str_skill_desc_2002282 = "澤塔放出「科南」，「科南」在周圍菱形24格內尋找最靠近的敵人，規劃路徑前往並自爆，對十字5格造成<color=#00F6FF>160%</color>的傷害。",
  str_skill_desc_2002283 = "澤塔放出「科南」，「科南」在周圍菱形24格內尋找最靠近的敵人，規劃路徑前往並自爆，對十字5格造成<color=#00F6FF>160%</color>的傷害。\n澤塔施放3階連鎖技能時，主動技能【斑斕祕技】所召喚的「科南」傷害範圍擴大到周圍1圈。",
  str_skill_name_3002281 = "什錦轟炸",
  str_skill_name_3052281 = "什錦轟炸",
  str_skill_name_3102281 = "什錦轟炸",
  str_skill_name_3152281 = "什錦轟炸",
  str_skill_desc_3002281 = "任選3個格子，重設其顏色並淨化。重設時會保留水屬性格子。",
  str_skill_desc_3052281 = "任選4個格子，重設其顏色並淨化。重設時會保留水屬性格子。",
  str_skill_desc_3102281 = "任選3個格子，將顏色填入<link=\"30100\"><#FFAE07><u>集彩板</u></color></link>後重設其顏色並淨化。重設時會保留水屬性格子。",
  str_skill_desc_3152281 = "任選4個格子，將顏色填入<link=\"30100\"><#FFAE07><u>集彩板</u></color></link>後重設其顏色並淨化。重設時會保留水屬性格子。",
  str_skill_name_3002282 = "斑斕祕技",
  str_skill_desc_3002282 = "消耗填滿顏色的<link=\"30100\"><#FFAE07><u>集彩板</u></color></link>，選擇1個可行走格子放置「科南」。本回合澤塔首次施放連鎖技能時，「科南」會同步索敵並攻擊敵人。",
  str_skill_passive_name_410228 = "炫彩爆破",
  str_skill_passive_name_420228 = "炫彩爆破",
  str_skill_passive_name_430228 = "炫彩爆破",
  str_skill_passive_desc_410228 = "澤塔獲得主動技能【斑斕祕技】與<link=\"30100\"><#FFAE07><u>集彩板</u></color></link>。透過斑斕祕技召喚的「科南」在澤塔施放連鎖技能時<color=#00F6FF>以自身為中心索敵攻擊</color>，索敵範圍與澤塔施放的連鎖技能<color=#00F6FF>相同</color>，造成傷害為澤塔施放連鎖技能傷害的<color=#00F6FF>{1}</color>。",
  str_skill_passive_desc_420228 = "澤塔獲得主動技能【斑斕祕技】與<link=\"30100\"><#FFAE07><u>集彩板</u></color></link>。透過斑斕祕技召喚的「科南」在澤塔施放連鎖技能時<color=#00F6FF>以自身為中心索敵攻擊</color>，索敵範圍與澤塔施放的連鎖技能<color=#00F6FF>相同</color>，造成傷害為澤塔施放連鎖技能傷害的<color=#00F6FF>{1}</color>。在澤塔施放第3階段連鎖技能時，透過斑斕祕技召喚的「科南」造成傷害範圍擴大到<color=#00F6FF>周圍1圈</color>。",
  str_skill_passive_desc_430228 = "澤塔獲得主動技能【斑斕祕技】與<link=\"30100\"><#FFAE07><u>集彩板</u></color></link>。透過斑斕祕技召喚的「科南」在澤塔施放連鎖技能時<color=#00F6FF>以自身為中心索敵攻擊</color>，索敵範圍與澤塔施放的連鎖技能<color=#00F6FF>相同</color>，造成傷害為澤塔施放連鎖技能傷害的<color=#00F6FF>{1}</color>。在澤塔施放第3階段連鎖技能時，透過斑斕祕技召喚的「科南」造成傷害範圍擴大到<color=#00F6FF>周圍1圈</color>。每當集彩板被填滿時治療隊伍，回復量為澤塔<color=#00F6FF>12%</color>的最大生命值。",
  str_skill_name_2002291 = "「紅門出現！」",
  str_skill_name_2002292 = "「紅門出現！」",
  str_skill_name_2002293 = "「紅門出現！」",
  str_skill_name_3002291 = "「全部消除！」",
  str_skill_name_3202291 = "「全部消除！」",
  str_skill_name_3302291 = "「全部消除！」",
  str_skill_name_3232291 = "「全部消除！」",
  str_skill_name_3262291 = "「全部消除！」",
  str_skill_name_3332291 = "「全部消除！」",
  str_skill_name_3362291 = "「全部消除！」",
  str_skill_passive_name_4002291 = "「續航撐住啊！」",
  str_skill_desc_2002291 = "對最靠近的2個敵人造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2002292 = "對最靠近的3個敵人造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2002293 = "對最靠近的4個敵人造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2202291 = "對最接近的2名敵人造成<color=#00F6FF>{1}%</color>的傷害，並附加1層灼燒狀態。",
  str_skill_desc_2202292 = "對最接近的3名敵人造成<color=#00F6FF>{1}%</color>的傷害，並附加1層灼燒狀態。",
  str_skill_desc_2202293 = "對最接近的4名敵人造成<color=#00F6FF>{1}%</color>的傷害，並附加1層灼燒狀態。",
  str_skill_desc_3002291 = "巴緹牙在戰鬥開始時便擁有<link=\"30110\"><#FFAE07><u>【待降方塊】</u></color></link>。任選1格，將與【待降方塊】形狀相同的格子轉為火屬性。",
  str_skill_desc_3202291 = "巴緹牙在戰鬥開始時便擁有<link=\"30111\"><#FFAE07><u>【待降方塊】</u></color></link>。任選1格，將與【待降方塊】形狀相同的格子轉為火屬性。可在【待降方塊】中消耗<color=#00F6FF>5</color>點能量重骰方塊形狀。經過火屬性格子可獲得<color=#00F6FF>1</color>點能量。下次主動技能施放前，每次重骰消耗的能量遞增<color=#00F6FF>5</color>點。",
  str_skill_desc_3232291 = "巴緹牙在戰鬥開始時便擁有<link=\"30112\"><#FFAE07><u>【待降方塊】</u></color></link>。任選1格，將與【待降方塊】形狀相同的格子轉為火屬性。可在【待降方塊】中消耗<color=#00F6FF>5</color>點能量重骰方塊形狀，初始能量<color=#00F6FF>10</color>點。經過火屬性格子可獲得<color=#00F6FF>1</color>點能量。下次主動技能施放前，每次重骰消耗的能量遞增<color=#00F6FF>5</color>點。",
  str_skill_desc_3262291 = "巴緹牙在戰鬥開始時便擁有<link=\"30113\"><#FFAE07><u>【待降方塊】</u></color></link>。任選1格，將與【待降方塊】形狀相同的格子轉為火屬性。可在【待降方塊】中消耗<color=#00F6FF>5</color>點能量重骰方塊形狀，初始能量<color=#00F6FF>10</color>點。經過火屬性格子可獲得<color=#00F6FF>1</color>點能量。",
  str_skill_desc_3302291 = "巴緹牙在戰鬥開始時便擁有<link=\"30114\"><#FFAE07><u>【待降方塊】</u></color></link>。任選1格，將與【待降方塊】形狀相同的格子轉為火屬性。可在【待降方塊】中消耗<color=#00F6FF>5</color>點能量重骰方塊形狀。經過火屬性格子可獲得<color=#00F6FF>1</color>點能量。下次主動技能施放前，每次重骰消耗的能量遞增<color=#00F6FF>5</color>點。鎖定【待降方塊】可以使形狀不會隨機改變。鎖定狀態下，使用重骰功能會強化該方塊。每強化1次，施放主動技能時額外在其中隨機1處生成深色格子。",
  str_skill_desc_3332291 = "巴緹牙在戰鬥開始時便擁有<link=\"30115\"><#FFAE07><u>【待降方塊】</u></color></link>。任選1格，將與【待降方塊】形狀相同的格子轉為火屬性。可在【待降方塊】中消耗<color=#00F6FF>5</color>點能量重骰方塊形狀，初始能量<color=#00F6FF>10</color>點。經過火屬性格子可獲得<color=#00F6FF>1</color>點能量。下次主動技能施放前，每次重骰消耗的能量遞增<color=#00F6FF>5</color>點。鎖定【待降方塊】可以使形狀不會隨機改變。鎖定狀態下，使用重骰功能會強化該方塊。每強化1次，施放主動技能時額外在其中隨機1處生成深色格子。",
  str_skill_desc_3362291 = "巴緹牙在戰鬥開始時便擁有<link=\"30116\"><#FFAE07><u>【待降方塊】</u></color></link>。任選1格，將與【待降方塊】形狀相同的格子轉為火屬性。可在【待降方塊】中消耗<color=#00F6FF>5</color>點能量重骰方塊形狀，初始能量<color=#00F6FF>10</color>點。經過火屬性格子可獲得<color=#00F6FF>1</color>點能量。鎖定【待降方塊】可以使形狀不會隨機改變。鎖定狀態下，使用重骰功能會強化該方塊。每強化1次，施放主動技能時額外在其中隨機1處生成深色格子。",
  str_skill_passive_desc_4002291 = "將隊伍中光靈對目標附加的灼燒狀態替換為<color=#00F6FF>蓄熱狀態</color>，每層對目標造成隊伍平均攻擊力<color=#00F6FF>{1}</color>的傷害，目標生命值越多傷害越高，最大翻倍，最高可疊加5層，持續2回合。每次經過<link=\"30093\"><#FFAE07><u>深色格子</u></color></link>時，對最接近的目標附加<color=#00F6FF>1</color>層蓄熱狀態。",
  str_skill_upgrade_desc_16022913 = "主動技能強化：主動技能變為<color=#FFFF00>先制攻擊</color>，進入戰鬥即可使用。【待降方塊】擁有10點初始能量（覺醒2階段生效）。",
  str_skill_upgrade_desc_16022916 = "主動技能強化：【待降方塊】重骰形狀需要消耗的能量不會遞增（覺醒2階段生效）。",
  str_skill_name_28002414 = "威壓",
  str_skill_desc_28002414 = "吞羅將施放強大法術，將光靈擊退。",
  str_skill_name_28002415 = "召喚",
  str_skill_desc_28002415 = "吞羅將於場內隨機位置召喚暗鬼。",
  str_skill_name_1003003 = "鎖定",
  str_skill_desc_1003003 = "影鬼每回合將最接近的1個隨機格子轉為鎖定格子。",
  str_skill_name_29102421 = "燃燒",
  str_skill_desc_29102421 = "對自身前4列範圍內的光靈造成傷害，並在隨機位置召喚火焰。",
  str_skill_name_29102422 = "烈焰大地",
  str_skill_desc_29102422 = "施放烈焰對全場造成傷害，並額外對場邊3行範圍內的目標造成1次高額傷害。",
  str_skill_name_15017611 = "南極光絨針旋",
  str_skill_desc_15017611 = "根據自身「南極光絨針」的印記層數，對周圍3圈內的光靈造成多次傷害，每次傷害對目標附加1根「南極光絨針」。如果無法攻擊到目標，則自身獲得3層「南極光絨針」印記。",
  str_skill_name_15017612 = "北銀河閃耀",
  str_skill_desc_15017612 = "將周圍2圈內目標身上的「南極光絨針」拔出，每根絨針對目標造成20%傷害。如果無法攻擊到目標，則自身獲得3層「南極光絨針」印記。",
  str_skill_name_15020011 = "掩護射擊",
  str_skill_desc_15020011 = "對周圍3圈內的敵方單位造成傷害。",
  str_skill_name_15020012 = "投影擾敵法",
  str_skill_desc_15020012 = "將光靈與啟光戰兵向兩者中心位置靠攏。",
  str_skill_name_547100101 = "萊因哈特普通攻擊",
  str_skill_desc_547100101 = "萊因哈特靠近敵人進行攻擊。",
  str_skill_name_547100102 = "啟明之轟擊",
  str_skill_desc_547100102 = "萊因哈特對敵人造成大量傷害。",
  str_skill_name_290980101 = "惡念穿威",
  str_skill_name_290980102 = "魂落審判",
  str_skill_name_290980103 = "潮鳴電摯",
  str_skill_name_290980104 = "聚能龍息",
  str_skill_desc_290980101 = "若X型範圍內有敵人，對其造成傷害並召喚末梢單位。否則在自身周圍召喚末梢單位。",
  str_skill_desc_290980102 = "若十字範圍內有敵人，對其造成傷害並召喚末梢單位。否則在自身周圍召喚末梢單位。",
  str_skill_desc_290980103 = "在自身周圍召喚末梢單位。",
  str_skill_desc_290980104 = "對全畫面範圍造成傷害，擊退敵人並在其周圍召喚末梢單位。",
  str_skill_name_200510101 = "尋釁矆睒",
  str_skill_desc_200510101 = "肇釁末梢靠近敵人進行攻擊",
  str_skill_name_290520111 = "末逐·梟桀之襲",
  str_skill_desc_290520111 = "斐桀洛向光靈移動，並造成大量傷害，隨後移動至遠離目標的位置。",
  str_skill_name_290520112 = "末逐·梟桀之擊",
  str_skill_desc_290520112 = "斐桀洛移動後，對範圍內的光靈造成傷害。",
  str_skill_name_290940113 = "末逐·幽火長矛",
  str_skill_desc_290940113 = "阿伊讓造成光靈當下生命值40%的傷害，根據該傷害值提高隊伍最大生命值，並在光靈十字最大範圍上的棋盤最外圈位置生成幽火。",
  str_skill_name_290940114 = "末逐·灼熱爆破",
  str_skill_desc_290940114 = "阿伊讓對自身周圍2圈內的光靈造成傷害。",
  str_skill_name_290940115 = "末逐·憤怒隕石",
  str_skill_desc_290940115 = "阿伊讓向光靈上回合所在位置召喚隕石攻擊，造成秒殺傷害。摧毀範圍中心格子，同時在十字4格生成損壞格子。",
  str_skill_upgrade_refine_desc_17010711 = "主動技能強化：增幅狀態下，連鎖技能傷害提高<color=#00F6FF>25%</color>。",
  str_skill_upgrade_refine_desc_17010712 = "裝備技能強化：每回合開始時，<color=#00F6FF>周圍1圈</color>每有1名敵人則獲得1點威能。",
  str_skill_upgrade_refine_desc_17010713 = "裝備技能強化：<color=#00F6FF>回合結束時</color>可獲得5點威能（此時每損失<color=#00F6FF>15%</color>生命值額外獲得1點）。",
  str_skill_desc_346107 = "消耗<color=#00F6FF>10</color>點威能，本回合進入增幅狀態：普通攻擊可攻擊斜方向，且普攻傷害增加<color=#00F6FF>20%</color>，連鎖傷害增加<color=#00F6FF>25%</color>（重複施放可疊加）。增幅狀態下，每擊殺1名敵人獲得2點威能。",
  str_skill_passive_desc_456107 = "戰鬥開始時獲得10點威能；每回合開始時，<color=#00F6FF>周圍1圈</color>每有1名敵人則獲得<color=#00F6FF>1</color>點威能；回合結束時若處於非增幅狀態，可獲得<color=#00F6FF>5</color>點威能（此時每損失20%生命值，額外獲得1點）。",
  str_skill_passive_desc_466107 = "戰鬥開始時獲得10點威能；每回合開始時，<color=#00F6FF>周圍1圈</color>每有1名敵人則獲得<color=#00F6FF>1</color>點威能；回合結束時可獲得<color=#00F6FF>5</color>點威能（此時每損失15%生命值，額外獲得1點）。",
  str_skill_upgrade_refine_desc_17010811 = "<color=#00F6FF>新增主動技能變體I</color>：消耗<color=#00F6FF>15</color>點威能，任選1格，對所選位置造成<color=#00F6FF>480%</color>的傷害。每施放1次，基礎攻擊力增加<color=#00F6FF>3%</color>，可多次施放。",
  str_skill_upgrade_refine_desc_17010812 = "主動技能強化：每施放1次，主動技能的最終傷害提高<color=#00F6FF>3%</color>。",
  str_skill_upgrade_refine_desc_17010813 = "主動技能強化：對生命值低於<color=#00F6FF>10%</color>的目標造成<color=#00F6FF>3倍</color>傷害。",
  str_skill_name_366108 = "熔岩墜落",
  str_skill_name_33610801 = "熔岩墜落·變體I",
  str_skill_name_36610801 = "熔岩墜落·變體I",
  str_skill_desc_33610801 = "消耗<color=#00F6FF>15</color>點威能，任選1格，對所選位置造成<color=#00F6FF>480%</color>的傷害。每施放1次，基礎攻擊力增加<color=#00F6FF>3%</color>，可多次施放。",
  str_skill_desc_356108 = "消耗<color=#00F6FF>10</color>點威能，任選1格，對所選位置造成<color=#00F6FF>240%</color>傷害，並對所選位置周圍<color=#00F6FF>十字4格</color>造成一半的<link=\"30015\"><#FFAE07><u>濺射</u></color></link>傷害。每施放1次基礎攻擊力增加<color=#00F6FF>3%</color>，主動技能最終傷害提高<color=#00F6FF>3%</color>，可多次施放。",
  str_skill_desc_35610801 = "消耗<color=#00F6FF>15</color>點威能，任選1格，對所選位置造成<color=#00F6FF>480%</color>的傷害。每施放1次基礎攻擊力增加<color=#00F6FF>3%</color>，主動技能最終傷害提高<color=#00F6FF>3%</color>，可多次施放。",
  str_skill_desc_366108 = "消耗<color=#00F6FF>10</color>點威能，任選1格，對所選位置造成<color=#00F6FF>240%</color>傷害，並對所選位置周圍<color=#00F6FF>十字4格</color>造成一半的<link=\"30015\"><#FFAE07><u>濺射</u></color></link>傷害。每施放1次基礎攻擊力增加<color=#00F6FF>3%</color>，主動技能最終傷害提高<color=#00F6FF>3%</color>，可多次施放。對生命值低於<color=#00F6FF>10%</color>的目標造成<color=#00F6FF>3倍</color>傷害。",
  str_skill_desc_36610801 = "消耗<color=#00F6FF>15</color>點威能，任選1格，對所選位置造成<color=#00F6FF>480%</color>的傷害。每施放1次基礎攻擊力增加<color=#00F6FF>3%</color>，主動技能最終傷害提高<color=#00F6FF>3%</color>，可多次施放。對生命值低於<color=#00F6FF>10%</color>的目標造成<color=#00F6FF>3倍</color>傷害。",
  str_skill_upgrade_refine_desc_17010911 = "主動技能強化：主動技能變為<color=#00F6FF>全畫面任選1格</color>，並且能攻擊到<color=#00F6FF>身後的目標</color>。",
  str_skill_upgrade_refine_desc_17010912 = "裝備技能強化：每回合<color=#00F6FF>前2次</color>普通攻擊可獲得<color=#00F6FF>1</color>點威能，且該次普通攻擊的傷害增加<color=#00F6FF>100%</color>。",
  str_skill_upgrade_refine_desc_17010913 = "新增主動技能：消耗<color=#00F6FF>10</color>點威能，本回合內連鎖技能目標<color=#00F6FF>+1</color>（重複施放可疊加）。",
  str_skill_name_340109 = "月夜狩獵",
  str_skill_desc_340109 = "消耗<color=#00F6FF>10</color>點威能並清除剩餘威能，任選1格，對角色到所選格方向上前後所有沿途及相鄰格上的敵人造成<color=#00F6FF><color=#00F6FF>150%</color></color>的傷害。每清除1點威能，最終傷害增加<color=#00F6FF>8%</color>。",
  str_skill_passive_desc_453109 = "每回合開始時獲得<color=#00F6FF>5</color>點威能。每回合<color=#00F6FF>前2次</color>普通攻擊可獲得<color=#00F6FF>1</color>點威能且該次普通攻擊的傷害增加<color=#00F6FF>100%</color>。",
  str_skill_name_360109 = "林間捕影",
  str_skill_desc_360109 = "消耗<color=#00F6FF>10</color>點威能，本回合內連鎖技能目標<color=#00F6FF>+1</color>（重複施放可疊加）。",
  str_skill_upgrade_refine_desc_17011011 = "裝備技能強化：普通攻擊有<color=#00F6FF>35%</color>機率對距離最遠的敵人施放1次雷擊。",
  str_skill_upgrade_refine_desc_17011012 = "裝備技能強化：每次施放雷擊時，若威能少於5點，獲得1點威能。",
  str_skill_upgrade_refine_desc_17011013 = "主動技能強化：每次施放雷擊後獲得1層鎮魂印記，施放主動技能將清除所有鎮魂印記，每清除1層，主動技能的傷害係數增加10%。",
  str_skill_passive_desc_443110 = "每回合開始時獲得<color=#00F6FF>5</color>點威能，每次以主動技能擊殺1名敵人時獲得<color=#00F6FF>2</color>點威能。普通攻擊有<color=#00F6FF>35%</color>機率對距離最遠的敵人施放1次雷擊。",
  str_skill_passive_desc_453110 = "每回合開始時獲得<color=#00F6FF>5</color>點威能，主動技能每擊殺1名敵人獲得<color=#00F6FF>2</color>點威能。普通攻擊有<color=#00F6FF>35%</color>機率對距離最遠的敵人施放1次雷擊。每次施放雷擊時，若威能少於5點，獲得1點威能。",
  str_skill_desc_366110 = "消耗<color=#00F6FF>10</color>點威能並清除剩餘威能與<link=\"30117\"><#FFAE07><u>鎮魂印記</u></color></link>，對全體敵人造成<color=#00F6FF>150%</color>傷害，每清除1點威能，傷害增加<color=#00F6FF>15%</color>並無視目標<color=#00F6FF>1%</color>的防禦。每清除1層鎮魂印記，主動技能的傷害係數增加<color=#00F6FF>10%</color>。",
  str_skill_upgrade_desc_16023013 = "裝備技能強化：每當理智值從50點（含）以上掉到50點以下，或從50點以下增至50點（含）以上時，將離隊伍最近的非火屬性格子轉為<color=#00F6FF>火屬性深色格子</color>。",
  str_skill_upgrade_desc_16023014 = "主動技能、裝備技能強化：造成傷害時，額外計入<color=#00F6FF>4,000</color>點隊伍已損失生命值。",
  str_skill_upgrade_desc_16023015 = "裝備技能強化：隊伍生命值越低，維多利亞·墓歌對有真主契約的敵人造成越高傷害。隊伍生命值為50%時，傷害加成達最大值<color=#00F6FF>15%</color>。",
  str_skill_name_2002301 = "猩紅罪牢",
  str_skill_name_2002302 = "猩紅罪牢",
  str_skill_name_2002303 = "猩紅罪牢",
  str_skill_name_3002301 = "血月狂宴",
  str_skill_name_3042301 = "血月狂宴",
  str_skill_name_30023011 = "血月狂宴",
  str_skill_name_30423011 = "血月狂宴",
  str_skill_name_3002302 = "起舞漣漪",
  str_skill_passive_name_4102301 = "寬恕的全知",
  str_skill_passive_name_4302301 = "寬恕的全知",
  str_skill_passive_name_4132301 = "寬恕的全知",
  str_skill_passive_name_4332301 = "寬恕的全知",
  str_skill_passive_name_4142301 = "寬恕的全知",
  str_skill_passive_name_4342301 = "寬恕的全知",
  str_skill_passive_name_4162301 = "寬恕的全知",
  str_skill_passive_name_4362301 = "寬恕的全知",
  str_skill_desc_2002301 = "對最接近的3名敵人造成<color=#00F6FF>{1}%</color>傷害，對有真主契約的敵人造成1次<color=#00F6FF>相同倍率</color>的傷害。",
  str_skill_desc_2002302 = "對最接近的3名敵人造成<color=#00F6FF>{1}%</color>傷害，對有真主契約的敵人造成1次<color=#00F6FF>相同倍率</color>的傷害。",
  str_skill_desc_2002303 = "對最接近的3名敵人造成<color=#00F6FF>{1}%</color>傷害，對有真主契約的敵人造成1次<color=#00F6FF>相同倍率</color>的傷害。",
  str_skill_desc_3002301 = "戰鬥時，維多利亞·墓歌擁有<link=\"30039\"><#FFAE07><u>「理智系統」</u></color></link>。扣除10點理智值，選擇1名目標施加<link=\"30118\"><#FFAE07><u>真主契約</u></color></link>，並對其造成相當於<color=#00F6FF>200%</color>隊伍已損失生命值的無視防禦傷害。",
  str_skill_desc_3042301 = "戰鬥時，維多利亞·墓歌擁有<link=\"30039\"><#FFAE07><u>「理智系統」</u></color></link>。扣除10點理智值，選擇1名目標施加<link=\"30118\"><#FFAE07><u>真主契約</u></color></link>，並對其造成相當於<color=#00F6FF>200%</color>隊伍已損失生命值的無視防禦傷害。造成傷害時，額外計入4,000點隊伍已損失的生命值。",
  str_skill_desc_3002302 = "將隊伍生命值與理智值的百分比對調。理智值為0時無法施放。進入戰鬥時獲得1次施放次數。",
  str_skill_passive_desc_4102301 = "每回合開始或每次經過深色格子時，對有真主契約的敵人造成1次相當於<color=#00F6FF>{1}</color>隊伍已損失生命值的無視防禦傷害。",
  str_skill_passive_desc_4302301 = "每回合開始或每次經過深色格子時，對具有真主契約的敵人造成1次相當於<color=#00F6FF>{1}</color>隊伍已損失生命值的無視防禦傷害。每當維多利亞·墓歌對具有真主契約的敵人造成傷害時，回復<color=#00F6FF>3%</color>損失的理智值（至少回復1點）。",
  str_skill_passive_desc_4132301 = "每回合開始或每次經過深色格子時，對具有真主契約的敵人造成1次相當於<color=#00F6FF>{1}</color>隊伍已損失生命值的無視防禦傷害。每當理智值從50點（含）以上掉到50點以下，或從50點以下增至50點（含）以上時，將離隊伍最近的非火屬性格子轉為<color=#00F6FF>火屬性深色格子</color>。",
  str_skill_passive_desc_4332301 = "每回合開始或每次經過深色格子時，對具有真主契約的敵人造成1次相當於<color=#00F6FF>{1}</color>隊伍已損失生命值的無視防禦傷害。每當維多利亞·墓歌對具有真主契約的敵人造成傷害時，回復<color=#00F6FF>3%</color>損失的理智值（至少回復1點）。每當理智值從50點（含）以上掉到50點以下，或從50點以下增至50點（含）以上時，將離隊伍最近的非火屬性格子轉為<color=#00F6FF>火屬性深色格子</color>。",
  str_skill_passive_desc_4142301 = "每回合開始或每次經過深色格子時，對具有真主契約的敵人造成1次相當於<color=#00F6FF>{1}</color>隊伍已損失生命值的無視防禦傷害。造成傷害時，額外計入<color=#00F6FF>4,000</color>點損失的生命值。每當理智值從50點（含）以上掉到50點以下，或從50點以下增至50點（含）以上時，將離隊伍最近的非火屬性格子轉為<color=#00F6FF>火屬性深色格子</color>。",
  str_skill_passive_desc_4342301 = "每回合開始或每次經過深色格子時，對具有真主契約的敵人造成1次相當於<color=#00F6FF>{1}</color>隊伍已損失生命值的無視防禦傷害。每當維多利亞·墓歌對具有真主契約的敵人造成傷害時，回復<color=#00F6FF>3%</color>損失的理智值（至少回復1點）。每當理智值從50點（含）以上掉到50點以下，或從50點以下增至50點（含）以上時，將離隊伍最近的非火屬性格子轉為<color=#00F6FF>火屬性深色格子</color>。",
  str_skill_passive_desc_4162301 = "每回合開始或每次經過深色格子時，對具有真主契約的敵人造成1次相當於<color=#00F6FF>{1}</color>隊伍已損失生命值的無視防禦傷害；造成傷害時，額外計入<color=#00F6FF>4,000</color>點損失的生命值。每當理智值從50點（含）以上掉到50點以下，或從50點以下增至50點（含）以上時，將離隊伍最近的非火屬性格子轉為<color=#00F6FF>火屬性深色格子</color>。隊伍生命值越低，維多利亞·墓歌對有真主契約的敵人造成越高傷害；隊伍生命值為50%時，傷害加成達最大值<color=#00F6FF>15%</color>。",
  str_skill_passive_desc_4362301 = "每回合開始或每次經過深色格子時，對具有真主契約的敵人造成1次相當於<color=#00F6FF>{1}</color>隊伍已損失生命值的無視防禦傷害。每當維多利亞·墓歌對具有真主契約的敵人造成傷害時，回復<color=#00F6FF>3%</color>損失的理智值（至少回復1點）。每當理智值從50點（含）以上掉到50點以下，或從50點以下增至50點（含）以上時，將離隊伍最近的非火屬性格子轉為<color=#00F6FF>火屬性深色格子</color>。隊伍生命值越低，維多利亞·墓歌對有真主契約的敵人造成越高傷害；隊伍生命值為50%時，傷害加成達最大值<color=#00F6FF>15%</color>。",
  str_skill_upgrade_refine_desc_16023011 = "裝備技能強化：傷害係數提升為<color=#00F6FF>35%</color>。",
  str_skill_upgrade_refine_desc_16023012 = "連鎖技能強化：對有「真主契約」敵人造成的傷害提升為<color=#00F6FF>1.1倍</color>。",
  str_skill_upgrade_refine_desc_16023013 = "主動技能強化：施放次數<color=#00F6FF>+1</color>。",
