  str_skill_passive_desc_4402301 = "每回合開始或每次經過深色格子時，對具有真主契約的敵人造成1次相當於<color=#00F6FF>35%</color>隊伍已損失生命值的無視防禦傷害。每當維多利亞·墓歌對具有真主契約的敵人造成傷害時，回復<color=#00F6FF>3%</color>損失的理智值（至少回復1點）。",
  str_skill_passive_desc_4432301 = "每回合開始或每次經過深色格子時，對具有真主契約的敵人造成1次相當於<color=#00F6FF>35%</color>隊伍已損失生命值的無視防禦傷害。每當維多利亞·墓歌對具有真主契約的敵人造成傷害時，回復<color=#00F6FF>3%</color>損失的理智值（至少回復1點）。每當理智值從50點（含）以上掉到50點以下，或從50點以下增至50點（含）以上時，將離隊伍最近的非火屬性格子轉為<color=#00F6FF>火屬性深色格子</color>。",
  str_skill_passive_desc_4442301 = "每回合開始或每次經過深色格子時，對具有真主契約的敵人造成1次相當於<color=#00F6FF>35%</color>隊伍已損失生命值的無視防禦傷害。每當維多利亞·墓歌對具有真主契約的敵人造成傷害時，回復<color=#00F6FF>3%</color>損失的理智值（至少回復1點）。每當理智值從50點（含）以上掉到50點以下，或從50點以下增至50點（含）以上時，將離隊伍最近的非火屬性格子轉為<color=#00F6FF>火屬性深色格子</color>。",
  str_skill_passive_desc_4462301 = "每回合開始或每次經過深色格子時，對具有真主契約的敵人造成1次相當於<color=#00F6FF>35%</color>隊伍已損失生命值的無視防禦傷害。每當維多利亞·墓歌對具有真主契約的敵人造成傷害時，回復<color=#00F6FF>3%</color>損失的理智值（至少回復1點）。每當理智值從50點（含）以上掉到50點以下，或從50點以下增至50點（含）以上時，將離隊伍最近的非火屬性格子轉為<color=#00F6FF>火屬性深色格子</color>。隊伍生命值越低，維多利亞·墓歌對有真主契約的敵人造成越高傷害；隊伍生命值為50%時，傷害加成達最大值<color=#00F6FF>15%</color>。",
  str_skill_desc_2502301 = "對最接近的3名敵人造成<color=#00F6FF>135%</color>傷害，對有真主契約的敵人造成1次<color=#00F6FF>1.1倍</color>的傷害。",
  str_skill_desc_2502302 = "對最接近的3名敵人造成<color=#00F6FF>150%</color>傷害，對有真主契約的敵人造成1次<color=#00F6FF>1.1倍</color>的傷害。",
  str_skill_desc_2502303 = "對最接近的3名敵人造成<color=#00F6FF>165%</color>傷害，對有真主契約的敵人造成1次<color=#00F6FF>1.1倍</color>的傷害。",
  str_skill_desc_3602302 = "將隊伍生命值與理智值的百分比對調。理智值為0時無法施放。進入戰鬥時獲得2次施放次數。",
  str_skill_name_2002311 = "血閃",
  str_skill_name_2002312 = "血閃",
  str_skill_name_2002313 = "血閃",
  str_skill_name_3002311 = "淵墮",
  str_skill_name_3032311 = "淵墮",
  str_skill_name_3202311 = "淵墮",
  str_skill_name_3232311 = "淵墮",
  str_skill_name_3302312 = "吻印",
  str_skill_desc_2002311 = "隨機對<color=#00F6FF>周圍2圈</color>內的敵人，造成3次<color=#00F6FF>130%</color>的傷害。對同一目標造成多次傷害時，從第2次起每次傷害減半。",
  str_skill_desc_2002312 = "隨機對<color=#00F6FF>周圍2圈</color>內的敵人，造成4次<color=#00F6FF>140%</color>的傷害。對同一目標造成多次傷害時，從第2次起每次傷害減半。",
  str_skill_desc_2002313 = "隨機對<color=#00F6FF>周圍3圈</color>內的敵人，造成5次<color=#00F6FF>150%</color>的傷害。對同一目標造成多次傷害時，從第2次起每次傷害減半。",
  str_skill_desc_3002311 = "戰鬥時，威廉擁有<link=\"30039\"><#FFAE07><u>【理智系統】</u></color></link>。任選1個格子，並在<color=#00F6FF>周圍2圈</color>內再次選擇1個格子，確定一個矩形區域。將點選格轉為水屬性深色格子，矩形內每個格子扣除<color=#00F6FF>2</color>點理智值。",
  str_skill_desc_3032311 = "戰鬥時，威廉擁有<link=\"30039\"><#FFAE07><u>【理智系統】</u></color></link>。任選1個格子，並在<color=#00F6FF>周圍3圈</color>內再次選擇1個格子，確定一個矩形區域。將點選格轉為水屬性深色格子，矩形內每個格子扣除<color=#00F6FF>2</color>點理智值。",
  str_skill_desc_3202311 = "戰鬥時，威廉擁有<link=\"30039\"><#FFAE07><u>【理智系統】</u></color></link>。任選1個格子，並在<color=#00F6FF>周圍2圈</color>內再次選擇1個格子，確定一個矩形區域。將點選格轉為水屬性深色格子，矩形內每個格子扣除<color=#00F6FF>2</color>點理智值。對該區域內所有敵人施加<color=#00F6FF>1</color>層「血暈」狀態，施放後理智值若低於<color=#00F6FF>50</color>則額外附加1層。\n",
  str_skill_desc_3232311 = "戰鬥時，威廉擁有<link=\"30039\"><#FFAE07><u>【理智系統】</u></color></link>。任選1個格子，並在<color=#00F6FF>周圍3圈</color>內再次選擇1個格子，確定一個矩形區域。將點選格轉為水屬性深色格子，矩形內每個格子扣除<color=#00F6FF>2</color>點理智值。對該區域內所有敵人施加<color=#00F6FF>1</color>層「血暈」狀態，施放後理智值若低於<color=#00F6FF>50</color>則額外附加1層。",
  str_skill_desc_3302312 = "理智值回復20點，施放後理智值上限降低20點。若理智值上限不為0，則可以連續施放。",
  str_skill_passive_name_4002311 = "夜葬",
  str_skill_passive_name_4062311 = "夜葬",
  str_skill_passive_desc_4002311 = "將隊伍中光靈對目標施加的恐懼狀態替換為<color=#00F6FF>血暈</color>狀態，每層使目標防禦力降低<color=#00F6FF>{1}</color>，可疊加3層，持續2回合。每當層數消失（包括目標死亡）或附加層數超過上限時，每層回復1點理智值。威廉連鎖技能每次傷害對目標附加1層<color=#00F6FF>血暈</color>狀態。",
  str_skill_passive_desc_4062311 = "將隊伍中光靈對目標施加的恐懼狀態替換為<color=#00F6FF>血暈</color>狀態，每層使目標防禦力降低<color=#00F6FF>{1}</color>，可疊加3層，持續2回合。每當層數消失（包括目標死亡）或附加層數超過上限時，每層回復2點理智值。威廉連鎖技能每次傷害對目標附加1層<color=#00F6FF>血暈</color>狀態。",
  str_skill_upgrade_desc_16023113 = "主動技能強化：主動技能變為<color=#FFFF00>先制攻擊</color>，進入戰鬥即可使用。選取格子的範圍擴大為3圈。",
  str_skill_upgrade_desc_16023116 = "裝備技能強化：血暈狀態消失或附加層數超過上限時，每層回復2點理智值。",
