  str_skill_desc_2002321 = "對<color=#00F6FF>菱形12格</color>造成<color=#00F6FF>{1}%</color>的傷害，並附加1層<link=\"10000\"><#FFAE07><u>流血</u></color></link>狀態，持續2回合。",
  str_skill_desc_2002322 = "對<color=#00F6FF>米字形16格</color>造成<color=#00F6FF>{1}%</color>的傷害，並附加1層<link=\"10000\"><#FFAE07><u>流血</u></color></link>狀態，持續2回合。",
  str_skill_desc_2002323 = "對<color=#00F6FF>周圍2圈</color>造成<color=#00F6FF>{1}%</color>的傷害，並附加1層<link=\"10000\"><#FFAE07><u>流血</u></color></link>狀態，持續2回合。",
  str_skill_desc_3002321 = "消耗隊伍<color=#00F6FF>10%</color>生命值，任選<color=#00F6FF>1</color>格轉為深色格子。生命值不足時無法施放。",
  str_skill_desc_3202322 = "<color=#FFFF00>施放後技能冷卻回合+1</color>。消耗隊伍<color=#00F6FF>25%</color>生命值，任選<color=#00F6FF>2</color>格轉為深色格子。生命值不足時無法施放。",
  str_skill_desc_3022321 = "消耗隊伍<color=#00F6FF>10%</color>生命值，任選<color=#00F6FF>1</color>格轉為深色格子。生命值不足時無法施放。",
  str_skill_desc_3222322 = "<color=#FFFF00>施放後技能冷卻回合+1</color>。消耗隊伍<color=#00F6FF>25%</color>生命值，任選<color=#00F6FF>2</color>格轉為深色格子。生命值不足時無法施放。",
  str_skill_desc_3302321 = "消耗隊伍<color=#00F6FF>10%</color>生命值，任選<color=#00F6FF>1</color>格轉為深色格子。生命值不足時無法施放。若施放後隊伍生命值低於<color=#00F6FF>30%</color>，則首個點選格會轉為火屬性深色格子。",
  str_skill_desc_3302322 = "<color=#FFFF00>施放後技能冷卻回合+1</color>。消耗隊伍<color=#00F6FF>25%</color>生命值，任選<color=#00F6FF>2</color>格轉為深色格子。生命值不足時無法施放。若施放後隊伍生命值低於<color=#00F6FF>30%</color>，則首個點選格會轉為火屬性深色格子。",
  str_skill_desc_3322321 = "消耗隊伍<color=#00F6FF>10%</color>生命值，任選<color=#00F6FF>1</color>格轉為深色格子。生命值不足時無法施放。若施放後隊伍生命值低於<color=#00F6FF>30%</color>，則首個點選格會轉為火屬性深色格子。",
  str_skill_desc_3322322 = "<color=#FFFF00>施放後技能冷卻回合+1</color>。消耗隊伍<color=#00F6FF>25%</color>生命值，任選<color=#00F6FF>2</color>格轉為深色格子。生命值不足時無法施放。若施放後隊伍生命值低於<color=#00F6FF>30%</color>，則首個點選格會轉為火屬性深色格子。",
  str_skill_passive_desc_4002321 = "生命值掉到<color=#00F6FF>50%</color>以下時，在最靠近的1個火屬性可行走格子上生成1個「殷紅祝福」，經過時可回復聖釘·祭禮攻擊力<color=#00F6FF>{1}</color>的生命值。",
  str_skill_passive_desc_4052321 = "生命值掉到<color=#00F6FF>50%</color>以下時，在最靠近的1個火屬性可行走格子上生成1個「殷紅祝福」，經過時可回復聖釘·祭禮攻擊力<color=#00F6FF>{1}</color>的生命值。經過「殷紅祝福」視為經過深色格子。",
  str_skill_passive_desc_4402321 = "生命值掉到<color=#00F6FF>50%</color>以下時，在最靠近的1個火屬性可行走格子上生成1個「殷紅祝福」，經過時可回復聖釘·祭禮攻擊力<color=#00F6FF>110%</color>的生命值。",
  str_skill_passive_desc_4452321 = "生命值掉到<color=#00F6FF>50%</color>以下時，在最靠近的1個火屬性可行走格子上生成1個「殷紅祝福」，經過時可回復聖釘·祭禮攻擊力<color=#00F6FF>110%</color>的生命值。經過「殷紅祝福」視為經過深色格子。",
  str_skill_passive_desc_4502321 = "生命值掉到<color=#00F6FF>50%</color>以下時，在最靠近的1個火屬性可行走格子上生成1個「殷紅祝福」，經過時可回復聖釘·祭禮攻擊力<color=#00F6FF>110%</color>的生命值和<color=#00F6FF>5%</color>的已損失生命值。",
  str_skill_passive_desc_4552321 = "生命值掉到<color=#00F6FF>50%</color>以下時，在最靠近的1個火屬性可行走格子上生成1個「殷紅祝福」，經過時可回復聖釘·祭禮攻擊力<color=#00F6FF>110%</color>的生命值和<color=#00F6FF>5%</color>的已損失生命值。經過「殷紅祝福」視為經過深色格子。",
  str_skill_passive_desc_4602321 = "生命值掉到<color=#00F6FF>50%</color>和<color=#00F6FF>30%</color>以下時，在最靠近的1個火屬性可行走格子上生成1個「殷紅祝福」，經過時可回復聖釘·祭禮攻擊力<color=#00F6FF>110%</color>的生命值和<color=#00F6FF>5%</color>的已損失生命值。",
  str_skill_passive_desc_4652321 = "生命值掉到<color=#00F6FF>50%</color>和<color=#00F6FF>30%</color>以下時，在最靠近的1個火屬性可行走格子上生成1個「殷紅祝福」，經過時可回復聖釘·祭禮攻擊力<color=#00F6FF>110%</color>的生命值和<color=#00F6FF>5%</color>的已損失生命值。經過「殷紅祝福」視為經過深色格子。",
  str_skill_upgrade_desc_15023212 = "主動技能強化：技能冷卻回合<color=#FFFF00>-1</color>。",
