  str_skill_desc_2602341 = "對最接近的2名敵人造成<color=#00F6FF>165%</color>的傷害。單回合內每次經過深色格子，連鎖技能目標<color=#00F6FF>+1</color>，傷害係數提高<color=#00F6FF>5%</color>。若實際命中的目標少於技能目標數量，則在命中的最近目標周圍生成1個深色格子。",
  str_skill_desc_2602342 = "對最接近的3名敵人造成<color=#00F6FF>170%</color>的傷害。單回合內每次經過深色格子，連鎖技能目標<color=#00F6FF>+1</color>，傷害係數提高<color=#00F6FF>5%</color>。若實際命中的目標少於技能目標數量，則在命中的最近目標周圍生成1個深色格子。",
  str_skill_desc_2602343 = "對最接近的4名敵人造成<color=#00F6FF>175%</color>的傷害。單回合內每次經過深色格子，連鎖技能目標<color=#00F6FF>+1</color>，傷害係數提高<color=#00F6FF>5%</color>。若實際命中的目標少於技能目標數量，則在命中的最近目標周圍生成1個深色格子。",
