  str_skill_passive_desc_410234 = "戰鬥時，萊莎、科洛蒂婭、派翠夏擁有<link=\"30122\"><#FFAE07><u>【戰術系統】</u></color></link>，科洛蒂婭每次施放主動技能獲得<color=#00F6FF>{1}</color>點戰術值。",
  str_skill_passive_desc_440234 = "戰鬥時，萊莎、科洛蒂婭、派翠夏擁有<link=\"30122\"><#FFAE07><u>【戰術系統】</u></color></link>，科洛蒂婭每次施放主動技能獲得<color=#00F6FF>20</color>點戰術值。",
  str_skill_upgrade_refine_desc_16023411 = "裝備技能強化：科洛蒂婭每次施放主動技能獲得<color=#00F6FF>20</color>點戰術值。",
  str_skill_upgrade_refine_desc_16023412 = "主動技能強化：對多格敵人的傷害增益提高<color=#00F6FF>50%</color>。",
  str_skill_upgrade_refine_desc_16023413 = "連鎖技能強化：單回合內每次經過深色格子，連鎖技能傷害係數提高<color=#00F6FF>5%</color>。",
  str_skill_desc_240461 = "對<color=#00F6FF>周圍4圈</color>內的<color=#00F6FF>3</color>個敵人造成<color=#00F6FF>120%</color>的傷害，並附加1層奚笑印記，最大8層。每層印記增加<color=#00F6FF>7%</color>的連鎖傷害。",
  str_skill_desc_240462 = "對<color=#00F6FF>周圍4圈</color>內的<color=#00F6FF>3</color>個敵人造成<color=#00F6FF>140%</color>的傷害，並附加2層奚笑印記，最大8層。每層印記增加<color=#00F6FF>7%</color>的連鎖傷害。",
  str_skill_desc_240463 = "對<color=#00F6FF>周圍4圈</color>內的<color=#00F6FF>3</color>個敵人造成<color=#00F6FF>155%</color>的傷害，並附加3層奚笑印記，最大8層。每層印記增加<color=#00F6FF>7%</color>的連鎖傷害。",
  str_skill_upgrade_refine_desc_13004612 = "連鎖技能強化：每層奚笑印記提高<color=#00F6FF>7%</color>的連鎖傷害。",
  str_skill_desc_300046 = "任選1個格子放置「咯咯」，以「咯咯」為中心牽引<color=#00F6FF>全體</color>敵人，並對擁有5層印記的敵人附加2回合<link=\"10006\"><#FFAE07><u>緩慢</u></color></link>狀態。",
  str_skill_desc_302046 = "任選1個格子放置「咯咯」，以「咯咯」為中心牽引<color=#00F6FF>全體</color>敵人，並對擁有4層印記的敵人附加2回合<link=\"10006\"><#FFAE07><u>緩慢</u></color></link>狀態，對6層印記的敵人附加1回合<link=\"10004\"><#FFAE07><u>麻痺</u></color></link>狀態。",
  str_skill_desc_305046 = "任選1個格子放置「咯咯」，以「咯咯」為中心牽引<color=#00F6FF>全體</color>敵人，並對擁有4層印記的敵人附加2回合<link=\"10006\"><#FFAE07><u>緩慢</u></color></link>狀態，對6層印記的敵人附加<color=#00F6FF>1</color>回合<link=\"10004\"><#FFAE07><u>麻痺</u></color></link>狀態。",
