  str_skill_desc_2002371 = "對<color=#00F6FF>菱形12格</color>造成<color=#00F6FF>160%</color>的傷害。",
  str_skill_desc_2002372 = "以<color=#00F6FF>菱形12格</color>範圍內最近的敵人為中心，對<color=#00F6FF>菱形13格</color>造成<color=#00F6FF>170%</color>的傷害。",
  str_skill_desc_2002373 = "以<color=#00F6FF>周圍2圈</color>範圍內最近的敵人為中心，對<color=#00F6FF>菱形13格</color>造成</color>180%<color=#00F6FF>的傷害。",
  str_skill_desc_2302371 = "對<color=#00F6FF>菱形12格</color>造成<color=#00F6FF>160%</color>的傷害。",
  str_skill_desc_2302372 = "以<color=#00F6FF>菱形12格</color>範圍內最近的敵人為中心，對<color=#00F6FF>菱形13格</color>造成<color=#00F6FF>170%</color>的傷害，並在該敵人所在位置召喚1個絢爛泡影。",
  str_skill_desc_2302373 = "以<color=#00F6FF>周圍2圈</color>範圍內最近的敵人為中心，對<color=#00F6FF>菱形13格</color>造成</color>180%<color=#00F6FF>的傷害，並在該敵人所在位置召喚1個絢爛泡影。",
  str_skill_desc_3002371 = "任選1個<color=#00F6FF>菱形12格</color>範圍內的可行走格子為起點，可無視阻擋在任意數量的<color=#00F6FF>水屬性格子</color>上連線，之後瞬移至連線終點格。若終點落在敵人身上，則對其造成<color=#00F6FF>200%</color>的傷害，之後位移到其周圍位置。",
  str_skill_desc_3032371 = "任選1個<color=#00F6FF>菱形12格</color>範圍內的可行走格子為起點，可無視阻擋在任意數量的<color=#00F6FF>水屬性格子</color>上連線，之後瞬移至連線終點格。若終點落在敵人身上，則對其造成<color=#00F6FF>300%</color>的傷害，之後位移到其周圍位置。",
  str_skill_desc_3202371 = "任選1個<color=#00F6FF>菱形12格</color>範圍內的可行走格子為起點，可無視阻擋在任意數量的<color=#00F6FF>水屬性格子、深色格子或絢爛泡影所在格子</color>上連線，之後瞬移至連線終點格。若終點落在敵人身上，則對其造成<color=#00F6FF>200%</color>的傷害，之後位移到其周圍位置。",
  str_skill_desc_3232371 = "任選1個<color=#00F6FF>菱形12格</color>範圍內的可行走格子為起點，可無視阻擋在任意數量的<color=#00F6FF>水屬性格子、深色格子或絢爛泡影所在格子</color>上連線，之後瞬移至連線終點格。若終點落在敵人身上，則對其造成<color=#00F6FF>300%</color>的傷害，之後位移到其周圍位置。",
  str_skill_passive_name_4102371 = "鏡花水月",
  str_skill_passive_desc_4102371 = "每回合開始時，在場上隨機<color=#00F6FF>2</color>個可行走格子上召喚絢爛泡影，持續3回合。每當移動或主動技能連線經過絢爛泡影時，對<color=#00F6FF>周圍3圈</color>內的3名敵人造成<color=#00F6FF>{1}</color>的傷害。",
  str_skill_passive_name_4402371 = "鏡花水月",
  str_skill_passive_desc_4402371 = "每回合開始時，在場上隨機<color=#00F6FF>2</color>個可行走格子上召喚絢爛泡影，持續3回合。每當移動或主動技能連線經過絢爛泡影時，對<color=#00F6FF>周圍3圈</color>內的3名敵人造成<color=#00F6FF>140%</color>的傷害。",
  str_skill_passive_name_4502371 = "鏡花水月",
  str_skill_passive_desc_4502371 = "每回合開始時，在場上隨機<color=#00F6FF>2</color>個可行走格子上召喚絢爛泡影，持續3回合。每當移動或主動技能連線經過絢爛泡影時，對<color=#00F6FF>周圍3圈</color>內的4名敵人造成<color=#00F6FF>140%</color>的傷害。",
  str_skill_passive_name_4602371 = "鏡花水月",
  str_skill_passive_desc_4602371 = "每回合開始時，在場上隨機<color=#00F6FF>2</color>個可行走格子上召喚絢爛泡影，持續3回合。每當移動或主動技能連線經過絢爛泡影時，對<color=#00F6FF>周圍3圈</color>內的4名敵人造成<color=#00F6FF>140%</color>的傷害。經過深色格子或絢爛泡影觸發時，可累積1點幻象源，每點幻象源提升<color=#00F6FF>1%</color>連鎖技能傷害。",
  str_skill_passive_name_4162371 = "鏡花水月",
  str_skill_passive_desc_4162371 = "每回合開始時，在場上隨機<color=#00F6FF>3</color>個可行走格子上召喚絢爛泡影，持續5回合。每當移動或主動技能連線經過絢爛泡影時，對<color=#00F6FF>周圍3圈</color>內的3名敵人造成<color=#00F6FF>{1}</color>的傷害。",
  str_skill_passive_name_4462371 = "鏡花水月",
  str_skill_passive_desc_4462371 = "每回合開始時，在場上隨機<color=#00F6FF>3</color>個可行走格子上召喚絢爛泡影，持續5回合。每當移動或主動技能連線經過絢爛泡影時，對<color=#00F6FF>周圍3圈</color>內的3名敵人造成<color=#00F6FF>140%</color>的傷害。",
  str_skill_passive_name_4562371 = "鏡花水月",
  str_skill_passive_desc_4562371 = "每回合開始時，在場上隨機<color=#00F6FF>3</color>個可行走格子上召喚絢爛泡影，持續5回合。每當移動或主動技能連線經過絢爛泡影時，對<color=#00F6FF>周圍3圈</color>內的4名敵人造成<color=#00F6FF>140%</color>的傷害。",
  str_skill_passive_name_4662371 = "鏡花水月",
  str_skill_passive_desc_4662371 = "每回合開始時，在場上隨機<color=#00F6FF>3</color>個可行走格子上召喚絢爛泡影，持續5回合。每當移動或主動技能連線經過絢爛泡影時，對<color=#00F6FF>周圍3圈</color>內的4名敵人造成<color=#00F6FF>140%</color>的傷害。經過深色格子或絢爛泡影觸發時，可累積1點幻象源，每點幻象源提升<color=#00F6FF>1%</color>連鎖技能傷害。",
  str_skill_upgrade_refine_desc_16023711 = "裝備技能強化：絢爛泡影觸發造成的傷害提升至<color=#00F6FF>140%</color>。",
  str_skill_upgrade_refine_desc_16023712 = "裝備技能強化：絢爛泡影觸發時，對範圍內<color=#00F6FF>4</color>名敵人造成傷害。",
  str_skill_upgrade_refine_desc_16023713 = "裝備技能強化：經過深色格子或絢爛泡影觸發時，可累積1點幻象源，每點幻象源提升<color=#00F6FF>1%</color>連鎖技能傷害。",
  str_skill_upgrade_desc_16023713 = "主動技能強化：技能冷卻回合<color=#FFFF00>-1</color>。若終點落在敵人身上，則對其造成<color=#FFFF00>300%</color>的傷害。",
  str_skill_upgrade_desc_16023716 = "裝備技能強化：絢爛泡影持續時間增為5回合，每回合開始時額外召喚1個絢爛泡影。",
  str_skill_name_291020103 = "擱淺的追逐",
  str_skill_name_291020104 = "渴求的愛意",
  str_skill_name_291020105 = "海妖的悲鳴",
  str_skill_desc_291020103 = "對光靈造成傷害，並在光靈周圍召喚禮砲。當自身生命低於70%/40%時，召喚數量分別+1。",
  str_skill_desc_291020104 = "在自身周圍1圈離光靈最遠的格子召喚索求。當自身生命低於50%時，召喚數量+1。",
  str_skill_desc_291020105 = "對光靈造成3次遞增的傷害，並將光靈擊退到場地邊緣。",
  str_skill_desc_291020113 = "對光靈造成傷害，並在光靈周圍召喚禮砲。",
  str_skill_passive_desc_443173 = "每當隊伍獲得（包括<link=\"30065\"><#FFAE07><u>吸收</u></color></link>）<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>時，立即對全場隨機<color=#00F6FF>1</color>個目標造成<color=#00F6FF>85%</color>的傷害。進入戰鬥時獲得<color=#00F6FF>33</color>層凡客印記，每次獲得強化格子減少<color=#00F6FF>1</color>層，印記清空後本場戰鬥進入犄影態：基礎攻擊力提高<color=#00F6FF>25%</color>，普通攻擊可攻擊斜方向，裝備技能傷害變為<color=#00F6FF>2.5</color>倍，連鎖技能命中同一目標後傷害不衰減。",
  str_skill_passive_desc_453173 = "每當隊伍獲得（包括<link=\"30065\"><#FFAE07><u>吸收</u></color></link>）<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>時，立即對全場隨機<color=#00F6FF>1</color>個目標造成<color=#00F6FF>85%</color>的傷害。進入戰鬥時獲得<color=#00F6FF>33</color>層凡客印記，每次獲得強化格子減少<color=#00F6FF>1</color>層，印記清除後本場戰鬥進入犄影態：基礎攻擊力提高<color=#00F6FF>25%</color>，普通攻擊可攻擊斜方向，裝備技能傷害變為<color=#00F6FF>2.5</color>倍，連鎖技能觸發條件分別減少<color=#00F6FF>1/2/3</color>且命中同一目標後傷害不衰減。",
  str_skill_passive_desc_463173 = "每當隊伍獲得（包括<link=\"30065\"><#FFAE07><u>吸收</u></color></link>）<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>時，立即對全場隨機<color=#00F6FF>1</color>個目標造成<color=#00F6FF>85%</color>的傷害。進入戰鬥時獲得<color=#00F6FF>33</color>層凡客印記，每次獲得強化格子減少<color=#00F6FF>1</color>層，印記清除後本場戰鬥進入犄影態：基礎攻擊力提高<color=#00F6FF>25%</color>，普通攻擊可攻擊斜方向，裝備技能傷害變為<color=#00F6FF>2.5</color>倍，連鎖技能觸發條件分別減少<color=#00F6FF>1/2/3</color>且命中同一目標後傷害不衰減。主動技能傷害係數提升為<color=#00F6FF>200%</color>。",
  str_skill_passive_desc_440173 = "每當隊伍獲得（包括<link=\"30065\"><#FFAE07><u>吸收</u></color></link>）<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>時，立即對全場隨機<color=#00F6FF>1</color>個目標造成<color=#00F6FF>85%</color>的傷害。進入戰鬥時獲得<color=#00F6FF>33</color>層凡客印記，每次獲得強化格子減少<color=#00F6FF>1</color>層，印記清空後本場戰鬥進入犄影態：基礎攻擊力提高<color=#00F6FF>20%</color>，普通攻擊可攻擊斜方向，裝備技能傷害變為<color=#00F6FF>2.5</color>倍，連鎖技能命中同一目標後傷害不衰減。",
  str_skill_passive_desc_450173 = "每當隊伍獲得（包括<link=\"30065\"><#FFAE07><u>吸收</u></color></link>）<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>時，立即對全場隨機<color=#00F6FF>1</color>個目標造成<color=#00F6FF>85%</color>的傷害。進入戰鬥時獲得<color=#00F6FF>33</color>層凡客印記，每次獲得強化格子減少<color=#00F6FF>1</color>層，印記清除後本場戰鬥進入犄影態：基礎攻擊力提高<color=#00F6FF>20%</color>，普通攻擊可攻擊斜方向，裝備技能傷害變為<color=#00F6FF>2.5</color>倍，連鎖技能觸發條件分別減少<color=#00F6FF>1/2/3</color>且命中同一目標後傷害不衰減。",
  str_skill_passive_desc_460173 = "每當隊伍獲得（包括<link=\"30065\"><#FFAE07><u>吸收</u></color></link>）<link=\"20001\"><#FFAE07><u>強化格子</u></color></link>時，立即對全場隨機<color=#00F6FF>1</color>個目標造成<color=#00F6FF>85%</color>的傷害。進入戰鬥時獲得<color=#00F6FF>33</color>層凡客印記，每次獲得強化格子減少<color=#00F6FF>1</color>層，印記清除後本場戰鬥進入犄影態：基礎攻擊力提高<color=#00F6FF>20%</color>，普通攻擊可攻擊斜方向，裝備技能傷害變為<color=#00F6FF>2.5</color>倍，連鎖技能觸發條件分別減少<color=#00F6FF>1/2/3</color>且命中同一目標後傷害不衰減。主動技能傷害係數提升為<color=#00F6FF>200%</color>。",
  str_skill_upgrade_refine_desc_16017311 = "裝備技能強化：傷害係數提升為85%。",
  str_skill_upgrade_refine_desc_16017312 = "裝備技能強化：進入犄影態後，連鎖技能觸發條件分別減少1/2/3。",
  str_skill_upgrade_refine_desc_16017313 = "裝備技能強化：進入犄影態後，主動技能傷害係數提升為200%。",
  str_skill_upgrade_refine_desc_14016911 = "裝備技能強化：塞提的基礎攻擊力提高<color=#00F6FF>33%</color>，每點擊墜點可使主動技能傷害係數提高<color=#00F6FF>22%</color>。",
  str_skill_upgrade_refine_desc_14016912 = "裝備技能強化：經過深色格子可獲得1點<color=#00F6FF>擊墜點</color>。",
  str_skill_upgrade_refine_desc_14016913 = "主動技能強化：可選擇範圍擴大為<color=#00F6FF>周圍1圈</color>。",
  str_skill_passive_desc_440169 = "塞提的基礎攻擊力提高<color=#00F6FF>33%</color>，每次連線塞提最多普通攻擊<color=#00F6FF>3</color>次，第3次普通攻擊傷害翻倍。3次之後的普通攻擊改為獲得1點<color=#00F6FF>擊墜點</color>，每點擊墜點提高<color=#00F6FF>22%</color>的主動技能傷害係數，施放主動技能後清空。",
  str_skill_passive_desc_450169 = "塞提的基礎攻擊力提高<color=#00F6FF>33%</color>，每次連線塞提最多普通攻擊<color=#00F6FF>3</color>次，第3次普通攻擊傷害翻倍。3次之後的普通攻擊改為獲得1點<color=#00F6FF>擊墜點</color>，每點擊墜點提高<color=#00F6FF>22%</color>的主動技能傷害係數，施放主動技能後清空。每次經過深色格子可額外獲得1點<color=#00F6FF>擊墜點</color>。",
  str_skill_name_360169 = "崩崩飛",
  str_skill_name_365169 = "崩崩飛",
  str_skill_desc_360169 = "對<color=#00F6FF>周圍1圈</color>的1名敵人造成<color=#00F6FF>300%</color>的傷害並擊退2格，若擊退過程中遇到<color=#00F6FF>阻擋</color>，還會使其額外受到<color=#00F6FF>200%</color>的傷害並<color=#00F6FF>眩暈</color>1回合；若阻擋為其他敵人，則該敵人也會受到傷害和眩暈。",
  str_skill_desc_365169 = "對<color=#00F6FF>周圍1圈</color>的1名敵人造成<color=#00F6FF>300%</color>的傷害並擊退3格，若擊退過程中遇到<color=#00F6FF>阻擋</color>，還會使其額外受到<color=#00F6FF>200%</color>的傷害並<color=#00F6FF>眩暈</color>1回合；若阻擋為其他敵人，則該敵人也會受到傷害和眩暈。",
  str_skill_name_20053011 = "深海的呢喃",
  str_skill_desc_20053011 = "對周圍1圈範圍內的敵人造成傷害。",
  str_skill_name_20054011 = "觸碰",
  str_skill_desc_20054011 = "當光靈處於周圍2圈範圍內，則在光靈附近召喚1名暗鬼協助自己。",
  str_skill_upgrade_desc_17023613 = "主動技能強化：每回合開始獲得5點威能。",
  str_skill_upgrade_desc_17023616 = "新增主動技能：祭劍座處於離隊狀態時施放可立即歸隊，並對沿途格子造成<color=#00F6FF>550%</color>的傷害。",
  str_skill_passive_name_4102361 = "致命運的怒音",
  str_skill_name_2002361 = "車爾尼的奇蹟",
  str_skill_name_2002362 = "車爾尼的奇蹟",
  str_skill_name_2002363 = "車爾尼的奇蹟",
  str_skill_name_2002364 = "車爾尼的奇蹟",
  str_skill_name_3302361 = "開闢的決意",
  str_skill_name_3302362 = "回歸的流星",
  str_skill_desc_3302361 = "戰鬥中可獲得<link=\"30125\"><#FFAE07><u>威能</u></color></link>。開放技能後祭劍座進入特殊的出戰模式，此模式下可單獨對祭劍座進行<link=\"30127\"><#FFAE07><u>連線操作</u></color></link>。連線完畢後祭劍座進入<link=\"30128\"><#FFAE07><u>離隊狀態</u></color></link>，在連線結束時的位置留下<link=\"30129\"><#FFAE07><u>殘影</u></color></link>作為下次施放主動技能時的連線起點。",
  str_skill_desc_3332361 = "戰鬥中可獲得<link=\"30126\"><#FFAE07><u>威能</u></color></link>。開放技能後祭劍座進入特殊的出戰模式，此模式下可單獨對祭劍座進行<link=\"30127\"><#FFAE07><u>連線操作</u></color></link>。連線完畢後祭劍座進入<link=\"30128\"><#FFAE07><u>離隊狀態</u></color></link>，在連線結束時的位置留下<link=\"30129\"><#FFAE07><u>殘影</u></color></link>作為下次施放主動技能時的連線起點。",
  str_skill_desc_3302362 = "祭劍座處於離隊狀態時施放可立即歸隊，並對沿途格子造成<color=#00F6FF>550%</color>的傷害。",
  str_skill_desc_2002361 = "對<color=#00F6FF>周圍4格</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2002362 = "對<color=#00F6FF>周圍1圈</color>造成<color=#00F6FF>{1}%</color>的傷害。若未處於離隊狀態，則獲得3點威能。",
  str_skill_desc_2002363 = "對<color=#00F6FF>菱形12格</color>造成<color=#00F6FF>{1}%</color>的傷害。若未處於離隊狀態，則獲得4點威能。",
  str_skill_desc_2002364 = "對<color=#00F6FF>周圍2圈</color>造成<color=#00F6FF>175%</color>的傷害。若未處於離隊狀態，則獲得5點威能。",
  str_skill_passive_desc_4102361 = "祭劍座為<color=#00F6FF>無屬性</color>光靈，攻擊與受擊時，屬性剋制係數均視為<color=#00F6FF>100%</color>。<color=#00F6FF>祭劍座擔任隊長期間會全程出戰，處於隊員位期間則只有在連線全為彩色格子時才會出戰</color>。每透過主動技能消耗1點威能，祭劍座獲得1層星辰之力，每層星辰之力使祭劍座的傷害提高<color=#00F6FF>{1}</color>，最多99層。",
  str_skill_passive_desc_4402361 = "祭劍座為<color=#00F6FF>無屬性</color>光靈，攻擊與受擊時，屬性剋制係數均視為<color=#00F6FF>100%</color>。<color=#00F6FF>祭劍座擔任隊長期間會全程出戰，處於隊員位期間則只有在連線全為彩色格子時才會出戰</color>。每透過主動技能消耗1點威能，祭劍座獲得1層星辰之力，每層星辰之力使祭劍座的傷害提高<color=#00F6FF>1.1%</color>，最多99層。",
  str_skill_passive_desc_4602361 = "祭劍座為<color=#00F6FF>無屬性</color>光靈，攻擊與受擊時，屬性剋制係數均視為<color=#00F6FF>100%</color>。<color=#00F6FF>祭劍座擔任隊長期間會全程出戰，處於隊員位期間則只有在連線全為彩色格子時才會出戰</color>。每透過主動技能消耗1點威能，祭劍座獲得2層星辰之力，每層星辰之力使祭劍座的傷害提高<color=#00F6FF>1.1%</color>，最多99層。",
  str_skill_upgrade_refine_desc_17023611 = "裝備技能強化：係數提升為<color=#00F6FF>1.1%</color>。",
  str_skill_upgrade_refine_desc_17023612 = "新增<color=#00F6FF>4</color>階段連鎖技能：所需連線格子數為12格，對周圍2圈範圍造成175%的傷害。若未處於離隊狀態，則獲得5點威能。",
  str_skill_upgrade_refine_desc_17023613 = "裝備技能強化：獲得的星辰之力層數<color=#00F6FF>翻倍</color>。",
  str_skill_upgrade_desc_16023813 = "主動技能強化：主動技能變為<color=#FFFF00>先制攻擊</color>，進入戰鬥即可使用。",
  str_skill_upgrade_desc_16023816 = "主動技能強化：可點選格子數<color=#00F6FF>+1</color>.",
  str_skill_name_2002381 = "天羽藏鋒",
  str_skill_desc_2002381 = "對<color=#00F6FF>最接近的1名敵人</color>投擲羽刃造成170%的傷害，然後彈射到<color=#00F6FF>離該目標最近</color>的另一名敵人身上。與目標每間隔1圈，最終傷害提高10%，最高提高50%。根據連鎖數量提供傷害加成。",
  str_skill_name_3002381 = "啟示寄語",
  str_skill_name_3062381 = "啟示寄語",
  str_skill_name_3302381 = "啟示寄語·變體I",
  str_skill_name_3362381 = "啟示寄語·變體I",
  str_skill_desc_3002381 = "任選<color=#00F6FF>5個</color>格子，生成強化格子。",
  str_skill_desc_3062381 = "任選<color=#00F6FF>6個</color>格子，生成強化格子。",
  str_skill_desc_3302381 = "<color=#FFFF00>施放後技能冷卻回合-1</color>。任選<color=#00F6FF>3個</color>格子，生成強化格子。",
  str_skill_desc_3362381 = "<color=#FFFF00>施放後技能冷卻回合-1</color>。任選<color=#00F6FF>4個</color>格子，生成強化格子。",
  str_skill_passive_name_4102381 = "繼承的星光",
  str_skill_passive_name_4162381 = "繼承的星光",
  str_skill_passive_desc_4102381 = "每獲得<color=#00F6FF>1個強化格子</color>，即獲得<color=#00F6FF>1層星光印記</color>。每當連鎖技能造成傷害時，消耗<color=#00F6FF>⅓</color>的星光印記層數，每層額外附加<color=#00F6FF>{1}</color>全隊平均攻擊力的傷害。",
  str_skill_passive_desc_4162381 = "每獲得<color=#00F6FF>1個強化格子</color>，即獲得<color=#00F6FF>1層星光印記</color>。每當連鎖技能造成傷害時，消耗<color=#00F6FF>⅓</color>的星光印記層數，每層額外附加<color=#00F6FF>{1}</color>全隊平均攻擊力的傷害。單回合內每獲得1個強化格子，連鎖技能觸發條件-1。",
  str_skill_upgrade_refine_desc_15017611 = "裝備技能強化：貝爾塔每第<color=#00F6FF>4</color>次普通攻擊對目標附加1根南極光絨針。",
  str_skill_upgrade_refine_desc_15017612 = "主動技能強化：每根絨針對目標造成<color=#00F6FF>100%</color>傷害。",
  str_skill_upgrade_refine_desc_15017613 = "主動技能強化：每根絨針對目標造成傷害時恢復等同於本次傷害<color=#00F6FF>15%~22.5%</color>的生命值。",
  str_skill_passive_desc_4401761 = "貝爾塔每第<color=#00F6FF>4</color>次普通攻擊對目標附加<color=#00F6FF>1</color>根<color=#00F6FF>南極光絨針</color>。",
  str_skill_passive_desc_4451761 = "貝爾塔每第<color=#00F6FF>4</color>次普通攻擊對目標附加<color=#00F6FF>1</color>根<color=#00F6FF>南極光絨針</color>。",
  str_skill_desc_3501761 = "將<color=#00F6FF>周圍2圈</color>所有敵人身上的<color=#00F6FF>南極光絨針</color>拔出，每根絨針對目標造成<color=#00F6FF>100%</color>傷害並恢復等同於本次傷害<color=#00F6FF>10%~15%</color>的生命值。隊伍生命值越低恢復係數越高。",
  str_skill_desc_3521761 = "將<color=#00F6FF>周圍3圈</color>所有敵人身上的<color=#00F6FF>南極光絨針</color>拔出，每根絨針對目標造成<color=#00F6FF>100%</color>傷害並恢復等同於本次傷害<color=#00F6FF>10%~15%</color>的生命值。隊伍生命值越低恢復係數越高。",
  str_skill_desc_3551761 = "將<color=#00F6FF>周圍3圈</color>所有敵人身上的<color=#00F6FF>南極光絨針</color>拔出，每根絨針對目標造成<color=#00F6FF>100%~120%</color>傷害並恢復等同於本次傷害<color=#00F6FF>10%~15%</color>的生命值。目標生命值越低傷害係數越高，隊伍生命值越低恢復係數越高。",
  str_skill_desc_3601761 = "將<color=#00F6FF>周圍2圈</color>所有敵人身上的<color=#00F6FF>南極光絨針</color>拔出，每根絨針對目標造成<color=#00F6FF>100%</color>傷害並恢復等同於本次傷害<color=#00F6FF>15%~22.5%</color>的生命值。隊伍生命值越低恢復係數越高。",
  str_skill_desc_3621761 = "將<color=#00F6FF>周圍3圈</color>所有敵人身上的<color=#00F6FF>南極光絨針</color>拔出，每根絨針對目標造成<color=#00F6FF>100%</color>傷害並恢復等同於本次傷害<color=#00F6FF>15%~22.5%</color>的生命值。隊伍生命值越低恢復係數越高。",
  str_skill_desc_3651761 = "將<color=#00F6FF>周圍3圈</color>所有敵人身上的<color=#00F6FF>南極光絨針</color>拔出，每根絨針對目標造成<color=#00F6FF>100%~120%</color>傷害並恢復等同於本次傷害<color=#00F6FF>15%~22.5%</color>的生命值。目標生命值越低傷害係數越高，隊伍生命值越低恢復係數越高。",
  str_skill_name_3501821 = "螭龍席捲·變體I",
  str_skill_name_3601821 = "螭龍席捲·變體II",
  str_skill_desc_3501821 = "<color=#00F6FF>2</color>盞<link=\"30074\"><#FFAE07><u>「淨龍輝」</u></color></link>亮起後主動技能就緒，<color=#FFFF00>施放後熄滅2盞「淨龍輝」</color>。選擇1個格子，對<color=#00F6FF>菱形13格</color>造成<color=#00F6FF>400%</color>的傷害。不觸發裝備技能「孑遺技」。",
  str_skill_desc_3601821 = "<color=#00F6FF>2</color>盞<link=\"30074\"><#FFAE07><u>「淨龍輝」</u></color></link>亮起後主動技能就緒，<color=#FFFF00>施放後熄滅2盞「淨龍輝」</color>。觸發裝備技能「孑遺技」，對<color=#00F6FF>全體</color>敵人造成<color=#00F6FF>300%</color>的傷害。",
  str_skill_upgrade_refine_desc_16018211 = "主動技能強化：傷害係數提升為400%。",
  str_skill_upgrade_refine_desc_16018212 = "<color=#00F6FF>新增主動技能變體I</color>：2盞「淨龍輝」亮起後主動技能就緒，施放後熄滅2盞「淨龍輝」。選擇1個格子，對菱形13格造成400%的傷害。不觸發裝備技能「孑遺技」。",
  str_skill_upgrade_refine_desc_16018213 = "<color=#00F6FF>新增主動技能變體II</color>：2盞「淨龍輝」亮起後主動技能就緒，施放後熄滅2盞「淨龍輝」。觸發裝備技能「孑遺技」，對全體敵人造成300%的傷害。",
  str_skill_desc_3401821 = "<color=#00F6FF>3</color>盞<link=\"30074\"><#FFAE07><u>「淨龍輝」</u></color></link>亮起後主動技能就緒，選擇1個格子，對<color=#00F6FF>菱形13格</color>造成<color=#00F6FF>400%</color>的傷害。施放後所有「淨龍輝」熄滅。",
  str_skill_upgrade_desc_16024113 = "主動技能強化：主動技能冷卻回合數<color=#00F6FF>-1</color>，傷害係數增加<color=#00F6FF>50%</color>。",
  str_skill_upgrade_desc_16024116 = "主動技能新增變體：消耗理智值與造成傷害<color=#00F6FF>翻倍</color>，至多生成<color=#00F6FF>3</color>個深色格子。",
  str_skill_name_2002411 = "脫繮爆燃",
  str_skill_name_2002412 = "脫繮爆燃",
  str_skill_name_2002413 = "脫繮爆燃",
