  str_skill_desc_2002411 = "對<color=#00F6FF>周圍1圈</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2002412 = "對<color=#00F6FF>菱形12格</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2002413 = "對<color=#00F6FF>周圍2圈</color>造成<color=#00F6FF>{1}%</color>的傷害。",
  str_skill_desc_2302411 = "對<color=#00F6FF>周圍1圈</color>造成<color=#00F6FF>{1}%</color>的傷害，<link=\"30124\"><#FFAE07><u>吸收</u></color></link>周圍4格內的深色格子。",
  str_skill_desc_2302412 = "對<color=#00F6FF>菱形12格</color>造成<color=#00F6FF>{1}%</color>的傷害，<link=\"30124\"><#FFAE07><u>吸收</u></color></link>周圍1圈內的深色格子。",
  str_skill_desc_2302413 = "對<color=#00F6FF>周圍2圈</color>造成<color=#00F6FF>{1}%</color>的傷害，<link=\"30124\"><#FFAE07><u>吸收</u></color></link>周圍菱形12格內的深色格子。",
  str_skill_desc_3002411 = "佩皮塔在進入戰鬥後自帶<link=\"30039\"><#FFAE07><u>【理智系統】</u></color></link>。消耗<color=#00F6FF>15</color>點理智值，任選1個敵人，對其造成150%的傷害，並在其腳下隨機1個格子生成深色格子。",
  str_skill_desc_3032411 = "佩皮塔在進入戰鬥後自帶<link=\"30039\"><#FFAE07><u>【理智系統】</u></color></link>。消耗<color=#00F6FF>15</color>點理智值，任選1個敵人，對其造成200%的傷害，並在其腳下隨機1個格子生成深色格子。",
  str_skill_desc_3062411 = "佩皮塔在進入戰鬥後自帶<link=\"30039\"><#FFAE07><u>【理智系統】</u></color></link>。消耗<color=#00F6FF>30</color>點理智值，任選1個敵人，對其造成400%的傷害，並在其腳下至多隨機3個格子生成深色格子。",
  str_skill_passive_name_4102411 = "心焰熾躍",
  str_skill_passive_name_4202411 = "心焰熾躍",
  str_skill_passive_desc_4102411 = "每當獲得深色格子時，佩皮塔獲得<color=#00F6FF>1</color>層心之焰，最多<color=#00F6FF>7</color>層。當前隊長每次普通攻擊時消耗1層心之焰，並提高本次普通攻擊<color=#00F6FF>{1}</color>的最終傷害。",
  str_skill_passive_desc_4202411 = "每當獲得深色格子時，佩皮塔獲得<color=#00F6FF>1</color>層心之焰，最多<color=#00F6FF>7</color>層。當前隊長每次普通攻擊時消耗1層心之焰，並提高本次普通攻擊<color=#00F6FF>{1}</color>的最終傷害。每回合開始時，在全場怪物腳下隨機生成<color=#00F6FF>2</color>個深色格子。",
